/// The FUSED `<node>.<key>[<i>]` path (item 648) reads one element straight off the stored list
/// and skips materializing a column of cloned lists. It is guarded by a PRE-SCAN that must send
/// every other shape to the general path, so these pin the shapes where falling through wrongly
/// would be a SILENT wrong answer rather than a slow one.
///
/// One fixture, every shape in it, so the pre-scan sees a MIXED column and must decline for all
/// of them — a per-shape fixture would let the fast path answer each one in isolation and prove
/// nothing about the guard.
#[test]
fn indexing_a_property_agrees_whatever_the_stored_value_is() {
    let mut b = Builder::default();

    // A plain list — the shape the fast path exists for.
    b.node(
        &["N"],
        &[("v", Value::List(vec![n(10.0), n(11.0), n(12.0)]))],
    );
    // A RECORD and a MAP: `[...]` on these reads a FIELD by string key, not a position.
    b.node(
        &["N"],
        &[(
            "v",
            Value::Record([("k".into(), n(99.0))].into_iter().collect()),
        )],
    );
    b.node(
        &["N"],
        &[(
            "v",
            Value::Map(std::sync::Arc::new(vec![(s("k"), n(88.0))])),
        )],
    );
    // A SCALAR, an empty list, and the key ABSENT — all NULL under a numeric index.
    b.node(&["N"], &[("v", n(7.0))]);
    b.node(&["N"], &[("v", Value::List(Vec::new()))]);
    b.node(&["N"], &[("other", n(1.0))]);
    let store = b.build();

    let at = |idx: Expr| -> Vec<String> {
        // `Plan::Project`, NOT `PathRecord`. The first version of these tests used PathRecord
        // and read back 0.0 / 1.0 / 2.0 — the ROW INDEX — because PathRecord does not append the
        // evaluated value as a column. That is the same wrong assumption that made item 641's
        // first harness measure PathRecord's own floor instead of the expression.
        let plan = Plan::Project {
            input: Box::new(Plan::Scan { label: None }),
            items: vec![(
                "x".to_string(),
                Expr::Index {
                    base: Box::new(prop(0, "v")),
                    index: Box::new(idx),
                    elem: crate::ir::ElemKind::Plain,
                },
            )],
        };
        let got = crate::exec::pull(&plan, &store, false).expect("plan runs");
        let col = got.slot(0);

        (0..got.rows())
            .map(|i| format!("{:?}", col.value_at(i)))
            .collect()
    };

    // Index 0: the list yields its first element; everything else is NULL.
    let zero = at(lit(n(0.0)));
    assert_eq!(zero[0], format!("{:?}", n(10.0)), "the list");
    for (i, got) in zero.iter().enumerate().skip(1) {
        assert_eq!(
            got,
            &format!("{:?}", Value::Null),
            "row {i} must be NULL: {zero:?}"
        );
    }

    // Index 2 reaches the list's third element and nothing else.
    let two = at(lit(n(2.0)));
    assert_eq!(two[0], format!("{:?}", n(12.0)));

    // OUT OF RANGE, NEGATIVE and NON-INTEGER are NULL even for the list.
    for bad in [3.0, -1.0, 0.5] {
        let got = at(lit(n(bad)));
        assert_eq!(
            got[0],
            format!("{:?}", Value::Null),
            "index {bad} must be NULL, got {got:?}"
        );
    }

    // A STRING index reads the record's and the map's field, which is the behaviour the fast
    // path must not swallow.
    let by_key = at(lit(s("k")));
    assert_eq!(by_key[1], format!("{:?}", n(99.0)), "the record field");
    assert_eq!(by_key[2], format!("{:?}", n(88.0)), "the map entry");
    assert_eq!(by_key[0], format!("{:?}", Value::Null), "a list has no 'k'");
}

/// The fused `<needle> IN <node>.<key>` path (item 649) scans the STORED list instead of
/// materializing a column of cloned lists. `IN` is THREE-VALUED, and that is where a wrong
/// answer would be silent: TRUE if any element equals the needle, else NULL if the needle or
/// ANY element is null (the membership cannot be decided), else FALSE.
///
/// Note the asymmetry that makes these cases load-bearing: a MATCH short-circuits to TRUE even
/// when a null element was already seen, so `[null, 1] IN`-containing 1 is TRUE, not NULL —
/// and a non-match with a null element is NULL, not FALSE.
#[test]
fn fused_in_over_a_stored_list_is_three_valued() {
    let mut b = Builder::default();
    b.node(&["N"], &[("v", Value::List(vec![n(1.0), n(2.0)]))]); // plain hit/miss
    b.node(&["N"], &[("v", Value::List(vec![Value::Null, n(1.0)]))]); // null BEFORE a match
    b.node(&["N"], &[("v", Value::List(vec![Value::Null, n(9.0)]))]); // null, no match
    b.node(&["N"], &[("v", Value::List(Vec::new()))]); // empty: decidable FALSE
    let store = b.build();

    let probe = |needle: Expr| -> Vec<String> {
        let plan = Plan::Project {
            input: Box::new(Plan::Scan { label: None }),
            items: vec![(
                "x".to_string(),
                Expr::In {
                    needle: Box::new(needle),
                    haystack: Box::new(prop(0, "v")),
                },
            )],
        };
        let got = crate::exec::pull(&plan, &store, false).expect("plan runs");

        (0..got.rows())
            .map(|i| format!("{:?}", got.slot(0).value_at(i)))
            .collect()
    };

    let t = format!("{:?}", Value::Bool(true));
    let f = format!("{:?}", Value::Bool(false));
    let null = format!("{:?}", Value::Null);

    // Needle 1: hit; hit DESPITE a null element seen first; no hit WITH a null → NULL; empty.
    assert_eq!(
        probe(lit(n(1.0))),
        vec![t.clone(), t.clone(), null.clone(), f.clone()]
    );

    // Needle 9: miss on a clean list → FALSE; miss with a null element → NULL; hit on row 2.
    assert_eq!(
        probe(lit(n(9.0))),
        vec![f.clone(), null.clone(), t.clone(), f.clone()]
    );

    // A NULL needle cannot be decided against a non-empty list, but an EMPTY list has no
    // element to be unknown about — and the engine still reports NULL there, because the needle
    // itself is null. Pinning whatever it does so a route change cannot alter it silently.
    let with_null = probe(lit(Value::Null));
    assert_eq!(with_null[0], null, "a null needle over a plain list");
    assert_eq!(with_null[1], null, "a null needle over a list with a null");

    // THE EMPTY LIST IS THE DISCRIMINATING ROW for the null needle, and mutation found that the
    // assertions above miss it. `saw_unknown = needle.is_null()` is redundant with the in-loop
    // `needle.is_null()` check for every NON-empty list — the loop sets it anyway — so dropping
    // the seed only shows up where the loop never runs. Without it this row reads FALSE.
    assert_eq!(
        with_null[3], null,
        "a null needle over an EMPTY list is still UNKNOWN"
    );
}

/// `IN` over a list property of an UNMATCHED `OPTIONAL MATCH` node. The slot holds the
/// `u32::MAX` sentinel, and `store.prop_ref(u32::MAX, …)` would index the column at
/// 4,294,967,295 — a PANIC. The fused path's pre-scan excludes it, and mutation showed that
/// guard untested for `IN`: removing the whole pre-scan SURVIVED, because its list half is
/// answer-equivalent (a non-list reads NULL either way) and nothing exercised the sentinel.
#[test]
fn fused_in_over_an_unmatched_optional_node_is_null() {
    let mut b = Builder::default();
    b.node(&["N"], &[("v", Value::List(vec![n(1.0), n(2.0)]))]);
    let store = b.build();

    let plan = opt_plan(
        "MATCH (a:N) OPTIONAL MATCH (x:Nope) RETURN 1 IN x.v AS got, 1 IN a.v AS anchor",
        &store,
    );
    let got = crate::exec::pull(&plan, &store, false).expect("the optional miss must not panic");

    assert_eq!(got.rows(), 1);

    let cells: Vec<String> = (0..got.slots.len())
        .map(|c| format!("{:?}", got.slot(c).value_at(0)))
        .collect();

    // The unmatched side is NULL; the matched side still finds its element — which is what says
    // the sentinel row was routed away WITHOUT disabling the path for everyone.
    assert!(
        cells.contains(&format!("{:?}", Value::Null)),
        "the optional miss must be NULL: {cells:?}"
    );
    assert!(
        cells.contains(&format!("{:?}", Value::Bool(true))),
        "the matched node must still match: {cells:?}"
    );
}

/// An UNMATCHED `OPTIONAL MATCH` leaves the node slot holding the `u32::MAX` null sentinel, and
/// `store.prop_ref(u32::MAX, …)` would index the column at 4,294,967,295 — an out-of-bounds
/// PANIC, not a wrong answer. The fused path's `id != u32::MAX` test is what keeps that row off
/// it, and mutation found the guard UNTESTED: removing it SURVIVED the whole suite because
/// nothing put a sentinel in the slot and then indexed a list property.
#[test]
fn indexing_a_list_property_of_an_unmatched_optional_node_is_null() {
    let mut b = Builder::default();
    b.node(&["N"], &[("v", Value::List(vec![n(1.0), n(2.0)]))]);
    let store = b.build();

    // `:Nope` matches nothing, so `x` is the sentinel on every row.
    let plan = opt_plan(
        "MATCH (a:N) OPTIONAL MATCH (x:Nope) RETURN x.v[0] AS got, a.v[0] AS anchor",
        &store,
    );
    let got = crate::exec::pull(&plan, &store, false).expect("the optional miss must not panic");

    assert_eq!(got.rows(), 1);

    let cells: Vec<String> = (0..got.slots.len())
        .map(|c| format!("{:?}", got.slot(c).value_at(0)))
        .collect();

    // The unmatched side is NULL; the matched side still reads its element, which is what says
    // the sentinel row was routed away WITHOUT disabling the path for everyone.
    assert!(
        cells.contains(&format!("{:?}", Value::Null)),
        "the optional miss must be NULL: {cells:?}"
    );
    assert!(
        cells.contains(&format!("{:?}", n(1.0))),
        "the matched node must still index: {cells:?}"
    );
}

#[test]
fn indexing_an_all_list_column_takes_the_fused_path_and_still_agrees() {
    // The pre-scan ADMITS this column, so this is the fast path proper. Ragged lengths, so an
    // off-by-one in the bounds test shows up as a wrong value rather than the same value.
    let mut b = Builder::default();
    b.node(&["N"], &[("v", Value::List(vec![n(1.0), n(2.0), n(3.0)]))]);
    b.node(&["N"], &[("v", Value::List(vec![n(4.0)]))]);
    b.node(&["N"], &[("v", Value::List(vec![n(5.0), n(6.0)]))]);
    let store = b.build();

    let at = |i: f64| -> Vec<String> {
        let plan = Plan::Project {
            input: Box::new(Plan::Scan { label: None }),
            items: vec![(
                "x".to_string(),
                Expr::Index {
                    base: Box::new(prop(0, "v")),
                    index: Box::new(lit(n(i))),
                    elem: crate::ir::ElemKind::Plain,
                },
            )],
        };
        let got = crate::exec::pull(&plan, &store, false).expect("plan runs");
        let col = got.slot(0);

        (0..got.rows())
            .map(|k| format!("{:?}", col.value_at(k)))
            .collect()
    };

    let null = format!("{:?}", Value::Null);

    assert_eq!(
        at(0.0),
        vec![
            format!("{:?}", n(1.0)),
            format!("{:?}", n(4.0)),
            format!("{:?}", n(5.0))
        ]
    );
    // Row 1 has ONE element, so index 1 is out of range for it alone.
    assert_eq!(
        at(1.0),
        vec![
            format!("{:?}", n(2.0)),
            null.clone(),
            format!("{:?}", n(6.0))
        ]
    );
    // Only row 0 reaches index 2.
    assert_eq!(
        at(2.0),
        vec![format!("{:?}", n(3.0)), null.clone(), null.clone()]
    );

    // THE BAD INDICES BELONG HERE, not only on the mixed fixture. Mutation found that gap: the
    // mixed column makes the pre-scan DECLINE, so its out-of-range / negative / non-integer
    // assertions exercise the GENERAL arm and said nothing about the fused one. Dropping the
    // integer check SURVIVED until these were added — `0.5 as usize` is 0, so it would have
    // returned element 0 for a fractional index.
    for bad in [3.0, -1.0, 0.5, f64::NAN] {
        assert_eq!(
            at(bad),
            vec![null.clone(), null.clone(), null.clone()],
            "index {bad} must be NULL on every row"
        );
    }
}

/// What does `element_id(x) = '<lit>'` cost per row, against reading a typed PROPERTY over the
/// same frontier? Item 619 priced this end-to-end at 2,274 us native / 28,888 us TS for an edge
/// walk, against 196 / 2,449 for `r.w = $w` — so `element_id` is ~12x the comparison it feeds,
/// in BOTH engines. `opt::id_seek_target`'s header names that as half (2) of 619 and records it
/// unbuilt.
///
/// This isolates the per-row half of it. `Expr::Call`'s `element_id` arm clones a `GStr` and
/// boxes a `Value::Str` PER ROW; the property comparison reads a typed column and allocates
/// nothing.
///
/// TWO CONTROLS, neither reachable by a change to the `element_id` arm:
/// - `x.w = <miss>` — a typed-column compare over the identical frontier and plan shape.
/// - `WHERE true` — the Filter floor itself (item 570: this is THE control for "why is the
///   filtered version slower").
///
/// The ext ids are the ones `Builder::build` mints — `"0"`, `"1"`, ... for nodes and `"e0"`,
/// `"e1"`, ... for edges. That matters: CLAUDE.md's "give edges ids" trap is that a fixture
/// WITHOUT them skips the external-id path entirely and prices nothing.
#[test]
#[ignore = "timing harness"]
fn element_id_cost_by_frontier() {
    use std::time::Instant;
    const REPS: u32 = 9;
    const NODES: usize = 100_000;

    let mut b = Builder::default();
    for i in 0..NODES {
        b.node(
            &["N"],
            &[
                ("w", n(i as f64)),
                // Unique per row ON PURPOSE: a dict column would be computed per distinct
                // value and the positive control would stop being expensive.
                ("s", Value::Str(format!("s{i}").as_str().into())),
            ],
        );
    }
    // One edge per node, so the edge frontier is the same width as the node frontier and the
    // two blocks below are comparable.
    for i in 0..NODES as u32 {
        b.edge(i, (i + 1) % NODES as u32, "R");
    }
    let store = b.build();

    let eid = |slot: u32| Expr::Call {
        name: "element_id".to_string(),
        args: vec![Expr::Slot(slot as usize)],
    };
    let eq = |l: Expr, r: Expr| Expr::Compare {
        op: CompareOp::Eq,
        left: Box::new(l),
        right: Box::new(r),
    };
    let s = |t: &str| lit(Value::Str(t.into()));

    println!(
        "{:<52}{:>10}{:>10}{:>9}",
        "case", "total us", "ns/row", "rows"
    );

    // NODE frontier: a bare scan binds the node in slot 0.
    let node_cases: Vec<(&str, Expr)> = vec![
        ("node  element_id(n) = MISS", eq(eid(0), s("nope"))),
        ("node  element_id(n) = HIT (one row)", eq(eid(0), s("7"))),
        (
            "node  element_id(n) REVERSED operand order",
            eq(s("nope"), eid(0)),
        ),
        (
            "node  CONTROL n.w = miss (typed column)",
            eq(prop(0, "w"), lit(n(-1.0))),
        ),
        (
            "node  CONTROL true (the Filter floor)",
            lit(Value::Bool(true)),
        ),
        // POSITIVE CONTROL: a predicate KNOWN to be expensive per row. If this reads the same
        // as the floor, the harness is measuring itself and no row above means anything.
        (
            "node  POSITIVE CONTROL upper(n.s) = miss",
            eq(
                Expr::Call {
                    name: "upper".to_string(),
                    args: vec![prop(0, "s")],
                },
                s("nope"),
            ),
        ),
    ];

    for (name, pred) in node_cases {
        let plan = Plan::Filter {
            input: Box::new(Plan::Scan { label: None }),
            pred,
        };
        let mut best = u128::MAX;
        let mut rows = usize::MAX;
        for _ in 0..REPS {
            let t0 = Instant::now();
            let got = crate::exec::pull(&plan, &store, false).expect("plan runs");
            best = best.min(t0.elapsed().as_nanos());
            rows = got.rows();
        }
        // PRINTED, not assumed: a row count of 0 everywhere would mean the predicate never ran.
        println!(
            "{:<52}{:>10.1}{:>10.2}{:>9}",
            name,
            best as f64 / 1000.0,
            best as f64 / NODES as f64,
            rows
        );
    }

    // ITEM 619's ACTUAL FIXTURE: a GQL EDGE walk end to end, not a hand-built node filter. The
    // block above shows no gap at all on a node frontier, but 619 measured
    // `MATCH ()-[r:R]->() WHERE element_id(r) = $x`, so that is what has to be reproduced
    // before its 12x is either confirmed or retracted.
    //
    // The FLOOR here is the walk with NO predicate: it isolates the expand, which both the
    // subject and the control pay in full. `Builder::edge` takes no properties, so 619's exact
    // `r.w = $w` control is not expressible on this fixture; the node-property predicate over
    // the same walk stands in for it, and the floor carries the comparison.
    println!();
    let gql_cases: &[(&str, &str)] = &[
        (
            "edge  FLOOR: the walk alone, no predicate",
            "MATCH ()-[r:R]->() RETURN count(*) AS c",
        ),
        (
            "edge  element_id(r) = MISS",
            "MATCH ()-[r:R]->() WHERE element_id(r) = 'nope' RETURN count(*) AS c",
        ),
        (
            "edge  element_id(r) = HIT (one edge)",
            "MATCH ()-[r:R]->() WHERE element_id(r) = 'e7' RETURN count(*) AS c",
        ),
        (
            "edge  CONTROL a.w = miss (typed node column)",
            "MATCH (a)-[r:R]->() WHERE a.w = -1.0 RETURN count(*) AS c",
        ),
        (
            "node  element_id(a) = MISS via GQL",
            "MATCH (a:N) WHERE element_id(a) = 'nope' RETURN count(*) AS c",
        ),
        // THE DECISIVE PAIR for half (2). Both of these are the FAR side of a hop, the one
        // shape 619 says cannot be seeded ("the predicate reads a slot the `Scan` does not
        // produce, so it stays a filter"). So both pay the full walk and differ only in the
        // predicate — which is exactly the `element_id` vs property comparison 619 made, with
        // the seed no longer able to mask it.
        (
            "far   element_id(b) = MISS after a hop (a FILTER)",
            "MATCH (a)-[r:R]->(b) WHERE element_id(b) = 'nope' RETURN count(*) AS c",
        ),
        (
            "far   CONTROL b.w = miss after a hop (a FILTER)",
            "MATCH (a)-[r:R]->(b) WHERE b.w = -1.0 RETURN count(*) AS c",
        ),
        // THE "BEFORE" NUMBER, without un-building anything. `try_filter_keep_element_id`
        // declines every operator but `Eq`/`Ne` (an ORDERING comparison on an id is a string
        // ordering under the value contract's total order, which that pass does not
        // reproduce). So a `>` on the same expression routes to the GENERAL path and prices
        // the per-row `GStr` clone + `Value::Str` box that item 619 named.
        (
            "far   element_id(b) > lit — DECLINES the keep-pass",
            "MATCH (a)-[r:R]->(b) WHERE element_id(b) > 'zzz' RETURN count(*) AS c",
        ),
        (
            "far   CONTROL b.s > lit (a string column, general too)",
            "MATCH (a)-[r:R]->(b) WHERE b.s > 'zzz' RETURN count(*) AS c",
        ),
    ];

    for (name, q) in gql_cases {
        let plan = opt_plan(q, &store);
        // VERIFY THE PLANNER REACHES THE SHAPE, rather than inferring it from the time: a
        // seeded plan and a walk that happens to be cheap are not distinguishable by duration.
        let shape = format!("{plan:?}");
        let seeded = shape.contains("EdgeSeed") || shape.contains("Seed");
        let mut best = u128::MAX;
        for _ in 0..REPS {
            let t0 = Instant::now();
            let got = crate::exec::pull(&plan, &store, false).expect("plan runs");
            best = best.min(t0.elapsed().as_nanos());
            std::hint::black_box(got.rows());
        }
        println!(
            "{:<52}{:>10.1}{:>10.2}{:>9}",
            name,
            best as f64 / 1000.0,
            best as f64 / NODES as f64,
            if seeded { "SEEDED" } else { "walk" }
        );
    }

    // LONG EXT IDS — the one remaining way half (2) could be real. `GStr` is a 16-byte German
    // string with a 12-byte INLINE capacity, so `Builder`'s minted `"e0"` / `"7"` ids are
    // copied by value and their `clone` allocates nothing. Past the cap the bytes live in a
    // refcounted block and `clone` becomes an atomic increment plus a matching decrement on
    // drop — which is the only version of "cloning a GStr" that could cost anything per row.
    //
    // 36 chars, UUID length. `from_ndjson` is the only way to set ext ids explicitly; the test
    // `Builder` mints its own and cannot express this.
    println!();
    let mut nd = String::new();
    const LONG: usize = 20_000;
    for i in 0..LONG {
        nd.push_str(&format!(
            "{{\"id\":\"{:036}\",\"labels\":[\"N\"],\"props\":{{\"w\":{i}}}}}\n",
            i
        ));
    }
    for i in 0..LONG {
        nd.push_str(&format!(
            "{{\"id\":\"e{:035}\",\"from\":\"{:036}\",\"to\":\"{:036}\",\"type\":\"R\",\"props\":{{}}}}\n",
            i,
            i,
            (i + 1) % LONG
        ));
    }
    let long_store = crate::ndjson::from_ndjson(&nd).expect("ndjson loads");

    let long_cases: &[(&str, &str)] = &[
        (
            "long  FLOOR: the walk alone",
            "MATCH (a)-[r:R]->(b) RETURN count(*) AS c",
        ),
        (
            "long  element_id(b) after a hop (heap-backed GStr)",
            "MATCH (a)-[r:R]->(b) WHERE element_id(b) = 'nope' RETURN count(*) AS c",
        ),
        (
            "long  CONTROL b.w = miss after a hop",
            "MATCH (a)-[r:R]->(b) WHERE b.w = -1.0 RETURN count(*) AS c",
        ),
    ];

    for (name, q) in long_cases {
        let plan = opt_plan(q, &long_store);
        let mut best = u128::MAX;
        for _ in 0..REPS {
            let t0 = Instant::now();
            let got = crate::exec::pull(&plan, &long_store, false).expect("plan runs");
            best = best.min(t0.elapsed().as_nanos());
            std::hint::black_box(got.rows());
        }
        println!(
            "{:<52}{:>10.1}{:>10.2}",
            name,
            best as f64 / 1000.0,
            best as f64 / LONG as f64
        );
    }
}

/// What does `<needle> IN <a list PROPERTY>` cost, and how much of it is the per-row CLONE?
///
/// `Expr::In` is the fourth site of the `value_at`-deep-copies-a-list pattern item 640 found:
/// `hs.value_at(i)` clones the WHOLE haystack to scan it. Unlike `Expr::Index` (item 641,
/// where borrowing REGRESSED 2.25x in the middle of a length sweep) this site needs every
/// element anyway, so a borrow would remove a copy without changing the work — which is the
/// shape that DID hold for `unwind_rows`.
///
/// Prediction, to be refuted or not: cost rises with haystack LENGTH faster than the scan
/// itself requires, and the excess is the copy.
///
/// Two controls:
///   missing   — a needle that is in NO list, so the scan always runs to the end. The length
///               term is then the same for both and only the copy differs.
///   first     — a needle at index 0, where the scan exits immediately but the COPY is still
///               the whole list. If the copy is the cost, `first` tracks `missing`; if the scan
///               is, `first` stays flat as length grows.
#[test]
#[ignore = "measurement harness: cargo test --release -- --ignored --nocapture in_cost_by_list_length"]
fn in_cost_by_list_length() {
    use std::time::Instant;
    const REPS: u32 = 7;
    const ROWS: usize = 100_000;

    println!("{:<44}{:>10}{:>10}", "case", "total us", "ns/row");

    for len in [1usize, 8, 64] {
        let mut b = Builder::default();
        let items: Vec<Value> = (0..len).map(|j| n(j as f64)).collect();

        for _ in 0..ROWS {
            b.node(&["N"], &[("tags", Value::List(items.clone()))]);
        }

        let store = b.build();
        let scan = || Plan::Scan { label: None };
        let in_tags = |needle: f64| Expr::In {
            needle: Box::new(lit(n(needle))),
            haystack: Box::new(prop(0, "tags")),
        };

        // `missing` is -1 (in no list); `first` is 0 (index 0 of every list).
        let cases: Vec<(&str, Expr)> = vec![
            ("IN, needle MISSING (full scan)", in_tags(-1.0)),
            ("IN, needle FIRST (scan exits at 0)", in_tags(0.0)),
        ];

        for (name, pred) in cases {
            let plan = Plan::Filter {
                input: Box::new(scan()),
                pred,
            };
            let mut best = u128::MAX;

            for _ in 0..REPS {
                let t0 = Instant::now();
                let got = crate::exec::pull(&plan, &store, false).expect("plan runs");
                best = best.min(t0.elapsed().as_nanos());
                // A missing needle keeps nothing; a present one keeps every row.
                assert!(got.rows() == 0 || got.rows() == ROWS, "rows {}", got.rows());
            }

            println!(
                "{:<44}{:>10.1}{:>10.2}",
                format!("len {len:>3}  {name}"),
                best as f64 / 1000.0,
                best as f64 / ROWS as f64
            );
        }
    }
}

/// What does reading ONE element of a list property cost, and does it scale with the list's
/// LENGTH? `Expr::Index` is the worst of the four `value_at`-deep-copies-a-list sites item 640
/// found: `bcol.value_at(i)` clones the WHOLE list to return a single element, so an O(1) read
/// should be doing O(len) work.
///
/// That is a prediction, and this is the harness that can refute it. `PathRecord` evaluates
/// its `value` once per row and is otherwise nearly free (0.63 ns/row in
/// `plan_cost_by_operator`), so the difference between indexing and a plain property read is
/// the index itself.
///
/// The CONTROL is a plain `Prop` read on the same node at the same length — it reads one
/// property and cannot touch the list, so a cost that rises with length on the index row while
/// the control stays flat is the clone. If BOTH rise, the fixture is the thing scaling and the
/// prediction is wrong.
#[test]
#[ignore = "measurement harness: cargo test --release -- --ignored --nocapture index_cost_by_list_length"]
fn index_cost_by_list_length() {
    use std::time::Instant;
    const REPS: u32 = 7;
    const ROWS: usize = 100_000;

    println!("{:<40}{:>10}{:>10}", "case", "total us", "ns/row");

    for len in [1usize, 8, 64] {
        let mut b = Builder::default();
        let items: Vec<Value> = (0..len).map(|j| n(j as f64)).collect();

        for _ in 0..ROWS {
            b.node(
                &["N"],
                &[("tags", Value::List(items.clone())), ("k", n(1.0))],
            );
        }

        let store = b.build();
        let scan = || Plan::Scan { label: None };

        let cases: Vec<(&str, Expr)> = vec![
            (
                "index [0] of the list",
                Expr::Index {
                    base: Box::new(prop(0, "tags")),
                    index: Box::new(lit(n(0.0))),
                    elem: crate::ir::ElemKind::Plain,
                },
            ),
            // The control: one property read on the same node, untouched by the list.
            ("plain prop read (control)", prop(0, "k")),
        ];

        for (name, value) in cases {
            // GROUP BY the expression, NOT `PathRecord`. The first version of this harness used
            // `PathRecord` and read 0.63 ns/row for BOTH the index and the control — exactly
            // `PathRecord`'s own floor in `plan_cost_by_operator`, because it does not evaluate
            // its `value` eagerly. A plain property read cannot cost 0.63 ns when
            // `Aggregate GROUP BY num` costs 6 ns/row INCLUDING the grouping, and the control
            // matching the subject to two decimal places is what gave it away.
            //
            // Aggregate's key IS evaluated per row, and the operator table already prices it,
            // so the grouping overhead is known and common to both rows here.
            let plan = Plan::Aggregate {
                input: Box::new(scan()),
                keys: vec![("g".to_string(), value)],
                aggs: vec![crate::ir::Agg {
                    func: AggFn::Count,
                    arg: None,
                    distinct: false,
                    name: "c".into(),
                    frac: None,
                    null_on_empty: false,
                    numeric_only: false,
                }],
            };
            let mut best = u128::MAX;

            for _ in 0..REPS {
                let t0 = Instant::now();
                let got = crate::exec::pull(&plan, &store, false).expect("plan runs");
                best = best.min(t0.elapsed().as_nanos());
                assert_eq!(got.rows(), 1, "every row shares one key");
            }

            println!(
                "{:<40}{:>10.1}{:>10.2}",
                format!("len {len:>3}  {name}"),
                best as f64 / 1000.0,
                best as f64 / ROWS as f64
            );
        }
    }
}

/// What does `UNWIND <a list PROPERTY>` cost, and how much of it is the per-row CLONE?
///
/// `plan_cost_by_operator` prices `Unwind` over a literal list, where item 640's slope showed
/// two separable costs: ~21 ns per property read inside the list, and a FIXED ~27 ns/row for
/// any non-constant list, independent of item count. The fixed part is the interesting one —
/// `unwind_rows` evaluates the list into a `Value::List` per row and then `value_at(i)` hands
/// it back OWNED, so the `Vec<Value>` is built once and cloned once per row.
///
/// Over a 2-element literal that is two numbers copied. Over a STORED LIST PROPERTY it is the
/// whole list, so the cost should scale with its LENGTH — which the literal fixture cannot
/// show, because its length and its item count are the same knob.
///
/// So this sweeps the length with the ROW COUNT and the OUTPUT row count both held fixed:
/// 200,000 output rows in every row of the table, from `ROWS / len` input rows each carrying
/// a list of `len`. A per-row clone shows as a cost that RISES with length even though the
/// work per output row is identical; a cost that is flat refutes the clone as the mechanism.
///
/// The CONSTANT-list column is the control the clone cannot reach: `unwind_rows` evaluates an
/// invariant list once, so that column should stay flat whatever the length does.
#[test]
#[ignore = "measurement harness: cargo test --release -- --ignored --nocapture unwind_cost_by_list_length"]
fn unwind_cost_by_list_length() {
    use std::time::Instant;
    const REPS: u32 = 7;
    const OUT: usize = 200_000;

    println!(
        "{:<34}{:>10}{:>10}{:>10}",
        "case", "total us", "ns/out", "rows"
    );

    for len in [1usize, 4, 16, 64] {
        let rows = OUT / len;
        let mut b = Builder::default();
        let items: Vec<Value> = (0..len).map(|j| n(j as f64)).collect();

        for _ in 0..rows {
            b.node(&["N"], &[("tags", Value::List(items.clone()))]);
        }

        let store = b.build();
        let scan = || Plan::Scan { label: None };

        let cases: Vec<(&str, Plan)> = vec![
            (
                "property list",
                Plan::Unwind {
                    input: Box::new(scan()),
                    list: Box::new(Expr::Prop {
                        slot: 0,
                        key: "tags".to_string(),
                    }),
                    var_slot: 1,
                    ordinal: None,
                },
            ),
            (
                // The control: an invariant list takes `unwind_rows`'s evaluate-once path, so
                // nothing here is cloned per row and the length must not matter.
                "CONSTANT list (control)",
                Plan::Unwind {
                    input: Box::new(scan()),
                    list: Box::new(Expr::List {
                        items: items.iter().cloned().map(Expr::Lit).collect(),
                    }),
                    var_slot: 1,
                    ordinal: None,
                },
            ),
        ];

        for (name, plan) in cases {
            let mut best = u128::MAX;
            let mut out_rows = 0;

            for _ in 0..REPS {
                let t0 = Instant::now();
                let got = crate::exec::pull(&plan, &store, false).expect("plan runs");
                best = best.min(t0.elapsed().as_nanos());
                out_rows = got.rows();
            }

            println!(
                "{:<34}{:>10.1}{:>10.2}{:>10}",
                format!("len {len:>3}  {name}"),
                best as f64 / 1000.0,
                best as f64 / out_rows as f64,
                out_rows
            );
        }
    }
}

#[test]
#[ignore = "measurement harness: cargo test --release -- --ignored --nocapture plan_cost_by_operator"]
fn plan_cost_by_operator() {
    use crate::ir::{CombineOp, SortKey};
    use std::time::Instant;
    const REPS: u32 = 7;
    const ROWS: u32 = 200_000;

    let mut b = Builder::default();
    for i in 0..ROWS {
        b.node(
            &[if i % 3 == 0 { "N" } else { "M" }],
            &[
                ("num", n(f64::from(i % 1000))),
                ("name", s(&format!("v{i}"))),
            ],
        );
    }
    // One edge per node, so a hop is 1:1 and its cost is per row rather than per fan-out.
    for i in 0..ROWS {
        b.edge(i, (i * 7 + 1) % ROWS, "R");
    }
    let store = b.build();

    let scan = || Plan::Scan { label: None };
    let num = || Expr::Prop {
        slot: 0,
        key: "num".to_string(),
    };
    let name = || Expr::Prop {
        slot: 0,
        key: "name".to_string(),
    };
    let hop = || Plan::Expand {
        input: Box::new(scan()),
        from: 0,
        dir: Dir::Out,
        edge_label: vec!["R".to_string()],
        bind_edge: false,
        double_loops: false,
    };

    let cases: Vec<(&str, Plan)> = vec![
        ("Scan (the floor)", scan()),
        (
            "Filter (typed compare)",
            Plan::Filter {
                input: Box::new(scan()),
                pred: Expr::Compare {
                    op: CompareOp::Lt,
                    left: Box::new(num()),
                    right: Box::new(Expr::Lit(Value::Num(500.0))),
                },
            },
        ),
        (
            "Project (1 scalar)",
            Plan::Project {
                input: Box::new(scan()),
                items: vec![("a".to_string(), num())],
            },
        ),
        (
            "Project (3 scalars)",
            Plan::Project {
                input: Box::new(scan()),
                items: vec![
                    ("a".to_string(), num()),
                    ("b".to_string(), name()),
                    ("c".to_string(), Expr::Slot(0)),
                ],
            },
        ),
        (
            "MapSlot",
            Plan::MapSlot {
                input: Box::new(scan()),
                slot: 0,
                value: Box::new(num()),
                append: false,
            },
        ),
        (
            "Distinct (whole row)",
            Plan::Distinct {
                input: Box::new(scan()),
            },
        ),
        (
            "DistinctBy (slot 0)",
            Plan::DistinctBy {
                input: Box::new(scan()),
                key_slots: vec![0],
            },
        ),
        (
            "Enumerate",
            Plan::Enumerate {
                input: Box::new(scan()),
                slot: 0,
            },
        ),
        (
            "Sample (n = ROWS)",
            Plan::Sample {
                input: Box::new(scan()),
                n: ROWS as usize,
            },
        ),
        (
            "Tail (n = ROWS)",
            Plan::Tail {
                input: Box::new(scan()),
                n: ROWS as usize,
            },
        ),
        (
            "NullPadIfEmpty",
            Plan::NullPadIfEmpty {
                input: Box::new(scan()),
                width: 1,
            },
        ),
        (
            "OrderPage (by num)",
            Plan::OrderPage {
                input: Box::new(scan()),
                keys: vec![SortKey {
                    expr: num(),
                    descending: false,
                    nulls_first: false,
                }],
                skip: None,
                limit: None,
                fault_on_element: false,
            },
        ),
        (
            // The COMPOSITE key, which has no typed path: `sort_idx` fast-paths a single
            // `Col::Num` and a single `Col::Str` and falls to `row_cmp` for everything else,
            // which boxes a `Value` per column PER COMPARISON. Priced against the single-key
            // row above it, which is the same sort over the same rows.
            "OrderPage (by num, name)",
            Plan::OrderPage {
                input: Box::new(scan()),
                keys: vec![
                    SortKey {
                        expr: num(),
                        descending: false,
                        nulls_first: false,
                    },
                    SortKey {
                        expr: name(),
                        descending: false,
                        nulls_first: false,
                    },
                ],
                skip: None,
                limit: None,
                fault_on_element: false,
            },
        ),
        (
            "OrderPage (by name, STR)",
            Plan::OrderPage {
                input: Box::new(scan()),
                keys: vec![SortKey {
                    expr: name(),
                    descending: false,
                    nulls_first: false,
                }],
                skip: None,
                limit: None,
                fault_on_element: false,
            },
        ),
        (
            "OrderPage (by num, LIMIT 10)",
            Plan::OrderPage {
                input: Box::new(scan()),
                keys: vec![SortKey {
                    expr: num(),
                    descending: false,
                    nulls_first: false,
                }],
                skip: None,
                limit: Some(10),
                fault_on_element: false,
            },
        ),
        ("Expand (1:1 hop)", hop()),
        (
            "Expand then EdgeVertex",
            Plan::EdgeVertex {
                input: Box::new(Plan::Expand {
                    input: Box::new(scan()),
                    from: 0,
                    dir: Dir::Out,
                    edge_label: vec!["R".to_string()],
                    bind_edge: true,
                    double_loops: false,
                }),
                edge_slot: 1,
                which: Dir::In,
                other: false,
            },
        ),
        (
            "Aggregate count(*)",
            Plan::Aggregate {
                input: Box::new(scan()),
                keys: vec![],
                aggs: vec![crate::ir::Agg {
                    func: AggFn::Count,
                    arg: None,
                    distinct: false,
                    name: "c".into(),
                    frac: None,
                    null_on_empty: false,
                    numeric_only: false,
                }],
            },
        ),
        (
            "Aggregate GROUP BY num",
            Plan::Aggregate {
                input: Box::new(scan()),
                keys: vec![("k".to_string(), num())],
                aggs: vec![crate::ir::Agg {
                    func: AggFn::Count,
                    arg: None,
                    distinct: false,
                    name: "c".into(),
                    frac: None,
                    null_on_empty: false,
                    numeric_only: false,
                }],
            },
        ),
        (
            "Union ALL (scan, scan)",
            Plan::Union {
                left: Box::new(scan()),
                right: Box::new(scan()),
                all: true,
                op: CombineOp::Union,
            },
        ),
        (
            "Join on slot 0",
            Plan::Join {
                left: Box::new(scan()),
                right: Box::new(scan()),
                on: vec![(0, 0)],
            },
        ),
        // --- operators the first version of this harness did not price ---
        //
        // It covered 19 of `Plan`'s 54 variants, and an unpriced operator is where a missing
        // path is likelier than in one already tuned. These are the ones constructible over
        // this fixture; the rest need a temporal column, a lineage, a Gremlin branch frontier
        // or a subquery body, and pricing them needs their own fixtures.
        ("EdgeScan (every edge)", Plan::EdgeScan),
        (
            "OptionalExpand (1:1, GQL null)",
            Plan::OptionalExpand {
                input: Box::new(scan()),
                from: 0,
                dir: Dir::Out,
                edge_label: vec!["R".to_string()],
                keep_source: false,
                bind_edge: false,
                landing_pred: None,
            },
        ),
        (
            // `keep_source: true` is produced by NO query today — GQL `OPTIONAL MATCH` always
            // sets `false`, and Gremlin's `optional()` lowers to the branch machinery rather
            // than this operator (both verified). Priced anyway because the two arms share the
            // loop, so a divergence between them would show here.
            "OptionalExpand (passthru, unreachable)",
            Plan::OptionalExpand {
                input: Box::new(scan()),
                from: 0,
                dir: Dir::Out,
                edge_label: vec!["R".to_string()],
                keep_source: true,
                bind_edge: false,
                landing_pred: None,
            },
        ),
        // `OptionalScan` is NOT here. It is a LEFT-OUTER correlated node scan, so over this
        // fixture it is 200,000 input rows times every matching node — about 13 billion rows,
        // which is not a per-row cost but a cross-product. Pricing it needs its own small
        // fixture and its own row count; measuring it here would measure the fan-out.
        //
        // (Learned the direct way: the first version of this list included it and the harness
        // had to be killed. A NEW harness case is an unbounded run until proven otherwise, so
        // this whole test now gets the same `timeout` + cgroup cap a mutation run gets.)
        (
            // A REFERENCE POINT, not a target: `{1,1}` and `{1}` both flatten to an
            // `Expand` in the optimizer (verified), so no query reaches the walker with these
            // bounds. What it prices is the walker's own per-row cost for one hop — useful for
            // judging a var-length row, useless as something to fix.
            "VarLength {1,1} (walker, unreachable)",
            Plan::VarLength {
                input: Box::new(scan()),
                from: 0,
                dir: Dir::Out,
                edge_label: vec!["R".to_string()],
                min: 1,
                max: 1,
                mode: PathMode::Walk,
                until: None,
                body_filter: None,
                double_loops: false,
                path_need: crate::ir::PathNeed::CountOnly,
            },
        ),
        (
            "PathRecord",
            Plan::PathRecord {
                input: Box::new(scan()),
                value: num(),
                tag: 0,
            },
        ),
        (
            "SortLocal (scalar slot)",
            Plan::SortLocal {
                input: Box::new(scan()),
                descending: false,
                by_key: false,
            },
        ),
        (
            // The ROW-INVARIANT spelling, which is the common one: `UNWIND $ids AS id` and
            // `UNWIND [1, 2] AS x` build the same list for every row, while the row below
            // reads a property and genuinely varies.
            "Unwind (2-element CONSTANT list)",
            Plan::Unwind {
                input: Box::new(scan()),
                list: Box::new(Expr::List {
                    items: vec![Expr::Lit(Value::Num(1.0)), Expr::Lit(Value::Num(2.0))],
                }),
                var_slot: 1,
                ordinal: None,
            },
        ),
        (
            "Unwind (2-element list)",
            Plan::Unwind {
                input: Box::new(scan()),
                list: Box::new(Expr::List {
                    items: vec![num(), num()],
                }),
                var_slot: 1,
                ordinal: None,
            },
        ),
        // THE SLOPE PAIR. The two rows above differ by 13.7x, but they differ in TWO ways at
        // once — the constant one reads no property and emits the same list every row — so the
        // ratio prices nothing on its own. These give the per-ITEM cost as a difference at a
        // fixed row count: 2-element minus 1-element, on each side, is one list item.
        //
        // Added because `Aggregate GROUP BY num` reads a property at 6.08 ns/row INCLUDING the
        // grouping, while the 2-element varying list appeared to pay ~34 ns per read. Either
        // the list path is genuinely slower per read or those two numbers are not comparable,
        // and a slope says which without guessing.
        (
            "Unwind (1-element CONSTANT list)",
            Plan::Unwind {
                input: Box::new(scan()),
                list: Box::new(Expr::List {
                    items: vec![Expr::Lit(Value::Num(1.0))],
                }),
                var_slot: 1,
                ordinal: None,
            },
        ),
        (
            "Unwind (1-element list)",
            Plan::Unwind {
                input: Box::new(scan()),
                list: Box::new(Expr::List { items: vec![num()] }),
                var_slot: 1,
                ordinal: None,
            },
        ),
        (
            "GroupToMap (over a grouped agg)",
            Plan::GroupToMap {
                input: Box::new(Plan::Aggregate {
                    input: Box::new(scan()),
                    keys: vec![("k".to_string(), num())],
                    aggs: vec![crate::ir::Agg {
                        func: AggFn::Count,
                        arg: None,
                        distinct: false,
                        name: "c".into(),
                        frac: None,
                        null_on_empty: false,
                        numeric_only: false,
                    }],
                }),
            },
        ),
        (
            "Tree",
            Plan::Tree {
                input: Box::new(scan()),
                by: None,
                leaf_value: None,
            },
        ),
    ];

    println!("\n=== plan operator cost, {ROWS} rows ===");
    println!(
        "{:<30} {:>10} {:>10} {:>8} {:>9}",
        "operator", "total_us", "ns/row", "xScan", "rows"
    );
    let mut base = 0.0f64;
    for (label, plan) in &cases {
        let mut lo = f64::MAX;
        let mut rows = 0usize;
        for _ in 0..REPS {
            let t = Instant::now();
            let got = crate::exec::pull(plan, &store, false);
            lo = lo.min(t.elapsed().as_secs_f64() * 1e6);
            rows = got.as_ref().map(crate::batch::Batch::rows).unwrap_or(0);
            assert!(got.is_ok(), "{label} must pull: {got:?}");
        }
        let per_row = lo * 1000.0 / f64::from(ROWS);
        if *label == "Scan (the floor)" {
            base = per_row;
        }
        println!(
            "{label:<30} {lo:>10.1} {per_row:>10.2} {:>8.1} {rows:>9}",
            if base > 0.0 { per_row / base } else { 0.0 }
        );
    }
}

/// What the in-place key comparison is WORTH, measured against the boxed path it replaced in
/// the SAME process (item 627).
///
/// ```text
/// cargo test --release --manifest-path crates/lenke-engine/Cargo.toml \
///   -- --ignored --nocapture sort_key_cost_in_place_vs_boxed
/// ```
///
/// A worktree A/B cannot do this honestly here: the pre-change build does not have these
/// cases in its harness, so the two processes would run different case lists and the rows
/// would carry each other's cache and thermal state. `FORCE_BOXED_CMP` makes both paths
/// reachable in one binary, so the only difference between the two columns is the comparator.
/// Rounds ALTERNATE and each column keeps its minimum.
#[test]
#[ignore = "measurement harness: cargo test --release -- --ignored --nocapture sort_key_cost_in_place_vs_boxed"]
fn sort_key_cost_in_place_vs_boxed() {
    use crate::exec::order::FORCE_BOXED_CMP;
    use crate::ir::SortKey;
    use std::time::Instant;
    const ROWS: u32 = 200_000;
    const ROUNDS: u32 = 3;

    let mut b = Builder::default();
    for i in 0..ROWS {
        b.node(
            &["N"],
            &[
                ("num", n(f64::from(i % 1000))),
                ("name", s(&format!("v{i}"))),
                ("grp", n(f64::from(i % 7))),
            ],
        );
    }
    let store = b.build();

    let key = |k: &str| SortKey {
        expr: Expr::Prop {
            slot: 0,
            key: k.to_string(),
        },
        descending: false,
        nulls_first: false,
    };
    let page = |keys: Vec<SortKey>| Plan::OrderPage {
        input: Box::new(Plan::Scan { label: None }),
        keys,
        skip: None,
        limit: None,
        fault_on_element: false,
    };
    let cases: Vec<(&str, Plan)> = vec![
        ("num, name", page(vec![key("num"), key("name")])),
        ("grp, num", page(vec![key("grp"), key("num")])),
        (
            "grp, name, num",
            page(vec![key("grp"), key("name"), key("num")]),
        ),
        // The CONTROLS the change cannot reach: a single `Col::Num` and a single `Col::Str`
        // key each take `sort_idx`'s own typed path and never call the comparator at all.
        ("num  (control)", page(vec![key("num")])),
        ("name (control)", page(vec![key("name")])),
    ];

    let mut best = vec![[f64::MAX; 2]; cases.len()];
    for _ in 0..ROUNDS {
        for (side, boxed) in [(0usize, true), (1usize, false)] {
            FORCE_BOXED_CMP.with(|c| c.set(boxed));
            for (c, (label, plan)) in cases.iter().enumerate() {
                let t = Instant::now();
                let got = crate::exec::pull(plan, &store, false);
                let us = t.elapsed().as_secs_f64() * 1e6;
                assert_eq!(got.expect(label).rows(), ROWS as usize, "{label}");
                best[c][side] = best[c][side].min(us);
            }
        }
    }
    FORCE_BOXED_CMP.with(|c| c.set(false));

    println!("\n=== sort key: boxed vs in place, {ROWS} rows, min of {ROUNDS} alternated ===");
    println!(
        "{:<20} {:>12} {:>12} {:>8}",
        "keys", "boxed ns/r", "in-place", "ratio"
    );
    for (c, (label, _)) in cases.iter().enumerate() {
        let [bx, ip] = best[c];
        println!(
            "{label:<20} {:>12.2} {:>12.2} {:>7.2}x",
            bx * 1000.0 / f64::from(ROWS),
            ip * 1000.0 / f64::from(ROWS),
            bx / ip
        );
    }
}

/// The in-place key comparison orders rows exactly as the boxed one did (item 627).
///
/// Compared in one process by flipping `exec::order::FORCE_BOXED_CMP`, row for row, because
/// the claim is byte-identity of the ORDER and nothing weaker. Hand-written expected rows
/// would only test what the author imagined about `cmp_total`'s own rules.
///
/// The fixture exists to reach the cases `cmp_cell` declines as much as the ones it answers:
/// a `Col::Gen` key with real NULLs (placement depends on `nulls_first`, which belongs to the
/// key and not the column), and an OPTIONAL node column carrying the `u32::MAX` sentinel that
/// `value_at` reads back as NULL. Both spellings of `nulls_first` are run for every shape,
/// because a decline that lost the null rule would be invisible under one of them.
#[test]
fn the_in_place_key_comparison_orders_like_the_boxed_one() {
    use crate::exec::order::FORCE_BOXED_CMP;
    use crate::ir::SortKey;

    let mut b = Builder::default();
    for i in 0..60u32 {
        // `grp` collides heavily so the SECOND key decides most comparisons -- a composite
        // sort whose first key is unique never reaches the second column at all.
        let mut props: Vec<(&str, Value)> = vec![
            ("grp", n(f64::from(i % 3))),
            ("num", n(f64::from(i % 7))),
            ("name", s(&format!("v{}", i % 11))),
            ("flag", crate::value::Value::Bool(i % 2 == 0)),
            // power(-1, 0.5) is NaN and power(-1, 2) is 1, so a key over this property is a
            // Num column with SOME NaN cells -- the only thing that separates the engine's
            // total order (NaN last, NaN == NaN) from `partial_cmp`.
            // `% 5`, deliberately NOT `% 3` like `grp`: with the two correlated, every row
            // inside a `grp` group had the same NaN-ness and a NaN never met a non-NaN, so
            // the total order and `partial_cmp` agreed and the mutant lived.
            ("half", n(if i % 5 == 0 { 0.5 } else { 2.0 })),
        ];
        // Present on only some rows, so the column is `Gen` WITH nulls.
        if i % 4 != 0 {
            props.push(("sparse", n(f64::from(i % 5))));
        }
        b.node(&["N"], &props);
    }
    for i in 0..60u32 {
        b.edge(i, (i * 7 + 1) % 60, "R");
        // Only some nodes get an `S` edge, so an OPTIONAL hop over it MIXES real ids with the
        // `u32::MAX` sentinel. An all-sentinel column ties on both paths and proves nothing --
        // which is how the first run let the sentinel-guard mutant live.
        if i % 3 == 0 {
            b.edge(i, (i * 11 + 2) % 60, "S");
        }
    }
    let store = b.build();

    let prop = |k: &str| Expr::Prop {
        slot: 0,
        key: k.to_string(),
    };
    let nan_key = Expr::Call {
        name: "power".to_string(),
        args: vec![Expr::Lit(n(-1.0)), prop("half")],
    };
    let key = |k: &str, descending: bool, nulls_first: bool| SortKey {
        expr: prop(k),
        descending,
        nulls_first,
    };

    for nulls_first in [false, true] {
        let shapes: Vec<(&str, Vec<SortKey>)> = vec![
            ("num", vec![key("num", false, nulls_first)]),
            ("name", vec![key("name", false, nulls_first)]),
            ("flag", vec![key("flag", false, nulls_first)]),
            (
                "sparse (Gen, nulls)",
                vec![key("sparse", false, nulls_first)],
            ),
            (
                "power(-1, half) -- SOME NaN",
                vec![SortKey {
                    expr: nan_key.clone(),
                    descending: false,
                    nulls_first,
                }],
            ),
            (
                "grp, power(-1, half)",
                vec![
                    key("grp", false, nulls_first),
                    SortKey {
                        expr: nan_key.clone(),
                        descending: false,
                        nulls_first,
                    },
                ],
            ),
            (
                "grp, name",
                vec![
                    key("grp", false, nulls_first),
                    key("name", false, nulls_first),
                ],
            ),
            (
                "grp DESC, num",
                vec![
                    key("grp", true, nulls_first),
                    key("num", false, nulls_first),
                ],
            ),
            (
                "grp, sparse, name",
                vec![
                    key("grp", false, nulls_first),
                    key("sparse", false, nulls_first),
                    key("name", false, nulls_first),
                ],
            ),
            (
                "flag DESC, num DESC",
                vec![
                    key("flag", true, nulls_first),
                    key("num", true, nulls_first),
                ],
            ),
        ];

        for (label, keys) in shapes {
            for plan in [
                // Over a bare scan, and over an OPTIONAL hop so a `Col::Nodes` key can carry
                // the `u32::MAX` sentinel that `cmp_cell` must decline.
                Plan::OrderPage {
                    input: Box::new(Plan::Scan { label: None }),
                    keys: keys.clone(),
                    skip: None,
                    limit: None,
                    fault_on_element: false,
                },
                Plan::OrderPage {
                    input: Box::new(Plan::OptionalExpand {
                        input: Box::new(Plan::Scan {
                            label: Some("N".to_string()),
                        }),
                        from: 0,
                        dir: Dir::Out,
                        edge_label: vec!["S".to_string()],
                        bind_edge: false,
                        keep_source: false,
                        landing_pred: None,
                    }),
                    keys: {
                        // Sort by the optional node column FIRST -- a MIX of real ids and
                        // `u32::MAX` sentinels. It reaches the comparator as the elements'
                        // EXTERNAL IDS (`element_col_to_ext_id`), never as a `Col::Nodes`,
                        // which is why `cmp_cell` has no element arm. The shape stays because
                        // it is how that conversion's NULL handling is covered at all.
                        let mut ks = vec![SortKey {
                            expr: Expr::Slot(1),
                            descending: false,
                            nulls_first,
                        }];
                        ks.extend(keys.iter().cloned());
                        ks
                    },
                    skip: None,
                    limit: None,
                    fault_on_element: false,
                },
            ] {
                FORCE_BOXED_CMP.with(|c| c.set(true));
                let boxed = crate::exec::pull(&plan, &store, false);
                FORCE_BOXED_CMP.with(|c| c.set(false));
                let fast = crate::exec::pull(&plan, &store, false);

                let (Ok(x), Ok(y)) = (&boxed, &fast) else {
                    panic!("{label} (nulls_first={nulls_first}): {boxed:?} vs {fast:?}");
                };
                assert_eq!(x.rows(), y.rows(), "{label}: row count");
                for sl in 0..x.slots.len() {
                    let cells = |bt: &crate::batch::Batch| -> Vec<String> {
                        (0..bt.rows())
                            .map(|i| format!("{:?}", bt.slot(sl).value_at(i)))
                            .collect()
                    };
                    assert_eq!(
                        cells(x),
                        cells(y),
                        "{label} (nulls_first={nulls_first}): slot {sl} ORDER differs"
                    );
                }
            }
        }
    }
    FORCE_BOXED_CMP.with(|c| c.set(false));
}

/// The whole-stream branch router returns what the per-row loop returns — on every shape, and
/// ROW FOR ROW IN ORDER, not just as a set (item 624).
///
/// The two paths are compared in one process by flipping `exec::FORCE_PER_ROW`, because a
/// comparison against hand-written expected rows would only test what the author imagined.
/// The fixture is built so the interesting cases are reachable: a vertex with NO out edge
/// (arm 0 produces nothing, so the row falls to arm 1), one with SEVERAL (the group has more
/// than one row, so the within-group order is observable), and one with exactly one.
///
/// **Order is the assertion that has teeth here.** The whole-stream path produces all of arm
/// A's rows and then all of arm B's; the per-row path interleaves them by input row. A
/// comparison as multisets would pass with the regrouping deleted.
#[test]
fn the_whole_stream_branch_router_agrees_with_the_per_row_loop() {
    let mut b = Builder::default();
    // 0: two out edges and one in    3: no edges at all
    // 1: one out edge                4: in edges only
    // 2: three out edges
    for i in 0..5u32 {
        b.node(
            &["N"],
            &[("num", n(f64::from(i))), ("name", s(&format!("v{i}")))],
        );
    }
    for (from, to) in [(0, 1), (0, 2), (1, 2), (2, 0), (2, 1), (2, 4), (1, 4)] {
        b.edge(from, to, "R");
    }
    for (from, to) in [(0, 3), (4, 0)] {
        b.edge(from, to, "S");
    }
    let store = b.build();

    // Every shape the router claims, plus the ones it must REFUSE.
    let queries = [
        // Coalesce: arm 0 empty for some rows, several rows for others.
        "g.V().coalesce(out('R'), out('S'))",
        "g.V().coalesce(out('S'), out('R'))",
        "g.V().coalesce(out('R'), in('R'))",
        "g.V().coalesce(out('S'), in('S'), out('R'))",
        "g.V().coalesce(out('R'), out('S')).values('name')",
        "g.V().coalesce(out('R').has('num', 2), out('S'))",
        "g.V().coalesce(outE('R').inV(), out('S'))",
        "g.V().coalesce(out('R').out('R'), out('S'))",
        "g.V().hasLabel('N').coalesce(out('R'), out('S')).values('num')",
        // choose with an else — both arms, and a cond true for only some rows.
        "g.V().choose(has('num', 2), out('R'), out('S'))",
        "g.V().choose(has('num', 0), out('R'), in('R'))",
        "g.V().choose(out('S'), out('R'), out('S'))",
        // Shapes the router must REFUSE. The CROSS-ROW ones are the load-bearing half, and
        // the first mutation run proved it: with a `_ => true` catch-all in the whitelist
        // every reducer arm still fell back, because an `Aggregate` builds a fresh `Batch`
        // and drops the sidecar -- so the reducer rows alone could not tell a whitelist from
        // no whitelist. These four can: `dedup`, `limit`, `tail` and `order` all GATHER, so
        // the sidecar survives them intact while the rows it describes have been chosen or
        // reordered by looking at other rows. Per-row they apply within one input row's
        // group; whole-stream they would apply across the entire frontier.
        "g.V().coalesce(out('R').dedup(), out('S'))",
        "g.V().coalesce(out('R').limit(1), out('S'))",
        "g.V().coalesce(out('R').tail(1), out('S'))",
        "g.V().coalesce(out('R').order().by('num'), out('S'))",
        "g.V().choose(has('num', 2), out('R').limit(1), out('S'))",
        "g.V().coalesce(out('R').count(), out('S'))",
        "g.V().coalesce(out('R').fold(), out('S'))",
        // optional() and an else-less choose: the SOURCE-fallback kinds. Deferred at 624 and
        // routed at 626, so these moved from "must refuse" to "must agree" without the
        // assertions changing -- which is the comparison doing its job. The interesting rows
        // are the MISSES, where the arm produces nothing and the source passes through:
        // vertex 3 has no edges at all and vertex 4 has only in-edges.
        "g.V().optional(out('R'))",
        "g.V().optional(out('S'))",
        "g.V().optional(out('R').has('num', 2))",
        "g.V().optional(out('R')).values('name')",
        "g.V().choose(has('num', 2), out('R'))",
        "g.V().choose(has('num', 99), out('R'))",
        "g.V().choose(out('S'), out('R'))",
        // A WIDER frontier, so the pass-through source is not slot 0. Every shape above
        // enters the branch on a width-1 frontier, where reading slot 0 and reading
        // `source_slot` are the same thing — mutation proved that leaves the source_slot
        // read untested.
        "g.V().outE('R').optional(inV())",
        "g.V().outE('R').optional(outV())",
        "g.V().outE('S').optional(inV())",
        "g.V().outE('R').choose(has('num', 2), inV())",
        "g.V().out('R').optional(out('S'))",
        // path() forces lineage, which is the hard `track` gate.
        "g.V().coalesce(out('R'), out('S')).path()",
    ];

    for q in queries {
        let plan = crate::gremlin::parse(q).unwrap_or_else(|e| panic!("{q}: {e}"));

        FORCE_PER_ROW.with(|c| c.set(true));
        let slow = crate::exec::pull(&plan, &store, false);
        FORCE_PER_ROW.with(|c| c.set(false));
        let fast = crate::exec::pull(&plan, &store, false);

        match (&slow, &fast) {
            (Ok(a), Ok(c)) => {
                assert_eq!(a.slots.len(), c.slots.len(), "{q}: slot COUNT differs");
                assert_eq!(a.rows(), c.rows(), "{q}: row COUNT differs");
                // `Value` has no `PartialEq` on purpose (NaN), so the cells are compared
                // through their Debug rendering -- which distinguishes every variant.
                for sl in 0..a.slots.len() {
                    let cells = |b: &crate::batch::Batch| -> Vec<String> {
                        (0..b.rows())
                            .map(|i| format!("{:?}", b.slot(sl).value_at(i)))
                            .collect()
                    };
                    assert_eq!(cells(a), cells(c), "{q}: slot {sl} differs IN ORDER");
                }
            }
            (Err(a), Err(c)) => assert_eq!(a, c, "{q}: errors differ"),
            _ => panic!("{q}: one path errored and the other did not: {slow:?} vs {fast:?}"),
        }
    }
    FORCE_PER_ROW.with(|c| c.set(false));
}

/// The router must FIRE on the shapes it claims — the lesson of items 619b and 621, where a
/// green test suite sat on top of a path that never ran. It is asserted here by the only
/// signal available from outside: with the per-row path forced, the same query is far slower.
/// A ratio, not a time, and a loose one (4x against a measured 36x), because this is a test.
#[test]
fn the_whole_stream_branch_router_actually_fires() {
    use std::time::Instant;

    const ROWS: u32 = 4_000;
    let mut b = Builder::default();
    for i in 0..ROWS {
        b.node(&["N"], &[("num", n(f64::from(i % 100)))]);
    }
    for i in 0..ROWS {
        b.edge(i, (i * 7 + 1) % ROWS, "R");
    }
    let store = b.build();
    let plan = crate::gremlin::parse("g.V().coalesce(out('R'), out('R'))").unwrap();

    let time_it = |forced: bool| {
        FORCE_PER_ROW.with(|c| c.set(forced));
        let mut lo = f64::MAX;
        for _ in 0..5 {
            let t = Instant::now();
            let got = crate::exec::pull(&plan, &store, false);
            lo = lo.min(t.elapsed().as_secs_f64());
            assert_eq!(got.unwrap().rows(), ROWS as usize);
        }
        lo
    };
    let slow = time_it(true);
    let fast = time_it(false);
    FORCE_PER_ROW.with(|c| c.set(false));

    assert!(
        slow > fast * 4.0,
        "the whole-stream router did not fire: per-row {slow:.6}s vs {fast:.6}s"
    );
}

/// What does each CONTROL-FLOW / SUBQUERY operator cost per row?
///
/// ```text
/// cargo test --release --manifest-path crates/lenke-engine/Cargo.toml \
///   -- --ignored --nocapture plan_cost_by_control_flow_operator
/// ```
///
/// The third harness of the family. [`plan_cost_by_operator`] prices the 24 streaming
/// operators, [`seed_cost_by_entry_point`] prices the entry points, writes and DDL are
/// deliberately out of both — and what was left over is this: the branch, quantified-path,
/// subquery and whole-graph-algorithm operators, 11 variants that nothing had ever priced.
///
/// **Every case here is a COMPILED QUERY, not a hand-built plan, because none of these is
/// constructible by hand today** — every construction site in the tree is a compiler or the
/// optimizer, so a hand-built one would be a shape the engine never runs. The cost of that is
/// that the planner may rewrite the operator away, which would silently price something else;
/// so each case names the variant it means to measure and the `shape` column says whether the
/// optimized plan still contains it. **A `MISSING` row is not a measurement.**
///
/// Two fixtures, each with its own `Scan` floor, because some of these are super-linear in the
/// row count and pricing them at 200,000 rows would run for hours rather than measure
/// anything. Compare a row only to the floor printed above it.
///
/// Two operators are absent on purpose:
/// - `IntervalExpand` — the test `Builder` cannot give an edge properties, and the as-of
///   question it answers is already `examples/interval_bench.rs`, with a fixture built for it.
/// - `CallProcedure` — a SOURCE, not a per-row operator; the unit for it is the call, which is
///   the `seed_cost_by_entry_point` shape, not this one.
#[test]
#[ignore = "measurement harness: cargo test --release -- --ignored --nocapture plan_cost_by_control_flow_operator"]
fn plan_cost_by_control_flow_operator() {
    use std::time::Instant;
    const REPS: u32 = 5;

    // Overridable: a super-linear operator found to be worse than expected wants a sweep, and
    // the point of the small fixture is that its right size is not known until it is measured.
    let env_rows = |k: &str, d: u32| -> u32 {
        std::env::var(k)
            .ok()
            .and_then(|v| v.parse().ok())
            .unwrap_or(d)
    };
    let big_rows = env_rows("LENKE_CF_ROWS", 200_000);
    let small_rows = env_rows("LENKE_CF_SMALL", 2_000);

    let fixture = |rows: u32| {
        let mut b = Builder::default();
        for i in 0..rows {
            // Node 0 also carries `Z`, so an `OPTIONAL MATCH (x:Z)` has exactly one row to
            // find: the HIT path at one row per input, rather than a cross product.
            let labels: &[&str] = if i == 0 {
                &["N", "Z"]
            } else if i % 3 == 0 {
                &["N"]
            } else {
                &["M"]
            };
            b.node(
                labels,
                &[
                    ("num", n(f64::from(i % 1000))),
                    ("name", s(&format!("v{i}"))),
                ],
            );
        }
        for i in 0..rows {
            b.edge(i, (i * 7 + 1) % rows, "R");
        }
        b.build()
    };

    // (label, the variant this row means to price, query, is_gremlin)
    type Case = (&'static str, &'static str, &'static str, bool);

    let big: Vec<Case> =
        vec![
        ("Scan (the floor)", "Scan", "", false),
        (
            "  …+Project (floor)",
            "Scan",
            "MATCH (a) RETURN a.num AS v",
            false,
        ),
        (
            "  …+count(*) (floor)",
            "Scan",
            "MATCH (a) RETURN count(*) AS c",
            false,
        ),
        (
            "OptionalScan (1 hit/row)",
            "OptionalScan",
            "MATCH (a) OPTIONAL MATCH (x:Z) RETURN x.num AS v",
            false,
        ),
        (
            "OptionalScan (0 hits/row)",
            "OptionalScan",
            "MATCH (a) OPTIONAL MATCH (x:Nope) RETURN x.num AS v",
            false,
        ),
        (
            // The list UNREAD: `opt` flattens this to `VarLength`, so the row prices the
            // flattening, not the operator. Kept as the control for the two below it — the
            // gap between this and `{1,2} (list read)` is what the rewrite is worth.
            "RepeatGroup {1,2} -> VarLength",
            "RepeatGroup",
            "MATCH (a)-[:R]->{1,2}(t) RETURN t.num AS v",
            false,
        ),
        (
            "RepeatGroup {1,1} (list read)",
            "RepeatGroup",
            "MATCH (a)-[e:R]->{1,1}(t) RETURN e AS g",
            false,
        ),
        (
            "RepeatGroup {1,2} (list read)",
            "RepeatGroup",
            "MATCH (a)-[e:R]->{1,2}(t) RETURN e AS g",
            false,
        ),
        (
            // A SINGLE-element unit lowers to `RepeatGroup`, so a nested group needs a
            // genuinely multi-element unit to be one at all.
            "NestedGroup {1,1} (2-elem unit)",
            "NestedGroup",
            "MATCH (a)((x)-[:R]->(m)<-[:R]-(y)){1,1} RETURN count(*) AS c",
            false,
        ),
        (
            "NestedGroup {1,2} (2-elem unit)",
            "NestedGroup",
            "MATCH (a)((x)-[:R]->(m)<-[:R]-(y)){1,2} RETURN count(*) AS c",
            false,
        ),
        (
            "CallInline (correlated)",
            "CallInline",
            "MATCH (a) CALL (a) { MATCH (a)-[:R]->(m) RETURN m.num AS mn } RETURN count(*) AS c",
            false,
        ),
        ("Branch (union, 2 arms)", "Branch", "g.V().union(out('R'), out('R'))", true),
        (
            "Reconverge (union + step)",
            "Reconverge",
            "g.V().union(out('R'), in('R')).values('name')",
            true,
        ),
        (
            "PerElementBranch (coalesce)",
            "PerElementBranch",
            "g.V().coalesce(out('R'), out('R'))",
            true,
        ),
        (
            "PerElementBranch (choose)",
            "PerElementBranch",
            "g.V().choose(has('num', 1), out('R'), in('R'))",
            true,
        ),
        // The two kinds item 624 deliberately LEFT on the per-row path: their fallback is
        // `source_of`, a width-1 batch mixed in among arm outputs of another width. Priced
        // here so the decision to defer them is a number rather than a shrug.
        (
            "PerElementBranch (optional)",
            "PerElementBranch",
            "g.V().optional(out('R'))",
            true,
        ),
        (
            "PerElementBranch (choose, no else)",
            "PerElementBranch",
            "g.V().choose(has('num', 1), out('R'))",
            true,
        ),
        ("Subgraph", "Subgraph", "g.V().outE('R').subgraph('sg').cap('sg')", true),
    ];

    let small: Vec<Case> = vec![
        ("Scan (the floor)", "Scan", "", false),
        (
            "ShortestPath (ANY, to 1 node)",
            "ShortestPath",
            "MATCH p = ANY SHORTEST (a)-[:R]->*(b:Z) RETURN path_length(p) AS len",
            false,
        ),
        (
            "ShortestPathEnum",
            "ShortestPathEnum",
            "g.V().shortestPath()",
            true,
        ),
        (
            "AlgoAnnotate (pageRank)",
            "AlgoAnnotate",
            "g.V().pageRank().values('name')",
            true,
        ),
        (
            "AlgoAnnotate (connectedComp)",
            "AlgoAnnotate",
            "g.V().connectedComponent().values('name')",
            true,
        ),
    ];

    for (title, rows, cases) in [
        ("200k rows", big_rows, &big),
        ("small fixture", small_rows, &small),
    ] {
        let store = fixture(rows);
        println!("\n=== control-flow operator cost, {title}: {rows} rows ===");
        println!(
            "{:<30} {:>10} {:>10} {:>8} {:>10} {:>8}",
            "operator", "total_us", "ns/row", "xScan", "out_rows", "shape"
        );
        let mut base = 0.0f64;
        for (label, want, q, gremlin) in cases.iter() {
            let plan = if q.is_empty() {
                Ok(Plan::Scan { label: None })
            } else if *gremlin {
                crate::gremlin::parse(q)
            } else {
                crate::gql::parse(q)
            };
            let Ok(plan) = plan else {
                println!("{label:<30} {:>10} PARSE ERR: {}", "-", plan.unwrap_err());
                continue;
            };
            // A string probe over the Debug rendering rather than a visitor: the question is
            // only "did the operator survive the optimizer", and a visitor over 55 variants
            // would be more code than the harness it guards.
            let shape = if format!("{plan:?}").contains(&format!("{want} {{")) || q.is_empty() {
                "ok"
            } else {
                "MISSING"
            };
            let mut lo = f64::MAX;
            let mut out = 0usize;
            let mut err = String::new();
            for _ in 0..REPS {
                let t = Instant::now();
                let got = crate::exec::pull(&plan, &store, false);
                lo = lo.min(t.elapsed().as_secs_f64() * 1e6);
                match &got {
                    Ok(b) => out = b.rows(),
                    Err(e) => err = format!("{e:?}"),
                }
            }
            if !err.is_empty() {
                println!("{label:<30} {:>10} RUN ERR: {err}", "-");
                continue;
            }
            let per_row = lo * 1000.0 / f64::from(rows);
            if base == 0.0 {
                base = per_row;
            }
            println!(
                "{label:<30} {lo:>10.1} {per_row:>10.2} {:>8.1} {out:>10} {shape:>8}",
                per_row / base
            );
        }
    }
}

/// What does an ENTRY POINT cost? The seed-family twin of [`plan_cost_by_operator`], which
/// cannot price these: every row there wraps the SAME 200,000-row scan, and a seed produces
/// one row. Wrapping a scan around a seed measures the scan. **The unit for a seed is the
/// SEEK**, so each case here runs many separate `pull`s, each with a different key.
///
/// ```text
/// cargo test --release --manifest-path crates/lenke-engine/Cargo.toml \
///   -- --ignored --nocapture seed_cost_by_entry_point
/// ```
///
/// Read it against TWO floors, not one. `NodeSeed (empty)` is pull overhead with no store
/// access at all; `NodeSeed (miss)` adds exactly one failed external-id hash probe. The gap
/// between those two is the id lookup itself, and the gap to `NodeSeed (1 id)` is what a HIT
/// adds on top of the probe. A single floor cannot separate those, which is why there are two.
///
/// The `NO index -> scan` rows are the deliberate controls: the same operator on the same
/// shape with the index absent. They are the only rows here that say what an index BUYS, and
/// they run far fewer seeks because each one is a whole 200,000-row scan.
#[test]
#[ignore = "measurement harness: cargo test --release -- --ignored --nocapture seed_cost_by_entry_point"]
fn seed_cost_by_entry_point() {
    use std::time::Instant;
    const REPS: u32 = 7;
    const ROWS: u32 = 200_000;
    // Overridable because a seed that is O(E) per seek cannot run 20,000 of them in any
    // reasonable time -- which is how item 615 found the one that was. Lower it to price
    // a known-expensive entry point (`LENKE_SEEKS=20`).
    let seek_budget: u32 = std::env::var("LENKE_SEEKS")
        .ok()
        .and_then(|v| v.parse().ok())
        .unwrap_or(20_000);
    /// A scan-fallback case is 200,000 rows a seek, so it gets a budget in seeks rather
    /// than the same count -- otherwise one row of this table runs 4 billion rows.
    const SCAN_SEEKS: u32 = 20;

    let mut b = Builder::default();
    for i in 0..ROWS {
        b.node(
            &[if i % 3 == 0 { "N" } else { "M" }],
            &[
                ("num", n(f64::from(i % 1000))),
                ("name", s(&format!("v{i}"))),
                // Same values as `num`, deliberately NOT indexed: the control key.
                ("bare", n(f64::from(i % 1000))),
            ],
        );
    }
    for i in 0..ROWS {
        b.edge(i, (i * 7 + 1) % ROWS, "R");
    }
    let mut store = b.build();
    store.create_index("name");
    store.create_index("num");
    store.create_range_index("num");

    // Each case maps a seek ORDINAL to a plan, so consecutive seeks touch different keys.
    // A case built once and pulled N times would measure a warm single entry.
    type Case = (&'static str, Box<dyn Fn(u32) -> Plan>);
    let cases: Vec<Case> = vec![
        (
            "NodeSeed (empty, pull floor)",
            Box::new(|_| Plan::NodeSeed {
                ext_ids: vec![],
                label: None,
            }),
        ),
        (
            "NodeSeed (miss)",
            Box::new(|i| Plan::NodeSeed {
                ext_ids: vec![format!("absent{i}")],
                label: None,
            }),
        ),
        (
            "NodeSeed (1 id)",
            Box::new(|i| Plan::NodeSeed {
                ext_ids: vec![(i % ROWS).to_string()],
                label: None,
            }),
        ),
        (
            "NodeSeed (64 ids)",
            Box::new(|i| Plan::NodeSeed {
                ext_ids: (0..64).map(|k| ((i * 64 + k) % ROWS).to_string()).collect(),
                label: None,
            }),
        ),
        (
            "EdgeSeed (1 id)",
            Box::new(|i| Plan::EdgeSeed {
                ext_ids: vec![format!("e{}", i % ROWS)],
            }),
        ),
        (
            "IndexSeek (name, unique, HASH)",
            Box::new(|i| Plan::IndexSeek {
                label: None,
                key: "name".to_string(),
                value: s(&format!("v{}", i % ROWS)),
            }),
        ),
        (
            "IndexSeek (num, 200/bucket, HASH)",
            Box::new(|i| Plan::IndexSeek {
                label: None,
                key: "num".to_string(),
                value: n(f64::from(i % 1000)),
            }),
        ),
        (
            "IndexSeek (bare, NO index -> scan)",
            Box::new(|i| Plan::IndexSeek {
                label: None,
                key: "bare".to_string(),
                value: n(f64::from(i % 1000)),
            }),
        ),
        (
            "RangeSeek (num < 5, RANGE index)",
            Box::new(|_| Plan::RangeSeek {
                upper: None,
                label: None,
                key: "num".to_string(),
                op: CompareOp::Lt,
                value: n(5.0),
            }),
        ),
        (
            "RangeSeek (bare < 5, NO index -> scan)",
            Box::new(|_| Plan::RangeSeek {
                upper: None,
                label: None,
                key: "bare".to_string(),
                op: CompareOp::Lt,
                value: n(5.0),
            }),
        ),
    ];

    println!("\n=== seed / entry-point cost, {ROWS} nodes ===");
    println!(
        "{:<40} {:>10} {:>10} {:>10} {:>6}",
        "entry point", "ns/seek", "ns/row", "rows/seek", "seeks"
    );
    for (label, make) in &cases {
        let seeks = if label.contains("NO index") {
            SCAN_SEEKS.min(seek_budget)
        } else {
            seek_budget
        };
        let plans: Vec<Plan> = (0..seeks).map(make).collect();
        let mut lo = f64::MAX;
        let mut rows = 0usize;
        for _ in 0..REPS {
            let t = Instant::now();
            let mut got = 0usize;
            for p in &plans {
                let r = crate::exec::pull(p, &store, false);
                assert!(r.is_ok(), "{label} must pull: {r:?}");
                got += r.as_ref().map(crate::batch::Batch::rows).unwrap_or(0);
            }
            lo = lo.min(t.elapsed().as_secs_f64() * 1e9);
            got_check(label, got);
            rows = got;
        }
        let per_seek = lo / f64::from(seeks);
        let per_row = if rows == 0 { 0.0 } else { lo / rows as f64 };
        println!(
            "{label:<40} {per_seek:>10.1} {per_row:>10.2} {:>10.1} {seeks:>6}",
            rows as f64 / f64::from(seeks)
        );
    }
}

/// `WHERE element_id(n) = '<id>'` must SEED, not scan — and must still answer exactly what
/// the scan answered. Item 617.
///
/// The plan assertion is the point: a fast path that silently declines is indistinguishable
/// from one that works, by rows alone. `plan_cost_by_operator`'s sibling lesson -- a route
/// CHOICE is answer-equivalent, so every mutant survives a rows-only test (see
/// [[perf-gate-needs-its-own-test]]). So this checks the OPERATOR, then the rows.
#[test]
fn a_gql_element_id_equality_seeds_instead_of_scanning() {
    let mut b = Builder::default();
    for i in 0..50u32 {
        b.node(
            &[if i % 2 == 0 { "P" } else { "Q" }],
            &[("n", n(f64::from(i)))],
        );
    }
    let store = b.build();

    // Both operand orders, with and without a label, and as a conjunct. Every one must
    // reach a NodeSeed: if only some do, the spellings cost differently, which is the
    // cliff `spelling_probe` exists to catch.
    let seeding = [
        "MATCH (x:P) WHERE element_id(x) = '4' RETURN x.n AS v",
        "MATCH (x:P) WHERE '4' = element_id(x) RETURN x.n AS v",
        "MATCH (x) WHERE element_id(x) = '4' RETURN x.n AS v",
        "MATCH (x:P) WHERE element_id(x) = '4' AND x.n > 0 RETURN x.n AS v",
        "MATCH (x:P) WHERE x.n > 0 AND element_id(x) = '4' RETURN x.n AS v",
    ];
    for q in seeding {
        let plan = crate::gql::parse(q).unwrap();
        let opt = crate::opt::optimize(plan);
        assert!(
            format!("{opt:?}").contains("NodeSeed"),
            "`{q}` did not seed — it is still scanning:\n{opt:?}"
        );
        let rows = run(&opt, &store);
        assert_eq!(rows.rows.len(), 1, "`{q}` must find node 4");
        assert_eq!(num(&rows.rows[0][0]), 4.0, "`{q}` found the wrong node");
    }
}

/// The LABEL survives the rewrite. `NodeSeed` has no label of its own in Gremlin, so the
/// rewrite has to carry the one the `Scan` had — otherwise a point lookup by id returns a
/// node of the WRONG label, which is a wrong answer and not a slow one.
///
/// Node 4 is a `P` and node 5 is a `Q`, so asking for `(x:P)` by node 5's id must find
/// NOTHING. Mutation: setting `label: None` in the rewrite is caught here (and by
/// `rewrite_fuzz`'s row oracles).
#[test]
fn a_gql_id_seek_still_honours_the_label() {
    let mut b = Builder::default();
    for i in 0..50u32 {
        b.node(
            &[if i % 2 == 0 { "P" } else { "Q" }],
            &[("n", n(f64::from(i)))],
        );
    }
    let store = b.build();

    let q = "MATCH (x:P) WHERE element_id(x) = '5' RETURN x.n AS v";
    let opt = crate::opt::optimize(crate::gql::parse(q).unwrap());
    assert!(format!("{opt:?}").contains("NodeSeed"), "must still seed");
    assert_eq!(
        run(&opt, &store).rows.len(),
        0,
        "node 5 is a Q — a P lookup by its id must find nothing"
    );

    // And the same id under its real label does find it, so the test above is not passing
    // because the seed is simply broken.
    let q = "MATCH (x:Q) WHERE element_id(x) = '5' RETURN x.n AS v";
    let opt = crate::opt::optimize(crate::gql::parse(q).unwrap());
    let rows = run(&opt, &store);
    assert_eq!(rows.rows.len(), 1, "node 5 IS a Q");
    assert_eq!(num(&rows.rows[0][0]), 5.0);
}

/// The shapes the rewrite must DECLINE, each because seeding would change the answer.
/// Declining leaves `Filter(Scan)`, which is right by construction — so every one of these
/// asserts the ROWS as well, not just that it declined.
#[test]
fn a_gql_id_seek_declines_what_it_cannot_answer() {
    let mut b = Builder::default();
    for i in 0..20u32 {
        b.node(&["P"], &[("n", n(f64::from(i)))]);
    }
    let store = b.build();

    // A NUMERIC literal. External ids are strings, so under the value contract's cross-type
    // `=` this matches nothing; seeding `"4"` from `= 4` would INVENT a row. Mutation
    // confirms this one is load-bearing: accepting `Value::Num` is caught by `rewrite_fuzz`.
    let q = "MATCH (x:P) WHERE element_id(x) = 4 RETURN x.n AS v";
    let opt = crate::opt::optimize(crate::gql::parse(q).unwrap());
    assert!(
        !format!("{opt:?}").contains("NodeSeed"),
        "a numeric id literal must not seed:\n{opt:?}"
    );
    assert_eq!(run(&opt, &store).rows.len(), 0, "and it matches nothing");

    // A RANGE over an id: a seed takes a set of ids, not an interval.
    let q = "MATCH (x:P) WHERE element_id(x) > '4' RETURN x.n AS v";
    let opt = crate::opt::optimize(crate::gql::parse(q).unwrap());
    assert!(
        !format!("{opt:?}").contains("NodeSeed"),
        "a range over an id must not seed:\n{opt:?}"
    );

    // An id that exists nowhere: seeds, and finds nothing.
    let q = "MATCH (x:P) WHERE element_id(x) = 'nope' RETURN x.n AS v";
    let opt = crate::opt::optimize(crate::gql::parse(q).unwrap());
    assert!(
        format!("{opt:?}").contains("NodeSeed"),
        "a miss still seeds"
    );
    assert_eq!(run(&opt, &store).rows.len(), 0);
}

/// A seed must not resurrect a DELETED node. `NodeSeed` filters on `is_alive`, but the
/// rewrite is what newly routes a GQL query through it, so the property is pinned here too.
#[test]
fn a_gql_id_seek_does_not_find_a_deleted_node() {
    let mut store = Builder::default().build();
    stmt(&mut store, "INSERT (:P {id: 'keep', n: 1})").unwrap();
    stmt(&mut store, "INSERT (:P {id: 'drop', n: 2})").unwrap();

    let q = "MATCH (x:P) WHERE element_id(x) = 'drop' RETURN x.n AS v";
    let opt = crate::opt::optimize(crate::gql::parse(q).unwrap());
    assert_eq!(run(&opt, &store).rows.len(), 1, "live before the delete");

    stmt(
        &mut store,
        "MATCH (x:P) WHERE element_id(x) = 'drop' DELETE x",
    )
    .unwrap();
    assert_eq!(
        run(&opt, &store).rows.len(),
        0,
        "the seed must not resurrect a deleted node"
    );
    // The other node is untouched, so the delete was not a whole-label sweep.
    let q = "MATCH (x:P) WHERE element_id(x) = 'keep' RETURN x.n AS v";
    let opt = crate::opt::optimize(crate::gql::parse(q).unwrap());
    assert_eq!(run(&opt, &store).rows.len(), 1);
}

/// A seed that silently returns NO rows prices as the fastest thing in the table, so every
/// case that is supposed to find something asserts that it did. This is the guard that would
/// have caught a typo in an external id, which otherwise reads as a spectacular win.
#[cfg(test)]
fn got_check(label: &str, got: usize) {
    let wants_rows = !label.contains("empty") && !label.contains("miss");
    assert!(
        !wants_rows || got > 0,
        "{label} found NOTHING -- it would price as free"
    );
}

/// One row of [`edge_id_insert_cost_by_graph_size`]: a label and a GQL statement template
/// taking the insert ordinal (so each insert carries a distinct id).
#[cfg(test)]
type InsertCase = (&'static str, fn(u32) -> String);

/// Does the cost of inserting an edge depend on how many edges the graph ALREADY has? It
/// should not. This harness answers it by measuring the same 200 inserts against graphs of
/// three sizes and reading the SCALING, not the absolute number.
///
/// ```text
/// cargo test --release --manifest-path crates/lenke-engine/Cargo.toml \
///   -- --ignored --nocapture edge_id_insert_cost_by_graph_size
/// ```
///
/// Three rows, and the two controls are the point:
///
/// - **edge, explicit id** pays the duplicate-identity check in `insert_edge_with_identity`.
/// - **edge, NO id** is the same statement minting a synthetic id, so it skips that check.
///   The fix for the first row cannot reach this one; if it moves, something else did.
/// - **node, explicit id** is the SAME duplicate check on the node side, which resolves
///   through the `ext_to_node` hash. It is the shape the edge row is supposed to look like.
///
/// A row that is flat in the graph size is O(1) in it. A row that triples when the graph
/// quadruples is not.
#[test]
#[ignore = "measurement harness: cargo test --release -- --ignored --nocapture edge_id_insert_cost_by_graph_size"]
fn edge_id_insert_cost_by_graph_size() {
    use std::time::Instant;
    const REPS: u32 = 5;
    const SIZES: [u32; 3] = [2_000, 8_000, 32_000];
    // Overridable because the reverse map behind the explicit-id row is built ONCE, on
    // the first lookup, and that build is amortized over however many inserts run here.
    // At 200 it is still a visible share of the row; raising it shows the asymptote.
    // (`LENKE_INSERTS=2000` was the second reading item 615 records.)
    let inserts: u32 = std::env::var("LENKE_INSERTS")
        .ok()
        .and_then(|v| v.parse().ok())
        .unwrap_or(200);

    // Each case is a GQL statement template taking the insert ordinal. Parsed OUTSIDE the
    // timing loop: this harness is about the write, and a parse per row would dilute it.
    let cases: [InsertCase; 5] = [
        ("edge, explicit id", |i| {
            format!("INSERT (:A)-[:R {{id: 'fresh{i}'}}]->(:B)")
        }),
        ("edge, NO id (control)", |_| {
            "INSERT (:A)-[:R {w: 1}]->(:B)".to_string()
        }),
        ("node, explicit id (control)", |i| {
            format!("INSERT (:A {{id: 'fresh{i}'}})")
        }),
        // The two prop-free rows separate the id CHECK from the property WRITE. The first
        // three rows all set at least one property, and a property column is sized to the
        // node count -- so if these two scale as well, the residual growth in the controls
        // is the column, not the identity lookup, and only the first row's 16x is the check.
        ("node, no props (control)", |_| "INSERT (:A)".to_string()),
        ("edge, no props (control)", |_| {
            "INSERT (:A)-[:R]->(:B)".to_string()
        }),
    ];

    println!("\n=== insert cost vs. EXISTING edge count, {inserts} inserts ===");
    print!("{:<30}", "case");
    for e in SIZES {
        print!(" {:>12}", format!("E={e}"));
    }
    println!(" {:>8}", "growth");

    for (label, make) in &cases {
        let plans: Vec<Plan> = (0..inserts)
            .map(|i| crate::gql::parse(&make(i)).expect("harness statement must parse"))
            .collect();
        let mut per_insert: Vec<f64> = Vec::new();
        for size in SIZES {
            let mut lo = f64::MAX;
            for _ in 0..REPS {
                // A FRESH store per rep, because these inserts MUTATE: a second rep would
                // meet its own 'fresh<i>' ids and fault on the duplicate it is measuring.
                let mut store = sized_store(size);
                let t = Instant::now();
                for p in &plans {
                    let r = crate::exec::execute(p, &mut store);
                    assert!(r.is_ok(), "{label} must insert: {r:?}");
                }
                lo = lo.min(t.elapsed().as_secs_f64() * 1e9);
            }
            per_insert.push(lo / f64::from(inserts));
        }
        print!("{label:<30}");
        for p in &per_insert {
            print!(" {:>10.0}ns", p);
        }
        // First to last, over a 16x graph: ~1.0 is O(1) in the graph size.
        let growth = per_insert.last().copied().unwrap_or(0.0) / per_insert[0].max(1.0);
        println!(" {growth:>7.1}x");
    }
}

/// `size` nodes and `size` edges, every element carrying a builder-minted external id --
/// which is what makes the duplicate-id scan do its full work rather than skip absent ids.
#[cfg(test)]
fn sized_store(size: u32) -> Store {
    let mut b = Builder::default();
    for i in 0..size {
        b.node(&["A"], &[("num", n(f64::from(i)))]);
    }
    for i in 0..size {
        b.edge(i, (i * 7 + 1) % size, "R");
    }
    b.build()
}

// --- The dense join path must equal the boxed one, row for row (item 82) ---

/// `hash_join`'s dense path keys on the raw `u32` of an element frontier; its general path
/// boxes each cell and serializes a `Vec<u8>`. The claim is that they agree on BOTH the rows
/// and their ORDER, and this checks it directly rather than asserting it in a comment.
///
/// The fixture is the equivalence: a `Col::Num` holding the same ids boxes to
/// `Value::Num(id)` — exactly what `value_at` gives for a `Col::Nodes` cell — so joining two
/// `Num` columns takes the general path over identical keys. Same ids, two paths, one answer.
#[test]
fn a_dense_join_matches_the_boxed_join_row_for_row() {
    // Duplicates on BOTH sides (so a key fans out to a product), a left id absent from the
    // right, and a right id absent from the left.
    let lids: Vec<u32> = vec![3, 1, 7, 1, 9, 3];
    let rids: Vec<u32> = vec![1, 3, 1, 4, 3, 3];
    // A TAG column per side, distinct per row. Without it the order is unobservable: every
    // output row of one bucket carries the same join VALUE, so reversing a bucket's fill order
    // changes which input rows were paired and nothing in the result shows it. (Verified —
    // that mutant passed a version of this test that compared only the join values.)
    let ltag: Vec<f64> = (0..lids.len()).map(|i| i as f64).collect();
    let rtag: Vec<f64> = (0..rids.len()).map(|j| 100.0 + j as f64).collect();

    let dense = crate::exec::hash_join(
        &Batch::of(vec![Col::Nodes(lids.clone()), Col::Num(ltag.clone())]),
        &Batch::of(vec![Col::Nodes(rids.clone()), Col::Num(rtag.clone())]),
        &[(0, 0)],
    );
    let boxed = crate::exec::hash_join(
        &Batch::of(vec![
            Col::Num(lids.iter().map(|&x| f64::from(x)).collect()),
            Col::Num(ltag),
        ]),
        &Batch::of(vec![
            Col::Num(rids.iter().map(|&x| f64::from(x)).collect()),
            Col::Num(rtag),
        ]),
        &[(0, 0)],
    );

    assert_eq!(
        dense.rows(),
        boxed.rows(),
        "the two paths must keep the same rows"
    );
    assert!(dense.rows() > 0, "the fixture must join something");
    // The TAGS, which identify WHICH input rows were paired, in output order.
    let tags = |b: &Batch| -> String {
        (0..b.rows())
            .map(|i| format!("{:?}/{:?}", b.slot(1).value_at(i), b.slot(3).value_at(i)))
            .collect::<Vec<_>>()
            .join(" ")
            .replace("Num(", "")
            .replace(".0)", "")
    };
    assert_eq!(
        tags(&dense),
        tags(&boxed),
        "the two paths must pair the same ROWS in the same order"
    );
    // And the order is the documented one: left rows in input order, each one's right matches
    // in input order. Left row 0 is id 3, whose right rows are j = 1, 4, 5 → tags 101, 104, 105.
    assert_eq!(
        tags(&dense),
        "0/101 0/104 0/105 1/100 1/102 3/100 3/102 5/101 5/104 5/105",
        "left ascending, each key's right rows ascending"
    );
}

/// The `u32::MAX` OPTIONAL-MATCH sentinel keys as ITSELF, on both paths: `value_at` maps it to
/// NULL, two NULLs serialize to the same bytes, and so two unmatched optional rows join. The
/// dense path reproduces that by keying on the raw id. It must NOT match a real id, and the
/// index must not be sized by four billion to hold it.
#[test]
fn a_dense_join_keys_the_optional_sentinel_as_itself() {
    let j = |l: Vec<u32>, r: Vec<u32>| -> usize {
        crate::exec::hash_join(
            &Batch::of(vec![Col::Nodes(l)]),
            &Batch::of(vec![Col::Nodes(r)]),
            &[(0, 0)],
        )
        .rows()
    };
    assert_eq!(
        j(vec![u32::MAX], vec![u32::MAX]),
        1,
        "two unmatched optionals join"
    );
    assert_eq!(
        j(vec![u32::MAX], vec![5]),
        0,
        "a sentinel does not match a real id"
    );
    assert_eq!(j(vec![5], vec![u32::MAX]), 0, "nor the other way round");
    assert_eq!(
        j(vec![u32::MAX, 5], vec![5, u32::MAX]),
        2,
        "each matches its own kind"
    );
    // A right side of ONLY sentinels still sizes its index by the sentinel slot alone.
    assert_eq!(j(vec![u32::MAX, u32::MAX], vec![u32::MAX]), 2);
    // A left id ABOVE everything on the right matches nothing and must not index out of range.
    assert_eq!(
        j(vec![9_999_999], vec![1, 2]),
        0,
        "an id past the index is a miss"
    );
    assert_eq!(j(vec![1, 9_999_999, 2], vec![2, 1]), 2);
}

/// A join on a slot that is NOT an element frontier, and a join on SEVERAL slots, both stay on
/// the general path — so the dense path cannot quietly answer a key it does not model.
#[test]
fn a_dense_join_declines_a_non_element_or_multi_slot_key() {
    // Two slots: a node frontier and a string. Joining on the STRING pair must still work.
    let left = Batch::of(vec![
        Col::Nodes(vec![1, 2]),
        Col::Str(vec![GStr::from("a"), GStr::from("b")]),
    ]);
    let right = Batch::of(vec![
        Col::Nodes(vec![9, 8]),
        Col::Str(vec![GStr::from("b"), GStr::from("a")]),
    ]);
    let on_str = crate::exec::hash_join(&left, &right, &[(1, 1)]);
    assert_eq!(on_str.rows(), 2, "a string key joins on the general path");
    // Pair (a) with (a) and (b) with (b): left row 0 is "a" → right row 1; left 1 is "b" → right 0.
    assert_eq!(format!("{:?}", on_str.slot(2).value_at(0)), "Num(8.0)");
    assert_eq!(format!("{:?}", on_str.slot(2).value_at(1)), "Num(9.0)");
    // TWO slot pairs — the dense path takes one pair only.
    let both = crate::exec::hash_join(&left, &right, &[(0, 0), (1, 1)]);
    assert_eq!(
        both.rows(),
        0,
        "no row agrees on both the node and the string"
    );
}

// --- Deduping an element frontier by a bit per id (item 83) ---

/// `SeenIds` replaces a `FnvSet<u32>`, so its contract is `FnvSet::insert`'s: true the FIRST
/// time an id is offered, false afterwards. Checked directly against a hash set over a
/// sequence that includes repeats, the `u32::MAX` OPTIONAL sentinel, and ids far apart enough
/// to grow the bitmap several times.
#[test]
fn seen_ids_answers_exactly_what_a_hash_set_would() {
    use crate::exec::order::SeenIds;
    let seq: Vec<u32> = vec![
        5,
        5,
        0,
        63,
        64,
        65,
        0,
        u32::MAX,
        1,
        u32::MAX,
        4096,
        63,
        4096,
        1_000_003,
        1_000_003,
        64,
    ];
    let mut bits = SeenIds::default();
    let mut set: FnvSet<u32> = FnvSet::default();
    for &id in &seq {
        assert_eq!(
            bits.insert(id),
            set.insert(id),
            "the two disagree on id {id} in {seq:?}"
        );
    }
    // And the sentinel really is deduped rather than skipped: offered twice, fresh once.
    let mut b2 = SeenIds::default();
    assert!(b2.insert(u32::MAX));
    assert!(!b2.insert(u32::MAX));
    // The sentinel flag is a RESOURCE guard, and this is the claim it makes. Keyed as a raw id
    // the ANSWER above is unchanged — removing the branch leaves every other test green — but
    // the bitmap would resize to 67 million words, 536 MB, for that one row.
    assert_eq!(
        b2.words(),
        0,
        "the sentinel must not size the bitmap by four billion"
    );
    let mut b3 = SeenIds::default();
    b3.insert(63);
    assert_eq!(
        b3.words(),
        1,
        "a real id sizes the bitmap by its own index, not more"
    );
    b3.insert(64);
    assert_eq!(b3.words(), 2);
}

/// `dedup` over an ELEMENT frontier keeps the first occurrence of each element, in first-seen
/// order. The bit-per-id set must not change which rows survive or their order.
#[test]
fn an_element_dedup_keeps_first_seen_order() {
    // A ring, so `out()` revisits vertices and the dedup has duplicates to remove.
    let store = dense_store(64, 3);
    let first = |q: &str| -> Vec<String> { first_col(&store, q, true) };

    let deduped = first("g.V().out('R').dedup().values('name')");
    let mut seen = std::collections::HashSet::new();
    let expected: Vec<String> = first("g.V().out('R').values('name')")
        .into_iter()
        .filter(|v| seen.insert(v.clone()))
        .collect();
    assert_eq!(
        deduped, expected,
        "dedup keeps the first occurrence of each, in the order they first appeared"
    );
    assert!(
        deduped.len() < expected.len() + 1 && deduped.len() > 1,
        "{}",
        deduped.len()
    );
    // And it really removed something, or the test proves nothing.
    assert!(
        first("g.V().out('R').values('name')").len() > deduped.len(),
        "the fixture must contain duplicates"
    );
}

/// An OPTIONAL miss binds the `u32::MAX` sentinel, and `DISTINCT` over a column holding it
/// must treat it as ONE value rather than growing a bitmap by four billion or dropping it.
#[test]
fn a_distinct_over_optional_misses_keeps_one_null() {
    let mut store = Builder::default().build();
    execute(
        &crate::gql::parse("INSERT (:P {k: 1}), (:P {k: 2}), (:P {k: 3})").unwrap(),
        &mut store,
    )
    .unwrap();
    // No `:R` edges at all, so every optional match misses and every row binds the sentinel.
    let rows = run(
        &opt_plan(
            "MATCH (p:P) OPTIONAL MATCH (p)-[:R]->(q) RETURN DISTINCT q AS x",
            &store,
        ),
        &store,
    )
    .rows;
    assert_eq!(rows.len(), 1, "three misses collapse to one NULL row");
    assert!(rows.iter().next().expect("a row")[0].is_null());
}

/// `RETURN DISTINCT <element>` keeps the first occurrence of each element in first-seen order,
/// and the OTHER typed arms of the same fast path must be untouched by the element one moving
/// to a bitset. A `Bool` column already used a dense `[bool; 2]`; `Num` keys on group bits (so
/// NaN payloads and signed zero collapse) and `Str` on the string, and neither can be a
/// bitset — those are the control arms.
#[test]
fn a_whole_row_distinct_keeps_first_seen_order_for_every_typed_column() {
    let mut store = Builder::default().build();
    execute(
        &crate::gql::parse(
            "INSERT (:P {k: 1, g: 'x', b: true, f: 1.5}), (:P {k: 2, g: 'y', b: false, f: -0.0}), \
             (:P {k: 3, g: 'x', b: true, f: 0.0})",
        )
        .unwrap(),
        &mut store,
    )
    .unwrap();
    // Edges make the element column repeat: both 1 and 2 point at 3.
    execute(
        &crate::gql::parse("MATCH (a:P), (b:P) WHERE a.k < 3 AND b.k = 3 INSERT (a)-[:R]->(b)")
            .unwrap(),
        &mut store,
    )
    .unwrap();

    let col0 = |q: &str| -> Vec<Value> {
        run(&opt_plan(q, &store), &store)
            .rows
            .iter()
            .map(|r| r[0].clone())
            .collect()
    };
    // The ELEMENT column: two rows reach vertex 3, and DISTINCT keeps one.
    let elems = col0("MATCH (a:P)-[:R]->(q) RETURN DISTINCT q");
    assert_eq!(
        elems.len(),
        1,
        "both hops land on the same vertex: {elems:?}"
    );

    // The control arms, each with a duplicate to remove.
    assert_eq!(
        col0("MATCH (p:P) RETURN DISTINCT p.g").len(),
        2,
        "two distinct strings"
    );
    assert_eq!(
        col0("MATCH (p:P) RETURN DISTINCT p.b").len(),
        2,
        "true and false"
    );
    // -0.0 and 0.0 share group bits, so they are ONE distinct value; 1.5 is the other.
    assert_eq!(
        col0("MATCH (p:P) RETURN DISTINCT p.f").len(),
        2,
        "signed zero collapses under the grouping contract"
    );
    assert_eq!(
        col0("MATCH (p:P) RETURN DISTINCT p.k").len(),
        3,
        "all distinct"
    );
}

// --- Stepping from an edge to an endpoint, without boxing the id (item 85) ---

/// `outE().outV()` is the one spelling that keeps a `Plan::EdgeVertex`: stepping from an
/// out-edge BACK to its source cannot be rewritten to a plain hop, while `outE().inV()`,
/// `otherV()` and `as('e').inV()` all are (verified — `EdgeVertex=false` for each). So this is
/// the shape that exercises the typed id read, and it has to give the same answer as the
/// vertices it started from.
#[test]
fn stepping_from_an_edge_to_its_source_returns_the_source() {
    let store = dense_store(40, 3);
    let names = |q: &str| -> Vec<String> {
        let mut v = first_col(&store, q, true);
        v.sort();
        v
    };
    // Every edge's source, deduped, is exactly the set of vertices that have an out-edge —
    // which on a degree-3 fixture is all of them.
    assert_eq!(
        names("g.V().outE('R').outV().dedup().values('name')"),
        names("g.V().values('name')"),
        "every vertex has an out-edge here, so every one is some edge's source"
    );
    // And the multiset is the out-degree: 3 per vertex, 120 edges.
    assert_eq!(
        first_col(&store, "g.V().outE('R').outV().values('name')", true).len(),
        120,
        "one row per edge"
    );
    // Two things a SORTED comparison cannot see, so this part asserts the UNSORTED sequence
    // over an explicit CHAIN (v0->v1->v2->v3):
    //
    //   which endpoint is read — an out-edge's `inV` is its TARGET, never its source. A
    //   regular digraph cannot show a swap (there every vertex has in-degree and out-degree 3,
    //   so the two multisets coincide), which is how the first version of this assertion
    //   passed on `dense_store`.
    //
    //   which ROW's id is read — a mutant reading `ids[(i + 1) % len]` permutes the rows, and
    //   EVERY permutation preserves a sorted multiset. Five `gremlin_ported` cases caught that
    //   mutant while this test did not, until it stopped sorting.
    let mut b = Builder::default();
    for i in 0..4u32 {
        b.node(&["N"], &[("name", s(&format!("v{i}")))]);
    }
    for i in 0..3u32 {
        b.edge(i, i + 1, "R");
    }
    let chain = b.build();
    assert_eq!(
        first_col(&chain, "g.V().outE('R').outV().values('name')", true),
        [r#"Str("v0")"#, r#"Str("v1")"#, r#"Str("v2")"#],
        "each edge's source, in edge order"
    );
    assert_eq!(
        first_col(&chain, "g.V().outE('R').inV().values('name')", true),
        [r#"Str("v1")"#, r#"Str("v2")"#, r#"Str("v3")"#],
        "each edge's target, in edge order"
    );
}

/// A MIXED/branch frontier carries its edges UNBOXED (`Value::Edge`) in a `Gen` column, which
/// is the arm the typed read falls back to. Both arms must agree, so the same step over a
/// branched frontier gives the same endpoints.
#[test]
fn an_edge_endpoint_step_agrees_over_a_branched_frontier() {
    let store = dense_store(40, 3);
    let sorted = |q: &str| -> Vec<String> {
        let mut v = first_col(&store, q, true);
        v.sort();
        v
    };
    // `union` of two identical edge arms doubles every row; the endpoints are the same set.
    let plain = sorted("g.V().outE('R').outV().dedup().values('name')");
    let branched = sorted("g.V().union(outE('R'), outE('R')).outV().dedup().values('name')");
    assert_eq!(
        plain, branched,
        "a branched edge frontier reaches the same sources"
    );
    assert_eq!(
        first_col(
            &store,
            "g.V().union(outE('R'), outE('R')).outV().values('name')",
            true
        )
        .len(),
        240,
        "two arms, one row per edge each"
    );
}

// --- An optional hop with no landing predicate needs one pass (item 86) ---

/// Three sources with 2, 0 and 1 out-edges, so the left-outer contract is visible: a source
/// with neighbours yields one row each and NO miss row, a source without yields exactly one.
fn optional_hop_fixture() -> Store {
    let mut store = Builder::default().build();
    execute(
        &crate::gql::parse("INSERT (:P {k: 0}), (:P {k: 1}), (:P {k: 2}), (:P {k: 3})").unwrap(),
        &mut store,
    )
    .unwrap();
    // 0 -> 1, 0 -> 2 (two), 1 -> none, 2 -> 3 (one), 3 -> none.
    for (a, b) in [(0, 1), (0, 2), (2, 3)] {
        execute(
            &crate::gql::parse(&format!(
                "MATCH (x:P), (y:P) WHERE x.k = {a} AND y.k = {b} INSERT (x)-[:R]->(y)"
            ))
            .unwrap(),
            &mut store,
        )
        .unwrap();
    }
    store
}

/// The ONE-PASS path and the two-pass path must agree, and an always-true landing predicate is
/// how to make the same question take the other one: `q.k >= 0` holds for every vertex here
/// and is not constant-foldable, so it keeps the masked path. Same rows, same order.
#[test]
fn an_optional_hop_agrees_with_and_without_a_landing_predicate() {
    let store = optional_hop_fixture();
    let pairs = |q: &str| -> Vec<String> {
        run(&opt_plan(q, &store), &store)
            .rows
            .iter()
            .map(|r| format!("{:?}/{:?}", r[0], r[1]))
            .collect()
    };
    let one_pass =
        pairs("MATCH (p:P) OPTIONAL MATCH (p)-[:R]->(q) RETURN p.k AS a, q.k AS b ORDER BY a, b");
    let two_pass = pairs(
        "MATCH (p:P) OPTIONAL MATCH (p)-[:R]->(q WHERE q.k >= 0) \
         RETURN p.k AS a, q.k AS b ORDER BY a, b",
    );
    assert_eq!(
        one_pass, two_pass,
        "the two paths must give the same rows in the same order"
    );
    // And the left-outer contract, stated rather than inferred: 0 has two neighbours, 1 and 3
    // have none (one NULL row each), 2 has one.
    assert_eq!(
        one_pass,
        vec![
            "Num(0.0)/Num(1.0)".to_string(),
            "Num(0.0)/Num(2.0)".to_string(),
            "Num(1.0)/Null".to_string(),
            "Num(2.0)/Num(3.0)".to_string(),
            "Num(3.0)/Null".to_string(),
        ],
        "one row per neighbour, and exactly one NULL row for a source with none"
    );
}

/// Gremlin's `optional(<hop>)` semantics: a miss passes the traverser through unchanged.
///
/// NOTE this does NOT reach `Plan::OptionalExpand` — verified, `optional(out())` lowers to the
/// branch machinery instead, so GQL's `OPTIONAL MATCH` is the only producer of that operator
/// and it always sets `keep_source: false`. The `keep_source: true` branch is covered by
/// `an_optional_expand_can_pass_the_source_through`, which builds the plan directly because
/// nothing else reaches it.
#[test]
fn a_gremlin_optional_hop_passes_a_miss_through() {
    let store = optional_hop_fixture();
    let got = first_col(&store, "g.V().optional(out('R')).values('k')", true);
    // 0 -> its two neighbours (k=1, k=2); 1 misses so it passes through as itself; 2 -> k=3;
    // 3 misses and passes through.
    let mut sorted = got.clone();
    sorted.sort();
    assert_eq!(
        sorted,
        ["Num(1.0)", "Num(1.0)", "Num(2.0)", "Num(3.0)", "Num(3.0)"],
        "a miss passes the source through, a hit yields its neighbours: {got:?}"
    );
}

/// With an edge bound, the appended edge column must hold the `u32::MAX` no-edge sentinel on a
/// miss — a row that landed nothing cannot carry an edge. The one-pass loop writes that column
/// itself, so it is its own claim.
#[test]
fn an_optional_hop_binding_an_edge_has_no_edge_on_a_miss() {
    let store = optional_hop_fixture();
    // `r` is bound; on a miss it must be NULL, and present otherwise.
    let rows = run(
        &opt_plan(
            "MATCH (p:P) OPTIONAL MATCH (p)-[r:R]->(q) \
             RETURN p.k AS a, r IS NULL AS no_edge ORDER BY a, no_edge",
            &store,
        ),
        &store,
    )
    .rows;
    let got: Vec<String> = rows
        .iter()
        .map(|r| format!("{:?}/{:?}", r[0], r[1]))
        .collect();
    assert_eq!(
        got,
        vec![
            "Num(0.0)/Bool(false)".to_string(),
            "Num(0.0)/Bool(false)".to_string(),
            "Num(1.0)/Bool(true)".to_string(),
            "Num(2.0)/Bool(false)".to_string(),
            "Num(3.0)/Bool(true)".to_string(),
        ],
        "an edge on every hit, none on either miss"
    );
}

/// The `keep_source: true` arm, built DIRECTLY because no query produces it: GQL
/// `OPTIONAL MATCH` always sets `false`, and Gremlin's `optional()` lowers to the branch
/// machinery rather than this operator (both verified). The field is documented as Gremlin
/// `optional(<hop>)`, so it is a contract the lowering may use later — and a mutant that lands
/// NULL instead of the source passes the entire suite without this test.
#[test]
fn an_optional_expand_can_pass_the_source_through() {
    let store = optional_hop_fixture();
    let plan = |keep_source: bool| Plan::OptionalExpand {
        input: Box::new(Plan::Scan {
            label: Some("P".to_string()),
        }),
        from: 0,
        dir: Dir::Out,
        edge_label: vec!["R".to_string()],
        keep_source,
        bind_edge: false,
        landing_pred: None,
    };
    let landed = |keep_source: bool| -> Vec<String> {
        let b = crate::exec::pull(&plan(keep_source), &store, false).expect("pulls");
        (0..b.rows())
            .map(|i| format!("{:?}", b.slot(1).value_at(i)))
            .collect()
    };
    // Sources 1 and 3 have no out-edge. With `keep_source` they land THEMSELVES; without, the
    // `u32::MAX` sentinel, which reads back as NULL.
    let passthru = landed(true);
    let nulls = landed(false);
    assert_eq!(passthru.len(), nulls.len(), "the same row count either way");
    assert_eq!(
        nulls.iter().filter(|v| v.as_str() == "Null").count(),
        2,
        "two sources miss, and without passthru each lands NULL: {nulls:?}"
    );
    assert_eq!(
        passthru.iter().filter(|v| v.as_str() == "Null").count(),
        0,
        "with passthru NOTHING lands NULL: {passthru:?}"
    );
}

// --- `order(local)` over a scalar frontier is the identity (item 87) ---

/// `order(local)` sorts INSIDE each row's value. A vertex, an edge or a scalar has nothing
/// inside it, so the step is a pass-through and the frontier must survive it.
///
/// It did not. The arm replaced slot 0 with a `Col::Gen` whatever it held, and a `Col::Nodes`
/// boxes to `Value::Num(id)` — so the frontier stopped being a frontier and every later step
/// found nothing. Measured on a 40-vertex degree-3 fixture before the fix:
/// `g.V().out('R').count()` was 120 and `g.V().order(local).out('R').count()` was ZERO.
///
/// GROUND TRUTH from a real TinkerPop console (`tinkerpop/gremlin-console`, `createModern()`):
/// `g.V().out('knows').count()` is 2 and `g.V().order(Scope.local).out('knows').count()` is
/// ALSO 2; `g.V().order(Scope.local).values('name').count()` is 6, the vertex count. The step
/// is transparent over a frontier, which is what these assert.
#[test]
fn order_local_over_a_scalar_frontier_is_transparent() {
    let store = dense_store(40, 3);
    let n = |q: &str| -> usize { first_col(&store, q, true).len() };
    // A vertex frontier: the hop after it must see the same vertices.
    assert_eq!(n("g.V().out('R').values('name')"), 120);
    assert_eq!(
        n("g.V().order(local).out('R').values('name')"),
        120,
        "order(local) must not consume the vertex frontier"
    );
    assert_eq!(
        n("g.V().order(local).values('name')"),
        40,
        "nor stop a property read"
    );
    // An EDGE frontier, and a scalar one.
    assert_eq!(n("g.V().outE('R').order(local).inV().values('name')"), 120);
    assert_eq!(n("g.V().values('name').order(local)"), 40);
    // DESC is the same pass-through — the flag must not make it sort something.
    assert_eq!(
        n("g.V().order(local).by(desc).out('R').values('name')"),
        120
    );
}

/// The CONTROL, and the point of the fix being narrow: over a slot that really does hold a
/// collection, `order(local)` must still sort it. A `fold()` builds a list, which lands in a
/// `Col::Gen` — the one representation that can hold one.
#[test]
fn order_local_still_sorts_a_real_collection() {
    let mut store = Builder::default().build();
    execute(
        &crate::gql::parse("INSERT (:N {name: 'c'}), (:N {name: 'a'}), (:N {name: 'b'})").unwrap(),
        &mut store,
    )
    .unwrap();
    let one = |q: &str| -> String {
        let got = first_col(&store, q, true);
        got.join(",")
    };
    // Unsorted insertion order, then sorted, then reversed — so the step is doing work.
    let raw = one("g.V().values('name').fold()");
    let asc = one("g.V().values('name').fold().order(local)");
    let desc = one("g.V().values('name').fold().order(local).by(desc)");
    assert!(
        raw.contains('a') && raw.contains('c'),
        "the fold must produce a list: {raw}"
    );
    assert_ne!(
        asc, desc,
        "ASC and DESC must differ, or nothing is being sorted"
    );
    assert!(
        asc.find("\\\"a\\\"").unwrap_or(usize::MAX) < asc.find("\\\"c\\\"").unwrap_or(0)
            || asc < desc,
        "ascending must order a before c: {asc} / {desc}"
    );
}

/// `order(local)` over a list of ELEMENTS faults, because an element has no natural order —
/// the same rule the global `order()` applies through `order_page`'s `fault_on_element`, which
/// this step never had.
///
/// GROUND TRUTH (`tinkerpop/gremlin-console`, `createModern()`):
///
/// ```text
/// g.E().fold().order(Scope.local)                -> THROWS ClassCastException
/// g.V().fold().order(Scope.local)                -> THROWS ClassCastException
/// g.V().values('name').fold().order(Scope.local) -> sorts
/// ```
///
/// The TS engine already raised `E_SYNTAX` with this exact message for these shapes while
/// native answered — the divergence the `order(local)` fuzzer arm found on its first run.
#[test]
fn order_local_over_a_list_of_elements_faults() {
    let store = dense_store(6, 2);
    let err = |q: &str| -> String {
        crate::exec::try_run(
            &crate::opt::optimize_indexed(crate::gremlin::parse(q).unwrap(), &store),
            &store,
        )
        .expect_err(&format!("must fault: {q}"))
    };
    for q in [
        "g.V().fold().order(local)",
        "g.E().fold().order(local)",
        "g.V().fold().order(local).by(desc)",
    ] {
        let e = err(q);
        assert!(
            e.contains("over graph elements is not supported"),
            "and with the message the global order() uses: {q} -> {e}"
        );
    }
    // The SAME message the global spelling produces, so the two do not drift apart. The global
    // one is caught STATICALLY — `g.V().order()` is rejected by the parser, before any row —
    // while the local one can only be caught at runtime, because whether a folded list holds
    // elements is not knowable from the text. Different moment, one message.
    let global = crate::gremlin::parse("g.V().order()")
        .expect_err("a global order() over a raw frontier is rejected at parse time");
    assert_eq!(
        global,
        err("g.V().fold().order(local)"),
        "one message whether it is caught at parse time or at run time"
    );
}

/// The CONTROL, and the reason the check looks at the keys ACTUALLY USED: a list of property
/// values still sorts, and a Map sorted `by(keys)` still sorts even though its values are not
/// orderable. TinkerPop agrees on both
/// (`groupCount().by('name').order(Scope.local).by(keys)` sorts).
#[test]
fn order_local_still_sorts_what_has_an_order() {
    let store = dense_store(6, 2);
    let ok = |q: &str| -> String {
        let rows = crate::exec::try_run(
            &crate::opt::optimize_indexed(crate::gremlin::parse(q).unwrap(), &store),
            &store,
        )
        .expect(q)
        .rows;
        format!("{:?}", rows.iter().next().map(|r| r[0].clone()))
    };
    let asc = ok("g.V().values('name').fold().order(local)");
    let desc = ok("g.V().values('name').fold().order(local).by(desc)");
    assert_ne!(
        asc, desc,
        "a list of property values still sorts, both directions"
    );
    assert!(asc.contains("v0"), "and holds the values: {asc}");
    // A Map keyed by a string: orderable by its KEYS whatever its values are.
    let by_keys = ok("g.V().groupCount().by('name').order(local).by(keys)");
    assert!(
        by_keys.contains("Map"),
        "a Map by(keys) still sorts: {by_keys}"
    );
}

/// The element check looks at the keys ACTUALLY USED, and the discriminating case is a Map
/// whose VALUES are elements and whose KEYS are not: `by(keys)` can order it, the default
/// cannot. No query in the Gremlin surface builds such a Map (`group().by(k)` gives
/// `key -> [elements]`, a list value), so the helper is tested directly — the only thing that
/// reaches the distinction.
#[test]
fn the_local_sort_element_check_reads_only_the_keys_it_will_use() {
    use crate::exec::aggregation::sort_local_key_is_element;
    use std::sync::Arc;
    let node = Value::Node(3);
    let name = Value::Str("a".into());

    // Map of name -> vertex.
    let m = Value::Map(Arc::new(vec![(name.clone(), node.clone())]));
    assert!(
        !sort_local_key_is_element(&m, true),
        "by(keys) orders on the string keys, which have an order"
    );
    assert!(
        sort_local_key_is_element(&m, false),
        "the default orders on the values, which are elements"
    );

    // And the mirror: vertex keys, string values.
    let m2 = Value::Map(Arc::new(vec![(node, name)]));
    assert!(
        sort_local_key_is_element(&m2, true),
        "by(keys) on element keys faults"
    );
    assert!(
        !sort_local_key_is_element(&m2, false),
        "its values still have an order"
    );

    // A list is checked whichever way, since its elements ARE the keys.
    let l = Value::List(vec![Value::Node(1)]);
    assert!(sort_local_key_is_element(&l, true));
    assert!(sort_local_key_is_element(&l, false));
    // A list of scalars never faults.
    let l2 = Value::List(vec![Value::Num(1.0), Value::Str("z".into())]);
    assert!(!sort_local_key_is_element(&l2, false));
}

// --- product-of-counts over a cartesian Join (try_join_product_count) -------------
//
// `count(*)` over INDEPENDENT patterns is the product of their counts. Every test here
// compares the fast path against the SAME query run with the fast paths unavailable,
// because an arithmetic oracle alone cannot catch a product that is self-consistently
// wrong about which rows a pattern matches.
//
// Sizes are four distinct numbers on purpose — |k=1| = 3, |k=2| = 5, so the product 15
// is not the sum 8, not 3^2 and not 5^2. A fixture where two of those coincide cannot
// tell a product from a mistake.

/// 12 `P` nodes: three with `k = 1`, five with `k = 2`, four with `k = 9`, each also
/// carrying `s = 'x'` so a NON-NUMERIC factor predicate has something to read; the first
/// two also carry `Q`. Four `E` edges.
fn product_store() -> Store {
    let mut b = Builder::default();
    let mut ids = Vec::new();
    for i in 0..12u32 {
        let k = if i < 3 {
            1.0
        } else if i < 8 {
            2.0
        } else {
            9.0
        };
        let labels: &[&str] = if i < 2 { &["P", "Q"] } else { &["P"] };
        ids.push(b.node(labels, &[("k", n(k)), ("s", s("x"))]));
    }
    for (f, t) in [(0usize, 1usize), (1, 2), (2, 3), (0, 3)] {
        b.edge(ids[f], ids[t], "E");
    }
    b.build()
}

/// The count a query returns, through whatever path the engine picks.
fn count_q(store: &Store, q: &str) -> f64 {
    let plan = crate::opt::optimize(crate::gql::parse(q).unwrap());
    match run(&plan, store).rows[0][0] {
        Value::Num(x) => x,
        ref other => panic!("not a number: {other:?}"),
    }
}

/// The same question with the aggregate fast paths DECLINED, by wrapping the count in a
/// shape they refuse. `ORDER BY` over the single aggregate row cannot change a scalar
/// count, and `plan_has_raw_element_order` is not what it trips — the modifier simply
/// puts an `OrderPage` between the aggregate and the projection, so the aggregate arm
/// still runs but this asserts the pair agree end to end. The decisive oracle is
/// `product_declines_*` below, which asserts on the plan itself.
fn count_general(store: &Store, q: &str) -> f64 {
    count_q(store, &format!("{q} ORDER BY c"))
}

#[test]
fn product_count_two_independent_patterns() {
    let st = product_store();
    let q = "MATCH (a:P {k: 1}), (b:P {k: 2}) RETURN count(*) AS c";
    assert_eq!(count_q(&st, q), 15.0, "3 x 5");
    assert_eq!(count_general(&st, q), 15.0);
}

#[test]
fn product_count_both_spellings_lower_to_one_plan() {
    // The comma list and separate MATCH clauses are the same question. In this engine
    // they also lower to the IDENTICAL plan, so this pins that rather than only the
    // answer — if they ever diverge, the slower spelling would silently stop taking the
    // product and only a timing probe would notice.
    let comma = crate::opt::optimize(
        crate::gql::parse("MATCH (a:P {k: 1}), (b:P {k: 2}) RETURN count(*) AS c").unwrap(),
    );
    let clauses = crate::opt::optimize(
        crate::gql::parse("MATCH (a:P {k: 1}) MATCH (b:P {k: 2}) RETURN count(*) AS c").unwrap(),
    );
    assert_eq!(format!("{comma:?}"), format!("{clauses:?}"));

    let st = product_store();
    assert_eq!(
        count_q(
            &st,
            "MATCH (a:P {k: 1}) MATCH (b:P {k: 2}) RETURN count(*) AS c"
        ),
        15.0
    );
}

#[test]
fn product_count_three_patterns_multiplies_all_factors() {
    let st = product_store();
    let q = "MATCH (a:P {k: 1}), (b:P {k: 2}), (d:Q) RETURN count(*) AS c";
    assert_eq!(count_q(&st, q), 30.0, "3 x 5 x 2");
    assert_eq!(count_general(&st, q), 30.0);
}

#[test]
fn product_count_unconstrained_factors_use_bucket_sizes() {
    let st = product_store();
    let q = "MATCH (a:P), (b:Q) RETURN count(*) AS c";
    assert_eq!(count_q(&st, q), 24.0, "12 x 2");
    assert_eq!(count_general(&st, q), 24.0);
}

#[test]
fn product_count_an_empty_factor_gives_zero() {
    let st = product_store();
    for q in [
        "MATCH (a:P {k: 7}), (b:P {k: 2}) RETURN count(*) AS c",
        "MATCH (a:Nope), (b:P {k: 2}) RETURN count(*) AS c",
    ] {
        assert_eq!(count_q(&st, q), 0.0, "{q}");
        assert_eq!(count_general(&st, q), 0.0, "{q}");
    }
}

#[test]
fn product_count_does_not_overflow_at_scale() {
    // The product is a ROW count and 10^9 is reachable at bench scale, so the multiply
    // saturates rather than wrapping. 20,000^3 = 8 x 10^12 exercises a product that
    // exceeds u32 without the enumeration that would make the test unrunnable.
    let mut b = Builder::default();
    for _ in 0..20_000u32 {
        b.node(&["P"], &[]);
    }
    let st = b.build();
    assert_eq!(
        count_q(&st, "MATCH (a:P), (b:P), (d:P) RETURN count(*) AS c"),
        8.0e12
    );
}

#[test]
fn product_declines_for_a_shared_variable() {
    // A shared variable makes `on` NON-empty — this is a join, not a product, and its
    // answer is |k=1| = 3 rather than 3 x 12.
    let st = product_store();
    let q = "MATCH (a:P {k: 1}), (a:P) RETURN count(*) AS c";
    assert_eq!(count_q(&st, q), 3.0);
    assert_ne!(count_q(&st, q), 36.0);
}

#[test]
fn product_declines_for_a_correlating_where() {
    // A clause `WHERE` lands as a `Filter` ABOVE the Join, which the fast path does not
    // match — `b.k = a.k` relates the patterns, so the answer is 3 x 3 and not 3 x 12.
    let st = product_store();
    let q = "MATCH (a:P {k: 1}), (b:P) WHERE b.k = a.k RETURN count(*) AS c";
    assert_eq!(count_q(&st, q), 9.0);
    assert_ne!(count_q(&st, q), 36.0);
}

#[test]
fn product_declines_for_count_distinct_and_grouping() {
    let st = product_store();
    // Each of these would be a WRONG answer if the product answered it: a shortcut
    // returns one row holding one global count.
    assert_eq!(
        count_q(
            &st,
            "MATCH (a:P {k: 1}), (b:P {k: 2}) RETURN count(DISTINCT a) AS c"
        ),
        3.0
    );
    let grouped = crate::opt::optimize(
        crate::gql::parse("MATCH (a:P {k: 1}), (b:P {k: 2}) RETURN count(*) AS c GROUP BY a")
            .unwrap(),
    );
    assert_eq!(run(&grouped, &st).rows.len(), 3, "one row per group");
}

#[test]
fn product_count_edge_factor_has_no_cross_pattern_uniqueness() {
    // Measured against the TypeScript engine before this was built: a multi-pattern
    // MATCH imposes NO cross-pattern edge uniqueness, so two edge patterns are |E|^2 and
    // not |E|^2 - |E|. Four E edges, so 16 — and this fixture's 4 makes 16 distinct from
    // the 12 a different-edges rule would give.
    let st = product_store();
    for q in [
        "MATCH ()-[:E]->(), ()-[:E]->() RETURN count(*) AS c",
        "MATCH ()-[r:E]->(), ()-[s:E]->() RETURN count(*) AS c",
    ] {
        assert_eq!(count_q(&st, q), 16.0, "{q}");
        assert_eq!(count_general(&st, q), 16.0, "{q}");
    }
}

#[test]
fn product_count_filter_constrained_factors() {
    // A non-equality predicate stays `Filter { Scan }` — the planner emits `IndexSeek`
    // only for an equality — so these factors go through the fallback arm, which
    // materializes the ONE side and takes its row count.
    //
    // This test was originally written as a `RangeSeek` case and asserted only the
    // answer, so it passed through general execution while the `RangeSeek` arm it was
    // meant to cover sat unreachable; mutation exposed that by surviving. It now asserts
    // the DETECTOR fires, which is the part that can regress silently.
    let st = product_store();
    // `k > 1` matches the five `k = 2` plus the four `k = 9`: 9 x 2 = 18, which is
    // neither 9 + 2 nor a square.
    assert_eq!(
        count_q(&st, "MATCH (a:P WHERE a.k > 1), (b:Q) RETURN count(*) AS c"),
        18.0
    );
    assert_eq!(
        count_general(&st, "MATCH (a:P WHERE a.k > 1), (b:Q) RETURN count(*) AS c"),
        18.0
    );
    // A non-numeric predicate too: every node has `s = 'x'`, so 12 x 2 = 24.
    assert_eq!(
        count_q(
            &st,
            "MATCH (a:P WHERE a.s = 'x'), (b:Q) RETURN count(*) AS c"
        ),
        24.0
    );
}

#[test]
fn product_fast_path_fires_exactly_where_intended() {
    // The answer tests above would all pass if the fast path never fired and general
    // execution carried them, so this asks the detector DIRECTLY. (The overflow test is
    // the other half of the evidence: 20,000^3 rows cannot be enumerated at all.)
    let st = product_store();
    let fires = |q: &str| -> Option<f64> {
        let plan = crate::opt::optimize(crate::gql::parse(q).unwrap());
        // Peel the Project to reach the Aggregate the ladder is called with.
        let Plan::Project { input, .. } = &plan else {
            panic!("expected a Project root for {q}");
        };
        let Plan::Aggregate { input, keys, aggs } = input.as_ref() else {
            panic!("expected an Aggregate under the Project for {q}");
        };
        try_join_product_count(input, keys, aggs, &st).map(|b| match b.slots[0].value_at(0) {
            Value::Num(x) => x,
            other => panic!("not a number: {other:?}"),
        })
    };

    // FIRES
    assert_eq!(
        fires("MATCH (a:P {k: 1}), (b:P {k: 2}) RETURN count(*) AS c"),
        Some(15.0)
    );
    assert_eq!(
        fires("MATCH (a:P {k: 1}) MATCH (b:P {k: 2}) RETURN count(*) AS c"),
        Some(15.0)
    );
    assert_eq!(
        fires("MATCH (a:P), (b:P), (d:Q) RETURN count(*) AS c"),
        Some(288.0)
    );
    assert_eq!(
        fires("MATCH ()-[:E]->(), ()-[:E]->() RETURN count(*) AS c"),
        Some(16.0)
    );
    // The fallback arm: a `Filter`-constrained factor, which no leaf arm matches.
    assert_eq!(
        fires("MATCH (a:P WHERE a.k > 1), (b:Q) RETURN count(*) AS c"),
        Some(18.0)
    );
    assert_eq!(
        fires("MATCH (a:P WHERE a.s = 'x'), (b:Q) RETURN count(*) AS c"),
        Some(24.0)
    );

    // DECLINES — each would be a wrong answer, and each must be refused by the detector
    // rather than merely corrected downstream.
    assert_eq!(
        fires("MATCH (a:P {k: 1}), (a:P) RETURN count(*) AS c"),
        None,
        "shared variable"
    );
    assert_eq!(
        fires("MATCH (a:P {k: 1}), (b:P) WHERE b.k = a.k RETURN count(*) AS c"),
        None,
        "correlating WHERE"
    );
    assert_eq!(
        fires("MATCH (a:P {k: 1}), (b:P {k: 2}) RETURN count(DISTINCT a) AS c"),
        None,
        "count(DISTINCT)"
    );
    assert_eq!(
        fires("MATCH (a:P {k: 1}) RETURN count(*) AS c"),
        None,
        "one pattern, no Join"
    );
}

/// A keyless page over a CROSS product caps both sides instead of building the whole
/// product and slicing it (audit item 151). The cap is claimed to be EXACT — the same
/// prefix the full product yields — so every test here compares the paged query against
/// the UNPAGED one sliced in the test, which is literally what the engine did before.
///
/// `hash_join` emits left-major, so output row `k` is left row `k / R` paired with right
/// row `k % R`. The claim rests on both indices being below `cap` for `k < cap`, and that
/// argument has two regimes — `R <= cap` and `R > cap` — which take different branches.
/// A fixture with only one of them tests half of it, so the sizes below straddle the caps.
#[cfg(test)]
fn cross_page_store(tail: u32, outer: u32) -> Store {
    let mut b = Builder::default();
    // Written TAIL FIRST so the two labels do not share id order with their pattern
    // position: a cap that truncated the wrong side would otherwise still line up.
    for i in 0..tail {
        b.node(
            &["User"],
            &[("name", crate::value::Value::Num(f64::from(i)))],
        );
    }
    for i in 0..outer {
        b.node(&["Tiny"], &[("k", crate::value::Value::Num(f64::from(i)))]);
    }
    b.build()
}

#[cfg(test)]
fn cross_rows(store: &Store, q: &str) -> Vec<(f64, f64)> {
    let plan = crate::opt::optimize_indexed(crate::gql::parse(q).unwrap(), store);
    let out = run(&plan, store);
    out.rows
        .iter()
        .map(|r| {
            let num = |c: &Value| match c {
                Value::Num(n) => *n,
                other => panic!("expected a number, got {other:?}"),
            };
            (num(&r[0]), num(&r[1]))
        })
        .collect()
}

#[test]
fn cross_page_prefix_matches_the_whole_product_when_the_right_side_is_small() {
    // R = 3 <= every cap below, so the right cap never binds and the enumeration is the
    // full one. Reaching output row `cap` needs left row `cap / 3`, which the left cap keeps.
    let store = cross_page_store(3, 4);
    let base = "MATCH (s:Tiny) MATCH (u:User) RETURN s.k AS k, u.name AS n";
    let whole = cross_rows(&store, base);
    assert_eq!(whole.len(), 12);
    for limit in [1usize, 2, 3, 4, 5, 11, 12, 13] {
        assert_eq!(
            cross_rows(&store, &format!("{base} LIMIT {limit}")),
            whole[..limit.min(whole.len())].to_vec(),
            "LIMIT {limit} must be the product's first {limit} rows"
        );
    }
}

#[test]
fn cross_page_prefix_matches_the_whole_product_when_the_right_side_is_large() {
    // R = 50 > the small caps, so the right cap DOES bind and left row 0 alone supplies
    // them all. This is the regime the other test cannot reach.
    let store = cross_page_store(50, 4);
    let base = "MATCH (s:Tiny) MATCH (u:User) RETURN s.k AS k, u.name AS n";
    let whole = cross_rows(&store, base);
    assert_eq!(whole.len(), 200);
    for limit in [1usize, 2, 7, 49, 50, 51, 99, 200, 201] {
        assert_eq!(
            cross_rows(&store, &format!("{base} LIMIT {limit}")),
            whole[..limit.min(whole.len())].to_vec(),
            "LIMIT {limit} must be the product's first {limit} rows"
        );
    }
}

#[test]
fn cross_page_honours_skip_as_well_as_limit() {
    // SKIP is where an off-by-one in the cap becomes visible: the cap is `skip + limit`, so
    // a cap one too small drops the window's LAST row while every LIMIT-only test still
    // passes. The windows below sit either side of R = 7 for that reason.
    let store = cross_page_store(7, 7);
    let base = "MATCH (s:Tiny) MATCH (u:User) RETURN s.k AS k, u.name AS n";
    let whole = cross_rows(&store, base);
    assert_eq!(whole.len(), 49);
    for (skip, limit) in [
        (0usize, 1usize),
        (1, 1),
        (1, 5),
        (6, 2),
        (7, 3),
        (8, 1),
        (13, 4),
        (47, 5),
        (49, 2),
    ] {
        let want = if skip >= whole.len() {
            Vec::new()
        } else {
            whole[skip..(skip + limit).min(whole.len())].to_vec()
        };
        assert_eq!(
            cross_rows(&store, &format!("{base} SKIP {skip} LIMIT {limit}")),
            want,
            "SKIP {skip} LIMIT {limit}"
        );
    }
}

#[test]
fn cross_page_caps_a_three_way_product_too() {
    // Three patterns nest two Joins, so the cap has to recurse through the inner one. A cap
    // that only handled a single Join would silently fall back to the full product here.
    let mut b = Builder::default();
    for i in 0..5 {
        b.node(&["A"], &[("k", crate::value::Value::Num(f64::from(i)))]);
    }
    for i in 0..5 {
        b.node(&["B"], &[("k", crate::value::Value::Num(f64::from(i)))]);
    }
    for i in 0..5 {
        b.node(&["C"], &[("k", crate::value::Value::Num(f64::from(i)))]);
    }
    let store = b.build();
    let base = "MATCH (a:A) MATCH (b:B) MATCH (c:C) RETURN a.k AS k, c.k AS n";
    let whole = cross_rows(&store, base);
    assert_eq!(whole.len(), 125);
    for limit in [1usize, 3, 25, 26, 125] {
        assert_eq!(
            cross_rows(&store, &format!("{base} LIMIT {limit}")),
            whole[..limit].to_vec(),
            "three-way LIMIT {limit}"
        );
    }
}

#[test]
fn cross_page_declines_a_keyed_join() {
    // The cap is only sound for a CROSS product. A join ON a shared variable pairs
    // selectively, so left row `i` does not contribute `R` output rows and the index
    // arithmetic the proof rests on does not hold — it must not fire.
    //
    // This test CANNOT kill a mutant that drops the `on.is_empty()` guard, and says so rather
    // than implying coverage it lacks: removing the guard leaves the whole suite green. The
    // reason is that the cap also needs BOTH sides cap-safe, and the shared variable which
    // makes `on` non-empty can only come from an EXPANSION — so a keyed join always has a
    // Filter/Expand side, `pull_capped` declines there first, and the guard is never the thing
    // that refuses. It stays as a stated precondition of the proof, not as a reachable branch.
    // What this test does guard is the ANSWER for the shape, which is worth pinning either way.
    let nd = concat!(
        "{\"type\":\"node\",\"id\":\"p\",\"labels\":[\"N\"],\"properties\":{\"id\":\"p\"}}\n",
        "{\"type\":\"node\",\"id\":\"q\",\"labels\":[\"N\"],\"properties\":{\"id\":\"q\"}}\n",
        "{\"type\":\"node\",\"id\":\"r\",\"labels\":[\"N\"],\"properties\":{\"id\":\"r\"}}\n",
        "{\"type\":\"edge\",\"id\":\"e0\",\"labels\":[\"E\"],\"from\":\"p\",\"to\":\"q\"}\n",
        "{\"type\":\"edge\",\"id\":\"e1\",\"labels\":[\"E\"],\"from\":\"r\",\"to\":\"q\"}\n",
    );
    let store = crate::ndjson::from_ndjson(nd).unwrap();
    let base = "MATCH (a:N)-[:E]->(q:N) MATCH (b:N)-[:E]->(q) RETURN a.id AS x, b.id AS y";
    let plan = crate::opt::optimize_indexed(crate::gql::parse(base).unwrap(), &store);
    // `Value` has no `PartialEq` (it lives in another crate), so rows are compared by their
    // debug rendering — enough to catch a wrong pairing, which is what these guard.
    let flat = |out: &Rows| -> Vec<String> { out.rows.iter().map(|r| format!("{r:?}")).collect() };
    let whole = flat(&run(&plan, &store));
    assert_eq!(whole.len(), 4, "p/r against p/r on the shared q");
    for limit in [1usize, 2, 3, 4] {
        let q = format!("{base} LIMIT {limit}");
        let plan = crate::opt::optimize_indexed(crate::gql::parse(&q).unwrap(), &store);
        assert_eq!(
            flat(&run(&plan, &store)),
            whole[..limit].to_vec(),
            "keyed join LIMIT {limit}"
        );
    }
}

#[test]
fn cross_page_keeps_the_lineage_of_a_named_path() {
    // `hash_join` carries the left side's lineage so a path accessor above a comma pattern
    // does not read NULL. The cap gathers a PREFIX of the joined batch, and dropping the
    // lineage in that gather would make the path NULL only under a LIMIT.
    //
    // The path has to be an EDGE-FREE single-node pattern (`p = (x:N)`), because the cap
    // requires both join sides to be cap-safe and an expansion is not: written with
    // `p = (x:N)-[:E]->(y:N)` the left side is a Filter over an Expand, `pull_capped` declines,
    // and the whole query takes the general path — so the test passed while exercising none of
    // this. Found by mutation: dropping the lineage gather left that version green.
    let mut b = Builder::default();
    for i in 0..4 {
        b.node(&["N"], &[("k", crate::value::Value::Num(f64::from(i)))]);
    }
    for i in 0..4 {
        b.node(&["M"], &[("k", crate::value::Value::Num(f64::from(i)))]);
    }
    let store = b.build();
    // The LIMIT has to be above 1 to reach the gather at all. At `LIMIT 1` both sides cap to
    // ONE row, their product is exactly one row, `joined.rows() > cap` is false and the
    // truncating branch — the only place the lineage is re-gathered — never runs. Mutation
    // found that too: with `LIMIT 1` a dropped lineage gather stayed green. `LIMIT 3` caps
    // each side to 3, making a 9-row product that must be cut to 3.
    let q = "MATCH p = (x:N), (m:M) RETURN size(nodes(p)) AS k, m.k AS n LIMIT 3";
    let plan = crate::opt::optimize_indexed(crate::gql::parse(q).unwrap(), &store);
    let got = run(&plan, &store);
    assert_eq!(got.rows.len(), 3);
    for row in 0..3 {
        assert_eq!(
            format!("{:?}", got.rows[row][0]),
            format!("{:?}", Value::Num(1.0)),
            "row {row}: a one-node path must still have its node after the prefix gather"
        );
    }
}

/// Two more row-MULTIPLYING operators learned to cap under a keyless page (audit item 153):
/// `Unwind` over a single seed row (`FOR x IN [...]`, which plans as a cross join against the
/// scan) and `OptionalExpand` (a left-outer hop). Both claim the cap returns the same PREFIX
/// the uncapped plan would, so every test here compares against the unpaged query sliced.
///
/// `OptionalExpand`'s licence is its own documented contract — every input row yields at least
/// one output row — so the fixtures below vary WHICH sources have neighbours. With every source
/// matching, a left-outer hop and a plain `Expand` are indistinguishable and none of this is
/// under test.
#[cfg(test)]
fn page_store(n: u32, edge_from: &[u32]) -> Store {
    let mut b = Builder::default();
    for i in 0..n {
        b.node(&["User"], &[("k", crate::value::Value::Num(f64::from(i)))]);
    }
    for &i in edge_from {
        b.edge(i, (i + 1) % n, "E");
    }
    b.build()
}

#[cfg(test)]
fn page_rows(store: &Store, q: &str) -> Vec<String> {
    let plan = crate::opt::optimize_indexed(crate::gql::parse(q).unwrap(), store);
    // `Value` has no `PartialEq` (another crate), so rows compare by debug rendering — enough
    // to catch a wrong pairing or a dropped row, which is what these guard.
    run(&plan, store)
        .rows
        .iter()
        .map(|r| format!("{r:?}"))
        .collect()
}

#[cfg(test)]
fn assert_windows(store: &Store, base: &str, windows: &[(usize, Option<usize>)]) {
    let whole = page_rows(store, base);
    for &(skip, limit) in windows {
        let q = match limit {
            Some(l) => format!("{base} SKIP {skip} LIMIT {l}"),
            None => format!("{base} SKIP {skip}"),
        };
        let end = limit.map_or(whole.len(), |l| (skip + l).min(whole.len()));
        let want = if skip >= whole.len() {
            Vec::new()
        } else {
            whole[skip..end].to_vec()
        };
        assert_eq!(page_rows(store, &q), want, "{q}");
    }
}

const PAGE_WINDOWS: &[(usize, Option<usize>)] = &[
    (0, Some(1)),
    (0, Some(2)),
    (0, Some(3)),
    (0, Some(7)),
    (1, Some(1)),
    (1, Some(4)),
    (2, Some(3)),
    (0, None),
    (3, None),
    (99, Some(2)),
];

#[test]
fn unwind_cross_join_pages_to_the_same_prefix() {
    let store = page_store(5, &[]);
    assert_windows(
        &store,
        "FOR x IN [1, 2, 3] MATCH (u:User) RETURN x AS a, u.k AS b",
        PAGE_WINDOWS,
    );
}

#[test]
fn unwind_cross_join_with_a_list_longer_than_the_page() {
    // The list is longer than every window, so the cap binds on the UNWIND side rather than
    // the scan side — the opposite regime from the test above.
    let store = page_store(3, &[]);
    assert_windows(
        &store,
        "FOR x IN [1, 2, 3, 4, 5, 6, 7, 8] MATCH (u:User) RETURN x AS a, u.k AS b",
        PAGE_WINDOWS,
    );
}

#[test]
fn an_empty_list_yields_no_rows_paged_or_not() {
    // The case that makes capping a GENERAL unwind input unsound: a row whose list is empty
    // contributes nothing, so the first output row can come from an arbitrarily later input
    // row. Here it means every window is empty, which a cap that assumed one-row-per-input
    // would get wrong.
    let store = page_store(4, &[]);
    assert!(page_rows(&store, "FOR x IN [] MATCH (u:User) RETURN x AS a, u.k AS b").is_empty());
    assert!(page_rows(
        &store,
        "FOR x IN [] MATCH (u:User) RETURN x AS a, u.k AS b LIMIT 3"
    )
    .is_empty());
}

#[test]
fn an_unwind_over_a_non_row_input_is_not_capped_and_still_answers() {
    // `MATCH … FOR …` puts rows under the unwind, so the `Plan::Row` guard declines. The point
    // is that declining still answers correctly — a cap that fired here could drop rows.
    let store = page_store(4, &[]);
    assert_windows(
        &store,
        "MATCH (u:User) FOR x IN [1, 2] RETURN u.k AS a, x AS b",
        PAGE_WINDOWS,
    );
}

#[test]
fn optional_expand_pages_when_the_first_source_hits() {
    let store = page_store(5, &[0, 1]);
    assert_windows(
        &store,
        "MATCH (u:User) OPTIONAL MATCH (u)-[:E]->(v) RETURN u.k AS a, v.k AS b",
        PAGE_WINDOWS,
    );
}

#[test]
fn optional_expand_pages_when_the_first_source_has_no_neighbour() {
    // The arrangement the contract is about: sources 0 and 1 have no neighbour, so the first
    // two output rows are MISS rows carrying NULL. A cap that quietly dropped a miss row would
    // shift the whole window, and only a fixture whose FIRST source misses can see it.
    let store = page_store(5, &[2, 3]);
    let base = "MATCH (u:User) OPTIONAL MATCH (u)-[:E]->(v) RETURN u.k AS a, v.k AS b";
    let whole = page_rows(&store, base);
    assert_eq!(whole.len(), 5, "one row per source, miss rows included");
    assert_windows(&store, base, PAGE_WINDOWS);
}

#[test]
fn optional_expand_pages_with_no_edges_at_all() {
    // Every row is a miss row. If the cap leaned on there being matches, this is where it
    // would return nothing.
    let store = page_store(5, &[]);
    let base = "MATCH (u:User) OPTIONAL MATCH (u)-[:E]->(v) RETURN u.k AS a, v.k AS b";
    assert_eq!(page_rows(&store, base).len(), 5);
    assert_windows(&store, base, PAGE_WINDOWS);
}

#[test]
fn optional_expand_pages_through_a_landing_predicate() {
    // `optional_expand` has a SECOND code path when a landing predicate is present (two
    // passes, so the predicate can be masked over the whole candidate set before the
    // left-outer decision). It upholds the same one-row-per-source contract, and the cap
    // applies to it too — so it needs its own fixture, with the predicate excluding some
    // matches and turning those sources into misses.
    let store = page_store(5, &[0, 1, 2, 3, 4]);
    assert_windows(
        &store,
        "MATCH (u:User) OPTIONAL MATCH (u)-[:E]->(v WHERE v.k > 2) RETURN u.k AS a, v.k AS b",
        PAGE_WINDOWS,
    );
}

#[test]
fn optional_expand_pages_with_the_edge_bound() {
    // Binding the edge adds a column before the node column, so a truncation that gathered the
    // wrong number of slots would show up here and not in the unbound spelling.
    let store = page_store(5, &[0, 2, 4]);
    assert_windows(
        &store,
        "MATCH (u:User) OPTIONAL MATCH (u)-[e:E]->(v) RETURN u.k AS a, v.k AS b",
        PAGE_WINDOWS,
    );
}

#[test]
fn a_plain_expand_is_still_not_capped() {
    // A plain `Expand` DROPS a source with no neighbour, so its output row `k` can come from
    // an arbitrarily later input row and the cap would be unsound. Guarded by answer: with
    // only sources 3 and 4 carrying edges, the first output row comes from input row 3, which
    // a one-row cap of the input would miss entirely.
    let store = page_store(5, &[3, 4]);
    let base = "MATCH (u:User)-[:E]->(v) RETURN u.k AS a, v.k AS b";
    let whole = page_rows(&store, base);
    assert_eq!(whole.len(), 2, "only the two sources with edges");
    assert_windows(&store, base, PAGE_WINDOWS);
}

/// A continuing `MATCH` whose pattern carries an inline `WHERE` used to CLOBBER the parser's
/// variable scope and never restore it (audit item 157). Five sites did
/// `self.scope = scope.clone()` with no restore, and the damage was three-fold:
///
///  - the JOIN KEY computed just after looked each sub-pattern variable up in `self.scope`,
///    which by then WAS the sub scope — so every sub slot matched itself and the key came out
///    as `[(0, 0), (1, 1)]`, joining `a` to `b` as well as `q` to `q`;
///  - later clauses could not see the outer names, raising a bogus `unknown variable a`;
///  - one site mismatched the slot space badly enough to PANIC in `batch.rs`
///    (`index out of bounds: the len is 2 but the index is 2`).
///
/// Each test pins an ANSWER, and the oracle is the equivalent spelling that never reached the
/// clobbered line — the comma form, or the trailing-`WHERE` form. Those were always right,
/// which is exactly why this survived so long.
#[cfg(test)]
fn scope_store() -> Store {
    let mut b = Builder::default();
    // Sources k = 0, 1, 2 — only k = 2 passes `k > 1`.
    for k in 0..3 {
        b.node(&["P"], &[("k", crate::value::Value::Num(f64::from(k)))]);
    }
    // One shared vertex with IN-DEGREE 3. A degree of 1 would make the right and wrong
    // answers coincide, which is the whole reason the bug was invisible.
    b.node(&["P"], &[("k", crate::value::Value::Num(9.0))]);
    b.edge(0, 3, "E");
    b.edge(1, 3, "E");
    b.edge(2, 3, "E");
    b.build()
}

#[cfg(test)]
fn scope_count(store: &Store, q: &str) -> f64 {
    let plan = crate::opt::optimize_indexed(crate::gql::parse(q).unwrap(), store);
    let out = run(&plan, store);
    match &out.rows[0][0] {
        Value::Num(n) => *n,
        other => panic!("expected a count, got {other:?}"),
    }
}

#[test]
fn a_continuing_match_with_an_inline_where_keeps_the_outer_scope() {
    // The headline wrong answer: 1 instead of 3. One is the number of pairs where `a` happened
    // to EQUAL `b`, which is what the corrupted join key asked for.
    let store = scope_store();
    let q = "MATCH (a:P)-[:E]->(q:P) MATCH (b:P WHERE b.k > 1)-[:E]->(q) RETURN count(*) AS c";
    assert_eq!(scope_count(&store, q), 3.0);
    // The comma spelling never reached the clobber, so it is the oracle.
    let comma = "MATCH (a:P)-[:E]->(q:P), (b:P WHERE b.k > 1)-[:E]->(q) RETURN count(*) AS c";
    assert_eq!(scope_count(&store, comma), 3.0);
    // And so is the trailing-WHERE spelling of the same question.
    let trailing =
        "MATCH (a:P)-[:E]->(q:P) MATCH (b:P)-[:E]->(q) WHERE b.k > 1 RETURN count(*) AS c";
    assert_eq!(scope_count(&store, trailing), 3.0);
}

#[test]
fn the_outer_variables_are_still_projectable_after_such_a_match() {
    // This spelling did not merely answer wrongly — it RAISED `unknown variable a`, because the
    // outer names were gone by the time RETURN was parsed.
    let store = scope_store();
    let q =
        "MATCH (a:P)-[:E]->(q:P) MATCH (b:P WHERE b.k > 1)-[:E]->(q) RETURN a.k AS ak, b.k AS bk";
    let plan = crate::opt::optimize_indexed(crate::gql::parse(q).unwrap(), &store);
    let out = run(&plan, &store);
    assert_eq!(out.rows.len(), 3);
    // Every row pairs some `a` with the single qualifying `b` (k = 2).
    for row in out.rows.iter() {
        assert_eq!(format!("{:?}", row[1]), format!("{:?}", Value::Num(2.0)));
    }
}

#[test]
fn an_uncorrelated_continuing_match_with_an_inline_where() {
    // No shared variable, so this is a 3 x 1 cross product. It used to raise `unknown variable`.
    let store = scope_store();
    let q = "MATCH (a:P)-[:E]->(q:P) MATCH (b:P WHERE b.k > 1)-[:E]->(r:P) RETURN count(*) AS c";
    assert_eq!(scope_count(&store, q), 3.0);
}

#[test]
fn an_inline_where_on_a_continuing_patterns_landing_node() {
    // A different one of the five sites: the predicate sits on the LANDING node rather than the
    // start. Same corruption, so the same 4-instead-of-16 shape.
    let store = scope_store();
    let q = "MATCH (a:P)-[:E]->(q:P) MATCH (b:P)-[:E]->(z:P WHERE z.k = 9) RETURN count(*) AS c";
    assert_eq!(scope_count(&store, q), 9.0, "3 x 3, a full cross product");
    let oracle = "MATCH (a:P)-[:E]->(q:P), (b:P)-[:E]->(z:P WHERE z.k = 9) RETURN count(*) AS c";
    assert_eq!(scope_count(&store, oracle), 9.0);
}

#[test]
fn an_inline_edge_where_in_a_continuing_match_does_not_panic() {
    // This one PANICKED in `batch.rs` with an out-of-bounds slot index, which surfaced to the
    // caller as a misleading `E_INVALID_VALUE`. The predicate was compiled against one slot
    // space and evaluated against another.
    let mut b = Builder::default();
    b.node(&["P"], &[("k", crate::value::Value::Num(0.0))]);
    b.node(&["P"], &[("k", crate::value::Value::Num(9.0))]);
    b.edge(0, 1, "E");
    let store = b.build();
    let q = "MATCH (a:P)-[:E]->(q:P) MATCH (b:P)-[e:E WHERE e.w >= 0]->(z:P) RETURN count(*) AS c";
    // `w` is absent on every edge, so the predicate selects nothing — the point is that it
    // ANSWERS rather than panicking.
    assert_eq!(scope_count(&store, q), 0.0);
}

#[test]
fn an_inline_edge_where_in_a_continuing_match_selects_correctly() {
    // The same site with the property present, so the predicate actually discriminates.
    // Built from NDJSON because `Builder::edge` takes no properties.
    let nd = concat!(
        "{\"type\":\"node\",\"id\":\"s\",\"labels\":[\"P\"],\"properties\":{\"k\":0}}\n",
        "{\"type\":\"node\",\"id\":\"h\",\"labels\":[\"P\"],\"properties\":{\"k\":9}}\n",
        "{\"type\":\"edge\",\"id\":\"e0\",\"labels\":[\"E\"],\"from\":\"s\",\"to\":\"h\",\"properties\":{\"w\":5}}\n",
    );
    let store = crate::ndjson::from_ndjson(nd).unwrap();
    let keep =
        "MATCH (a:P)-[:E]->(q:P) MATCH (b:P)-[e:E WHERE e.w >= 0]->(z:P) RETURN count(*) AS c";
    let drop =
        "MATCH (a:P)-[:E]->(q:P) MATCH (b:P)-[e:E WHERE e.w >= 99]->(z:P) RETURN count(*) AS c";
    assert_eq!(scope_count(&store, keep), 1.0);
    assert_eq!(scope_count(&store, drop), 0.0);
}

#[test]
fn three_clauses_each_with_an_inline_where_keep_the_scope() {
    // The scope has to survive TWICE, and the third clause's variables must be projectable.
    let store = scope_store();
    let q = "MATCH (a:P)-[:E]->(q:P) MATCH (b:P WHERE b.k > 1)-[:E]->(q) \
             MATCH (c:P WHERE c.k = 0)-[:E]->(q) RETURN a.k AS ak, c.k AS ck";
    let plan = crate::opt::optimize_indexed(crate::gql::parse(q).unwrap(), &store);
    let out = run(&plan, &store);
    assert_eq!(out.rows.len(), 3);
    for row in out.rows.iter() {
        assert_eq!(format!("{:?}", row[1]), format!("{:?}", Value::Num(0.0)));
    }
}

#[test]
fn a_node_only_continuing_match_with_an_inline_where() {
    // No segment at all on the continuing pattern — a bare node with a predicate.
    let store = scope_store();
    let q = "MATCH (a:P)-[:E]->(q:P) MATCH (b:P WHERE b.k > 1) RETURN count(*) AS c";
    // 3 pattern rows x 2 qualifying nodes. TWO, not one: the shared vertex carries k = 9, which
    // also passes `k > 1` — written as 1 first, and the test said so. The oracle below is what
    // settles it rather than the arithmetic in this comment.
    assert_eq!(scope_count(&store, q), 6.0);
    let oracle = "MATCH (a:P)-[:E]->(q:P), (b:P WHERE b.k > 1) RETURN count(*) AS c";
    assert_eq!(scope_count(&store, oracle), 6.0);
}

#[test]
fn a_with_boundary_before_a_continuing_match_with_an_inline_where() {
    // `WITH` rebinds the scope to its carried columns, a different path into the same site.
    let store = scope_store();
    let q = "MATCH (a:P)-[:E]->(q:P) WITH q AS q MATCH (b:P WHERE b.k > 1)-[:E]->(q) \
             RETURN count(*) AS c";
    assert_eq!(scope_count(&store, q), 3.0);
}

#[test]
fn a_quantified_continuing_pattern_with_an_inline_where_keeps_the_scope() {
    // Two of the five clobber sites are in the QUANTIFIED branches, and nothing reached them
    // until this test existed: mutation showed both restores could be removed with the suite
    // still green. A `{1,2}` continuing pattern with a predicate on its landing node.
    let store = scope_store();
    let q = "MATCH (a:P)-[:E]->(q:P) MATCH (b:P)-[:E]->{1,2}(z:P WHERE z.k = 9) \
             RETURN count(*) AS c";
    let comma = "MATCH (a:P)-[:E]->(q:P), (b:P)-[:E]->{1,2}(z:P WHERE z.k = 9) \
                 RETURN count(*) AS c";
    // The comma spelling never reached the clobber, so it is the oracle for whatever the right
    // number is — the point is that the two spellings agree.
    assert_eq!(scope_count(&store, q), scope_count(&store, comma));
    assert!(
        scope_count(&store, q) > 0.0,
        "the fixture must produce rows"
    );
}

#[test]
fn a_quantified_continuing_pattern_with_a_per_hop_edge_where() {
    // The other quantified site: a per-hop `WHERE` on the repeated edge.
    let nd = concat!(
        "{\"type\":\"node\",\"id\":\"s\",\"labels\":[\"P\"],\"properties\":{\"k\":0}}\n",
        "{\"type\":\"node\",\"id\":\"m\",\"labels\":[\"P\"],\"properties\":{\"k\":1}}\n",
        "{\"type\":\"node\",\"id\":\"h\",\"labels\":[\"P\"],\"properties\":{\"k\":9}}\n",
        "{\"type\":\"edge\",\"id\":\"e0\",\"labels\":[\"E\"],\"from\":\"s\",\"to\":\"m\",\"properties\":{\"w\":5}}\n",
        "{\"type\":\"edge\",\"id\":\"e1\",\"labels\":[\"E\"],\"from\":\"m\",\"to\":\"h\",\"properties\":{\"w\":5}}\n",
    );
    let store = crate::ndjson::from_ndjson(nd).unwrap();
    let q = "MATCH (a:P)-[:E]->(q:P) MATCH (b:P)-[e:E WHERE e.w >= 0]->{1,2}(z:P) \
             RETURN count(*) AS c";
    let comma = "MATCH (a:P)-[:E]->(q:P), (b:P)-[e:E WHERE e.w >= 0]->{1,2}(z:P) \
                 RETURN count(*) AS c";
    assert_eq!(scope_count(&store, q), scope_count(&store, comma));
    assert!(
        scope_count(&store, q) > 0.0,
        "the fixture must produce rows"
    );
}

/// A continuing `MATCH` whose inline `WHERE` reads an OUTER variable (audit item 158). Item 157
/// left this raising `unknown variable a`, because such a predicate spans two slot spaces — the
/// pattern's own 0-based one and the working table's — so it cannot filter the pattern's seed.
/// It is now deferred to after the join, where one scope holds both.
///
/// **The oracle is the trailing-`WHERE` spelling**, which expresses the same question and was
/// always supported: `MATCH … MATCH (b:P)-[:E]->(q) WHERE b.k = a.k`. Every test below asserts
/// the two agree, so none of them rests on arithmetic in a comment.
#[test]
fn a_correlated_inline_where_on_a_continuing_match() {
    let store = scope_store();
    let inline = "MATCH (a:P)-[:E]->(q:P) MATCH (b:P WHERE b.k = a.k)-[:E]->(q) \
                  RETURN count(*) AS c";
    let oracle =
        "MATCH (a:P)-[:E]->(q:P) MATCH (b:P)-[:E]->(q) WHERE b.k = a.k RETURN count(*) AS c";
    assert_eq!(scope_count(&store, inline), scope_count(&store, oracle));
    // Three sources all reach the one shared vertex, and `b.k = a.k` keeps the diagonal.
    assert_eq!(scope_count(&store, inline), 3.0);
}

#[test]
fn a_correlated_inline_where_with_a_comparison() {
    let store = scope_store();
    for op in ["<", ">", "<>", "<=", ">="] {
        let inline = format!(
            "MATCH (a:P)-[:E]->(q:P) MATCH (b:P WHERE b.k {op} a.k)-[:E]->(q) RETURN count(*) AS c"
        );
        let oracle = format!(
            "MATCH (a:P)-[:E]->(q:P) MATCH (b:P)-[:E]->(q) WHERE b.k {op} a.k RETURN count(*) AS c"
        );
        assert_eq!(
            scope_count(&store, &inline),
            scope_count(&store, &oracle),
            "operator {op}"
        );
    }
}

#[test]
fn a_correlated_conjunct_beside_an_own_variable_one() {
    // Mixing the two kinds in one predicate: the whole thing goes after the join, because the
    // token scan cannot split it and splitting is not what this fixes.
    let store = scope_store();
    let inline = "MATCH (a:P)-[:E]->(q:P) MATCH (b:P WHERE b.k = a.k AND b.k > 0)-[:E]->(q) \
                  RETURN count(*) AS c";
    let oracle = "MATCH (a:P)-[:E]->(q:P) MATCH (b:P)-[:E]->(q) WHERE b.k = a.k AND b.k > 0 \
                  RETURN count(*) AS c";
    assert_eq!(scope_count(&store, inline), scope_count(&store, oracle));
    assert_eq!(
        scope_count(&store, inline),
        2.0,
        "the k = 0 pair is dropped"
    );
}

#[test]
fn a_correlated_inline_where_plus_a_trailing_clause_where() {
    // Both predicates must apply. The inline one is attached first, which is the order they
    // appear in the query.
    let store = scope_store();
    let q = "MATCH (a:P)-[:E]->(q:P) MATCH (b:P WHERE b.k = a.k)-[:E]->(q) WHERE a.k > 0 \
             RETURN count(*) AS c";
    let oracle = "MATCH (a:P)-[:E]->(q:P) MATCH (b:P)-[:E]->(q) WHERE b.k = a.k AND a.k > 0 \
                  RETURN count(*) AS c";
    assert_eq!(scope_count(&store, q), scope_count(&store, oracle));
    assert_eq!(scope_count(&store, q), 2.0);
}

#[test]
fn a_correlated_predicate_may_read_the_outer_patterns_far_end() {
    // `q` is the outer pattern's LANDING node, not its start — any outer variable will do.
    let store = scope_store();
    let inline = "MATCH (a:P)-[:E]->(q:P) MATCH (b:P WHERE b.k = q.k)-[:E]->(r:P) \
                  RETURN count(*) AS c";
    let oracle = "MATCH (a:P)-[:E]->(q:P) MATCH (b:P)-[:E]->(r:P) WHERE b.k = q.k \
                  RETURN count(*) AS c";
    assert_eq!(scope_count(&store, inline), scope_count(&store, oracle));
}

#[test]
fn a_correlated_predicate_on_an_uncorrelated_pattern() {
    // No SHARED variable, so the join is a cross product and the predicate is the only thing
    // relating the two patterns — which is exactly what it could not do before.
    let store = scope_store();
    let inline = "MATCH (a:P)-[:E]->(q:P) MATCH (b:P WHERE b.k = a.k)-[:E]->(r:P) \
                  RETURN count(*) AS c";
    let oracle = "MATCH (a:P)-[:E]->(q:P) MATCH (b:P)-[:E]->(r:P) WHERE b.k = a.k \
                  RETURN count(*) AS c";
    assert_eq!(scope_count(&store, inline), scope_count(&store, oracle));
}

#[test]
fn a_correlated_predicate_on_a_node_only_continuing_pattern() {
    let store = scope_store();
    let inline = "MATCH (a:P)-[:E]->(q:P) MATCH (b:P WHERE b.k = a.k) RETURN count(*) AS c";
    let oracle = "MATCH (a:P)-[:E]->(q:P) MATCH (b:P) WHERE b.k = a.k RETURN count(*) AS c";
    assert_eq!(scope_count(&store, inline), scope_count(&store, oracle));
}

#[test]
fn a_correlated_predicate_after_a_with_boundary() {
    // `WITH` rebinds the scope, so the outer names available to the predicate are its carried
    // columns — a different route to the same deferral.
    let store = scope_store();
    let inline = "MATCH (a:P)-[:E]->(q:P) WITH a AS a, q AS q \
                  MATCH (b:P WHERE b.k = a.k)-[:E]->(q) RETURN count(*) AS c";
    let oracle = "MATCH (a:P)-[:E]->(q:P) WITH a AS a, q AS q \
                  MATCH (b:P)-[:E]->(q) WHERE b.k = a.k RETURN count(*) AS c";
    assert_eq!(scope_count(&store, inline), scope_count(&store, oracle));
}

#[test]
fn an_own_variables_only_predicate_still_answers_identically() {
    // The other side of the split: this one keeps filtering the SEED, which is where it prunes
    // before the expansion. Only the answer is assertable here, and it must not have moved.
    let store = scope_store();
    let inline = "MATCH (a:P)-[:E]->(q:P) MATCH (b:P WHERE b.k > 1)-[:E]->(q) RETURN count(*) AS c";
    let oracle = "MATCH (a:P)-[:E]->(q:P) MATCH (b:P)-[:E]->(q) WHERE b.k > 1 RETURN count(*) AS c";
    assert_eq!(scope_count(&store, inline), scope_count(&store, oracle));
    assert_eq!(scope_count(&store, inline), 3.0);
}

#[test]
fn a_property_named_like_an_outer_variable_still_answers() {
    // The token scan sees a bare `Ident` and cannot tell a property name from a variable, so
    // `(b WHERE b.a = 1)` with an outer variable `a` is reported as an outer read and takes the
    // after-join route. Slower, never wrong — and this pins the "never wrong" half.
    let nd = concat!(
        "{\"type\":\"node\",\"id\":\"x\",\"labels\":[\"P\"],\"properties\":{\"a\":1,\"k\":0}}\n",
        "{\"type\":\"node\",\"id\":\"y\",\"labels\":[\"P\"],\"properties\":{\"a\":2,\"k\":9}}\n",
        "{\"type\":\"edge\",\"id\":\"e0\",\"labels\":[\"E\"],\"from\":\"x\",\"to\":\"y\"}\n",
    );
    let store = crate::ndjson::from_ndjson(nd).unwrap();
    let inline = "MATCH (a:P)-[:E]->(q:P) MATCH (b:P WHERE b.a = 1)-[:E]->(z:P) \
                  RETURN count(*) AS c";
    let oracle = "MATCH (a:P)-[:E]->(q:P) MATCH (b:P)-[:E]->(z:P) WHERE b.a = 1 \
                  RETURN count(*) AS c";
    assert_eq!(scope_count(&store, inline), scope_count(&store, oracle));
    assert_eq!(scope_count(&store, inline), 1.0);
}

/// The single `count(*)` for `MATCH (n:N) WHERE n.k IN $l RETURN count(*)`, with `l` bound as a
/// PARAM — which is the ONLY spelling that reaches the hashed path, and the reason these tests
/// look the way they do.
///
/// An inline literal list parses to `Expr::List`, and above `normalize_pred`'s 32-item gate it
/// STAYS an `Expr::List` haystack; `in_set` matches `Expr::Lit(Value::List)`, which a param
/// becomes when `parse_with_params` substitutes it. Written with an inline list these tests
/// exercised the linear scan instead, and a mutation sweep caught it the only way it could:
/// **0 of 8 mutants died**, including one that reported a hit as FALSE.
fn in_set_count(values: Vec<Value>, st: &Store) -> f64 {
    in_set_count_of("n.k IN $l", values, st)
}

/// `count(*)` for an arbitrary predicate over the bound list.
///
/// The NOT-wrapped form is what separates UNKNOWN from FALSE: a `WHERE` drops both, so a count
/// alone cannot tell them apart and two mutants survived against it. `NOT UNKNOWN` is UNKNOWN
/// (still dropped) while `NOT FALSE` is TRUE (kept), so the same fixture under `NOT` reports
/// different numbers for the two.
fn in_set_count_of(pred: &str, values: Vec<Value>, st: &Store) -> f64 {
    let plan = crate::gql::parse_with_params(
        &format!("MATCH (n:N) WHERE {pred} RETURN count(*) AS c"),
        &[("l".to_string(), Value::List(values))],
    )
    .unwrap();
    match &run(&plan, st).rows.iter().next().expect("one count row")[0] {
        Value::Num(n) => *n,
        other => panic!("not a number: {other:?}"),
    }
}

/// 33 filler strings — one past `normalize_pred`'s `items.len() <= 32` OR-chain rewrite, so the
/// predicate survives to exec as an `Expr::In`.
fn in_set_pad() -> Vec<Value> {
    (0..33).map(|i| s(&format!("p{i}"))).collect()
}

/// `extra` prepended to [`in_set_pad`], as the bound list.
fn in_set_list(extra: &[Value]) -> Vec<Value> {
    let mut v: Vec<Value> = extra.to_vec();
    v.extend(in_set_pad());
    v
}

/// A big `IN $list` takes the hashed membership path (`in_set`), and it must answer exactly as
/// the per-row linear scan it replaces (audit item 185).
#[test]
fn in_set_matches_the_linear_scan_for_a_large_list() {
    let mut b = Builder::default();
    b.node(&["N"], &[("k", s("a"))]); // n0
    b.node(&["N"], &[("k", s("b"))]); // n1
    b.node(&["N"], &[("k", s("zz"))]); // n2: in no list below
    let st = b.build();

    assert_eq!(in_set_count(in_set_list(&[s("a"), s("b")]), &st), 2.0);
    assert_eq!(in_set_count(in_set_list(&[s("a")]), &st), 1.0);
    assert_eq!(in_set_count(in_set_list(&[s("nope")]), &st), 0.0);
    // A duplicate value must not double-count the row it matches.
    assert_eq!(
        in_set_count(in_set_list(&[s("a"), s("a"), s("b")]), &st),
        2.0
    );
}

/// A NULL element in a large `IN` list makes a NON-matching row UNKNOWN, not FALSE — the one
/// part of the three-valued answer a bare membership test cannot see, so `InSet` carries a
/// `has_null` flag for it. A matching row is still TRUE.
#[test]
fn in_set_keeps_null_three_valued() {
    let mut b = Builder::default();
    b.node(&["N"], &[("k", s("a"))]); // n0: matches
    b.node(&["N"], &[("k", s("zz"))]); // n1: no match
    let st = b.build();

    // A plain count cannot tell UNKNOWN from FALSE — a `WHERE` drops both — so each case is
    // asserted BOTH ways. Under `NOT`, UNKNOWN stays dropped and FALSE becomes TRUE.
    //
    // With a null in the list: n0 TRUE, n1 UNKNOWN. So 1 either way, and 0 under NOT.
    assert_eq!(in_set_count(in_set_list(&[s("a"), Value::Null]), &st), 1.0);
    assert_eq!(
        in_set_count_of("NOT (n.k IN $l)", in_set_list(&[s("a"), Value::Null]), &st),
        0.0,
        "a null in the list makes the non-matching row UNKNOWN, and NOT UNKNOWN is dropped"
    );
    // WITHOUT a null: n0 TRUE, n1 a clean FALSE. Same 1 — and 1 under NOT, where the FALSE row
    // flips to TRUE. That difference is the whole observable effect of `has_null`.
    assert_eq!(in_set_count(in_set_list(&[s("a")]), &st), 1.0);
    assert_eq!(
        in_set_count_of("NOT (n.k IN $l)", in_set_list(&[s("a")]), &st),
        1.0,
        "with no null, the non-matching row is FALSE and NOT FALSE is kept"
    );
    // With ONLY a null, nothing matches and every row is UNKNOWN: 0 both ways.
    assert_eq!(in_set_count(in_set_list(&[Value::Null]), &st), 0.0);
    assert_eq!(
        in_set_count_of("NOT (n.k IN $l)", in_set_list(&[Value::Null]), &st),
        0.0
    );
}

/// A needle that is a STORED null is UNKNOWN, never a match — even when the list holds a null,
/// where probing would otherwise find `group_key(null)` and report a hit. No node in the fixture
/// above stores a null `k`, so that branch went unexercised and a mutant removing it survived.
#[test]
fn in_set_drops_a_stored_null_needle() {
    let mut b = Builder::default();
    b.node(&["N"], &[("k", s("a"))]); // n0: matches
    b.node(&["N"], &[("k", Value::Null)]); // n1: a STORED null needle
    let st = b.build();

    assert_eq!(in_set_count(in_set_list(&[s("a"), Value::Null]), &st), 1.0);
    // UNKNOWN rather than FALSE, so `NOT` does not resurrect it.
    assert_eq!(
        in_set_count_of("NOT (n.k IN $l)", in_set_list(&[s("a"), Value::Null]), &st),
        0.0
    );
    // The list WITHOUT a null is the case that pins the early return. A null needle must still
    // be UNKNOWN; probing instead would find nothing and report a clean FALSE, which `NOT`
    // turns into a kept row. With the null in the list both paths agree, which is why the
    // assertions above left a mutant alive.
    assert_eq!(in_set_count(in_set_list(&[s("a")]), &st), 1.0);
    assert_eq!(
        in_set_count_of("NOT (n.k IN $l)", in_set_list(&[s("a")]), &st),
        0.0,
        "a null needle is UNKNOWN, so NOT leaves it dropped — not FALSE, which NOT would keep"
    );
}

/// The CHOICE itself, asserted on `in_set` directly: taking the hashed path changes no answer, so
/// a mutant that never takes it passes every result-based test. Each case differs from its
/// neighbour in exactly one input.
#[test]
fn in_set_decides_when_to_hash() {
    use crate::exec::evaluator::in_set;
    let lit = |items: Vec<Value>| Expr::Lit(Value::List(items));
    let strs = |k: usize| -> Vec<Value> { (0..k).map(|i| s(&format!("v{i}"))).collect() };

    // Long enough, all scalars: hashed. The same list one under the minimum: left on the scan.
    assert!(in_set(&lit(strs(33)), 8).is_some());
    assert!(in_set(&lit(strs(7)), 8).is_none());
    // A non-list haystack never hashes.
    assert!(in_set(&Expr::Lit(s("a")), 8).is_none());
    // An inline list EXPRESSION is not a `Lit` list — which is why these tests bind a param.
    assert!(in_set(
        &Expr::List {
            items: vec![Expr::Lit(s("a"))]
        },
        1
    )
    .is_none());
    // One unsupported element declines the whole list: a nested list, and a NaN.
    let mut nested = strs(33);
    nested.push(Value::List(vec![n(1.0)]));
    assert!(in_set(&lit(nested), 8).is_none());
    let mut nan = strs(33);
    nan.push(n(f64::NAN));
    assert!(in_set(&lit(nan), 8).is_none());
    // Infinity is NOT excluded: `equals` makes `Inf == Inf` true and `group_key` agrees.
    let mut inf = strs(33);
    inf.push(n(f64::INFINITY));
    assert!(in_set(&lit(inf), 8).is_some());
    // A null element is carried, not refused — it decides FALSE vs UNKNOWN.
    let mut with_null = strs(33);
    with_null.push(Value::Null);
    assert!(in_set(&lit(with_null), 8).is_some());
}

/// `group_key` (what `InSet` hashes) groups two NaNs together, where predicate equality makes
/// NaN equal to NOTHING — the one place the two disagree. A NaN NEEDLE must match nothing, and
/// `InSet::contains` returns before probing for exactly that reason.
///
/// A NaN ELEMENT is unreachable from the query surface: `0.0/0.0` RAISES (the division-by-zero
/// rule) and a bound NaN param becomes null under the numeric policy. So the element-side
/// exclusion is defensive; the needle side is reachable, because a NaN can be stored directly,
/// which is what this fixture does.
#[test]
fn in_set_keeps_a_nan_needle_unequal() {
    let mut b = Builder::default();
    b.node(&["N"], &[("k", n(1.0))]); // n0: matches
    b.node(&["N"], &[("k", n(f64::NAN))]); // n1: a stored NaN, matches nothing
    let st = b.build();

    assert_eq!(in_set_count(in_set_list(&[n(1.0)]), &st), 1.0);
    // With a null in the list the NaN row is UNKNOWN rather than FALSE — still not a match.
    assert_eq!(in_set_count(in_set_list(&[n(1.0), Value::Null]), &st), 1.0);
}

/// `-0.0` and `0.0` are equal under BOTH `equals` and `group_key`, so the hashed path must agree
/// with the scan: a `0.0` needle matches a `-0.0` element.
#[test]
fn in_set_treats_minus_zero_as_zero() {
    let mut b = Builder::default();
    b.node(&["N"], &[("k", n(0.0))]);
    let st = b.build();

    assert_eq!(in_set_count(in_set_list(&[n(-0.0)]), &st), 1.0);
}

/// An element kind `InSet` does not cover — a nested LIST — hands the whole batch back to the
/// linear scan, and the answer is unchanged. `equals` compares lists elementwise while
/// `group_key` canonicalizes them, so the two could disagree on a nested NaN.
#[test]
fn in_set_declines_on_a_non_scalar_element() {
    let mut b = Builder::default();
    b.node(&["N"], &[("k", s("a"))]);
    let st = b.build();
    let nested = Value::List(vec![n(1.0), n(2.0)]);

    assert_eq!(in_set_count(in_set_list(&[s("a"), nested]), &st), 1.0);
}

/// An INFINITE element is carried, not refused: `equals` compares `Num`s with `==`, so
/// `Inf == Inf` is TRUE and `group_key` agrees. A stored infinity therefore matches, and
/// excluding every non-finite would have been over-conservative — a mutant accepting them
/// changed no answer, which is what pointed at it.
#[test]
fn in_set_matches_an_infinite_element() {
    let mut b = Builder::default();
    b.node(&["N"], &[("k", n(1.0))]); // n0
    b.node(&["N"], &[("k", n(f64::INFINITY))]); // n1: matches the Inf element
    let st = b.build();

    assert_eq!(
        in_set_count(in_set_list(&[n(1.0), n(f64::INFINITY)]), &st),
        2.0
    );
    assert_eq!(in_set_count(in_set_list(&[n(1.0)]), &st), 1.0);
}

/// Cross-type membership stays FALSE: a string needle against numeric elements matches nothing,
/// because `group_key` carries a type tag exactly as `equals` is type-strict.
#[test]
fn in_set_is_type_strict() {
    let mut b = Builder::default();
    b.node(&["N"], &[("k", s("1"))]); // the STRING "1", not the number
    let st = b.build();

    assert_eq!(in_set_count(in_set_list(&[n(1.0)]), &st), 0.0);
}

/// A needle whose property is ABSENT is UNKNOWN, never a match — the same as a null needle, and
/// the hashed path returns before probing.
#[test]
fn in_set_drops_an_absent_needle() {
    let mut b = Builder::default();
    b.node(&["N"], &[("k", s("a"))]); // n0: matches
    b.node(&["N"], &[("other", s("x"))]); // n1: no `k` at all
    let st = b.build();

    assert_eq!(in_set_count(in_set_list(&[s("a")]), &st), 1.0);
}

/// Each row is probed INDEPENDENTLY: the key buffer `InSet::contains` reuses must be cleared, or
/// row two probes row one's key concatenated with its own. Needs several matching rows with
/// DIFFERENT values to be visible at all.
#[test]
fn in_set_probes_each_row_independently() {
    let mut b = Builder::default();
    b.node(&["N"], &[("k", s("a"))]);
    b.node(&["N"], &[("k", s("b"))]);
    b.node(&["N"], &[("k", s("c"))]);
    let st = b.build();

    assert_eq!(
        in_set_count(in_set_list(&[s("a"), s("b"), s("c")]), &st),
        3.0
    );
}

/// A lopsided fixture for the capped cross-join arm — a 2-row left against a 6-row right, so
/// the two halves of the cap bound are separable: a cap BELOW the right's surviving count
/// needs one left row, and a cap ABOVE it needs `ceil(cap / survivors)` of them.
fn lopsided_product() -> Store {
    let mut b = Builder::default();
    b.node(&["Tiny"], &[("k", n(1.0))]);
    b.node(&["Tiny"], &[("k", n(2.0))]);
    for i in 0..6 {
        b.node(&["User"], &[("k", n(f64::from(i)))]);
    }
    b.build()
}

/// `MATCH (s:Tiny) MATCH (u:User) WHERE u.k > gt RETURN s.k LIMIT n`, as the planner builds
/// it after item 273's right-side pushdown: the `Filter` sits INSIDE the right input, which
/// is what `pull_capped` used to decline.
fn limited_filtered_product(gt: f64, limit: Option<usize>) -> Plan {
    let body = Plan::Project {
        input: Box::new(Plan::Join {
            left: Box::new(scan("Tiny")),
            right: Box::new(Plan::Filter {
                input: Box::new(scan("User")),
                pred: cmp(CompareOp::Gt, prop(0, "k"), Expr::Lit(n(gt))),
            }),
            on: vec![],
        }),
        items: vec![("k".to_string(), prop(0, "k"))],
    };

    match limit {
        None => body,
        Some(l) => Plan::OrderPage {
            input: Box::new(body),
            keys: vec![],
            skip: None,
            limit: Some(l),
            fault_on_element: false,
        },
    }
}

/// A cap BELOW the surviving count: 4 users pass `k > 1`, so a cap of 3 is filled from the
/// FIRST left row alone and three right rows suffice.
#[test]
fn a_capped_filtered_product_below_the_surviving_count() {
    let store = lopsided_product();
    let out = run(&limited_filtered_product(1.0, Some(3)), &store);

    assert_eq!(out.rows.len(), 3, "the cap must be filled exactly");
}

/// A cap ABOVE it: the whole filtered product is 2 x 4 = 8, so a cap of 8 needs BOTH left
/// rows. A bound that only ever took one left row would return 4 here.
#[test]
fn a_capped_filtered_product_above_the_surviving_count() {
    let store = lopsided_product();
    let out = run(&limited_filtered_product(1.0, Some(8)), &store);

    assert_eq!(out.rows.len(), 8, "the whole filtered product is 8 rows");
}

/// A cap larger than the product cannot be filled, and the answer is the product itself —
/// capping must not silently drop rows.
#[test]
fn a_cap_larger_than_the_filtered_product() {
    let store = lopsided_product();
    let out = run(&limited_filtered_product(1.0, Some(100)), &store);

    assert_eq!(out.rows.len(), 8);
}

/// A SELECTIVE predicate, survivors far fewer than the cap: one user passes `k > 4`, so the
/// product is 2 x 1 = 2 whatever the cap says.
#[test]
fn a_capped_filtered_product_with_a_selective_predicate() {
    let store = lopsided_product();
    let out = run(&limited_filtered_product(4.0, Some(64)), &store);

    assert_eq!(out.rows.len(), 2);
}

/// An EMPTY filtered side: the cap can never be filled, so the stream walks the whole bucket
/// and still answers nothing. A bound that assumed the cap was reachable would loop or invent
/// rows.
#[test]
fn a_capped_filtered_product_whose_side_is_empty() {
    let store = lopsided_product();
    let out = run(&limited_filtered_product(1000.0, Some(64)), &store);

    assert_eq!(out.rows.len(), 0);
}

/// THE PROPERTY THE ARM RESTS ON: every capped answer is a SUBSET of the uncapped one, at
/// every cap. A wrong bound can keep the row COUNT right while inventing a row, which only
/// this comparison catches.
#[test]
fn a_capped_filtered_product_never_invents_a_row() {
    let store = lopsided_product();
    let mut all = names_of(&run(&limited_filtered_product(1.0, None), &store), 0);
    all.sort();

    assert_eq!(all.len(), 8, "the uncapped product is the oracle");

    for cap in 1..=8 {
        let mut got = names_of(&run(&limited_filtered_product(1.0, Some(cap)), &store), 0);
        got.sort();

        assert_eq!(got.len(), cap, "cap {cap} must yield {cap} rows");

        for row in &got {
            assert!(all.contains(row), "cap {cap} invented a row: {row}");
        }
    }
}

/// A cross product emits rows LEFT-MAJOR: every right row for the first left row, then every
/// right row for the second, and each side in ascending input order.
///
/// Pinned because NOTHING else does. `hash_join`'s `on: []` fast path (item 284) replaced an
/// index probe with a direct double loop, and both produce this order — the probe indexed `j`
/// ascending and probed `i` ascending — but mutation found the claim unguarded: swapping the
/// loops to RIGHT-major keeps every row and every count, and the whole suite still passed.
/// The byte-identity fuzzers cannot see it either, because they canonicalise unordered row
/// order. So the argument from reading both paths is true and was load-bearing on nobody.
#[test]
fn a_cross_product_emits_rows_left_major() {
    let mut b = Builder::default();
    b.node(&["L"], &[("k", n(10.0))]);
    b.node(&["L"], &[("k", n(20.0))]);
    b.node(&["R"], &[("k", n(1.0))]);
    b.node(&["R"], &[("k", n(2.0))]);
    b.node(&["R"], &[("k", n(3.0))]);
    let store = b.build();

    let plan = Plan::Project {
        input: Box::new(Plan::Join {
            left: Box::new(scan("L")),
            right: Box::new(scan("R")),
            on: vec![],
        }),
        items: vec![
            ("l".to_string(), prop(0, "k")),
            ("r".to_string(), prop(1, "k")),
        ],
    };

    let out = run(&plan, &store);
    let pairs: Vec<String> = out
        .rows
        .iter()
        .map(|row| format!("{:?}/{:?}", row[0], row[1]))
        .collect();

    // LEFT-major: l=10 against r=1,2,3 and only then l=20. Right-major would interleave the
    // left values (10/1, 20/1, 10/2, …) with the same six rows and the same counts.
    assert_eq!(
        pairs,
        vec![
            "Num(10.0)/Num(1.0)",
            "Num(10.0)/Num(2.0)",
            "Num(10.0)/Num(3.0)",
            "Num(20.0)/Num(1.0)",
            "Num(20.0)/Num(2.0)",
            "Num(20.0)/Num(3.0)",
        ],
        "a cross product must be left-major, with each side ascending"
    );
}

/// A fixture for the CORRELATED capped product (item 288) — a 3-row left against a 12-row
/// right, where `u.k = s.k` matches exactly one right row per left row and `u.k > s.k` matches
/// many. Two predicates over one fixture separate "the cap fills inside one left row" from "the
/// cap needs every left row", which is the boundary item 283's retracted design got wrong.
fn correlated_product_store() -> Store {
    let mut b = Builder::default();
    for i in 0..3 {
        b.node(&["Tiny"], &[("k", n(f64::from(i)))]);
    }
    for i in 0..12 {
        b.node(&["User"], &[("k", n(f64::from(i)))]);
    }
    b.build()
}

/// `MATCH (s:Tiny) MATCH (u:User) WHERE u.k <op> s.k RETURN s.k, u.k LIMIT n`.
///
/// The `Filter` sits ABOVE the join and that is the whole point: a predicate reading BOTH
/// sides cannot be pushed into either (item 273's `right_pushable` needs every slot on one
/// side), so this is the shape `pull_capped` declined before item 288.
fn correlated_limited_product(op: CompareOp, limit: Option<usize>) -> Plan {
    let body = Plan::Project {
        input: Box::new(Plan::Filter {
            input: Box::new(Plan::Join {
                left: Box::new(scan("Tiny")),
                right: Box::new(scan("User")),
                on: vec![],
            }),
            pred: cmp(op, prop(1, "k"), prop(0, "k")),
        }),
        items: vec![
            ("s".to_string(), prop(0, "k")),
            ("u".to_string(), prop(1, "k")),
        ],
    };

    match limit {
        None => body,
        Some(l) => Plan::OrderPage {
            input: Box::new(body),
            keys: vec![],
            skip: None,
            limit: Some(l),
            fault_on_element: false,
        },
    }
}

/// Every row of the capped answer, as `s/u` pairs in the order the plan emitted them.
fn correlated_pairs(op: CompareOp, limit: Option<usize>, store: &Store) -> Vec<String> {
    run(&correlated_limited_product(op, limit), store)
        .rows
        .iter()
        .map(|row| format!("{:?}/{:?}", row[0], row[1]))
        .collect()
}

/// THE PREFIX PROPERTY, which is what the arm rests on: a capped correlated product must be the
/// uncapped answer's first `cap` rows, IN ORDER.
///
/// Asserted for every cap rather than one, because a bound off by one hides at exactly one
/// value — item 275's mutation found its cap bound that way, and a nested loop has TWO bounds.
/// Order matters here in a way it does not for the uncapped plan: a prefix is only well defined
/// against a fixed order, so this is also what pins the loop as LEFT-major (a right-major loop
/// keeps every row and changes which `cap` of them survive).
#[test]
fn a_capped_correlated_product_is_a_prefix_of_the_uncapped_one() {
    let store = correlated_product_store();

    for op in [CompareOp::Eq, CompareOp::Gt] {
        let all = correlated_pairs(op, None, &store);

        assert!(
            all.len() >= 3,
            "the uncapped answer is the oracle and must be non-trivial, got {}",
            all.len()
        );

        for cap in 0..=all.len() + 2 {
            let got = correlated_pairs(op, Some(cap), &store);
            let want = &all[..cap.min(all.len())];

            assert_eq!(
                got, want,
                "cap {cap} for {op:?} must be the uncapped prefix"
            );
        }
    }
}

/// The EQUALITY shape is the one item 283's design lost on: the answer is exactly one row per
/// left row, so a cap equal to the left count can only be filled by visiting every left row.
/// A loop that stopped after the first left row would return one row here.
#[test]
fn a_capped_correlated_equality_visits_every_left_row() {
    let store = correlated_product_store();
    let got = correlated_pairs(CompareOp::Eq, Some(3), &store);

    assert_eq!(
        got,
        vec![
            "Num(0.0)/Num(0.0)",
            "Num(1.0)/Num(1.0)",
            "Num(2.0)/Num(2.0)",
        ],
        "one row per left row, left-major"
    );
}

/// A cap the FIRST left row fills on its own must not visit a second — and the only
/// observable of that is which rows come back, so this asserts them rather than the work.
#[test]
fn a_capped_correlated_product_fills_from_the_first_left_row() {
    let store = correlated_product_store();
    // `u.k > 0` holds for 11 of the 12 users, so a cap of 4 is filled by left row 0 alone.
    let got = correlated_pairs(CompareOp::Gt, Some(4), &store);

    assert_eq!(
        got,
        vec![
            "Num(0.0)/Num(1.0)",
            "Num(0.0)/Num(2.0)",
            "Num(0.0)/Num(3.0)",
            "Num(0.0)/Num(4.0)",
        ],
        "every row must come from the first left row, in ascending right order"
    );
}

/// An IMPOSSIBLE correlation: no pair survives, so the cap never fills and the loop runs to
/// completion. It must answer EMPTY rather than loop, over-read, or return a stale row — and
/// the width must survive, because a following operator reads a slot.
#[test]
fn an_impossible_correlated_correlation_under_a_cap_is_empty() {
    let mut b = Builder::default();
    b.node(&["Tiny"], &[("k", n(1.0))]);
    b.node(&["User"], &[("k", n(500.0))]);
    let store = b.build();

    let plan = Plan::OrderPage {
        input: Box::new(Plan::Project {
            input: Box::new(Plan::Filter {
                input: Box::new(Plan::Join {
                    left: Box::new(scan("Tiny")),
                    right: Box::new(scan("User")),
                    on: vec![],
                }),
                // `u.k = s.k` with 500 against 1 — never true.
                pred: cmp(CompareOp::Eq, prop(1, "k"), prop(0, "k")),
            }),
            items: vec![("s".to_string(), prop(0, "k"))],
        }),
        keys: vec![],
        skip: None,
        limit: Some(5),
        fault_on_element: false,
    };

    let out = run(&plan, &store);

    assert_eq!(
        out.rows.len(),
        0,
        "no pair survives, so no row may be emitted"
    );
}

/// An EMPTY side under a cap. Neither loop body runs, and the arm must still produce a batch of
/// the right WIDTH — `Batch::of` over empty gathers, not a bare empty batch, because a
/// following operator reads slot 1.
#[test]
fn a_capped_correlated_product_over_an_empty_side_is_empty() {
    for (tiny, user) in [(0, 3), (3, 0), (0, 0)] {
        let mut b = Builder::default();
        for i in 0..tiny {
            b.node(&["Tiny"], &[("k", n(f64::from(i)))]);
        }
        for i in 0..user {
            b.node(&["User"], &[("k", n(f64::from(i)))]);
        }
        let store = b.build();

        let got = correlated_pairs(CompareOp::Gt, Some(4), &store);

        assert!(
            got.is_empty(),
            "an empty side must yield no rows (tiny={tiny}, user={user}), got {got:?}"
        );
    }
}

/// A cap LARGER than the answer returns the whole answer — the bound must not truncate below
/// what exists, which is the off-by-one in the other direction from the prefix test's.
#[test]
fn a_capped_correlated_product_under_a_slack_cap_is_complete() {
    let store = correlated_product_store();
    let all = correlated_pairs(CompareOp::Eq, None, &store);
    let got = correlated_pairs(CompareOp::Eq, Some(1000), &store);

    assert_eq!(got, all, "a slack cap must not lose a row");
}

/// THE BLOCK BOUNDARY. The arm walks the right side in blocks that START at 256 and DOUBLE, so
/// every bound in it is exercised only by a right side bigger than 256 — a 12-row fixture runs
/// one block and proves nothing about the stride, the doubling, or the `(start + block).min()`
/// clamp. This fixture spans several blocks and puts the ONLY surviving pair in the last one.
#[test]
fn a_capped_correlated_product_finds_a_match_past_the_first_block() {
    let mut b = Builder::default();
    b.node(&["Tiny"], &[("k", n(900.0))]);
    for i in 0..1000 {
        b.node(&["User"], &[("k", n(f64::from(i)))]);
    }
    let store = b.build();

    // Exactly one pair matches, at right row 900 — past the first block (256) and past the
    // second (512), so it is found only if the stride advances correctly.
    let got = correlated_pairs(CompareOp::Eq, Some(1), &store);

    assert_eq!(
        got,
        vec!["Num(900.0)/Num(900.0)"],
        "the match lies past the first blocks and must still be found"
    );
}

/// And the same fixture with a cap of 2, where the second survivor is in a LATER block than the
/// first — so the loop must resume from where it stopped rather than restarting or skipping.
#[test]
fn a_capped_correlated_product_resumes_across_blocks() {
    let mut b = Builder::default();
    b.node(&["Tiny"], &[("k", n(300.0))]);
    for i in 0..1000 {
        b.node(&["User"], &[("k", n(f64::from(i)))]);
    }
    let store = b.build();

    // `u.k >= 300` survives for right rows 300..999: the first survivor is in the block
    // covering 256..768 and the 600th is far later.
    let got = correlated_pairs(CompareOp::Ge, Some(3), &store);

    assert_eq!(
        got,
        vec![
            "Num(300.0)/Num(300.0)",
            "Num(300.0)/Num(301.0)",
            "Num(300.0)/Num(302.0)",
        ],
        "survivors must be ascending and contiguous across the block stride"
    );
}

/// `pull_capped`'s CONTRACT, asserted directly rather than through its caller: at most `cap`
/// rows, for every cap.
///
/// This exists because mutation P2 — move the cap check from BEFORE the push to after it, so
/// the loop keeps one row too many — SURVIVED the whole suite. The reason is a masking layer:
/// `pull_capped`'s only caller is the keyless `OrderPage` arm, which passes `skip + limit` and
/// then calls `order_page` to slice to `limit` anyway. So over-producing by one row is invisible
/// through every query-level test, and `cap == 0` (unreachable in practice, since `LIMIT 0` is
/// short-circuited earlier) is invisible twice over.
///
/// The documented contract is still "at most `cap`", and the other row-multiplying arms uphold
/// it with `truncate_batch`. A guard that only the contract observes needs a test that observes
/// the contract — calling `pull_capped` itself, with the slicing caller removed from the
/// picture. That is the "remove the masking layer in the same mutant" rule applied as a test
/// rather than as a mutant.
#[test]
fn pull_capped_never_exceeds_its_cap_on_a_correlated_product() {
    let store = correlated_product_store();
    // The `Filter { Join }` body WITHOUT the `OrderPage` wrapper, so nothing slices afterwards.
    let body = correlated_limited_product(CompareOp::Gt, None);

    for cap in 0..=40 {
        let got = super::pull_capped(&body, &store, false, cap)
            .expect("the arm must not fault")
            .expect("the arm must accept a Filter over an empty-on Join");

        assert!(
            got.rows() <= cap,
            "pull_capped returned {} rows for cap {cap}",
            got.rows()
        );
    }
}

/// LEFT-MAJOR, across a BLOCK BOUNDARY, with a left row whose matches lie in a LATER block than
/// a different left row's.
///
/// This test exists because a compiling RIGHT-MAJOR loop (mutant P1b) passed every other test
/// in this file, including the prefix test. The reason is a fixture artefact worth writing down:
/// while the whole right side fits inside ONE block, right-major DEGENERATES to left-major —
/// the block loop runs once and the inner left loop then yields left row 0's survivors first,
/// which is the same order. And while left row 0 has at least `cap` survivors inside the first
/// block, the two orders also agree, because the cap fills before the second left row is
/// reached. Every other fixture here hits one of those two cases.
///
/// So the distinguishing shape needs: a right side spanning several blocks, AND a left row
/// whose only match is in a LATE block while a LATER left row matches in the FIRST one. Here
/// `s300` matches only right row 300 (third block) and `s0` matches right row 0 (first block):
/// left-major must answer `s300` first, right-major answers `s0` first.
#[test]
fn a_capped_correlated_product_is_left_major_across_blocks() {
    let mut b = Builder::default();
    b.node(&["Tiny"], &[("k", n(300.0))]);
    b.node(&["Tiny"], &[("k", n(0.0))]);
    for i in 0..600 {
        b.node(&["User"], &[("k", n(f64::from(i)))]);
    }
    let store = b.build();

    let all = correlated_pairs(CompareOp::Eq, None, &store);

    assert_eq!(
        all,
        vec!["Num(300.0)/Num(300.0)", "Num(0.0)/Num(0.0)"],
        "the UNCAPPED answer is left-major, which is what the cap must prefix"
    );

    let got = correlated_pairs(CompareOp::Eq, Some(1), &store);

    assert_eq!(
        got,
        vec!["Num(300.0)/Num(300.0)"],
        "cap 1 must take the FIRST left row's match, which lives in a later block than the \
         second left row's — a right-major loop answers Num(0.0)/Num(0.0) here"
    );
}

/// A named PATH across the join, under a cap, carries each row's OWN path.
///
/// `hash_join` has this guarded (`a_path_above_a_join_carries_the_right_rows`), and the new
/// capped arm COPIES its rule — left lineage wins, because a path written before the comma lands
/// there. Mutation showed the copy was not covered by that test: reversing the preference in
/// `hash_join` fails it, and reversing it in the capped arm passed the whole suite. A rule
/// copied from a guarded place is not itself guarded.
#[test]
fn a_path_above_a_capped_correlated_product_carries_its_own_rows() {
    let nd = [
        r#"{"id":"1","labels":["T"],"props":{"n":1}}"#,
        r#"{"id":"2","labels":["T"],"props":{"n":2}}"#,
        r#"{"id":"3","labels":["T"],"props":{"n":3}}"#,
        r#"{"from":"1","to":"2","labels":["E"],"props":{}}"#,
        r#"{"from":"3","to":"2","labels":["E"],"props":{}}"#,
    ]
    .join("\n");
    let store = crate::ndjson::from_ndjson(&nd).unwrap();
    // A correlating predicate (`c.n > a.n`) over a comma product, so the `Filter` stays ABOVE
    // the join and the capped arm takes it; `p` is named on the LEFT pattern.
    let q = "MATCH p = (a:T)-[:E]->(b), (c:T) WHERE c.n > a.n \
             RETURN nodes(p) AS ns, a.n AS t LIMIT 1";
    let rows = crate::exec::try_run(&opt_plan(q, &store), &store).unwrap();

    assert_eq!(rows.rows.len(), 1, "the cap must be filled exactly");

    let ns = format!("{:?}", rows.rows[0][0]);
    let t = format!("{:?}", rows.rows[0][1]);
    // Whichever row the cap kept, its path must START at that row's own `a` — the lineage
    // taken from the RIGHT side would carry `c`'s (absent) path or another row's.
    let want_first = match t.as_str() {
        "Num(1.0)" => "\"1\"",
        "Num(3.0)" => "\"3\"",
        other => panic!("unexpected a.n {other}"),
    };

    assert!(
        ns.contains(want_first),
        "the kept row (a.n={t}) must start its path at {want_first}: {ns}"
    );
}

/// A fan-out fixture for the frontier guard: `n` `P` nodes, each with `deg` out-edges, so a
/// `h`-hop pattern materializes `n * deg^h` rows at width `h + 1`.
fn fanout_store(nodes: u32, deg: u32) -> Store {
    let mut b = Builder::default();
    for i in 0..nodes {
        b.node(&["P"], &[("k", n(f64::from(i % 50)))]);
    }
    for i in 0..nodes {
        for d in 0..deg {
            b.edge(i, (i * 7919 + d) % nodes, "E");
        }
    }
    b.build()
}

/// A `hops`-segment chain PROJECTING the far node — deliberately not `count(*)`, which `exec`
/// answers with a degree-product tally that never runs the expansion at all. (The first version
/// of this item's probe used `count(*)` and measured nothing; so did `count(far.k)`.)
fn hop_project(hops: usize) -> String {
    let mut q = String::from("MATCH (a:P)");
    for h in 0..hops {
        q.push_str(&format!("-[:E]->(x{h})"));
    }
    format!("{q} RETURN x{}.k AS k", hops - 1)
}

/// THE reason the frontier ceiling needs a WIDTH dimension, and the direct analogue of
/// `the_ceiling_counts_path_elements_not_just_rows` one step over: two expansions over the same
/// fixture reach the SAME row count at DIFFERENT widths, and it is the width that decides what
/// the gathers allocate.
///
/// A 3-hop chain over 400 nodes at degree 5 is 50,000 rows at width 4; a 1-hop chain over the
/// same fixture reaches 2,000 rows at width 2. A cells ceiling placed between them stops the
/// wide one and passes the narrow one, with the ROW ceiling left wide open in both — which is
/// what a row-counting guard cannot express.
#[test]
fn the_frontier_ceiling_counts_cells_not_just_rows() {
    let mut store = fanout_store(400, 5);
    store.set_limit(crate::store::ConfigId::LimitsIntermediate, 50_000_000);
    // 2,000 rows x 2 slots = 4,000 cells for one hop; 50,000 x 4 = 200,000 for three.
    store.set_limit(crate::store::ConfigId::LimitsIntermediateCells, 100_000);

    assert_eq!(
        try_gql(&hop_project(1), &store),
        Ok(2_000),
        "one hop is 4,000 cells and must pass"
    );

    let err = try_gql(&hop_project(3), &store).expect_err("three hops is 200,000 cells");
    assert!(err.starts_with("E_RESOURCE_EXHAUSTED"), "{err}");
    assert!(
        err.contains("cells"),
        "the message must name the unit: {err}"
    );
}

/// PREDICTIVE, not reactive: the guard must stop the expansion PART-WAY, so the row count it
/// reports is smaller than the frontier the query would have produced.
///
/// This is the whole point of moving the check inside `expand`. `guard_intermediate` inspects an
/// already-built batch — Rust evaluates `guard_intermediate(expand(...))`'s argument first — so
/// it can only report the FULL size, after paying for it. A reported count below the full
/// product is the observable proof that the allocation was abandoned early.
#[test]
fn the_frontier_ceiling_stops_the_expansion_part_way() {
    let mut store = fanout_store(400, 5);
    store.set_limit(crate::store::ConfigId::LimitsIntermediateCells, 100_000);

    let err = try_gql(&hop_project(3), &store).expect_err("must trip");
    // The full 3-hop frontier is 50,000 rows; the ceiling is 100,000 cells at width 4, so it
    // must give up around 25,000 rows — comfortably under the full product.
    let reported: u64 = err
        .split(" reached ")
        .nth(1)
        .and_then(|s| s.split(' ').next())
        .and_then(|s| s.parse().ok())
        .unwrap_or_else(|| panic!("the message must report a row count: {err}"));

    assert!(
        reported < 50_000,
        "the guard must abandon BEFORE the full 50,000-row frontier, got {reported}"
    );
    assert!(reported > 0, "it must report what it had built: {reported}");
}

/// The guard costs a query under the ceiling nothing: every row comes back.
#[test]
fn a_frontier_under_the_cells_ceiling_returns_every_row() {
    let store = fanout_store(400, 5);

    // Defaults: 200M cells. Three hops is 200,000 cells — four orders of magnitude under.
    assert_eq!(try_gql(&hop_project(3), &store), Ok(50_000));
}

/// A ceiling that cannot be moved is not a limit. Raising it must admit a query it refused;
/// lowering it must refuse one it admitted.
#[test]
fn the_cells_ceiling_is_a_knob_in_both_directions() {
    let mut raised = fanout_store(400, 5);
    raised.set_limit(crate::store::ConfigId::LimitsIntermediateCells, u64::MAX);
    assert_eq!(
        try_gql(&hop_project(3), &raised),
        Ok(50_000),
        "raised: the refused query must now pass"
    );

    let mut lowered = fanout_store(400, 5);
    lowered.set_limit(crate::store::ConfigId::LimitsIntermediateCells, 1_000);
    let err = try_gql(&hop_project(1), &lowered)
        .expect_err("lowered: 2,000 rows x 2 slots must exceed 1,000 cells");
    assert!(err.starts_with("E_RESOURCE_EXHAUSTED"), "{err}");
}

/// The ROW ceiling still fires on its own, so the new dimension is additive rather than a
/// replacement — an existing deployment's `limits.intermediate` keeps its meaning.
#[test]
fn the_row_ceiling_still_fires_independently_of_cells() {
    let mut store = fanout_store(400, 5);
    // Cells wide open, rows tight: the 50,000-row 3-hop frontier must still be refused.
    store.set_limit(crate::store::ConfigId::LimitsIntermediateCells, u64::MAX);
    store.set_limit(crate::store::ConfigId::LimitsIntermediate, 5_000);

    let err = try_gql(&hop_project(3), &store).expect_err("the row ceiling must still bite");
    assert!(err.starts_with("E_RESOURCE_EXHAUSTED"), "{err}");
    assert!(
        err.contains("rows exceeded") || err.contains("cells"),
        "either guard may claim it, but it must be a resource error: {err}"
    );
}

/// An EMPTY expansion is not a frontier: an unknown edge type, and a source column holding no
/// nodes, must both answer empty rather than tripping a ceiling of zero.
#[test]
fn an_empty_expansion_does_not_trip_a_zero_ceiling() {
    let mut store = fanout_store(400, 5);
    store.set_limit(crate::store::ConfigId::LimitsIntermediateCells, 0);

    // An unknown edge type matches nothing, so no row is ever pushed and the check — which
    // runs on `keep.len()` BEFORE the first push — sees zero cells.
    assert_eq!(
        try_gql("MATCH (a:P)-[:NOPE]->(x) RETURN x.k AS k", &store),
        Ok(0),
        "an unknown edge type expands to nothing and must not trip"
    );
}

/// The width must be counted EXACTLY, and these two tests exist because mutation proved it was
/// not: dropping the landed-node slot (`+ 1`) and dropping the bound-edge slot both SURVIVED the
/// tests above, whose ceilings sat far enough from the boundary that an off-by-one in width
/// flipped no outcome. Width is the entire claim of this ceiling, so it needs a ceiling placed
/// where one slot decides.
///
/// One hop over 400 nodes at degree 5 is 2,000 rows at width 2 = 4,000 cells. A ceiling of
/// 3,000 trips on the true width and PASSES on width 1.
#[test]
fn the_landed_node_slot_counts_toward_the_width() {
    let mut store = fanout_store(400, 5);
    store.set_limit(crate::store::ConfigId::LimitsIntermediateCells, 3_000);

    let err = try_gql(&hop_project(1), &store)
        .expect_err("2,000 rows x 2 slots = 4,000 cells must exceed 3,000");
    assert!(err.starts_with("E_RESOURCE_EXHAUSTED"), "{err}");
    assert!(
        err.contains("x 2 slots"),
        "the width must be reported as 2 (start + landed), got: {err}"
    );
}

/// And the bound EDGE slot: `-[r:E]->` gathers a third column, so the same 2,000 rows are 6,000
/// cells rather than 4,000. A ceiling of 5,000 trips only if the edge slot is counted.
#[test]
fn a_bound_edge_slot_counts_toward_the_width() {
    let mut store = fanout_store(400, 5);
    store.set_limit(crate::store::ConfigId::LimitsIntermediateCells, 5_000);

    // Without the edge bound: 2,000 x 2 = 4,000 cells, under the ceiling.
    assert_eq!(
        try_gql(&hop_project(1), &store),
        Ok(2_000),
        "the unbound-edge spelling is 4,000 cells and must pass"
    );

    // With it bound: 2,000 x 3 = 6,000 cells, over.
    let err = try_gql("MATCH (a:P)-[r:E]->(x) RETURN x.k AS k", &store)
        .expect_err("binding the edge adds a slot and must trip");
    assert!(err.starts_with("E_RESOURCE_EXHAUSTED"), "{err}");
    assert!(
        err.contains("x 3 slots"),
        "the width must be reported as 3 (start + edge + landed), got: {err}"
    );
}

/// The index-backed `count(DISTINCT n.k)` must answer exactly what the column SCAN answers
/// (audit item 369). This is a DIFFERENTIAL test against the path it replaces, which is the only
/// form worth having for a fast path: the same store and the same query, run with and without the
/// index, must agree on every shape — and where they could disagree (a present null, an absent
/// property, a dotted path, a non-vacuous label) is exactly what the rows below are.
///
/// A fast path that is WRONG is worse than one that is slow, so the gates are identical to
/// `try_scan_distinct_count`'s and the two extra preconditions (an index on the key, a vacuous
/// label) only ever make this one DECLINE.
#[test]
fn an_indexed_distinct_count_agrees_with_the_scan() {
    // `Value` has no `PartialEq` (the same reason `parse_cache` compares plans through `Debug`),
    // and `Debug` is the right currency anyway: two answers that render identically are the same
    // answer.
    let answer = |store: &crate::store::Store, q: &str| -> String {
        let plan = crate::opt::optimize_indexed(crate::gql::parse(q).unwrap(), store);

        format!("{:?}", run(&plan, store).rows[0][0])
    };

    // `P` is on every node, so it is VACUOUS and the shortcut may fire; `Q` is on one, so it is
    // not and the shortcut must decline.
    let nd = concat!(
        "{\"id\":\"a\",\"labels\":[\"P\"],\"props\":{\"k\":\"x\",\"n\":1}}\n",
        "{\"id\":\"b\",\"labels\":[\"P\"],\"props\":{\"k\":\"y\",\"n\":1}}\n",
        "{\"id\":\"c\",\"labels\":[\"P\"],\"props\":{\"k\":\"x\",\"n\":2}}\n",
        "{\"id\":\"d\",\"labels\":[\"P\",\"Q\"],\"props\":{\"k\":\"z\",\"n\":3}}\n",
        "{\"id\":\"e\",\"labels\":[\"P\"],\"props\":{\"n\":4}}"
    );

    for q in [
        // unlabelled and vacuously labelled: the shortcut is eligible for both
        "MATCH (n) RETURN count(DISTINCT n.k) AS c",
        "MATCH (n:P) RETURN count(DISTINCT n.k) AS c",
        // NON-vacuous label: the shortcut must decline, and the answer must still be right
        "MATCH (n:Q) RETURN count(DISTINCT n.k) AS c",
        // a key one node lacks entirely
        "MATCH (n) RETURN count(DISTINCT n.n) AS c",
        // a key NOTHING has — neither path may invent a value
        "MATCH (n) RETURN count(DISTINCT n.absent) AS c",
        // NOT DISTINCT: the shortcut must not answer a plain `count(k)` with the distinct count.
        // `k` has four holders and three distinct values, so the two differ and a shortcut that
        // ignored `agg.distinct` would be caught here rather than by inspection.
        "MATCH (n) RETURN count(n.k) AS c",
        "MATCH (n:P) RETURN count(n.k) AS c",
        // GROUPED: a `GROUP BY` must not be answered by a scalar count either.
        "MATCH (n) LET g = n.n RETURN g, count(DISTINCT n.k) AS c GROUP BY g ORDER BY g",
    ] {
        let bare = crate::ndjson::from_ndjson(nd).unwrap();
        let mut indexed = crate::ndjson::from_ndjson(nd).unwrap();

        indexed.create_index("k");
        indexed.create_index("n");

        let want = answer(&bare, q);
        let got = answer(&indexed, q);

        assert_eq!(got, want, "indexed answer must match the scan for `{q}`");
    }

    // A present NULL, which is the shape item 368 was about: `count(DISTINCT …)` excludes it and
    // so does the index, but they have to agree rather than both be plausible.
    let with_null = concat!(
        "{\"id\":\"a\",\"labels\":[\"P\"],\"props\":{\"k\":\"x\"}}\n",
        "{\"id\":\"b\",\"labels\":[\"P\"],\"props\":{\"k\":null}}\n",
        "{\"id\":\"c\",\"labels\":[\"P\"],\"props\":{}}"
    );
    let q = "MATCH (n) RETURN count(DISTINCT n.k) AS c";
    let bare = crate::ndjson::from_ndjson(with_null).unwrap();
    let mut indexed = crate::ndjson::from_ndjson(with_null).unwrap();

    indexed.create_index("k");

    assert_eq!(answer(&bare, q), "Num(1.0)", "only `x` is a value");
    assert_eq!(answer(&indexed, q), "Num(1.0)", "and the index agrees");

    // THE SHORTCUT MUST ACTUALLY FIRE — a test that only compares answers passes with the
    // shortcut deleted. `try_indexed_distinct_count` returns `Some` exactly when it is eligible,
    // so it is asserted directly: eligible for an indexed key, declining for an unindexed one and
    // for a non-vacuous label.
    let mut st = crate::ndjson::from_ndjson(nd).unwrap();

    st.create_index("k");

    let eligible = |q: &str, store: &crate::store::Store| -> bool {
        let plan = crate::opt::optimize_indexed(crate::gql::parse(q).unwrap(), store);
        let crate::ir::Plan::Project { input, .. } = &plan else {
            panic!("expected a Project");
        };
        let crate::ir::Plan::Aggregate { input, keys, aggs } = input.as_ref() else {
            panic!("expected an Aggregate");
        };

        crate::exec::fastpath::try_indexed_distinct_count(input, keys, aggs, store).is_some()
    };

    assert!(
        eligible("MATCH (n) RETURN count(DISTINCT n.k) AS c", &st),
        "an indexed key over an unlabelled scan must take the shortcut"
    );
    assert!(
        eligible("MATCH (n:P) RETURN count(DISTINCT n.k) AS c", &st),
        "...and over a VACUOUS label"
    );
    assert!(
        !eligible("MATCH (n:Q) RETURN count(DISTINCT n.k) AS c", &st),
        "a NON-vacuous label must decline: the index is any-label"
    );
    assert!(
        !eligible("MATCH (n) RETURN count(DISTINCT n.n) AS c", &st),
        "an UNINDEXED key must decline"
    );

    // THE GATES THAT DISPATCH ORDER WOULD OTHERWISE HIDE, asserted directly on the function the
    // way `try_scan_count_prop` tests its own dotted decline.
    //
    // A broken `distinct` or `keys` gate here cannot be observed through a QUERY: a non-distinct
    // `count(plain_prop)` is claimed by `try_scan_count_prop` earlier in the chain, and a dotted
    // argument lowers to `Expr::Field`, not `Expr::Prop`, so it never matches this pattern at all.
    // Both gates are therefore defensive — and relying on the order of the fast-path chain for
    // CORRECTNESS is exactly the kind of thing that breaks when someone reorders it, so they are
    // pinned where the reliance is not needed.
    assert!(
        !eligible("MATCH (n) RETURN count(n.k) AS c", &st),
        "a NON-DISTINCT count must decline: this answers the distinct count"
    );
    assert!(
        !eligible(
            "MATCH (n) LET g = n.n RETURN g, count(DISTINCT n.k) AS c GROUP BY g",
            &st
        ),
        "a GROUPED count must decline: this answers one scalar"
    );
}

/// The range-index `min`/`max` must answer exactly what the column scan answers (audit item 371),
/// including where the two could plausibly diverge: a NaN, a mixed-type column, a present null, an
/// absent property and a non-vacuous label.
///
/// DIFFERENTIAL against the path it replaces — the same store and query with and without the range
/// index. The order claim ("`OrdVal` compares by `cmp_total`, which is what min/max use") is a claim
/// about two comparators agreeing, and reading them is not evidence; the mixed-type and NaN rows
/// are.
#[test]
fn an_indexed_min_max_agrees_with_the_scan() {
    let answer = |store: &crate::store::Store, q: &str| -> String {
        let plan = crate::opt::optimize_indexed(crate::gql::parse(q).unwrap(), store);

        format!("{:?}", run(&plan, store).rows[0][0])
    };

    // `P` is on every node (VACUOUS); `Q` on one, so it is not.
    let numeric = concat!(
        "{\"id\":\"a\",\"labels\":[\"P\"],\"props\":{\"n\":10}}\n",
        "{\"id\":\"b\",\"labels\":[\"P\"],\"props\":{\"n\":-3.5}}\n",
        "{\"id\":\"c\",\"labels\":[\"P\",\"Q\"],\"props\":{\"n\":99}}\n",
        "{\"id\":\"d\",\"labels\":[\"P\"],\"props\":{}}"
    );
    // A column the engine cannot keep numeric: strings AND numbers, so `Column::Num`'s fast path
    // cannot serve it and only the GENERAL aggregate can — the shape where an order disagreement
    // would show.
    let mixed = concat!(
        "{\"id\":\"a\",\"labels\":[\"P\"],\"props\":{\"m\":10}}\n",
        "{\"id\":\"b\",\"labels\":[\"P\"],\"props\":{\"m\":\"zebra\"}}\n",
        "{\"id\":\"c\",\"labels\":[\"P\"],\"props\":{\"m\":\"apple\"}}\n",
        "{\"id\":\"d\",\"labels\":[\"P\"],\"props\":{\"m\":-1}}"
    );
    // A present NULL beside real values: min/max ignore it, and so does the index.
    let nulled = concat!(
        "{\"id\":\"a\",\"labels\":[\"P\"],\"props\":{\"k\":5}}\n",
        "{\"id\":\"b\",\"labels\":[\"P\"],\"props\":{\"k\":null}}\n",
        "{\"id\":\"c\",\"labels\":[\"P\"],\"props\":{\"k\":2}}"
    );
    // Nothing carries the key at all: both paths must answer NULL, not invent a value.
    let empty = "{\"id\":\"a\",\"labels\":[\"P\"],\"props\":{\"other\":1}}";

    for (nd, key, queries) in [
        (
            numeric,
            "n",
            &[
                "MATCH (n) RETURN min(n.n) AS v",
                "MATCH (n) RETURN max(n.n) AS v",
                "MATCH (n:P) RETURN min(n.n) AS v",
                "MATCH (n:P) RETURN max(n.n) AS v",
                // NON-vacuous label: the shortcut must decline and the answer must still be right
                "MATCH (n:Q) RETURN min(n.n) AS v",
                "MATCH (n:Q) RETURN max(n.n) AS v",
                // DISTINCT is declined by every sibling, so it must stay on the general path
                "MATCH (n) RETURN min(DISTINCT n.n) AS v",
            ][..],
        ),
        (
            mixed,
            "m",
            &[
                "MATCH (n) RETURN min(n.m) AS v",
                "MATCH (n) RETURN max(n.m) AS v",
            ][..],
        ),
        (
            nulled,
            "k",
            &[
                "MATCH (n) RETURN min(n.k) AS v",
                "MATCH (n) RETURN max(n.k) AS v",
            ][..],
        ),
        (
            empty,
            "nothing",
            &[
                "MATCH (n) RETURN min(n.nothing) AS v",
                "MATCH (n) RETURN max(n.nothing) AS v",
            ][..],
        ),
    ] {
        for q in queries {
            let bare = crate::ndjson::from_ndjson(nd).unwrap();
            let mut indexed = crate::ndjson::from_ndjson(nd).unwrap();

            indexed.create_range_index(key);

            assert_eq!(
                answer(&indexed, q),
                answer(&bare, q),
                "indexed answer must match the scan for `{q}`"
            );
        }
    }

    // A NaN, which the fixture cannot express (ingest coerces it to null) — computed with SET, the
    // way the differential fuzzer has to. The repo's policy puts NaN LAST in the total order, so it
    // is the maximum, and the index must agree.
    let mut bare = crate::ndjson::from_ndjson(numeric).unwrap();
    let mut indexed = crate::ndjson::from_ndjson(numeric).unwrap();

    for st in [&mut bare, &mut indexed] {
        let plan = crate::opt::optimize_indexed(
            crate::gql::parse("MATCH (n) WHERE n.n = 10 SET n.n = sin(1e400) RETURN count(*) AS c")
                .unwrap(),
            st,
        );

        crate::exec::run_query(plan, st).expect("the SET runs");
    }

    indexed.create_range_index("n");

    for q in [
        "MATCH (n) RETURN min(n.n) AS v",
        "MATCH (n) RETURN max(n.n) AS v",
    ] {
        assert_eq!(
            answer(&indexed, q),
            answer(&bare, q),
            "a NaN must sort the same for the index and the scan: `{q}`"
        );
    }

    // THE SHORTCUT MUST ACTUALLY FIRE. A differential test passes with the shortcut DELETED, so
    // eligibility is asserted on the function directly — the same reason item 369 does.
    let mut st = crate::ndjson::from_ndjson(numeric).unwrap();

    st.create_range_index("n");

    let eligible = |q: &str, store: &crate::store::Store| -> bool {
        let plan = crate::opt::optimize_indexed(crate::gql::parse(q).unwrap(), store);
        let crate::ir::Plan::Project { input, .. } = &plan else {
            panic!("expected a Project");
        };
        let crate::ir::Plan::Aggregate { input, keys, aggs } = input.as_ref() else {
            panic!("expected an Aggregate");
        };

        crate::exec::fastpath::try_indexed_min_max(input, keys, aggs, store).is_some()
    };

    assert!(
        eligible("MATCH (n) RETURN min(n.n) AS v", &st),
        "unlabelled min"
    );
    assert!(
        eligible("MATCH (n) RETURN max(n.n) AS v", &st),
        "unlabelled max"
    );
    assert!(
        eligible("MATCH (n:P) RETURN min(n.n) AS v", &st),
        "a VACUOUS label is eligible"
    );
    assert!(
        !eligible("MATCH (n:Q) RETURN min(n.n) AS v", &st),
        "a NON-vacuous label must decline: the index is any-label"
    );
    assert!(
        !eligible("MATCH (n) RETURN min(n.other) AS v", &st),
        "a key with no RANGE index must decline"
    );
    assert!(
        !eligible("MATCH (n) RETURN min(DISTINCT n.n) AS v", &st),
        "DISTINCT declines, matching every sibling fast path"
    );
    assert!(
        !eligible("MATCH (n) RETURN avg(n.n) AS v", &st),
        "only min and max"
    );
}

/// REGRESSION for audit item 373: `SHORTEST k` (k >= 2) over an UNBOUNDED quantifier must FAULT,
/// not take the process down.
///
/// `collect_trails` enumerates every edge-disjoint trail and clones each into `per_end`. Its only
/// bound was "a trail may not reuse an edge" — which bounds DEPTH and says nothing about the
/// NUMBER of trails, and that number is superexponential. The BFS selectors (`Any`/`All`) were
/// always under the trail limit; `SHORTEST k` routes to `shortest_k_path` and so around it.
///
/// **TWENTY nodes and sixty edges exhausted a 4 GB cgroup cap.** It is not a scale problem — the
/// same query OOMs at n=20 and n=120 alike — so this test is cheap: a tiny graph and a tiny limit
/// fault in microseconds. The TS engine already raised here (`E_RESOURCE_EXHAUSTED`), so native
/// was the one out of step, and the fix brings the two onto the same ceiling.
#[test]
fn a_shortest_k_over_an_unbounded_quantifier_faults_instead_of_exhausting_memory() {
    use crate::store::ConfigId;

    let mut b = crate::store::Builder::default();
    for _ in 0..20u32 {
        b.node(&["N"], &[]);
    }
    // Dense enough that the trail count explodes; small enough that the fault is instant.
    let mut seed = 99u64;
    for i in 0..20u32 {
        for _ in 0..3 {
            seed = seed.wrapping_mul(6_364_136_223_846_793_005).wrapping_add(1);
            b.edge(i, ((seed >> 33) as u32) % 20, "R");
        }
    }

    let mut store = b.build();

    store.set_limit(ConfigId::LimitsTrail, 5_000);

    for q in [
        "MATCH p = SHORTEST 2 (x:N)-[:R]->*(y:N) RETURN cardinality(p) AS n",
        "MATCH p = SHORTEST 2 (x:N)-[:R]->+(y:N) RETURN cardinality(p) AS n",
        "MATCH p = SHORTEST 3 (x:N)-[:R]->*(y:N) RETURN cardinality(p) AS n",
    ] {
        let plan = crate::opt::optimize_indexed(crate::gql::parse(q).unwrap(), &store);
        let err = crate::exec::try_run(&plan, &store).expect_err(&format!("{q} must fault"));

        assert!(
            err.contains("E_RESOURCE_EXHAUSTED"),
            "{q}: want a resource fault, got {err:?}"
        );
    }

    // AND THE SHAPES THAT MUST STILL WORK — the guard may only stop the runaway. Each of these
    // enumerates few enough trails to finish, and a budget that refused them would be a
    // regression dressed as a fix.
    for q in [
        "MATCH p = ANY SHORTEST (x:N)-[:R]->*(y:N) RETURN count(*) AS c",
        "MATCH p = SHORTEST 1 (x:N)-[:R]->*(y:N) RETURN count(*) AS c",
        "MATCH p = SHORTEST 2 (x:N)-[:R]->{1,3}(y:N) RETURN count(*) AS c",
    ] {
        let plan = crate::opt::optimize_indexed(crate::gql::parse(q).unwrap(), &store);

        crate::exec::try_run(&plan, &store).unwrap_or_else(|e| panic!("{q} must run, got {e}"));
    }
}

/// Item 372: `try_varlen_agg` folds the aggregate during the walk, but it matched
/// `Plan::VarLength` DIRECTLY — and an endpoint LABEL lowers to a `Filter` ABOVE the hop, so
/// `(b:Person)` sent the fold to the materializing aggregate while `(b)` kept it. Peeling that
/// filter is only correct if the label is actually APPLIED during the fold, and the fixture is
/// what decides whether this test can tell: on a graph where every node carries the label,
/// every assertion below passes with the guard deleted. Hence MIXED labels and hand-computed
/// expectations.
///
/// 4 nodes, `KNOWS` edges 0->1, 0->2, 1->3, 2->3. A `{1,2}` trail reaches, as a multiset:
/// from 0 — 1, 2, 3 (via 1), 3 (via 2); from 1 — 3; from 2 — 3. So endpoints are
/// [1, 2, 3, 3, 3, 3] with ages [100, 20, 200, 200, 200, 200].
#[test]
fn an_endpoint_label_on_a_varlen_aggregate_is_applied_during_the_fold() {
    use crate::value::Value;

    let mut b = crate::store::Builder::default();
    b.node(&["Person"], &[("age", Value::Num(10.0))]); // 0
    b.node(&["Robot"], &[("age", Value::Num(100.0))]); // 1
    b.node(&["Person"], &[("age", Value::Num(20.0))]); // 2
    b.node(&["Robot"], &[("age", Value::Num(200.0))]); // 3
    b.edge(0, 1, "KNOWS");
    b.edge(0, 2, "KNOWS");
    b.edge(1, 3, "KNOWS");
    b.edge(2, 3, "KNOWS");
    let store = b.build();

    let scalar = |q: &str| -> f64 {
        let plan = crate::opt::optimize_indexed(crate::gql::parse(q).unwrap(), &store);
        let out = crate::exec::try_run(&plan, &store).unwrap_or_else(|e| panic!("{q}: {e}"));
        match &out.rows[0][0] {
            Value::Num(n) => *n,
            other => panic!("{q}: want a number, got {other:?}"),
        }
    };

    // The three spellings disagree BY CONSTRUCTION, which is what gives the rest its teeth:
    // a guard that did nothing would make all three equal 920.
    assert_eq!(
        scalar("MATCH (a)-[:KNOWS]->{1,2}(b) RETURN sum(b.age) AS n"),
        920.0
    );
    assert_eq!(
        scalar("MATCH (a)-[:KNOWS]->{1,2}(b:Person) RETURN sum(b.age) AS n"),
        20.0
    );
    assert_eq!(
        scalar("MATCH (a)-[:KNOWS]->{1,2}(b:Robot) RETURN sum(b.age) AS n"),
        900.0
    );

    assert_eq!(
        scalar("MATCH (a)-[:KNOWS]->{1,2}(b) RETURN max(b.age) AS n"),
        200.0
    );
    assert_eq!(
        scalar("MATCH (a)-[:KNOWS]->{1,2}(b:Person) RETURN max(b.age) AS n"),
        20.0
    );
    assert_eq!(
        scalar("MATCH (a)-[:KNOWS]->{1,2}(b:Person) RETURN min(b.age) AS n"),
        20.0
    );
    assert_eq!(
        scalar("MATCH (a)-[:KNOWS]->{1,2}(b:Robot) RETURN min(b.age) AS n"),
        100.0
    );

    // An EQUIVALENT spelling of the same label test. GQL lowers `(b:Person)` and
    // `WHERE 'Person' IN labels(b)` to the same `IsLabeled`, so the two must not diverge —
    // the invariant that a predicate's spelling cannot change its answer or its cost.
    assert_eq!(
        scalar("MATCH (a)-[:KNOWS]->{1,2}(b) WHERE 'Person' IN labels(b) RETURN sum(b.age) AS n"),
        20.0
    );

    // A VACUOUS label takes the tautology arm (every live node carries it), which skips the
    // membership test entirely. It must still be the bare answer, not a silently empty one.
    let mut u = crate::store::Builder::default();
    for i in 0..4u32 {
        u.node(&["Person"], &[("age", Value::Num(f64::from(i) * 10.0))]);
    }
    u.edge(0, 1, "KNOWS");
    u.edge(1, 2, "KNOWS");
    let ustore = u.build();
    let uscalar = |q: &str| -> f64 {
        let plan = crate::opt::optimize_indexed(crate::gql::parse(q).unwrap(), &ustore);
        let out = crate::exec::try_run(&plan, &ustore).unwrap_or_else(|e| panic!("{q}: {e}"));
        match &out.rows[0][0] {
            Value::Num(n) => *n,
            other => panic!("{q}: want a number, got {other:?}"),
        }
    };
    assert_eq!(
        uscalar("MATCH (a)-[:KNOWS]->{1,2}(b:Person) RETURN sum(b.age) AS n"),
        uscalar("MATCH (a)-[:KNOWS]->{1,2}(b) RETURN sum(b.age) AS n"),
    );
}

/// Item 375: `try_scan_num_agg` gained `Min`/`Max` and moved ABOVE `try_frontier_prop_agg`,
/// because a bare `Scan` is a trivial frontier and the frontier path was claiming scan
/// min/max — answering them at 6.4x what this columnar fold charges for `sum` over the same
/// column. Two paths now answer min/max, so the thing worth testing is not an expectation I
/// typed but that THE TWO AGREE.
///
/// Every node carries a self-edge, so `(a)-[:E]->(b)` reaches each node exactly once and goes
/// to `try_frontier_prop_agg`, while `(p:N)` goes to the new columnar arm over the same set.
/// The interesting inputs are the ones where a hand-rolled `f64::min`/`max` would diverge from
/// `cmp_num_total`: NaN (greatest, all NaNs tie) and `-0.0` vs `0.0` (deliberately EQUAL —
/// `total_cmp` would split them, which is why the value contract uses `partial_cmp`).
#[test]
fn scan_min_max_agrees_with_the_frontier_path_it_was_moved_above() {
    use crate::value::Value;

    let build = |vals: &[Option<f64>]| {
        let mut b = crate::store::Builder::default();
        for v in vals {
            match v {
                Some(x) => b.node(&["N"], &[("v", Value::Num(*x))]),
                None => b.node(&["N"], &[]),
            };
        }
        for i in 0..vals.len() as u32 {
            b.edge(i, i, "E"); // self-edge: the hop reaches each node exactly once
        }
        b.build()
    };

    let cell = |store: &crate::store::Store, q: &str| -> Value {
        let plan = crate::opt::optimize_indexed(crate::gql::parse(q).unwrap(), store);
        let out = crate::exec::try_run(&plan, store).unwrap_or_else(|e| panic!("{q}: {e}"));
        out.rows[0][0].clone()
    };

    for (name, vals) in [
        ("plain", vec![Some(3.0), Some(-1.0), Some(7.0), Some(2.0)]),
        ("with NaN", vec![Some(3.0), Some(f64::NAN), Some(-1.0)]),
        ("all NaN", vec![Some(f64::NAN), Some(f64::NAN)]),
        ("some absent", vec![Some(5.0), None, Some(-2.0), None]),
        // An absent slot holds 0.0 in the column, so a fold that ignored the `present`
        // mask would answer 0.0 here and be INVISIBLE on data that straddles zero. Found
        // by mutation: the straddling case above survived ignoring the mask entirely.
        ("absent, all positive", vec![Some(5.0), None, Some(3.0)]),
        ("absent, all negative", vec![Some(-5.0), None, Some(-3.0)]),
        ("all absent", vec![None, None]),
        (
            "infinities",
            vec![Some(f64::INFINITY), Some(f64::NEG_INFINITY), Some(0.0)],
        ),
    ] {
        let store = build(&vals);
        for f in ["min", "max"] {
            let scanned = cell(&store, &format!("MATCH (p:N) RETURN {f}(p.v) AS n"));
            let hopped = cell(
                &store,
                &format!("MATCH (a:N)-[:E]->(b) RETURN {f}(b.v) AS n"),
            );
            // Compare by BITS, not by `==`: NaN != NaN and -0.0 == 0.0 under float equality,
            // so a plain comparison would pass on exactly the inputs this test exists for.
            let bits = |v: &Value| match v {
                Value::Num(x) => Some(x.to_bits()),
                Value::Null => None,
                other => panic!("{name}/{f}: want a number or null, got {other:?}"),
            };
            assert_eq!(
                bits(&scanned),
                bits(&hopped),
                "{name}/{f}: scan path gave {scanned:?}, frontier path gave {hopped:?}"
            );
        }
    }

    // SIGNED ZERO is deliberately NOT in the agreement loop above, and the reason is worth
    // stating rather than quietly omitting. `cmp_num_total` rates `-0.0` and `0.0` EQUAL, so
    // each fold keeps whichever it visited FIRST, and the two paths visit in different
    // orders — so as raw `Value`s they genuinely disagree, and a bit-comparison sees it.
    //
    // It cannot escape, which is why this is an assertion about zero and not about the sign:
    // the JSON egress renders both as `0` (pinned by `json.rs`'s own `(-0.0, "0")` case,
    // matching `JSON.stringify(-0)` in JS), so the sign bit never reaches a result on either
    // engine. The value model's "there is no negative zero" promise is kept at the boundary
    // where it is observable, not in the fold.
    for vals in [vec![Some(0.0), Some(-0.0)], vec![Some(-0.0), Some(0.0)]] {
        let store = build(&vals);
        for f in ["min", "max"] {
            for q in [
                format!("MATCH (p:N) RETURN {f}(p.v) AS n"),
                format!("MATCH (a:N)-[:E]->(b) RETURN {f}(b.v) AS n"),
            ] {
                match cell(&store, &q) {
                    Value::Num(x) => assert!(x == 0.0, "{q}: want a zero, got {x:?}"),
                    other => panic!("{q}: want a number, got {other:?}"),
                }
            }
        }
    }

    // A LABELLED SUBSET takes the non-`whole` branch (the id-list walk) rather than the
    // whole-column one, so both loops are covered rather than only the vectorized one.
    let mut b = crate::store::Builder::default();
    b.node(&["N"], &[("v", Value::Num(10.0))]);
    b.node(&["M"], &[("v", Value::Num(-99.0))]); // must NOT be seen by a :N aggregate
    b.node(&["N"], &[("v", Value::Num(4.0))]);
    let store = b.build();
    // `Value` has no `PartialEq` on purpose — the total order is the one comparison — so
    // assert on the extracted number.
    let num = |v: Value| match v {
        Value::Num(x) => Some(x),
        Value::Null => None,
        other => panic!("want a number or null, got {other:?}"),
    };
    assert_eq!(
        num(cell(&store, "MATCH (p:N) RETURN min(p.v) AS n")),
        Some(4.0)
    );
    assert_eq!(
        num(cell(&store, "MATCH (p:N) RETURN max(p.v) AS n")),
        Some(10.0)
    );
    // An empty label has no extremum: NULL, not 0.0 (which is what `sum` correctly gives).
    assert_eq!(
        num(cell(&store, "MATCH (p:Nope) RETURN max(p.v) AS n")),
        None
    );
    assert_eq!(
        num(cell(&store, "MATCH (p:Nope) RETURN sum(p.v) AS n")),
        Some(0.0)
    );
}

/// Item 376: `count(k)` over a hop frontier folds the per-node path MULTIPLICITIES instead
/// of materializing the frontier ids. The multiplicity is the whole correctness question — a
/// node reached three times contributes three rows — and a fixture without parallel edges
/// cannot tell a multiplicity-aware fold from one that counts each node once.
///
/// The reference is a spelling that CANNOT take the new path: adding `WHERE … IS NOT NULL`
/// puts a `Filter` in the chain, so the general aggregate answers it. Same question, different
/// path, so the two must agree — rather than both agreeing with arithmetic I typed.
#[test]
fn frontier_count_of_a_property_counts_path_multiplicity() {
    use crate::value::Value;

    let mut b = crate::store::Builder::default();
    b.node(&["N"], &[]); // 0 — v ABSENT
    b.node(
        &["N"],
        &[("v", Value::Num(1.0)), ("s", Value::Str("x".into()))],
    ); // 1
    b.node(&["N"], &[]); // 2 — v ABSENT
    b.node(
        &["N"],
        &[("v", Value::Num(3.0)), ("s", Value::Str("y".into()))],
    ); // 3
    b.edge(0, 1, "E");
    b.edge(0, 1, "E"); // PARALLEL: node 1 is reached twice and must count twice
    b.edge(0, 2, "E");
    b.edge(1, 3, "E");
    let store = b.build();

    let num = |q: &str| -> f64 {
        let plan = crate::opt::optimize_indexed(crate::gql::parse(q).unwrap(), &store);
        let out = crate::exec::try_run(&plan, &store).unwrap_or_else(|e| panic!("{q}: {e}"));
        match &out.rows[0][0] {
            Value::Num(n) => *n,
            other => panic!("{q}: want a number, got {other:?}"),
        }
    };

    // Rows are (0,1), (0,1), (0,2), (1,3). `v` is present on 1 and 3, so: 1 twice, 3 once = 3.
    // A fold that counted each reached NODE once instead of once per path would answer 2.
    assert_eq!(num("MATCH (a:N)-[:E]->(b) RETURN count(b.v) AS n"), 3.0);
    assert_eq!(
        num("MATCH (a:N)-[:E]->(b) WHERE b.v IS NOT NULL RETURN count(*) AS n"),
        3.0,
        "the filtered count(*) takes a DIFFERENT path and must agree"
    );
    // All four rows, for contrast: this is `count(*)`, which is a different fast path.
    assert_eq!(num("MATCH (a:N)-[:E]->(b) RETURN count(*) AS n"), 4.0);

    // A count never reads the VALUE, so the fold is not restricted to numeric columns the
    // way min/max is. A string column must work identically.
    assert_eq!(num("MATCH (a:N)-[:E]->(b) RETURN count(b.s) AS n"), 3.0);
    assert_eq!(
        num("MATCH (a:N)-[:E]->(b) WHERE b.s IS NOT NULL RETURN count(*) AS n"),
        3.0
    );

    // A column absent EVERYWHERE falls back rather than answering from a missing column.
    assert_eq!(num("MATCH (a:N)-[:E]->(b) RETURN count(b.nope) AS n"), 0.0);

    // A bare SCAN is declined explicitly and belongs to `try_scan_count_prop`; the answer
    // must be unchanged by that decline (2 of the 4 nodes carry `v`).
    assert_eq!(num("MATCH (p:N) RETURN count(p.v) AS n"), 2.0);

    // TWO hops, so the multiplicity compounds: (0,1)->3 twice via the parallel pair, plus
    // (1,3) has no outgoing edge. Reference again by the filtered spelling.
    assert_eq!(
        num("MATCH (a:N)-[:E]->()-[:E]->(c) RETURN count(c.v) AS n"),
        num("MATCH (a:N)-[:E]->()-[:E]->(c) WHERE c.v IS NOT NULL RETURN count(*) AS n"),
    );
}

/// Item 376: `try_frontier_count_prop` declines a bare `Scan`, and that gate is UNREACHABLE
/// through the chain — `try_scan_count_prop` is placed before it. So no end-to-end query can
/// exercise the decline, and a mutant that deletes it survives every behavioural test (both
/// paths return the same count; measured within noise of each other). Assert it directly, the
/// way item 369 pinned its own unreachable gates, so the gate is not merely untested code.
#[test]
fn the_frontier_count_prop_fast_path_declines_a_bare_scan() {
    use crate::ir::{Agg, AggFn, Expr, Plan};
    use crate::value::Value;

    let mut b = crate::store::Builder::default();
    b.node(&["N"], &[("v", Value::Num(1.0))]);
    b.node(&["N"], &[]);
    let store = b.build();

    let agg = Agg {
        func: AggFn::Count,
        arg: Some(Expr::Prop {
            slot: 0,
            key: "v".into(),
        }),
        distinct: false,
        name: "n".into(),
        frac: None,
        null_on_empty: false,
        numeric_only: false,
    };
    let scan = Plan::Scan {
        label: Some("N".into()),
    };

    assert!(
        crate::exec::fastpath::try_frontier_count_prop(&scan, &[], &[agg], &store).is_none(),
        "a bare Scan belongs to try_scan_count_prop; this entry must decline it even though \
         the chain already keeps it from arriving here"
    );
}

/// Item 473's placement claim, made checkable: `try_frontier_multi_agg` sits below a dozen
/// single-aggregate entries and the call site justifies that with _"disjoint from all of them
/// by arity, so it cannot shadow a single-aggregate shape"_. That is a statement about the
/// OTHER entries' gates, and nothing enforced it.
///
/// It matters because of how this class of bug presents. An entry placed below one that claims
/// its shape is dead code that still passes every test it has — both paths return the same
/// answer, so no differential test can see it and the bench row just reads 1.0x. Items 371, 375
/// and 422 are three instances, each found by an `eprintln` at function entry.
///
/// The route itself cannot be asserted behaviourally (it is answer-equivalent by construction),
/// but the PREMISE can: on a two-aggregate frontier shape, every single-aggregate entry above
/// this one must decline. If someone later relaxes an arity gate upstream, this fails here
/// instead of silently making the multi-agg fold unreachable.
///
/// BOTH AGGREGATE ORDERS, and mutation is what said so. Every upstream entry reads `aggs[0]`
/// and then applies its own CONTENT gate — `try_frontier_count` wants `count(*)`,
/// `try_frontier_prop_agg` wants a property argument. So for any one ordering, all but one of
/// them decline on content before arity is ever consulted, and an arity mutant in the others
/// survives. Relaxing `try_frontier_count`'s arity is caught only by `count(*)` FIRST, and
/// `try_frontier_prop_agg`'s only by `max(b.v)` first. "Disjoint by arity" is therefore a
/// weaker claim than it reads: for most entries on a given shape the content gate is what is
/// load-bearing, and the arity gate is reachable in exactly one ordering.
#[test]
fn the_single_aggregate_frontier_entries_all_decline_a_two_aggregate_shape() {
    let mut b = crate::store::Builder::default();
    let n0 = b.node(&["N"], &[("v", Value::Num(1.0))]);
    let n1 = b.node(&["N"], &[("v", Value::Num(7.0))]);
    b.edge(n0, n1, "E");
    b.edge(n1, n0, "E");
    let store = b.build();

    // Each of these is a single-aggregate fold placed ABOVE `try_frontier_multi_agg` in the
    // ladder. `aggs.len() == 1` is what keeps them off a two-aggregate shape.
    /// One ladder entry, as the ladder calls it.
    type LadderEntry = fn(&Plan, &[(String, Expr)], &[Agg], &Store) -> Option<Batch>;

    let single_agg_entries: [(&str, LadderEntry); 5] = [
        (
            "try_frontier_count",
            crate::exec::fastpath::try_frontier_count,
        ),
        (
            "try_frontier_prop_agg",
            crate::exec::fastpath::try_frontier_prop_agg,
        ),
        (
            "try_frontier_count_prop",
            crate::exec::fastpath::try_frontier_count_prop,
        ),
        ("try_scan_num_agg", crate::exec::fastpath::try_scan_num_agg),
        ("try_scan_str_agg", crate::exec::fastpath::try_scan_str_agg),
    ];

    for q in [
        "MATCH (a:N)-[:E]->(b:N) RETURN count(*) AS c, max(b.v) AS m",
        "MATCH (a:N)-[:E]->(b:N) RETURN max(b.v) AS m, count(*) AS c",
    ] {
        let plan = crate::opt::optimize_indexed(crate::gql::parse(q).unwrap(), &store);
        let Plan::Project { input, .. } = &plan else {
            panic!("expected a Project over the Aggregate");
        };
        let Plan::Aggregate { input, keys, aggs } = input.as_ref() else {
            panic!("expected an Aggregate");
        };
        assert_eq!(
            aggs.len(),
            2,
            "the fixture must present TWO aggregates: {q}"
        );

        // The entry this is all about does claim the shape — otherwise the decline assertions
        // below would hold vacuously for any plan at all.
        assert!(
            crate::exec::fastpath::try_frontier_multi_agg(input, keys, aggs, &store).is_some(),
            "the multi-agg frontier fold must claim a two-aggregate frontier shape: {q}"
        );

        for (name, entry) in single_agg_entries {
            assert!(
                entry(input, keys, aggs, &store).is_none(),
                "{name} must decline a TWO-aggregate shape ({q}); it sits above \
                 try_frontier_multi_agg, so claiming this shape would make that fold \
                 unreachable without failing any answer-based test"
            );
        }
    }

    // AND THE OTHER DIRECTION, which a surviving mutant is what showed was missing. Relaxing
    // `aggs.len() < 2` to `aggs.is_empty()` leaves every assertion above it true — a two-agg
    // shape is still claimed, and the declines are statements about other functions. Disjointness
    // is symmetric and so is the pin: this entry must also refuse the ONE-aggregate shapes owned
    // by the entries BELOW it (`try_filtered_scan_num_agg`, `try_scan_multi_agg`, the distinct
    // counts), or its arity floor is doing nothing.
    let q1 = "MATCH (a:N)-[:E]->(b:N) RETURN max(b.v) AS m";
    let plan1 = crate::opt::optimize_indexed(crate::gql::parse(q1).unwrap(), &store);
    let Plan::Project { input: input1, .. } = &plan1 else {
        panic!("expected a Project over the Aggregate");
    };
    let Plan::Aggregate {
        input: input1,
        keys: keys1,
        aggs: aggs1,
    } = input1.as_ref()
    else {
        panic!("expected an Aggregate");
    };
    assert_eq!(
        aggs1.len(),
        1,
        "the control fixture must present ONE aggregate"
    );
    assert!(
        crate::exec::fastpath::try_frontier_multi_agg(input1, keys1, aggs1, &store).is_none(),
        "the multi-agg fold must decline a ONE-aggregate shape: entries below it own that shape, \
         and claiming it would shadow them silently"
    );
}

/// Item 379: an endpoint move after an edge frontier is 1:1, so a bare `count(*)` over one
/// can count the move's INPUT. `g.V().outE(L).outV().count()` was 1720.9us against
/// `outE(L).count()`'s 118.4us — 14.6x for a number that must be equal.
///
/// The test pins the GATES, because each was established by evidence outside the code and a
/// future reader cannot re-derive them from the rewrite alone:
///
/// - `bothV` is 1:TWO. TinkerPop ground truth, run in a console rather than recalled: over 4
///   edges `outE.bothV` is 8 and `bothE.bothV` is 16, while `outE.outV`, `outE.inV`,
///   `outE.otherV` and `bothE.otherV` are all 1:1. Rewriting it HALVES the answer, which is
///   why the count itself is asserted and not just the plan shape.
/// - `EdgeVertex` DROPS a row whose edge slot holds a non-edge ("vertex/scalar from another
///   arm) has no endpoint, so skip it"), so the elision needs an input that PROVABLY binds an
///   edge. The step being 1:1 in TinkerPop does not license eliding it over any input.
///
/// `inV`/`otherV` are elided at LOWERING already — their plans are byte-identical to the bare
/// `Expand` — so `outV` is the only spelling this rewrite can reach.
#[test]
fn a_one_to_one_endpoint_move_is_elided_under_a_bare_count() {
    // Deterministic, with a SELF-LOOP — the structure where endpoint steps diverge, and the
    // one the TinkerPop console check also used.
    let mut b = crate::store::Builder::default();
    for _ in 0..40u32 {
        b.node(&["Person"], &[("age", crate::value::Value::Num(30.0))]);
    }
    let mut seed = 7u64;
    for i in 0..40u32 {
        for _ in 0..3 {
            seed = seed.wrapping_mul(6_364_136_223_846_793_005).wrapping_add(1);
            b.edge(i, ((seed >> 33) as u32) % 40, "KNOWS");
        }
    }
    b.edge(0, 0, "KNOWS"); // self-loop
    let store = b.build();

    let plan_of = |q: &str| -> String {
        let raw = crate::gremlin::parse(q).unwrap_or_else(|e| panic!("{q}: {e}"));
        format!("{:?}", crate::opt::optimize_indexed(raw, &store))
    };
    let count_of = |q: &str| -> f64 {
        let raw = crate::gremlin::parse(q).unwrap_or_else(|e| panic!("{q}: {e}"));
        let plan = crate::opt::optimize_indexed(raw, &store);
        let out = crate::exec::try_run(&plan, &store).unwrap_or_else(|e| panic!("{q}: {e}"));
        match &out.rows[0][0] {
            crate::value::Value::Num(n) => *n,
            other => panic!("{q}: want a number, got {other:?}"),
        }
    };

    let edges = count_of("g.V().hasLabel('Person').outE('KNOWS').count()");

    // ELIDED, and still the edge count — a 1:1 move cannot change it.
    for q in [
        "g.V().hasLabel('Person').outE('KNOWS').outV().count()",
        "g.V().hasLabel('Person').outE('KNOWS').inV().count()",
    ] {
        assert!(
            !plan_of(q).contains("EdgeVertex"),
            "{q}: a 1:1 endpoint move under a bare count must be elided"
        );
        assert_eq!(
            count_of(q),
            edges,
            "{q}: a 1:1 move must not change the count"
        );
    }

    // KEPT, and TWICE the edge count. If the gate ever admits `bothV` this halves.
    for q in [
        "g.V().hasLabel('Person').outE('KNOWS').bothV().count()",
        "g.V().hasLabel('Person').bothE('KNOWS').bothV().count()",
    ] {
        assert!(
            plan_of(q).contains("EdgeVertex"),
            "{q}: bothV is 1:2 and must NOT be elided"
        );
    }
    assert_eq!(
        count_of("g.V().hasLabel('Person').outE('KNOWS').bothV().count()"),
        edges * 2.0,
        "bothV yields BOTH endpoints per edge (TinkerPop: outE.bothV = 8 over 4 edges)"
    );

    // NOT a bare `count(*)` over the move: something between the move and the count depends
    // on the vertices it produced, so the move must stay. `dedup()` is the sharp case — it
    // makes the move's OUTPUT determine the count, so eliding it would answer the edge count
    // where the query asks for distinct sources.
    for q in [
        "g.V().hasLabel('Person').outE('KNOWS').outV().values('age').count()",
        "g.V().hasLabel('Person').outE('KNOWS').outV().dedup().count()",
    ] {
        assert!(
            plan_of(q).contains("EdgeVertex"),
            "{q}: the vertices this move produces are READ, so it must not be elided"
        );
    }
    // A GROUPED count reads the moved-to vertex for its key, so the move must stay. This
    // pins the `keys.is_empty()` gate, which nothing else here exercises.
    for q in [
        "g.V().hasLabel('Person').outE('KNOWS').outV().groupCount().by('age')",
        "g.V().hasLabel('Person').outE('KNOWS').outV().group().by('age').by(count())",
    ] {
        assert!(
            plan_of(q).contains("EdgeVertex"),
            "{q}: a grouping key reads the moved-to vertex, so the move must not be elided"
        );
    }
    // And the dedup answer is genuinely smaller than the edge count, which is what makes the
    // assertion above about behaviour rather than about plan text.
    assert!(
        count_of("g.V().hasLabel('Person').outE('KNOWS').outV().dedup().count()") < edges,
        "distinct sources must be fewer than edges on this fixture, or the test proves nothing"
    );
}

/// Item 380: a Gremlin `order().by('<key>')` **FILTERS** — it drops elements lacking the key.
/// It is NOT a permutation, so it is NOT row-count-preserving, and it may NOT be elided under
/// a bare `count(*)` the way item 379 elides a 1:1 endpoint move.
///
/// This test exists because that elision was about to be written. The reasoning was specific
/// and wrong: a sort permutes rows, a permutation preserves cardinality — but `order().by(k)`
/// is not a permutation. TinkerPop, run in a console over 4 vertices of which 2 carry `age`:
///
/// ```text
/// V.count               = 4
/// V.order.by(age).count = 2     <-- the two keyless vertices are GONE
/// V.values(age).count   = 2
/// ```
///
/// A 17,000x speedup (5097.8us -> 0.3us at 100k vertices) was available for answering 4 where
/// the answer is 2. Fast and silently wrong is the worst failure this engine can ship, so the
/// semantics get a test rather than a comment.
#[test]
fn a_gremlin_order_by_key_filters_and_so_cannot_be_elided_under_a_count() {
    let mut b = crate::store::Builder::default();
    b.node(&["P"], &[("age", crate::value::Value::Num(30.0))]);
    b.node(&["P"], &[("age", crate::value::Value::Num(10.0))]);
    b.node(&["P"], &[]); // no `age`
    b.node(&["P"], &[]); // no `age`
    let store = b.build();

    let num = |q: &str| -> f64 {
        let raw = crate::gremlin::parse(q).unwrap_or_else(|e| panic!("{q}: {e}"));
        let plan = crate::opt::optimize_indexed(raw, &store);
        let out = crate::exec::try_run(&plan, &store).unwrap_or_else(|e| panic!("{q}: {e}"));
        match &out.rows.iter().next().expect("one row")[0] {
            crate::value::Value::Num(n) => *n,
            other => panic!("{q}: want a number, got {other:?}"),
        }
    };

    // The three numbers TinkerPop gives, which lenke matches.
    assert_eq!(num("g.V().hasLabel('P').count()"), 4.0);
    assert_eq!(
        num("g.V().hasLabel('P').order().by('age').count()"),
        2.0,
        "order().by(k) DROPS elements lacking k — eliding it would answer 4"
    );
    assert_eq!(num("g.V().hasLabel('P').values('age').count()"), 2.0);

    // And the plan must still CARRY the sort: an optimizer that removes it is the bug this
    // test is here to stop, and the count above would catch it only while this fixture has
    // keyless vertices. Assert the structure too, so a future fixture change cannot quietly
    // disarm the check.
    let raw = crate::gremlin::parse("g.V().hasLabel('P').order().by('age').count()").unwrap();
    let plan = format!("{:?}", crate::opt::optimize_indexed(raw, &store));
    assert!(
        plan.contains("OrderPage"),
        "the sort must survive optimization under a bare count: {plan}"
    );
}

/// Item 421: `try_scan_str_agg` gives a scan `min`/`max` over a STRING column the columnar
/// fold `try_scan_num_agg` has for `Num`, with a DICTIONARY arm that compares no strings
/// per row at all. Two paths now answer string min/max, so — exactly as for item 375's
/// numeric twin — what is worth testing is not an expectation I typed but that THE TWO AGREE.
///
/// Every node carries a self-edge, so `(a)-[:E]->(b)` reaches each node exactly once and goes
/// to `try_frontier_prop_agg`, while `(p:N)` goes to the new columnar arm over the same set.
#[test]
fn scan_string_min_max_agrees_with_the_frontier_path() {
    use crate::value::Value;

    // `extra` seeds the dictionary from a node OUTSIDE the `:N` label, which is what makes the
    // `present` gate observable in the Dict arm — see the label-scoped case below.
    let build = |vals: &[Option<&str>], extra: Option<&str>| {
        let mut b = crate::store::Builder::default();
        if let Some(s) = extra {
            b.node(&["Q"], &[("v", Value::Str(s.into()))]);
        }
        for v in vals {
            match v {
                Some(s) => b.node(&["N"], &[("v", Value::Str((*s).into()))]),
                None => b.node(&["N"], &[]),
            };
        }
        let n = vals.len() as u32 + u32::from(extra.is_some());
        for i in 0..n {
            b.edge(i, i, "E"); // self-edge: the hop reaches each node exactly once
        }
        b.build()
    };

    // `Value` has no `PartialEq` on purpose — `exec.rs` says to compare through
    // `value::equals`/`cmp_total` rather than `==` — so agreement is checked through the same
    // total order the folds themselves use.
    let same = |a: &Value, b: &Value| crate::value::cmp_total(a, b).is_eq();
    let cell = |store: &crate::store::Store, q: &str| -> Value {
        let plan = crate::opt::optimize_indexed(crate::gql::parse(q).unwrap(), store);
        let out = crate::exec::try_run(&plan, store).unwrap_or_else(|e| panic!("{q}: {e}"));
        out.rows[0][0].clone()
    };

    for (name, vals) in [
        ("plain", vec![Some("pear"), Some("apple"), Some("fig")]),
        // Byte order, not locale: uppercase sorts before lowercase, and a shorter string that
        // is a prefix sorts first. A fold using anything but `GStr::cmp` diverges here.
        (
            "case and prefix",
            vec![Some("Zebra"), Some("apple"), Some("app")],
        ),
        ("empty string", vec![Some(""), Some("a")]),
        ("non-ascii", vec![Some("Ã¥"), Some("z"), Some("A")]),
        ("one row", vec![Some("solo")]),
        ("some absent", vec![Some("mid"), None, Some("end")]),
        ("all absent", vec![None, None]),
        (
            "duplicates",
            vec![Some("b"), Some("b"), Some("a"), Some("b")],
        ),
    ] {
        for extra in [None, Some("zzz_outside_the_label")] {
            let store = build(&vals, extra);
            for f in ["min", "max"] {
                let scanned = cell(&store, &format!("MATCH (p:N) RETURN {f}(p.v) AS n"));
                let hopped = cell(
                    &store,
                    &format!("MATCH (a:N)-[:E]->(b) RETURN {f}(b.v) AS n"),
                );
                assert!(
                    same(&scanned, &hopped),
                    "{name}/{f}/extra={extra:?}: scan gave {scanned:?}, frontier gave {hopped:?}"
                );
            }
        }
    }

    // THE CASE THE `present` GATE IS FOR, in the Dict arm specifically. An absent slot holds
    // code 0, which names `dict[0]` — a real string. So ignoring the mask can only change the
    // answer when `dict[0]` is NOT otherwise among the scanned rows, and that needs the first
    // appearance to come from a node the scan does not visit. `zzz` is on a `:Q`, every `:N`
    // value sorts below it, and one `:N` has no value at all: a fold that read `codes` without
    // the mask answers `zzz`.
    // The values REPEAT, because dictionary encoding is a saving and the store only takes it
    // when there is one: three distinct values over three present rows measured `dict=false`,
    // which made a first version of this assertion fail on a fixture that was testing the
    // `Str` arm while claiming to test the Dict one.
    let mut leak: Vec<Option<&str>> = Vec::new();
    for _ in 0..10 {
        leak.extend([Some("a"), None, Some("b")]);
    }
    let store = build(&leak, Some("zzz"));
    assert!(
        store.scan_is_cheap("v"),
        "fixture no longer dictionary-encoded, so this case tests nothing"
    );
    let got = cell(&store, "MATCH (p:N) RETURN max(p.v) AS n");
    assert!(
        same(&got, &Value::Str("b".into())),
        "an absent slot's code 0 leaked `dict[0]` into a label-scoped max: got {got:?}"
    );

    // And the same question over a column too wide to dictionary-encode, so the `Str` arm runs.
    // Without this the Dict arm would be the only one measured OR tested, which is how item 407
    // found an encoding-blind threshold.
    let wide: Vec<String> = (0..600).map(|i| format!("s{i:04}")).collect();
    let mut b = crate::store::Builder::default();
    for s in &wide {
        b.node(&["N"], &[("v", Value::Str(s.as_str().into()))]);
    }
    for i in 0..wide.len() as u32 {
        b.edge(i, i, "E");
    }
    let store = b.build();
    assert!(
        !store.scan_is_cheap("v"),
        "fixture IS dictionary-encoded, so the plain `Str` arm is untested"
    );
    for (f, want) in [("min", "s0000"), ("max", "s0599")] {
        let scanned = cell(&store, &format!("MATCH (p:N) RETURN {f}(p.v) AS n"));
        let hopped = cell(
            &store,
            &format!("MATCH (a:N)-[:E]->(b) RETURN {f}(b.v) AS n"),
        );
        assert!(
            same(&scanned, &Value::Str(want.into())),
            "wide {f}: want {want}, got {scanned:?}"
        );
        assert!(
            same(&scanned, &hopped),
            "wide {f}: scan gave {scanned:?}, frontier gave {hopped:?}"
        );
    }

    // `sum`/`avg` over strings must still FAULT rather than be folded — this path takes only
    // `Min`/`Max`, and a gate that let the others through would answer where the general path
    // raises.
    for f in ["sum", "avg"] {
        let q = format!("MATCH (p:N) RETURN {f}(p.v) AS n");
        let plan = crate::opt::optimize_indexed(crate::gql::parse(&q).unwrap(), &store);
        assert!(
            crate::exec::try_run(&plan, &store).is_err(),
            "{f}() over a string column should be a data exception"
        );
    }
}

/// Item 422: the FILTERED-scan twin of item 421's string fold. `try_filtered_scan_str_agg`
/// answers `MATCH (p:N) WHERE <pred> RETURN max(p.v)` off the column instead of the general
/// path, with the same `Str`/`Dict` split — so there are now THREE spellings of one question
/// (bare scan, filtered scan, hop) and what is worth asserting is that they agree.
///
/// The hop spelling still goes to `try_frontier_prop_agg`, whose `Column::Num` gate sends a
/// string to the general fold — which makes it the perfect oracle here: a path this change
/// cannot reach, answering the same question over the same rows.
#[test]
fn filtered_scan_string_min_max_agrees_with_the_unfiltered_and_hop_spellings() {
    use crate::value::Value;

    let same = |a: &Value, b: &Value| crate::value::cmp_total(a, b).is_eq();
    let cell = |store: &crate::store::Store, q: &str| -> Value {
        let plan = crate::opt::optimize_indexed(crate::gql::parse(q).unwrap(), store);
        let out = crate::exec::try_run(&plan, store).unwrap_or_else(|e| panic!("{q}: {e}"));
        out.rows[0][0].clone()
    };

    // `w` is the numeric key the predicate filters on; `v` the string being folded. The values
    // REPEAT so the column is dictionary-encoded (a 3-distinct-over-3-rows fixture is not —
    // item 421 learned that the slow way), and the repeats are arranged so that the extremum
    // among SURVIVORS differs from the extremum over the whole column for several thresholds.
    let strs = ["m", "a", "z", "d", "q", "b"];
    let mut b = crate::store::Builder::default();
    for i in 0..60u32 {
        let s = strs[(i % 6) as usize];
        if i % 7 == 0 {
            // No `v` at all: the agg's own property may be absent even where the filter passes.
            b.node(&["N"], &[("w", Value::Num(f64::from(i)))]);
        } else {
            b.node(
                &["N"],
                &[("w", Value::Num(f64::from(i))), ("v", Value::Str(s.into()))],
            );
        }
    }
    for i in 0..60u32 {
        b.edge(i, i, "E"); // self-edge: the hop reaches each node exactly once
    }
    let store = b.build();
    assert!(
        store.scan_is_cheap("v"),
        "fixture no longer dictionary-encoded, so the Dict arm is untested"
    );

    for thresh in ["-1", "0", "5", "29", "58", "59", "1000"] {
        for f in ["min", "max"] {
            let filtered = cell(
                &store,
                &format!("MATCH (p:N) WHERE p.w > {thresh} RETURN {f}(p.v) AS n"),
            );
            // The hop spelling with the SAME predicate, which `try_frontier_prop_agg` declines
            // for a string column — so this is the general fold.
            let hopped = cell(
                &store,
                &format!("MATCH (a:N)-[:E]->(b) WHERE b.w > {thresh} RETURN {f}(b.v) AS n"),
            );
            assert!(
                same(&filtered, &hopped),
                "w>{thresh}/{f}: filtered scan gave {filtered:?}, general gave {hopped:?}"
            );
        }
    }

    // `thresh = 1000` keeps nothing, so both must be NULL rather than the empty string or a
    // leaked `dict[0]`.
    assert!(
        matches!(
            cell(&store, "MATCH (p:N) WHERE p.w > 1000 RETURN max(p.v) AS n"),
            Value::Null
        ),
        "an empty survivor set must fold to NULL"
    );

    // THE DICT LEAK, filtered. `zz` is on a node the predicate EXCLUDES, and it is the greatest
    // string, so a fold that marked codes without consulting `keep` answers `zz`. The node also
    // carries the lowest `w`, which is what puts it outside every threshold used here.
    let mut b = crate::store::Builder::default();
    b.node(
        &["N"],
        &[("w", Value::Num(0.0)), ("v", Value::Str("zz".into()))],
    );
    for i in 1..40u32 {
        if i % 9 == 5 {
            // A SURVIVOR with no `v`. Its code is 0, which names `dict[0]` = "zz" — so this is
            // the row that makes the `present` check observable. Without it the mutant that
            // drops that check survives: every absent slot it would wrongly read names a string
            // that is already among the survivors, which the first version of this fixture
            // established by letting exactly that mutant through.
            b.node(&["N"], &[("w", Value::Num(f64::from(i)))]);
            continue;
        }
        b.node(
            &["N"],
            &[
                ("w", Value::Num(f64::from(i))),
                ("v", Value::Str(if i % 2 == 0 { "a" } else { "b" }.into())),
            ],
        );
    }
    for i in 0..40u32 {
        b.edge(i, i, "E");
    }
    let store = b.build();
    assert!(
        store.scan_is_cheap("v"),
        "the leak case needs a Dict column"
    );
    let got = cell(&store, "MATCH (p:N) WHERE p.w > 0 RETURN max(p.v) AS n");
    assert!(
        same(&got, &Value::Str("b".into())),
        "an excluded row's code leaked into a filtered max: got {got:?}"
    );

    // And the plain `Str` arm: too many distinct values to dictionary-encode.
    let wide: Vec<String> = (0..600).map(|i| format!("s{i:04}")).collect();
    let mut b = crate::store::Builder::default();
    for (i, s) in wide.iter().enumerate() {
        b.node(
            &["N"],
            &[
                ("w", Value::Num(i as f64)),
                ("v", Value::Str(s.as_str().into())),
            ],
        );
    }
    for i in 0..wide.len() as u32 {
        b.edge(i, i, "E");
    }
    let store = b.build();
    assert!(
        !store.scan_is_cheap("v"),
        "fixture IS dictionary-encoded, so the plain `Str` arm is untested"
    );
    for (f, want) in [("min", "s0100"), ("max", "s0599")] {
        let got = cell(
            &store,
            &format!("MATCH (p:N) WHERE p.w > 99 RETURN {f}(p.v) AS n"),
        );
        assert!(
            same(&got, &Value::Str(want.into())),
            "wide filtered {f}: want {want}, got {got:?}"
        );
    }

    // `sum`/`avg` over a filtered string column must still FAULT, not be folded.
    for f in ["sum", "avg"] {
        let q = format!("MATCH (p:N) WHERE p.w > 0 RETURN {f}(p.v) AS n");
        let plan = crate::opt::optimize_indexed(crate::gql::parse(&q).unwrap(), &store);
        assert!(
            crate::exec::try_run(&plan, &store).is_err(),
            "{f}() over a string column should be a data exception"
        );
    }
}

/// Item 432: `try_3hop_product_count` peels a PER-HOP direction, so all EIGHT direction
/// combinations of a 3-hop chain take the degree product where only the all-`out` one did.
///
/// The comment on `try_nhop_sweep_count`'s peel said this was unavailable — "the 3-hop product's
/// identity really does want one orientation, since its `level1`/`outdeg3` arrays are both built
/// from `store.out`" — which was a fact about the CODE mistaken for one about the identity:
///
/// ```text
///   total = SUM over hop-2 edges (b - c) of  level1[b] x deg3(c)
/// ```
///
/// Each term reads a DIFFERENT hop's adjacency, so each may independently be `out` or `inc`.
/// That is a claim about arithmetic, and the only way to check it is against a path that does NOT
/// use the product. Finding one took a trace: `count(*) + 0` is a different route in the TS
/// engine (620.5 ms against 138.6 at 200,000 vertices) and **is not one here** — an `eprintln` at
/// the product's entry showed it firing for the `+ 0` spelling too, so the first version of this
/// test compared the product with ITSELF and all five direction mutants survived it. `count(d)`
/// also fires it. `count(d.k)` does not, and every node in the fixture carries `k`, so it counts
/// the same rows.
///
/// The fixture is deliberately IRREGULAR and contains cycles (14 -> 0, 15 -> 1), so a hop walked
/// the wrong way still finds walks instead of returning zero — which is what makes a wrong
/// direction a disagreement rather than a silent nothing.
#[test]
fn three_hop_product_agrees_with_the_general_path_in_every_direction() {
    use crate::value::Value;

    let store = {
        let mut b = crate::store::Builder::default();
        for i in 0..18u32 {
            let label = match i {
                0..=2 => "A",
                3..=8 => "B",
                9..=13 => "C",
                _ => "D",
            };
            b.node(&[label, "Univ"], &[("k", Value::Num(f64::from(i % 3)))]);
        }
        for (from, to) in [
            (0u32, 4u32),
            (0, 5),
            (1, 4),
            (2, 6),
            (3, 7),
            (4, 9),
            (4, 10),
            (5, 9),
            (6, 11),
            (7, 12),
            (9, 14),
            (9, 15),
            (10, 14),
            (11, 16),
            (12, 17),
            (14, 0),
            (15, 1),
        ] {
            b.edge(from, to, "E");
        }
        // A second edge type, so a hop that kept the wrong label counts the wrong walks.
        b.edge(4, 11, "F");
        b.edge(5, 12, "F");
        b.build()
    };
    let num = |q: &str| -> f64 {
        let raw = crate::gql::parse(q).unwrap_or_else(|e| panic!("{q}: {e}"));
        let plan = crate::opt::optimize_indexed(raw, &store);
        let out = crate::exec::try_run(&plan, &store).unwrap_or_else(|e| panic!("{q}: {e}"));
        match out.rows.iter().next().and_then(|r| r.first()) {
            Some(Value::Num(n)) => *n,
            other => panic!("{q}: want a number, got {other:?}"),
        }
    };

    let mut checked = 0;
    for arrows in [
        ["->", "->", "->"],
        ["->", "->", "<-"],
        ["->", "<-", "->"],
        ["->", "<-", "<-"],
        ["<-", "->", "->"],
        ["<-", "->", "<-"],
        ["<-", "<-", "->"],
        ["<-", "<-", "<-"],
    ] {
        for (head, types) in [
            ("(a)", ["E", "E", "E"]),
            ("(a:A)", ["E", "E", "E"]),
            // A VACUOUS start label, which seeds every vertex and so exercises the `None` arm of
            // the seed loop rather than the label bucket.
            ("(a:Univ)", ["E", "E", "E"]),
            ("(a)", ["E", "F", "E"]),
        ] {
            let leg = |j: usize| {
                if arrows[j] == "->" {
                    format!("-[:{}]->", types[j])
                } else {
                    format!("<-[:{}]-", types[j])
                }
            };
            let q = format!(
                "MATCH {head}{}(b){}(c){}(d) RETURN count(*) AS c",
                leg(0),
                leg(1),
                leg(2)
            );
            let general = q.replace("count(*)", "count(d.k)");
            let (fast, slow) = (num(&q), num(&general));
            assert!(
                (fast - slow).abs() < 1e-9,
                "{q}: product gave {fast}, general path gave {slow}"
            );
            checked += 1;
        }
    }
    // The loop above is the test; this pins that it did not silently skip every case.
    assert_eq!(checked, 32);

    // AN UNDIRECTED HOP must still DECLINE. One edge can be walked two ways, so an undirected
    // chain is not a chain of fixed steps and the product's identity does not hold for it — but
    // `peel_dir_hops` returning `true` for `Dir::Both` would silently walk one index and
    // undercount. The eight-way loop above cannot see that (every hop there is directed), and
    // the mutant admitting `Dir::Both` survived it.
    for q in [
        "MATCH (a)-[:E]-(b)-[:E]->(c)-[:E]->(d) RETURN count(*) AS c",
        "MATCH (a)-[:E]->(b)-[:E]-(c)-[:E]->(d) RETURN count(*) AS c",
        "MATCH (a)-[:E]->(b)-[:E]->(c)-[:E]-(d) RETURN count(*) AS c",
        "MATCH (a)-[:E]-(b)-[:E]-(c)-[:E]-(d) RETURN count(*) AS c",
    ] {
        let general = q.replace("count(*)", "count(d.k)");
        let (fast, slow) = (num(q), num(&general));

        assert!(
            (fast - slow).abs() < 1e-9,
            "{q}: product gave {fast}, general path gave {slow}"
        );
    }
}

/// Item 435: `MATCH ANY SHORTEST (a:P)-[:E]->{1,3}(b:P)` DROPPED the endpoint's label and
/// returned every reachable node. The lowering said so in as many words — "Endpoint node at
/// slot 1: inline props filter it; its label is ignored (as for any landing node in this
/// subset)" — and `landing_label_filter`, the helper for exactly this (a node with no `Scan` to
/// carry a seed label, so the whole constraint is a filter), was never called.
///
/// Found by a two-engine perf SCREEN (`bun run probe:gap`), not by a correctness test: the TS
/// engine answers it correctly, so the row was flagged as an ANSWER disagreement while being
/// timed. The differential fuzzer could not have found it — it generates no quantified paths.
///
/// The fixture's point is that only SOME nodes carry the endpoint label. Four hand-built graphs
/// (a diamond, a self-loop, a 2-cycle, a triangle) all agreed before the fix, because every node
/// in them was `:P` and a vacuous label is one you can drop for free.
#[test]
fn any_shortest_applies_the_endpoint_label() {
    use crate::value::Value;

    // 0 -> 1 -> 2 -> 3 and 0 -> 4 -> 5. Only v0 and v3 are `:P`; the rest are `:Q`.
    let store = {
        let mut b = crate::store::Builder::default();
        for i in 0..6u32 {
            let label = if i == 0 || i == 3 { "P" } else { "Q" };
            b.node(&[label], &[("i", Value::Num(f64::from(i)))]);
        }
        for (from, to) in [(0u32, 1u32), (1, 2), (2, 3), (0, 4), (4, 5)] {
            b.edge(from, to, "E");
        }
        b.build()
    };
    let ids = |q: &str| -> Vec<i64> {
        let raw = crate::gql::parse(q).unwrap_or_else(|e| panic!("{q}: {e}"));
        let plan = crate::opt::optimize_indexed(raw, &store);
        let out = crate::exec::try_run(&plan, &store).unwrap_or_else(|e| panic!("{q}: {e}"));
        // Row order is unspecified for an unordered query, so compare as a MULTISET.
        let mut v: Vec<i64> = out
            .rows
            .iter()
            .map(|r| match r.first() {
                Some(Value::Num(n)) => *n as i64,
                other => panic!("{q}: want a number, got {other:?}"),
            })
            .collect();
        v.sort_unstable();
        v
    };

    // Only v3 is a `:P` reachable from a `:P` within three hops.
    assert_eq!(
        ids("MATCH ANY SHORTEST (a:P)-[:E]->{1,3}(b:P) RETURN b.i AS bi"),
        vec![3],
        "the endpoint label was dropped"
    );
    // `:Q` picks out the others, so the filter is not just rejecting everything.
    assert_eq!(
        ids("MATCH ANY SHORTEST (a:P)-[:E]->{1,3}(b:Q) RETURN b.i AS bi"),
        vec![1, 2, 4, 5]
    );
    // UNLABELLED is the union, which is what the buggy version returned for every spelling.
    assert_eq!(
        ids("MATCH ANY SHORTEST (a:P)-[:E]->{1,3}(b) RETURN b.i AS bi"),
        vec![1, 2, 3, 4, 5]
    );
    // A label on the START is unaffected and was always applied; `:Q` sources reach v3 too.
    assert_eq!(
        ids("MATCH ANY SHORTEST (a:Q)-[:E]->{1,3}(b:P) RETURN b.i AS bi"),
        vec![3, 3]
    );
    // The SAME pattern without the selector filtered correctly all along — it is the oracle
    // that says which of the two answers above is the right one.
    assert_eq!(
        ids("MATCH (a:P)-[:E]->{1,3}(b:P) RETURN b.i AS bi"),
        vec![3]
    );
    // A compound label expression goes through `landing_label_filter`'s OTHER arm (`vb_le`),
    // and it has to EXCLUDE something to test anything: `:P|Q` matches every node in this
    // fixture, so the mutant that drops the compound arm passed it. `:P|R` has no `:R`, so it
    // must give the same answer as `:P` alone.
    assert_eq!(
        ids("MATCH ANY SHORTEST (a:P)-[:E]->{1,3}(b:P|R) RETURN b.i AS bi"),
        vec![3],
        "the compound-label arm was dropped"
    );
    assert_eq!(
        ids("MATCH ANY SHORTEST (a:P)-[:E]->{1,3}(b:P|Q) RETURN b.i AS bi"),
        vec![1, 2, 3, 4, 5]
    );
}

/// Item 436: an aggregate NESTED INSIDE A SCALAR FUNCTION — `abs(min(a.k))`,
/// `size(collect(a.k))`, `coalesce(max(a.k), 0)` — was a parse error, "unknown function `min`",
/// while the TS engine answered all of them.
///
/// The cause was where hoisting was switched on: `peek_agg` looks at a return item's FIRST
/// token, so `max(a.k) + 1` re-parsed with hoisting and `abs(min(a.k))` did not — it fell to the
/// plain-expression branch, where `min` is a scalar function that does not exist. Hoisting is now
/// on for every item and is inert when the item holds no aggregate.
///
/// Found by extending item 434's two-engine screen, which reported `collect` as an unknown
/// function on the native side only.
#[test]
fn an_aggregate_nested_in_a_scalar_function_parses() {
    use crate::value::Value;

    let store = {
        let mut b = crate::store::Builder::default();
        for i in 0..3i64 {
            b.node(&["P"], &[("k", Value::Num((i - 1) as f64))]);
        }
        b.build()
    };
    let one = |q: &str| -> Value {
        let raw = crate::gql::parse(q).unwrap_or_else(|e| panic!("{q}: {e}"));
        let plan = crate::opt::optimize_indexed(raw, &store);
        let out = crate::exec::try_run(&plan, &store).unwrap_or_else(|e| panic!("{q}: {e}"));
        out.rows
            .iter()
            .next()
            .and_then(|r| r.first())
            .cloned()
            .unwrap_or(Value::Null)
    };
    let num = |q: &str| -> f64 {
        match one(q) {
            Value::Num(n) => n,
            other => panic!("{q}: want a number, got {other:?}"),
        }
    };

    // `k` is -1, 0, 1 — so `abs` and `coalesce` have something to do, and a fixture where the
    // minimum were already positive would let `abs` be dropped for free.
    assert_eq!(num("MATCH (a:P) RETURN abs(min(a.k)) AS c"), 1.0);
    assert_eq!(num("MATCH (a:P) RETURN abs(min(a.k) - 10) AS c"), 11.0);
    assert_eq!(num("MATCH (a:P) RETURN coalesce(max(a.k), 0) AS c"), 1.0);
    assert_eq!(num("MATCH (a:P) RETURN size(collect(a.k)) AS c"), 3.0);
    // `count(*)` inside a call failed with a DIFFERENT error ("expected an expression, got
    // Some(Star)"), so it is pinned separately.
    assert_eq!(num("MATCH (a:P) RETURN abs(count(*)) AS c"), 3.0);
    // Nested two deep, which the single-level cases above would not catch.
    assert_eq!(
        num("MATCH (a:P) RETURN abs(coalesce(min(a.k), 0)) AS c"),
        1.0
    );

    // CONTROLS: items with no aggregate must be unchanged, which is the whole claim about
    // enabling hoisting everywhere being inert.
    assert_eq!(num("MATCH (a:P) RETURN max(a.k) + 1 AS c"), 2.0);
    assert_eq!(num("MATCH (a:P) RETURN count(*) AS c"), 3.0);
    // `Value` has no `PartialEq` on purpose — compare through the value contract's order.
    assert!(crate::value::cmp_total(
        &one("MATCH (a:P) RETURN upper('x') AS c"),
        &Value::Str("X".into())
    )
    .is_eq());
    // A plain projection still returns a ROW PER NODE rather than collapsing to one group —
    // which is what a wrongly-hoisted item would do.
    let rows = {
        let q = "MATCH (a:P) RETURN a.k AS k";
        let raw = crate::gql::parse(q).unwrap();
        let plan = crate::opt::optimize_indexed(raw, &store);
        crate::exec::try_run(&plan, &store).unwrap().rows.len()
    };
    assert_eq!(rows, 3, "a plain projection was collapsed into one group");
}

/// Item 438: `try_filter_keep_arith` fuses `<prop> <arith> <lit> <cmp> <lit>` into the keep pass
/// — `a.k * 2 > 10` went from 10.251 ms to 2.159 at 1,000,000 nodes (4.75x), landing on the plain
/// comparison's cost.
///
/// The ORACLE is the same predicate with a redundant `+ 0` wrapped round the arithmetic:
/// `(a.k * 2) + 0 > 10`. Its outer left operand is an `Arith`, not a `Prop`, so the arm declines
/// it and `eval` answers — and the wrap cannot change a finite result. Both sides THROWING also
/// counts as agreement, which is how the division-by-zero cases are compared.
///
/// 2,250 forms: five arithmetic operators x five literals x six comparisons x five thresholds,
/// each in three spellings (property first, literal first, and the threshold on the left).
#[test]
fn fused_arithmetic_filter_agrees_with_the_general_path() {
    use crate::value::Value;

    let store = {
        let mut b = crate::store::Builder::default();
        // Negatives, zero, a half-integer, and 1e308 so that `* 2` OVERFLOWS to infinity — the
        // general path's raw-f64 arm does NOT test the result for finiteness, so the fused arm
        // must not either, and without a value this large that divergence is unreachable.
        for v in [
            -7.5f64, -3.0, -1.0, 0.0, 0.5, 1.0, 2.0, 3.0, 7.0, 11.0, 1e17, 1e308,
        ] {
            b.node(&["N"], &[("k", Value::Num(v))]);
        }
        // No `k` at all, so the `present` gate is observable.
        b.node(&["N"], &[]);
        b.build()
    };
    let count = |q: &str| -> Result<f64, String> {
        let raw = crate::gql::parse(q)?;
        let plan = crate::opt::optimize_indexed(raw, &store);
        let out = crate::exec::try_run(&plan, &store).map_err(|e| e.to_string())?;
        match out.rows.iter().next().and_then(|r| r.first()) {
            Some(Value::Num(n)) => Ok(*n),
            other => Err(format!("want a number, got {other:?}")),
        }
    };
    let mut checked = 0;

    for op in ["+", "-", "*", "/", "%"] {
        for lit in ["0", "1", "2", "-2", "0.5"] {
            for cmp in ["=", "<>", "<", "<=", ">", ">="] {
                for t in ["0", "1", "5", "-1", "2.5"] {
                    let forms = [format!("a.k {op} {lit}"), format!("{lit} {op} a.k")];

                    for expr in &forms {
                        let fast =
                            format!("MATCH (a:N) WHERE {expr} {cmp} {t} RETURN count(*) AS c");
                        let slow = format!(
                            "MATCH (a:N) WHERE ({expr}) + 0 {cmp} {t} RETURN count(*) AS c"
                        );

                        match (count(&fast), count(&slow)) {
                            (Ok(f), Ok(s)) => assert!(
                                (f - s).abs() < 1e-9,
                                "{fast}: fused gave {f}, general gave {s}"
                            ),
                            // Both throwing is agreement — the division-by-zero forms.
                            (Err(_), Err(_)) => {}
                            (f, s) => panic!("{fast}: fused {f:?}, general {s:?}"),
                        }

                        checked += 1;
                    }

                    // The threshold on the LEFT, which `flip_op` normalizes.
                    let expr = &forms[0];
                    let fast = format!("MATCH (a:N) WHERE {t} {cmp} {expr} RETURN count(*) AS c");
                    let slow =
                        format!("MATCH (a:N) WHERE {t} {cmp} ({expr}) + 0 RETURN count(*) AS c");

                    match (count(&fast), count(&slow)) {
                        (Ok(f), Ok(s)) => assert!(
                            (f - s).abs() < 1e-9,
                            "{fast}: fused gave {f}, general gave {s}"
                        ),
                        (Err(_), Err(_)) => {}
                        (f, s) => panic!("{fast}: fused {f:?}, general {s:?}"),
                    }

                    checked += 1;
                }
            }
        }
    }

    assert_eq!(checked, 2250, "the grid shrank");

    // DIVISION BY ZERO still THROWS rather than being silently answered: the fused arm declines a
    // zero literal divisor, and declines `lit / a.k` outright because the divisor is then a
    // column and any row holding 0 would have to throw.
    assert!(count("MATCH (a:N) WHERE a.k / 0 > 1 RETURN count(*) AS c").is_err());
    assert!(count("MATCH (a:N) WHERE a.k % 0 > 1 RETURN count(*) AS c").is_err());
    assert!(count("MATCH (a:N) WHERE 1 / a.k > 1 RETURN count(*) AS c").is_err());

    // OVERFLOW is compared as infinity, not dropped. `1e308 * 2` is one row.
    assert_eq!(
        count("MATCH (a:N) WHERE a.k * 2 > 1e308 RETURN count(*) AS c").unwrap(),
        1.0
    );
}

/// Item 620: an edge id PINS a hop to one source node, so `Plan::EdgeEndpointSeed` replaces
/// the `Scan` under it — 398.73 µs → 1.90 (210x) on a 100,000-edge graph.
///
/// Each row asserts the OPERATOR and then the rows, because a seed is a route CHOICE and
/// route choices are answer-equivalent: a version that silently declined would return exactly
/// these rows ([[perf-gate-needs-its-own-test]]). The DECLINES are asserted the same way, and
/// they carry the two row counts that make them necessary rather than cautious.
#[test]
fn an_edge_id_pin_seeds_the_one_source_node() {
    let store = {
        let mut b = crate::store::Builder::default();
        for i in 0..5u32 {
            b.node(&["P"], &[("k", n(f64::from(i)))]);
        }
        // e0..e4, a 1:1 ring, so a hit is exactly one row and `Both` is exactly two.
        for i in 0..5u32 {
            b.edge(i, (i + 1) % 5, "R");
        }
        b.build()
    };
    // (query, must it seed?, how many rows)
    let cases: &[(&str, bool, usize)] = &[
        // The plain out-hop, and the IN spelling, which seeds the OTHER endpoint.
        ("MATCH ()-[r:R]->() WHERE element_id(r) = 'e2' RETURN element_id(r) AS v", true, 1),
        ("MATCH ()<-[r:R]-() WHERE element_id(r) = 'e2' RETURN element_id(r) AS v", true, 1),
        // Either operand order.
        ("MATCH ()-[r:R]->() WHERE 'e2' = element_id(r) RETURN element_id(r) AS v", true, 1),
        // BOTH ends labelled. The landing label lowers to a `Filter(IsLabeled)` BETWEEN the hop
        // and the pin, and the filter-merge rule declines to fuse them (an `element_id` call
        // can raise) — so without `seed_from_pinned_edge_id` looking through ONE intervening
        // filter, this spelling would scan while the unlabelled one seeded: a ~200x cliff
        // between two spellings of one query.
        (
            "MATCH (a:P)-[r:R]->(b:P) WHERE element_id(r) = 'e2' RETURN a.k AS x, b.k AS y",
            true,
            1,
        ),
        // A CONJUNCTION. The pushdown arm fires first and lands the slot-0 half below the hop,
        // so the fixpoint must still reach the seed on a later pass — and the pushed predicate
        // has to keep its place over the seed.
        (
            "MATCH (a:P)-[r:R]->(b) WHERE element_id(r) = 'e2' AND a.k >= 0 RETURN a.k AS x",
            true,
            1,
        ),
        // A conjunct that EXCLUDES the pinned edge's source: the seed is still taken, and the
        // filter still removes the row. This is the superset-not-subset property, asserted.
        (
            "MATCH (a:P)-[r:R]->(b) WHERE element_id(r) = 'e2' AND a.k > 99 RETURN a.k AS x",
            true,
            0,
        ),
        // A miss, and a source whose label does not match: both seed, both find nothing.
        ("MATCH ()-[r:R]->() WHERE element_id(r) = 'nope' RETURN element_id(r) AS v", true, 0),
        ("MATCH (a:Q)-[r:R]->() WHERE element_id(r) = 'e2' RETURN element_id(r) AS v", true, 0),
        // DECLINE: `Both`. A `Both` hop over a full scan yields the edge from EACH endpoint —
        // TWO rows — so seeding one endpoint would LOSE one. The row count is what makes that
        // concrete rather than a claim.
        ("MATCH ()-[r:R]-() WHERE element_id(r) = 'e2' RETURN element_id(r) AS v", false, 2),
        // DECLINE: an `Or` keeps rows the pinned edge cannot produce, so narrowing the seed
        // from one arm would lose the other's.
        (
            "MATCH ()-[r:R]->() WHERE element_id(r) = 'e2' OR element_id(r) = 'e3' RETURN element_id(r) AS v",
            false,
            2,
        ),
        // DECLINE: a NUMERIC comparand. An external id is a string, so this matches nothing —
        // seeding from `2` would have to invent an id.
        ("MATCH ()-[r:R]->() WHERE element_id(r) = 2 RETURN element_id(r) AS v", false, 0),
        // DECLINE: the pin is on the LANDING node, not the edge, so there is no edge id to
        // seed from and the `element_id` filter of item 619 answers it.
        ("MATCH ()-[r:R]->(b) WHERE element_id(b) = '3' RETURN element_id(b) AS v", false, 1),
    ];

    for (q, want_seed, want_rows) in cases {
        let plan = crate::opt::optimize_indexed(
            crate::gql::parse(q).unwrap_or_else(|e| panic!("parse `{q}`: {e}")),
            &store,
        );
        let seeded = format!("{plan:?}").contains("EdgeEndpointSeed");
        assert_eq!(
            seeded, *want_seed,
            "`{q}` seeded={seeded}, want {want_seed}\n{plan:?}"
        );
        let rows = crate::exec::try_run(&plan, &store)
            .unwrap_or_else(|e| panic!("run `{q}`: {e}"))
            .rows
            .len();
        assert_eq!(
            rows, *want_rows,
            "`{q}` returned {rows} rows, want {want_rows}"
        );
    }
}

/// A seeded edge-id hop must not resurrect a DELETED edge, and must survive the edge being
/// deleted after the plan was built — the plan carries the EXTERNAL id and resolves it at
/// exec, so this is the property that choice buys.
#[test]
fn a_seeded_edge_id_pin_follows_the_live_graph() {
    let mut store = Builder::default().build();
    stmt(
        &mut store,
        "INSERT (:P {id: 'a'})-[:R {id: 'keep'}]->(:P {id: 'b'})",
    )
    .unwrap();
    stmt(
        &mut store,
        "INSERT (:P {id: 'c'})-[:R {id: 'drop'}]->(:P {id: 'd'})",
    )
    .unwrap();

    let q = "MATCH ()-[r:R]->() WHERE element_id(r) = 'drop' RETURN element_id(r) AS v";
    let plan = crate::opt::optimize_indexed(crate::gql::parse(q).unwrap(), &store);
    assert!(
        format!("{plan:?}").contains("EdgeEndpointSeed"),
        "must seed"
    );
    assert_eq!(crate::exec::try_run(&plan, &store).unwrap().rows.len(), 1);

    stmt(
        &mut store,
        "MATCH ()-[r:R]->() WHERE element_id(r) = 'drop' DELETE r",
    )
    .unwrap();

    // The SAME optimized plan, re-run against the mutated store.
    assert_eq!(
        crate::exec::try_run(&plan, &store).unwrap().rows.len(),
        0,
        "a deleted edge must not be resurrected by a plan built before the delete"
    );
    // And the other edge is untouched, so the delete was not a sweep.
    let q = "MATCH ()-[r:R]->() WHERE element_id(r) = 'keep' RETURN element_id(r) AS v";
    let plan = crate::opt::optimize_indexed(crate::gql::parse(q).unwrap(), &store);
    assert_eq!(crate::exec::try_run(&plan, &store).unwrap().rows.len(), 1);
}

/// Item 619: `try_filter_keep_element_id` compares `element_id(x)` over BORROWED ids instead
/// of materializing a `Value::Str` per row — the EDGE pattern 2106 µs → 399 (5.28x) and the
/// FAR-SIDE node id 2042 → 322 (6.33x), both shapes `opt` cannot seed.
///
/// **THESE QUERIES PROJECT, THEY DO NOT COUNT, and that is load-bearing.** The first version
/// of this test used `RETURN count(*)`, and instrumenting the arm showed it NEVER FIRED for
/// those queries — an aggregate over a filtered hop takes a different route — so the test was
/// comparing the general path against itself for exactly the cases it was meant to cover, and
/// a mutant that coerced a numeric literal survived it. A projection reaches the arm, and it
/// is also the shape the A/B measured. **Verified by instrumentation, not assumed.**
///
/// The ORACLE is item 438/449's trick in a new key: `element_id(x) >= 'v' AND element_id(x)
/// <= 'v'` is `element_id(x) = 'v'` under the value contract's TOTAL ORDER, and both of its
/// conjuncts carry an ORDERING operator, which the fused arm declines outright — so the oracle
/// is answered by `eval` while the subject takes the fast path. Three-valued logic matches
/// too: where the id is NULL, the equality and both ordering conjuncts are all UNKNOWN.
///
/// **Agreement alone would pass if both sides were wrong**, so every case also pins the
/// ABSOLUTE row count. A hit is exactly 1 of 10; `<>` is the complement of 9, which is the
/// half an arm computing `ext == want` and forgetting to invert gets wrong — and that mistake
/// returns 1 instead of 9, so a one-element fixture could not see it.
#[test]
fn the_fused_element_id_filter_agrees_with_the_general_path() {
    const N: u32 = 10;
    let store = {
        let mut b = crate::store::Builder::default();
        for i in 0..N {
            b.node(&["N"], &[("k", n(f64::from(i)))]);
        }
        for i in 0..N {
            b.edge(i, (i + 1) % N, "R");
        }
        b.build()
    };

    let rows = |q: &str| -> usize {
        let raw = crate::gql::parse(q).unwrap_or_else(|e| panic!("parse `{q}`: {e}"));
        let plan = crate::opt::optimize_indexed(raw, &store);
        crate::exec::try_run(&plan, &store)
            .unwrap_or_else(|e| panic!("run `{q}`: {e}"))
            .rows
            .len()
    };

    let mut checked = 0;
    // Edge ids are `e0..e9` and node ids `0..9` (the Builder's minting scheme). A hit, a miss,
    // and both boundaries. The hop is 1:1, so a far-side hit is one row, not a fan-out.
    for (shape, ids) in [
        (
            "MATCH ()-[r:R]->() WHERE {} RETURN r.w AS v",
            ["e0", "e5", "e9", "nope"],
        ),
        (
            "MATCH (a:N)-[:R]->(b) WHERE {} RETURN b.k AS v",
            ["0", "5", "9", "nope"],
        ),
    ] {
        let var = if shape.contains("[r:R]") { "r" } else { "b" };

        for id in ids {
            let hit = id != "nope";
            let total = N as usize;

            for (op, want) in [
                ("=", if hit { 1 } else { 0 }),
                ("<>", if hit { total - 1 } else { total }),
            ] {
                let subject = shape.replace("{}", &format!("element_id({var}) {op} '{id}'"));
                let pair = format!("element_id({var}) >= '{id}' AND element_id({var}) <= '{id}'");
                let oracle = shape.replace(
                    "{}",
                    &if op == "=" {
                        pair.clone()
                    } else {
                        format!("NOT ({pair})")
                    },
                );

                let got = rows(&subject);
                let via_eval = rows(&oracle);

                assert_eq!(
                    got, via_eval,
                    "`{subject}` = {got} but the general path says {via_eval}"
                );
                assert_eq!(
                    got, want,
                    "`{subject}` = {got}, want {want} — agreement alone would hide this"
                );
                checked += 1;
            }
        }
    }

    assert_eq!(checked, 16, "every shape x id x operator must be compared");
}

/// The shapes `try_filter_keep_element_id` must DECLINE, each asserted on the ANSWER — a
/// decline that returned the wrong rows would be worse than no fast path at all.
///
/// Projections, for the reason the test above gives: a `count(*)` spelling does not reach the
/// arm, so it would assert nothing about it.
#[test]
fn the_fused_element_id_filter_declines_what_it_cannot_express() {
    let store = {
        let mut b = crate::store::Builder::default();
        for i in 0..5u32 {
            b.node(&["N"], &[("k", n(f64::from(i)))]);
        }
        // EDGES ARE LOAD-BEARING: without them the far-side shape matches nothing whatever the
        // arm does, and every assertion below passes vacuously.
        for i in 0..5u32 {
            b.edge(i, (i + 1) % 5, "R");
        }
        b.build()
    };
    let rows = |q: &str| -> usize {
        let plan = crate::opt::optimize_indexed(crate::gql::parse(q).unwrap(), &store);
        crate::exec::try_run(&plan, &store).unwrap().rows.len()
    };

    // A NUMERIC literal. An external id IS a string, so under the value contract's cross-type
    // `=` this matches nothing — and the arm must not coerce `3` into `"3"`, which WOULD match
    // node 3. The correct answer is 0 of 5 and the coercing one is 1 of 5.
    assert_eq!(
        rows("MATCH (a:N)-[:R]->(b) WHERE element_id(b) = 3 RETURN b.k AS v"),
        0,
        "a numeric id literal must match nothing, not be coerced"
    );
    // The control for that row: the STRING spelling does find node 3, so the zero above is a
    // real decline and not a fixture that matches nothing.
    assert_eq!(
        rows("MATCH (a:N)-[:R]->(b) WHERE element_id(b) = '3' RETURN b.k AS v"),
        1,
        "the string spelling must find node 3 — else the assertion above proves nothing"
    );
    // An ORDERING comparison: a string ordering the arm does not reproduce, so it declines and
    // `eval` answers. Ids are '0'..'4', so `> '2'` is two of five.
    assert_eq!(
        rows("MATCH (a:N)-[:R]->(b) WHERE element_id(b) > '2' RETURN b.k AS v"),
        2,
        "an ordering comparison on an id still answers, via the general path"
    );
}

/// The OPTIONAL-MISS SENTINEL: `element_id` of a slot nothing landed in is NULL, so the
/// comparison is UNKNOWN and the row DROPS — for `<>` exactly as for `=`.
///
/// **This shape is reachable, which `try_filter_keep_call`'s neighbouring comment says it is
/// not.** A clause `WHERE` after `OPTIONAL MATCH` IS rejected by the parser — but the trailing
/// `FILTER` spelling of the same predicate is not, and it lands a `Filter` directly over the
/// optional hop. (That pair is what `spelling_probe` tracks under "a trailing FILTER vs a
/// clause WHERE".) Worth knowing on its own: the sibling arm's `coalesce` decline, declared
/// unmeasurable for want of exactly this shape, can in fact be measured.
///
/// The arm's EXPLICIT `u32::MAX` check is REDUNDANT, and mutation established that rather
/// than assumption: deleting it changes no answer, because `node_ext_id_ref(u32::MAX)` is out
/// of bounds and returns `None`, so the next guard drops the row anyway. It is kept as
/// documentation of intent — a reader should not have to derive the sentinel's fate from a
/// `Vec::get` bound — but do NOT read its surviving mutant as a hole here. The BEHAVIOUR is
/// what is pinned, and it holds either way.
///
/// The `<>` row is the point: three of the four nodes have no out-edge, so an arm that
/// compared the sentinel would call all three "not equal to '1'" and keep them.
#[test]
fn the_fused_element_id_filter_drops_an_optional_miss() {
    let store = {
        let mut b = crate::store::Builder::default();
        for i in 0..4u32 {
            b.node(&["N"], &[("k", n(f64::from(i)))]);
        }
        // ONLY node 0 has an out-edge, so an optional hop leaves THREE misses.
        b.edge(0, 1, "R");
        b.build()
    };
    let rows = |q: &str| -> usize {
        let plan = crate::opt::optimize_indexed(crate::gql::parse(q).unwrap(), &store);
        crate::exec::try_run(&plan, &store).unwrap().rows.len()
    };

    assert_eq!(
        rows("MATCH (a:N) OPTIONAL MATCH (a)-[:R]->(b) FILTER element_id(b) = '1' RETURN b.k AS v"),
        1,
        "only the one real landing matches"
    );
    assert_eq!(
        rows(
            "MATCH (a:N) OPTIONAL MATCH (a)-[:R]->(b) FILTER element_id(b) <> '1' RETURN b.k AS v"
        ),
        0,
        "the three optional MISSES are UNKNOWN and must drop, not count as `<> '1'`"
    );
}

/// Item 449: `try_filter_keep_call` fuses `<scalar fn of one prop> <cmp> <lit>` into the keep
/// pass — `coalesce(a.k, 0) > 5` went from 38.435 ms to 1.482 at 1,000,000 nodes (25.9x) and
/// `abs(a.k) > 5` from 10.582 to 1.815 (5.8x), both landing on the plain comparison's cost.
///
/// The ORACLE is item 438's: the same predicate with a redundant `+ 0` wrapped round the call.
/// Its outer node is an `Arith` whose operand is a `Call` rather than a `Prop`, so BOTH fused
/// arms decline it and `eval` answers — and `+ 0` cannot change a finite result, which every
/// value here is (`unary_finite_num_fn` admits only finite→finite functions and the `coalesce`
/// default is a literal).
///
/// The fixture's load-bearing row is the node with NO `k`, because the two families disagree
/// about exactly that cell: a unary function drops it (NULL → NULL → UNKNOWN) and `coalesce`
/// KEEPS it with the default substituted. A fixture where every node had a `k` would pass
/// against an arm that skipped absent rows, which is the one mistake this arm could plausibly
/// make — and it would pass against an arm that substituted for `abs` too.
#[test]
fn fused_scalar_call_filter_agrees_with_the_general_path() {
    use crate::value::Value;

    let store = {
        let mut b = crate::store::Builder::default();
        // Negatives and zero so `abs`/`sign` are observable, half-integers so `floor`/`ceil`/
        // `round` differ from each other and from the raw value, and 1e308 so a large magnitude
        // is covered.
        for v in [
            -7.5f64, -3.0, -0.5, 0.0, 0.5, 1.0, 2.5, 3.0, 7.0, 11.0, 1e17, 1e308,
        ] {
            b.node(&["N"], &[("k", Value::Num(v))]);
        }
        // No `k` at all. This is the row the whole test turns on.
        b.node(&["N"], &[]);
        b.build()
    };
    let count = |q: &str| -> Result<f64, String> {
        let raw = crate::gql::parse(q)?;
        let plan = crate::opt::optimize_indexed(raw, &store);
        let out = crate::exec::try_run(&plan, &store).map_err(|e| e.to_string())?;
        match out.rows.iter().next().and_then(|r| r.first()) {
            Some(Value::Num(n)) => Ok(*n),
            other => Err(format!("want a number, got {other:?}")),
        }
    };
    let mut checked = 0;
    // Every name `unary_finite_num_fn` admits, plus `coalesce` at several defaults — including
    // one that passes a high threshold and one that fails every threshold, so the substituted
    // value is observable in both directions.
    let exprs: Vec<String> = ["abs", "floor", "ceil", "ceiling", "round", "sign"]
        .iter()
        .map(|f| format!("{f}(a.k)"))
        .chain(
            ["0", "1", "-1", "99", "2.5"]
                .iter()
                .map(|d| format!("coalesce(a.k, {d})")),
        )
        .collect();

    for expr in &exprs {
        for cmp in ["=", "<>", "<", "<=", ">", ">="] {
            for t in ["0", "1", "5", "-1", "2.5", "99"] {
                let fast = format!("MATCH (a:N) WHERE {expr} {cmp} {t} RETURN count(*) AS c");
                let slow = format!("MATCH (a:N) WHERE ({expr}) + 0 {cmp} {t} RETURN count(*) AS c");

                match (count(&fast), count(&slow)) {
                    (Ok(f), Ok(s)) => assert!(
                        (f - s).abs() < 1e-9,
                        "{fast}: fused gave {f}, general gave {s}"
                    ),
                    (Err(_), Err(_)) => {}
                    (f, s) => panic!("{fast}: fused {f:?}, general {s:?}"),
                }

                checked += 1;

                // The threshold on the LEFT, which `flip_op` normalizes.
                let fast = format!("MATCH (a:N) WHERE {t} {cmp} {expr} RETURN count(*) AS c");
                let slow = format!("MATCH (a:N) WHERE {t} {cmp} ({expr}) + 0 RETURN count(*) AS c");

                match (count(&fast), count(&slow)) {
                    (Ok(f), Ok(s)) => assert!(
                        (f - s).abs() < 1e-9,
                        "{fast}: fused gave {f}, general gave {s}"
                    ),
                    (Err(_), Err(_)) => {}
                    (f, s) => panic!("{fast}: fused {f:?}, general {s:?}"),
                }

                checked += 1;
            }
        }
    }

    assert_eq!(checked, 11 * 6 * 6 * 2, "form count drifted: {checked}");
}

/// Item 449's two DECLINES, each because the general path does something the keep pass cannot.
///
/// A fast path that answers where it should decline is the failure mode no differential test
/// over a present column can see, so both are pinned directly against the answer rather than
/// against an oracle spelling.
#[test]
fn fused_scalar_call_filter_declines_an_absent_column() {
    use crate::value::Value;

    let store = {
        let mut b = crate::store::Builder::default();

        for v in [1.0f64, 2.0, 3.0] {
            b.node(&["N"], &[("k", Value::Num(v))]);
        }

        b.build()
    };
    let count = |q: &str| -> f64 {
        let raw = crate::gql::parse(q).expect("parse");
        let plan = crate::opt::optimize_indexed(raw, &store);
        let out = crate::exec::try_run(&plan, &store).expect("run");
        match out.rows.iter().next().and_then(|r| r.first()) {
            Some(Value::Num(n)) => *n,
            other => panic!("want a number, got {other:?}"),
        }
    };

    // `missing` has no column at all, so EVERY cell is null. `coalesce` therefore yields the
    // default for every row and keeps all three; the arm declines rather than streaming a column
    // that is not there. An arm returning an empty keep-list would answer 0 and look like a
    // correct "nothing matches".
    assert_eq!(
        count("MATCH (a:N) WHERE coalesce(a.missing, 99) > 5 RETURN count(*) AS c"),
        3.0
    );
    assert_eq!(
        count("MATCH (a:N) WHERE coalesce(a.missing, 0) > 5 RETURN count(*) AS c"),
        0.0
    );
    // A unary function over the same absent column keeps nothing, which is the other direction.
    assert_eq!(
        count("MATCH (a:N) WHERE abs(a.missing) > 5 RETURN count(*) AS c"),
        0.0
    );
    // And a function the arm does NOT admit (`sqrt` can make a NaN from a finite input, so
    // `unary_finite_num_fn` excludes it) still answers correctly through the general path:
    // sqrt(1) is not > 1, sqrt(2) and sqrt(3) are. (Written as 1.0 first, which was my
    // arithmetic rather than the engine's — the test caught me, not it.)
    assert_eq!(
        count("MATCH (a:N) WHERE sqrt(a.k) > 1 RETURN count(*) AS c"),
        2.0
    );
    // `coalesce` with a non-numeric default declines; the general path compares a string to a
    // number, which is a no-match rather than a throw for `=`.
    assert_eq!(
        count("MATCH (a:N) WHERE coalesce(a.k, 'x') = 2 RETURN count(*) AS c"),
        1.0
    );
}

/// Item 450: `try_filter_keep_case` unwraps a boolean `CASE` used AS a filter predicate and
/// delegates to its condition — `CASE WHEN a.k > 5 THEN true ELSE false END` went from 26.676 ms
/// to 1.072 at 1,000,000 nodes (24.9x), landing below the plain comparison's own cost.
///
/// The ORACLE is the same `CASE` compared to `true`: `(<case>) = true`. That makes the predicate
/// an `Expr::Compare` whose side is an `Expr::Case`, which no fused arm matches, so `eval`
/// answers — and `x = true` keeps exactly the rows `x` keeps, since a filter keeps only TRUE and
/// `true = true` is TRUE while `false = true` and `NULL = true` are FALSE and NULL.
///
/// The oracle is only valid while the `CASE` result is BOOLEAN-or-NULL, which is why the grid's
/// arms are exactly those. Written first with numeric arms too, it reported a divergence on
/// `CASE WHEN a.k > 5 THEN true ELSE 0 END` — the bare form RAISES (0 is a non-boolean in a
/// boolean position) while `(…) = true` answers 3 — and both are right: they are different
/// queries, because `0 = true` is FALSE rather than an error (checked in both engines). **An
/// oracle spelling is part of the claim, not a neutral wrapper**, which is item 432's lesson
/// about oracles being engine-specific arriving from the other direction. The non-boolean arms
/// are pinned directly in `fused_case_filter_keeps_its_restrictions` instead.
///
/// The grid is still mostly DECLINES: of the three `THEN` arms only `true` is admissible and of
/// the four `ELSE` arms only three are. That is the point — a fast path that answers where it
/// should decline is the failure this grid looks for, and `ELSE true` (which keeps the rows the
/// condition DROPS) is the form that would expose a collapse applied too eagerly.
#[test]
fn fused_case_filter_agrees_with_the_general_path() {
    use crate::value::Value;

    let store = {
        let mut b = crate::store::Builder::default();

        for v in [-7.5f64, -1.0, 0.0, 1.0, 2.5, 6.0, 7.0, 11.0] {
            b.node(
                &["N"],
                &[("k", Value::Num(v)), ("s", Value::Str("yes".into()))],
            );
        }
        // No `k` and no `s`, so every condition has an UNKNOWN row — which is the row the
        // three-valued collapse turns on. Without it, `ELSE false` and `ELSE true` would agree
        // on this fixture and the decline would be untested.
        b.node(&["N"], &[]);
        b.build()
    };
    let count = |q: &str| -> Result<f64, String> {
        let raw = crate::gql::parse(q)?;
        let plan = crate::opt::optimize_indexed(raw, &store);
        let out = crate::exec::try_run(&plan, &store).map_err(|e| e.to_string())?;
        match out.rows.iter().next().and_then(|r| r.first()) {
            Some(Value::Num(n)) => Ok(*n),
            other => Err(format!("want a number, got {other:?}")),
        }
    };
    let mut checked = 0;
    // Conditions spanning every fused arm this delegates into: the plain comparison, item 438's
    // arithmetic, item 449's call arms, and a string compare — so the composition is covered,
    // not just the unwrapping.
    let conds = [
        "a.k > 5",
        "a.k < 5",
        "a.k = 1",
        "a.k <> 1",
        "a.k + 1 > 6",
        "abs(a.k) > 5",
        "coalesce(a.k, 99) > 5",
        "coalesce(a.k, 0) > 5",
        "a.s = 'yes'",
        "a.missing > 5",
    ];

    for cond in conds {
        for then in ["true", "false", "null"] {
            for els in ["", " ELSE false", " ELSE true", " ELSE null"] {
                let case = format!("CASE WHEN {cond} THEN {then}{els} END");
                let fast = format!("MATCH (a:N) WHERE ({case}) RETURN count(*) AS c");
                let slow = format!("MATCH (a:N) WHERE ({case}) = true RETURN count(*) AS c");

                match (count(&fast), count(&slow)) {
                    (Ok(f), Ok(s)) => assert!(
                        (f - s).abs() < 1e-9,
                        "{fast}: fused gave {f}, general gave {s}"
                    ),
                    // Both throwing is agreement — a non-boolean `CASE` result in a boolean
                    // position is a data exception on either path.
                    (Err(_), Err(_)) => {}
                    (f, s) => panic!("{fast}: fused {f:?}, general {s:?}"),
                }

                checked += 1;
            }
        }
    }

    assert_eq!(checked, 10 * 3 * 4, "form count drifted: {checked}");
}

/// Item 450's restriction, pinned against the ANSWER rather than an oracle spelling.
///
/// The collapse is sound only because a filter drops FALSE and UNKNOWN identically. Each case
/// here is one where that stops being true, and an over-eager unwrap would get it wrong in a
/// specific, checkable way.
#[test]
fn fused_case_filter_keeps_its_restrictions() {
    use crate::value::Value;

    let store = {
        let mut b = crate::store::Builder::default();

        for v in [1.0f64, 7.0] {
            b.node(&["N"], &[("k", Value::Num(v))]);
        }
        // The UNKNOWN row.
        b.node(&["N"], &[]);
        b.build()
    };
    let count = |q: &str| -> f64 {
        let raw = crate::gql::parse(q).expect("parse");
        let plan = crate::opt::optimize_indexed(raw, &store);
        let out = crate::exec::try_run(&plan, &store).expect("run");
        match out.rows.iter().next().and_then(|r| r.first()) {
            Some(Value::Num(n)) => *n,
            other => panic!("want a number, got {other:?}"),
        }
    };

    // The admitted form: only `k = 7` passes `> 5`.
    assert_eq!(
        count(
            "MATCH (a:N) WHERE (CASE WHEN a.k > 5 THEN true ELSE false END) RETURN count(*) AS c"
        ),
        1.0
    );
    assert_eq!(
        count("MATCH (a:N) WHERE (CASE WHEN a.k > 5 THEN true END) RETURN count(*) AS c"),
        1.0
    );
    // `ELSE true` keeps the rows the condition DROPS — both the FALSE row and the UNKNOWN one —
    // so it is the complement, not the condition. Unwrapping it would answer 1.
    assert_eq!(
        count("MATCH (a:N) WHERE (CASE WHEN a.k > 5 THEN true ELSE true END) RETURN count(*) AS c"),
        3.0
    );
    // `THEN false ELSE true` is the complement too, and for the same reason: UNKNOWN takes the
    // ELSE. Unwrapping would answer 1 instead of 2.
    assert_eq!(
        count(
            "MATCH (a:N) WHERE (CASE WHEN a.k > 5 THEN false ELSE true END) RETURN count(*) AS c"
        ),
        2.0
    );
    // A non-boolean THEN in a boolean position is a data exception, not a truthy value.
    assert!(
        {
            let raw = crate::gql::parse(
                "MATCH (a:N) WHERE (CASE WHEN a.k > 5 THEN 1 ELSE 0 END) RETURN count(*) AS c",
            )
            .expect("parse");
            let plan = crate::opt::optimize_indexed(raw, &store);
            crate::exec::try_run(&plan, &store).is_err()
        },
        "a numeric CASE result in a boolean position must raise"
    );
    // TWO branches are not delegated (the keep-list would be a sorted merge of two), and the
    // general path still answers correctly: `k = 7` takes the first, `k = 1` takes the second.
    assert_eq!(count("MATCH (a:N) WHERE (CASE WHEN a.k > 5 THEN true WHEN a.k < 5 THEN true ELSE false END) RETURN count(*) AS c"), 2.0);
    // A NON-BOOLEAN arm reached by some row raises, and the same `CASE` compared to `true` does
    // NOT — these are different queries, which is why the differential grid above cannot use
    // `= true` as an oracle for them. `0 = true` is FALSE, not an error, so the comparison form
    // answers the 1 row whose condition held.
    assert!(
        {
            let raw = crate::gql::parse(
                "MATCH (a:N) WHERE (CASE WHEN a.k > 5 THEN true ELSE 0 END) RETURN count(*) AS c",
            )
            .expect("parse");
            let plan = crate::opt::optimize_indexed(raw, &store);
            crate::exec::try_run(&plan, &store).is_err()
        },
        "a numeric ELSE reached by a row must raise in a boolean position"
    );
    assert_eq!(count("MATCH (a:N) WHERE (CASE WHEN a.k > 5 THEN true ELSE 0 END) = true RETURN count(*) AS c"), 1.0);
    // And a non-boolean arm NO row reaches does not raise, which is the lazy-evaluation
    // behaviour the eager path falls back to — so the restriction is about reachability, not
    // about the literal appearing.
    assert_eq!(count("MATCH (a:N) WHERE (CASE WHEN a.k > 5 THEN true WHEN false THEN 0 ELSE false END) RETURN count(*) AS c"), 1.0);
}

/// Item 451: `try_stream_num_count`'s SINGLE-BOUND specialization — a filtered `count(*)` with
/// one numeric bound went from 1.681 ms to 0.460 at 1,000,000 nodes (3.7x) by hoisting the bound
/// out of the per-element `Vec` iteration into a monomorphic closure.
///
/// The ORACLE is item 450's wrapper: `(CASE WHEN <pred> THEN true ELSE false END)`. That is a
/// different ROUTE — `Expr::Case` reaches `try_filter_keep`, never this streaming count — and
/// item 450 established the two are equivalent in a filter. Using one fast path as the oracle for
/// another is only sound because that equivalence is itself tested; the alternative wrapper
/// (`<pred> AND true`) would have been a guess about which arms decline it.
///
/// The fixture's nulls and NaN are the point. A NULL cell satisfies no numeric predicate, and a
/// NaN is unordered so every ordering comparison is FALSE on it while `<>` is TRUE — so an arm
/// that tested `!present` as a pass, or that used a total order, would differ here and nowhere
/// else.
#[test]
fn streamed_single_bound_count_agrees_with_the_general_path() {
    use crate::value::Value;

    let store = {
        let mut b = crate::store::Builder::default();

        for v in [-7.5f64, -1.0, 0.0, 1.0, 2.5, 5.0, 6.0, 7.0, 11.0, f64::NAN] {
            b.node(&["N"], &[("k", Value::Num(v))]);
        }
        // No `k` at all: a NULL cell passes nothing, in either direction of every operator.
        b.node(&["N"], &[]);
        b.node(&["N"], &[]);
        b.build()
    };
    let count = |q: &str| -> f64 {
        let raw = crate::gql::parse(q).expect("parse");
        let plan = crate::opt::optimize_indexed(raw, &store);
        let out = crate::exec::try_run(&plan, &store).expect("run");
        match out.rows.iter().next().and_then(|r| r.first()) {
            Some(Value::Num(n)) => *n,
            other => panic!("want a number, got {other:?}"),
        }
    };
    let mut checked = 0;

    for cmp in ["=", "<>", "<", "<=", ">", ">="] {
        for t in ["0", "1", "5", "-1", "2.5", "11", "99"] {
            let pred = format!("a.k {cmp} {t}");
            let streamed = count(&format!("MATCH (a:N) WHERE {pred} RETURN count(*) AS c"));
            let general = count(&format!(
                "MATCH (a:N) WHERE (CASE WHEN {pred} THEN true ELSE false END) RETURN count(*) AS c"
            ));

            assert!(
                (streamed - general).abs() < 1e-9,
                "{pred}: streamed gave {streamed}, keep-pass gave {general}"
            );

            // And the REVERSED operand order, which `num_conj_on_slot` normalizes.
            let flipped = format!("{t} {cmp} a.k");
            let streamed = count(&format!("MATCH (a:N) WHERE {flipped} RETURN count(*) AS c"));
            let general = count(&format!(
                "MATCH (a:N) WHERE (CASE WHEN {flipped} THEN true ELSE false END) RETURN count(*) AS c"
            ));

            assert!(
                (streamed - general).abs() < 1e-9,
                "{flipped}: streamed gave {streamed}, keep-pass gave {general}"
            );

            checked += 2;
        }
    }

    assert_eq!(checked, 6 * 7 * 2, "form count drifted: {checked}");
}

/// Item 451's two arms that are NOT the single-bound specialization, pinned so the split cannot
/// silently send a shape down the wrong one.
#[test]
fn streamed_count_keeps_its_presence_and_multi_bound_arms() {
    use crate::value::Value;

    let store = {
        let mut b = crate::store::Builder::default();

        for v in [1.0f64, 6.0, 7.0] {
            b.node(&["N"], &[("k", Value::Num(v))]);
        }

        b.node(&["N"], &[]);
        b.build()
    };
    let count = |q: &str| -> f64 {
        let raw = crate::gql::parse(q).expect("parse");
        let plan = crate::opt::optimize_indexed(raw, &store);
        let out = crate::exec::try_run(&plan, &store).expect("run");
        match out.rows.iter().next().and_then(|r| r.first()) {
            Some(Value::Num(n)) => *n,
            other => panic!("want a number, got {other:?}"),
        }
    };

    // ZERO bounds — a bare presence gate — counts PRESENCE, which is a different rule from any
    // bounded compare: it includes a stored present-null. Three nodes have `k`, one does not.
    assert_eq!(
        count("MATCH (a:N) WHERE a.k IS NOT NULL RETURN count(*) AS c"),
        3.0
    );
    assert_eq!(
        count("MATCH (a:N) WHERE a.k IS NULL RETURN count(*) AS c"),
        1.0
    );
    // TWO bounds take the general `Vec` arm, which the specialization must not swallow: only
    // `k = 6` is strictly between.
    assert_eq!(
        count("MATCH (a:N) WHERE a.k > 5 AND a.k < 7 RETURN count(*) AS c"),
        1.0
    );
    assert_eq!(
        count("MATCH (a:N) WHERE a.k > 5 AND a.k < 100 RETURN count(*) AS c"),
        2.0
    );
    // Three bounds, so the arm cannot be a two-element special case either.
    assert_eq!(
        count("MATCH (a:N) WHERE a.k > 0 AND a.k < 100 AND a.k <> 6 RETURN count(*) AS c"),
        2.0
    );
    // And the single bound itself, so this test fails if the split stops routing at all.
    assert_eq!(count("MATCH (a:N) WHERE a.k > 5 RETURN count(*) AS c"), 2.0);
}

/// Item 453: `try_stream_range_count` — a TWO-bound range in a filtered `count(*)` went from
/// 1.782 ms to 0.461 at 1,000,000 nodes (3.9x), landing on the single-bound cost item 451
/// reached.
///
/// The ORACLE is item 450's wrapper: `(CASE WHEN <pred> THEN true ELSE false END)` routes through
/// `try_filter_keep`, never this streaming count, and item 450 established the equivalence.
///
/// Both WRITTEN ORDERS of every range, because the arm classifies its bounds rather than matching
/// them pairwise — `k < 100 AND k > 5` is the same range as `k > 5 AND k < 100` and an arm that
/// only recognised one spelling would be the exact class of gap this engine exists not to have.
/// And the NON-range pairs (two lower bounds, two equalities, a `<>`) which must fall through to
/// the general arm and still answer.
#[test]
fn streamed_range_count_agrees_with_the_general_path() {
    use crate::value::Value;

    let store = {
        let mut b = crate::store::Builder::default();

        // The thresholds below are 0, 1, 5, 2.5 and 11, so stored values SIT ON them — which is
        // the only way an inclusive bound can be told from an exclusive one. Plus a NaN, which
        // every ordering comparison is FALSE on, and two absent cells.
        for v in [-7.5f64, -1.0, 0.0, 1.0, 2.5, 5.0, 6.0, 11.0, 12.0, f64::NAN] {
            b.node(&["N"], &[("k", Value::Num(v))]);
        }

        b.node(&["N"], &[]);
        b.node(&["N"], &[]);
        b.build()
    };
    let count = |q: &str| -> f64 {
        let raw = crate::gql::parse(q).expect("parse");
        let plan = crate::opt::optimize_indexed(raw, &store);
        let out = crate::exec::try_run(&plan, &store).expect("run");
        match out.rows.iter().next().and_then(|r| r.first()) {
            Some(Value::Num(n)) => *n,
            other => panic!("want a number, got {other:?}"),
        }
    };
    let mut checked = 0;
    let agree = |pred: &str| {
        let streamed = count(&format!("MATCH (a:N) WHERE {pred} RETURN count(*) AS c"));
        let general = count(&format!(
            "MATCH (a:N) WHERE (CASE WHEN {pred} THEN true ELSE false END) RETURN count(*) AS c"
        ));

        assert!(
            (streamed - general).abs() < 1e-9,
            "{pred}: streamed gave {streamed}, keep-pass gave {general}"
        );
    };

    for lo_op in [">", ">="] {
        for hi_op in ["<", "<="] {
            for lo in ["0", "1", "2.5", "5", "-1"] {
                for hi in ["1", "5", "11", "2.5", "99"] {
                    // Both written orders of the same range.
                    agree(&format!("a.k {lo_op} {lo} AND a.k {hi_op} {hi}"));
                    agree(&format!("a.k {hi_op} {hi} AND a.k {lo_op} {lo}"));
                    checked += 2;
                }
            }
        }
    }

    // NON-range pairs, which must decline to the general arm.
    for pred in [
        "a.k > 5 AND a.k > 1",
        "a.k < 5 AND a.k < 11",
        "a.k = 5 AND a.k = 5",
        "a.k = 5 AND a.k > 1",
        "a.k <> 5 AND a.k < 11",
        "a.k > 1 AND a.k <> 5",
        "a.k >= 1 AND a.k >= 2.5",
    ] {
        agree(pred);
        checked += 1;
    }

    // THREE bounds, which is the shape the split exists to protect.
    for pred in [
        "a.k > 1 AND a.k < 11 AND a.k <> 5",
        "a.k > 1 AND a.k < 11 AND a.k > 2.5",
    ] {
        agree(pred);
        checked += 1;
    }

    assert_eq!(
        checked,
        2 * 2 * 5 * 5 * 2 + 7 + 2,
        "form count drifted: {checked}"
    );
}

/// Item 453's inclusivity, pinned against the ANSWER so an arm that confused `>` with `>=`
/// cannot pass. Each threshold has a stored value sitting exactly on it.
#[test]
fn streamed_range_count_distinguishes_inclusive_bounds() {
    use crate::value::Value;

    let store = {
        let mut b = crate::store::Builder::default();

        for v in [1.0f64, 2.0, 3.0, 4.0, 5.0] {
            b.node(&["N"], &[("k", Value::Num(v))]);
        }

        b.build()
    };
    let count = |q: &str| -> f64 {
        let raw = crate::gql::parse(q).expect("parse");
        let plan = crate::opt::optimize_indexed(raw, &store);
        let out = crate::exec::try_run(&plan, &store).expect("run");
        match out.rows.iter().next().and_then(|r| r.first()) {
            Some(Value::Num(n)) => *n,
            other => panic!("want a number, got {other:?}"),
        }
    };

    // 1..5 stored. Each of the four arms keeps a DIFFERENT count over the same thresholds, which
    // is what makes the four-way dispatch testable at all.
    assert_eq!(
        count("MATCH (a:N) WHERE a.k > 2 AND a.k < 4 RETURN count(*) AS c"),
        1.0
    );
    assert_eq!(
        count("MATCH (a:N) WHERE a.k > 2 AND a.k <= 4 RETURN count(*) AS c"),
        2.0
    );
    assert_eq!(
        count("MATCH (a:N) WHERE a.k >= 2 AND a.k < 4 RETURN count(*) AS c"),
        2.0
    );
    assert_eq!(
        count("MATCH (a:N) WHERE a.k >= 2 AND a.k <= 4 RETURN count(*) AS c"),
        3.0
    );
    // And the reversed written order of each, which must agree exactly.
    assert_eq!(
        count("MATCH (a:N) WHERE a.k < 4 AND a.k > 2 RETURN count(*) AS c"),
        1.0
    );
    assert_eq!(
        count("MATCH (a:N) WHERE a.k <= 4 AND a.k > 2 RETURN count(*) AS c"),
        2.0
    );
    assert_eq!(
        count("MATCH (a:N) WHERE a.k < 4 AND a.k >= 2 RETURN count(*) AS c"),
        2.0
    );
    assert_eq!(
        count("MATCH (a:N) WHERE a.k <= 4 AND a.k >= 2 RETURN count(*) AS c"),
        3.0
    );
    // An EMPTY range, so a swapped lo/hi would show as every row rather than none.
    assert_eq!(
        count("MATCH (a:N) WHERE a.k > 4 AND a.k < 2 RETURN count(*) AS c"),
        0.0
    );
}

/// Item 458: `coalesce` over COLUMNS, resolved once — `count(coalesce(a.k, 0))` went from 31.2 ms
/// to 3.44 at 1,000,000 rows (8.9x), landing on the vectorized floor, and the absent-first-arg
/// spelling from 37.0 to 22.0 (1.67x).
///
/// The fixture's point is the THREE column representations plus an absent one, because the
/// identity shortcut is keyed on exactly that: `Col::Num`, `Col::Bool` and `Col::Str` have no
/// null representation, so a first argument of one of those makes every later argument
/// unreachable. A fixture with only numbers would leave the string and boolean arms untested and
/// the absent arm — the one that still merges — unexercised.
#[test]
fn coalesce_over_columns_matches_the_boxed_reading() {
    use crate::value::Value;

    let store = {
        let mut b = crate::store::Builder::default();

        b.node(
            &["N"],
            &[
                ("k", Value::Num(7.0)),
                ("s", Value::Str("a".into())),
                ("f", Value::Bool(true)),
            ],
        );
        b.node(&["N"], &[("s", Value::Str("b".into()))]);
        b.node(
            &["N"],
            &[
                ("k", Value::Num(0.0)),
                ("s", Value::Str("c".into())),
                ("f", Value::Bool(false)),
            ],
        );
        b.build()
    };
    // Compared as DEBUG STRINGS because `Value` has no `PartialEq` across the crate boundary;
    // that also makes a null distinguishable from a missing row in the failure output.
    let one = |q: &str| -> String {
        let raw = crate::gql::parse(q).expect("parse");
        let plan = crate::opt::optimize_indexed(raw, &store);
        let out = crate::exec::try_run(&plan, &store).expect("run");

        out.rows
            .iter()
            .filter_map(|r| r.first())
            .map(|v| format!("{v:?}"))
            .collect::<Vec<_>>()
            .join(",")
    };

    // A non-nullable first argument IS the answer: the later ones are unreachable, and a `-1`
    // appearing anywhere would mean the shortcut had been taken for a column that can be null.
    assert_eq!(
        one("MATCH (a:N) RETURN coalesce(a.k, -1) AS v ORDER BY v"),
        // `-1` for the row with no `k`: the column HAS a null, so it is a `Col::Gen` and the
        // identity shortcut must not fire. Written first as `Null`, which was my reading of
        // the single-argument spelling rather than this one — the test caught me.
        "Num(-1.0),Num(0.0),Num(7.0)"
    );
    assert_eq!(
        one("MATCH (a:N) RETURN coalesce(a.s, 'z') AS v ORDER BY v"),
        "Str(\"a\"),Str(\"b\"),Str(\"c\")"
    );
    // An ABSENT first argument takes the merge path, and the second argument supplies every row.
    assert_eq!(
        one("MATCH (a:N) RETURN coalesce(a.missing, 'z') AS v"),
        "Str(\"z\"),Str(\"z\"),Str(\"z\")"
    );
    // THREE arguments, where the second is also absent, so the third decides.
    assert_eq!(
        one("MATCH (a:N) RETURN coalesce(a.missing, a.other, 5) AS v"),
        "Num(5.0),Num(5.0),Num(5.0)"
    );
    // Every argument null is null, not an error and not a skipped row.
    assert_eq!(
        one("MATCH (a:N) RETURN coalesce(a.missing, a.other) AS v"),
        "Null,Null,Null"
    );
    // ONE argument is the argument.
    assert_eq!(
        one("MATCH (a:N) RETURN coalesce(a.k) AS v ORDER BY v"),
        "Num(0.0),Num(7.0),Null"
    );
    // A column WITH nulls is a `Col::Gen`, so the identity must NOT fire and the default has to
    // reach the row that lacks `k`. This is the assertion that fails if the shortcut is keyed on
    // the wrong thing.
    assert_eq!(
        one("MATCH (a:N) RETURN coalesce(a.k, -1) AS v ORDER BY v"),
        // `-1` for the row with no `k`: the column HAS a null, so it is a `Col::Gen` and the
        // identity shortcut must not fire. Written first as `Null`, which was my reading of
        // the single-argument spelling rather than this one — the test caught me.
        "Num(-1.0),Num(0.0),Num(7.0)"
    );
}

/// Item 458's RAISE PARITY, which is the semantic the arm could most easily have broken.
///
/// `coalesce` is lazy in the VALUE sense and this arm keeps that, but the path it replaces
/// materializes every argument column BEFORE the row loop — so a later argument that faults
/// raises even when the first argument is non-null everywhere. Evaluating the arguments lazily
/// here would be a divergence dressed as an optimization, and both engines were checked to agree
/// before it was written.
#[test]
fn coalesce_still_raises_for_a_faulting_later_argument() {
    use crate::value::Value;

    let store = {
        let mut b = crate::store::Builder::default();

        b.node(&["N"], &[("k", Value::Num(7.0))]);
        b.node(&["N"], &[("k", Value::Num(1.0))]);
        b.build()
    };
    let run = |q: &str| -> bool {
        let raw = crate::gql::parse(q).expect("parse");
        let plan = crate::opt::optimize_indexed(raw, &store);

        crate::exec::try_run(&plan, &store).is_err()
    };

    // The first argument is non-null for EVERY row, so a lazy reading would never reach the
    // divisor. Both engines raise.
    assert!(run("MATCH (a:N) RETURN coalesce(a.k, 1/0) AS v"));
    assert!(run("MATCH (a:N) RETURN coalesce(a.k, a.k/0) AS v"));
    assert!(run("MATCH (a:N) RETURN coalesce(a.missing, 1/0) AS v"));
    // And the control: the same shape without the faulting argument does NOT raise.
    assert!(!run("MATCH (a:N) RETURN coalesce(a.k, 1/1) AS v"));
}

/// Item 458's `Nodes`/`Edges` exclusion from the identity shortcut.
///
/// `Col::Num`, `Col::Bool` and `Col::Str` have no null representation, which is what licenses
/// returning the first argument unchanged. `Col::Nodes` DOES have one — the `u32::MAX`
/// OPTIONAL-miss sentinel — so the identity would skip the fallback for exactly the rows that
/// need it. Mutation found this uncovered: admitting `Nodes` left every other test green.
///
/// What this pins is the FALLBACK, not the rendering. Native renders a node in this position as
/// its raw id where the TS engine renders the element; that divergence is pre-existing (verified
/// against the commit before this arm) and recorded in `CLOSED.md` separately.
#[test]
fn coalesce_does_not_take_the_identity_on_a_node_column() {
    use crate::value::Value;

    let store = {
        let mut b = crate::store::Builder::default();
        // Only the FIRST `:P` has an outgoing edge, so one row matches the optional hop and one
        // misses it. A fixture where every row matched could not tell the fallback from the
        // identity at all.
        let v1 = b.node(&["P"], &[("k", Value::Num(1.0))]);
        b.node(&["P"], &[("k", Value::Num(2.0))]);
        let z = b.node(&["Z"], &[("k", Value::Num(9.0))]);

        b.edge(v1, z, "E");
        b.build()
    };
    let one = |q: &str| -> String {
        let raw = crate::gql::parse(q).expect("parse");
        let plan = crate::opt::optimize_indexed(raw, &store);
        let out = crate::exec::try_run(&plan, &store).expect("run");

        out.rows
            .iter()
            .filter_map(|r| r.first())
            .map(|v| format!("{v:?}"))
            .collect::<Vec<_>>()
            .join(",")
    };

    // The PROPERTY spelling: the matched row takes `z.k` (9) and the missed row falls back to
    // `a.k` (2). This is the engine-agnostic half.
    assert_eq!(
        one("MATCH (a:P) OPTIONAL MATCH (a)-[:E]->(z) RETURN coalesce(z.k, a.k) AS v ORDER BY v"),
        "Num(2.0),Num(9.0)"
    );
    // The ELEMENT spelling, which is the one the identity shortcut would break: the missed row
    // must still fall back to `a` rather than yielding the sentinel.
    assert_eq!(
        one("MATCH (a:P) OPTIONAL MATCH (a)-[:E]->(z) RETURN coalesce(z, a) AS v"),
        "Num(2.0),Num(1.0)"
    );
}

/// Item 459: every unary numeric function with its NAME resolved once — `count(sqrt(a.k))` went
/// from 32.9 ms to 12.7 at 1,000,000 rows (2.6x), and the other fourteen non-finite-safe
/// functions take the same arm.
///
/// What this pins is the MAPPING and the null/raise plumbing, not the arithmetic: the bodies are
/// `f64`'s own and `scalar_num_fn` now delegates to the same `unary_num_fn`, so there is one
/// body per function. A mapping error — `ln` wired to `log10`, `asin` to `acos` — is invisible
/// to a test that only checks "a number came back", so every expectation below is a value only
/// that function produces.
#[test]
fn resolved_unary_numeric_functions_map_to_the_right_body() {
    use crate::value::Value;

    let store = {
        let mut b = crate::store::Builder::default();

        b.node(&["N"], &[("k", Value::Num(100.0))]);
        b.build()
    };
    let one = |expr: &str| -> String {
        let q = format!("MATCH (a:N) RETURN {expr} AS v");
        let raw = crate::gql::parse(&q).expect("parse");
        let plan = crate::opt::optimize_indexed(raw, &store);
        let out = crate::exec::try_run(&plan, &store).expect("run");

        out.rows
            .iter()
            .filter_map(|r| r.first())
            .map(|v| format!("{v:?}"))
            .collect::<Vec<_>>()
            .join(",")
    };

    // Each constant is distinctive for its function over k = 100: `sqrt` 10, `log10` 2, `ln` of
    // 1 is 0, `exp` of 0 is 1, and the trig pair at 0 are 0 and 1. Swapping any two of these
    // bodies changes at least one answer.
    assert_eq!(one("sqrt(a.k)"), "Num(10.0)");
    assert_eq!(one("log10(a.k)"), "Num(2.0)");
    assert_eq!(one("ln(a.k - 99)"), "Num(0.0)");
    assert_eq!(one("exp(a.k - 100)"), "Num(1.0)");
    assert_eq!(one("sin(a.k - 100)"), "Num(0.0)");
    assert_eq!(one("cos(a.k - 100)"), "Num(1.0)");
    assert_eq!(one("tan(a.k - 100)"), "Num(0.0)");
    assert_eq!(one("asin(a.k - 100)"), "Num(0.0)");
    assert_eq!(one("atan(a.k - 100)"), "Num(0.0)");
    assert_eq!(one("sinh(a.k - 100)"), "Num(0.0)");
    assert_eq!(one("cosh(a.k - 100)"), "Num(1.0)");
    assert_eq!(one("tanh(a.k - 100)"), "Num(0.0)");
    assert_eq!(one("degrees(a.k - 100)"), "Num(0.0)");
    assert_eq!(one("radians(a.k - 100)"), "Num(0.0)");
    // `acos(1)` is 0 and `acos(0)` is PI/2 — the one that distinguishes it from `asin`.
    assert_eq!(one("acos(a.k - 99)"), "Num(0.0)");
    // The finite-safe six still answer through their own vectorized arm.
    assert_eq!(one("abs(0 - a.k)"), "Num(100.0)");
    assert_eq!(one("floor(a.k + 0.5)"), "Num(100.0)");
    assert_eq!(one("ceil(a.k + 0.5)"), "Num(101.0)");
    assert_eq!(one("round(a.k + 0.5)"), "Num(101.0)");
    assert_eq!(one("sign(0 - a.k)"), "Num(-1.0)");
    // A computed NaN or infinity is KEPT, not coerced — `sqrt(-1)` and `ln(0)`.
    assert_eq!(one("sqrt(0 - a.k)"), "Num(NaN)");
    assert_eq!(one("ln(a.k - 100)"), "Num(-inf)");
    // `sign(NaN)` is NaN, not 0. NaN is false for both `> 0` and `< 0`, so without its guard it
    // falls through to the else-arm — the wrong answer that guard's own comment records, and
    // which survived mutation until this line existed (every other `sign` case here is finite).
    assert_eq!(one("sign(sqrt(0 - a.k))"), "Num(NaN)");
    assert_eq!(one("sign(a.k - 100)"), "Num(0.0)");
}

/// Item 459's null and RAISE plumbing, which is where the arm could silently diverge.
#[test]
fn resolved_unary_numeric_functions_keep_null_and_raise() {
    use crate::value::Value;

    let store = {
        let mut b = crate::store::Builder::default();

        b.node(
            &["N"],
            &[("k", Value::Num(4.0)), ("s", Value::Str("x".into()))],
        );
        // No `k` and no `s`, so the column carries a null beside a value.
        b.node(&["N"], &[]);
        b.build()
    };
    let rows = |expr: &str| -> Result<String, String> {
        let q = format!("MATCH (a:N) RETURN {expr} AS v");
        let raw = crate::gql::parse(&q)?;
        let plan = crate::opt::optimize_indexed(raw, &store);
        let out = crate::exec::try_run(&plan, &store).map_err(|e| e.to_string())?;

        Ok(out
            .rows
            .iter()
            .filter_map(|r| r.first())
            .map(|v| format!("{v:?}"))
            .collect::<Vec<_>>()
            .join(","))
    };

    // A NULL argument propagates to NULL, beside a row that computes.
    assert_eq!(rows("sqrt(a.k)").unwrap(), "Num(2.0),Null");
    // NEGATIVE ZERO is collapsed, because the numeric model has none (item 460). `0.0 * -2.0`
    // is -0.0 under IEEE, and `cot(-0.0)` is -Inf where `cot(+0.0)` is +Inf — so comparing the
    // result against 0.0 answers FALSE or TRUE depending on whether the collapse happened.
    // Item 459's first version read `Value::Num(x)` directly and skipped it, shipping a wrong
    // answer that the differential fuzzer caught the same tick. Going through `num_of` is what
    // keeps the policy in one place; this asserts it from the outside.
    assert_eq!(
        rows("0.0 <= cot(0.0 * (0 - a.k))").unwrap(),
        "Bool(true),Null"
    );
    assert_eq!(rows("0.0 <= cot(0.0 * a.k)").unwrap(), "Bool(true),Null");
    // A non-null NON-NUMERIC argument is a DATA EXCEPTION, not a null. This is the assertion the
    // first version of the arm failed: it used `num_of` and answered NULL.
    assert!(rows("sqrt(a.s)").is_err(), "sqrt of a string must raise");
    assert!(rows("ln(a.s)").is_err(), "ln of a string must raise");
    // And the raise survives the row that is NULL — the string row is reached either way.
    assert!(rows("cos(a.s)").is_err(), "cos of a string must raise");
}

/// Item 461: the NEGATIVE ZERO policy, pinned across every path a computed -0 can reach.
///
/// Item 460 fixed one of these and was found by a random fuzzer seed. The seed was luck: nothing
/// deterministic covered the class, and the same mistake in a neighbouring arm would have shipped
/// the same way. This is the "grep the pattern elsewhere" step of the method, written down as
/// assertions instead of as a sweep I did once.
///
/// The policy: the numeric model has NO negative zero (`value::num_of` collapses -0.0 to +0.0, a
/// deliberate deviation from IEEE). It only becomes observable through an operation whose result
/// differs on the sign of zero — `1/x` and anything built on it, which in this engine means
/// `cot` and division. Comparisons cannot see it (`-0.0 == 0.0`), which is why a stored -0 is
/// harmless and only a COMPUTED one matters.
///
/// Every expression below produces a -0 under IEEE and must behave as +0. All were checked to
/// agree with the TS engine before being written here.
#[test]
fn computed_negative_zero_is_collapsed_everywhere_it_can_be_seen() {
    use crate::value::Value;

    let store = {
        let mut b = crate::store::Builder::default();
        // A NEGATIVE k, so `0.0 * k` is -0.0 under IEEE. A positive one beside it, so an
        // assertion that passed by collapsing everything to one answer would still be visible.
        b.node(&["P"], &[("k", Value::Num(-2.0))]);
        b.node(&["P"], &[("k", Value::Num(2.0))]);
        b.build()
    };
    let one = |expr: &str| -> String {
        let q = format!("MATCH (n:P) RETURN {expr} AS v ORDER BY v");
        let raw = crate::gql::parse(&q).expect("parse");
        let plan = crate::opt::optimize_indexed(raw, &store);
        let out = crate::exec::try_run(&plan, &store).expect("run");

        out.rows
            .iter()
            .filter_map(|r| r.first())
            .map(|v| format!("{v:?}"))
            .collect::<Vec<_>>()
            .join(",")
    };
    let raises = |expr: &str| -> bool {
        let q = format!("MATCH (n:P) RETURN {expr} AS v");
        let raw = crate::gql::parse(&q).expect("parse");
        let plan = crate::opt::optimize_indexed(raw, &store);

        crate::exec::try_run(&plan, &store).is_err()
    };
    let count = |pred: &str| -> f64 {
        let q = format!("MATCH (n:P) WHERE {pred} RETURN count(*) AS c");
        let raw = crate::gql::parse(&q).expect("parse");
        let plan = crate::opt::optimize_indexed(raw, &store);
        let out = crate::exec::try_run(&plan, &store).expect("run");

        match out.rows.iter().next().and_then(|r| r.first()) {
            Some(Value::Num(n)) => *n,
            other => panic!("want a number, got {other:?}"),
        }
    };

    // `cot` of a multiplied zero — item 460's own case, in the PROJECTION.
    assert_eq!(one("0.0 <= cot(0.0 * n.k)"), "Bool(true),Bool(true)");
    // And in a FILTER, which is a different route entirely.
    assert_eq!(count("0.0 <= cot(0.0 * n.k)"), 2.0);
    // A SUBTRACTED zero reaches it the other way: `0.0 - 2.0` is negative, `0.0 - 0.0` is +0.
    assert_eq!(one("0.0 <= cot(n.k - n.k)"), "Bool(true),Bool(true)");
    // DIVISION cannot see the sign at all: dividing by a computed zero RAISES rather than
    // yielding an infinity, so there is no ±0 question on that path. Written first as an
    // infinity assertion, which failed with "division by zero" — the engine's answer is better
    // than my expectation and this records which operations the policy actually has to cover.
    assert!(
        raises("0.0 <= (1.0 / (0.0 * n.k))"),
        "dividing by a computed zero must raise"
    );
    assert!(
        raises("0.0 <= (1.0 / round(0.0 * n.k))"),
        "same through a rounding function"
    );
    // Through `floor`/`ceil`/`round`, which PRESERVE a -0 into the column the next operation
    // reads — the leak that would make a neighbouring arm fail the same way.
    assert_eq!(one("0.0 <= cot(floor(0.0 * n.k))"), "Bool(true),Bool(true)");
    assert_eq!(one("0.0 <= cot(ceil(0.0 * n.k))"), "Bool(true),Bool(true)");
    assert_eq!(one("0.0 <= cot(round(0.0 * n.k))"), "Bool(true),Bool(true)");
    // `sign` of a computed -0 is 0, not -0 and not -1.
    assert_eq!(one("sign(0.0 * n.k)"), "Num(0.0),Num(0.0)");
    // And an AGGREGATE over computed -0s.
    assert_eq!(one("abs(0.0 * n.k)"), "Num(0.0),Num(0.0)");
}

/// Item 462: `try_filter_keep_arith` takes ONE nested level — `a.k * 2 + 1 > 7` — which it used
/// to decline, at 6.0x (12.7-13.5 ms against 2.08-2.26 for the one-level `a.k * 2 > 6` at the
/// same row count).
///
/// The ORACLE is item 438's, which still works and for a better reason than before: wrapping the
/// predicate in a redundant `+ 0` now makes it THREE levels, which this arm declines, so `eval`
/// answers. `+ 0` cannot change a finite result.
///
/// Both operand orders at BOTH levels, because the arm matches four shapes —
/// `(p op l) op l`, `(l op p) op l`, `l op (p op l)`, `l op (l op p)` — and a spelling it
/// recognised in only one position would be the equivalent-spelling gap this engine exists not
/// to have.
#[test]
fn nested_arithmetic_filter_agrees_with_the_general_path() {
    use crate::value::Value;

    let store = {
        let mut b = crate::store::Builder::default();

        // Negatives, zero, a half-integer, and 1e308 so an inner `* 2` OVERFLOWS to infinity —
        // the general path does NOT test the result for finiteness and neither may this arm,
        // which is item 438's rule inherited one level down.
        for v in [
            -7.5f64, -3.0, -1.0, 0.0, 0.5, 1.0, 2.0, 3.0, 7.0, 11.0, 1e308,
        ] {
            b.node(&["N"], &[("k", Value::Num(v))]);
        }

        b.node(&["N"], &[]);
        b.build()
    };
    let count = |q: &str| -> Result<f64, String> {
        let raw = crate::gql::parse(q)?;
        let plan = crate::opt::optimize_indexed(raw, &store);
        let out = crate::exec::try_run(&plan, &store).map_err(|e| e.to_string())?;

        match out.rows.iter().next().and_then(|r| r.first()) {
            Some(Value::Num(n)) => Ok(*n),
            other => Err(format!("want a number, got {other:?}")),
        }
    };
    let mut checked = 0;

    for iop in ["+", "-", "*", "/", "%"] {
        for oop in ["+", "-", "*"] {
            for lit in ["0", "1", "2", "-2", "0.5"] {
                for cmp in ["=", "<>", "<", ">="] {
                    for t in ["0", "1", "5", "-1"] {
                        // The four shapes, inner and outer operand orders independently.
                        for expr in [
                            format!("(a.k {iop} {lit}) {oop} {lit}"),
                            format!("({lit} {iop} a.k) {oop} {lit}"),
                            format!("{lit} {oop} (a.k {iop} {lit})"),
                            format!("{lit} {oop} ({lit} {iop} a.k)"),
                        ] {
                            let fast =
                                format!("MATCH (a:N) WHERE {expr} {cmp} {t} RETURN count(*) AS c");
                            let slow = format!(
                                "MATCH (a:N) WHERE ({expr}) + 0 {cmp} {t} RETURN count(*) AS c"
                            );

                            match (count(&fast), count(&slow)) {
                                (Ok(f), Ok(s)) => assert!(
                                    (f - s).abs() < 1e-9,
                                    "{fast}: fused gave {f}, general gave {s}"
                                ),
                                // Both throwing is agreement — the division-by-zero forms.
                                (Err(_), Err(_)) => {}
                                (f, s) => panic!("{fast}: fused {f:?}, general {s:?}"),
                            }

                            checked += 1;
                        }
                    }
                }
            }
        }
    }

    assert_eq!(
        checked,
        5 * 3 * 5 * 4 * 4 * 4,
        "form count drifted: {checked}"
    );
}

/// Item 462's declines, pinned against the ANSWER.
#[test]
fn nested_arithmetic_filter_keeps_its_declines() {
    use crate::value::Value;

    let store = {
        let mut b = crate::store::Builder::default();

        for v in [1.0f64, 2.0, 3.0, 4.0] {
            b.node(&["N"], &[("k", Value::Num(v)), ("j", Value::Num(2.0))]);
        }

        b.build()
    };
    let count = |q: &str| -> Result<f64, String> {
        let raw = crate::gql::parse(q)?;
        let plan = crate::opt::optimize_indexed(raw, &store);
        let out = crate::exec::try_run(&plan, &store).map_err(|e| e.to_string())?;

        match out.rows.iter().next().and_then(|r| r.first()) {
            Some(Value::Num(n)) => Ok(*n),
            other => Err(format!("want a number, got {other:?}")),
        }
    };

    // THREE levels decline and still answer: `k*2+1+0 > 7` keeps k = 4 alone.
    assert_eq!(
        count("MATCH (a:N) WHERE a.k * 2 + 1 + 0 > 7 RETURN count(*) AS c").unwrap(),
        1.0
    );
    // TWO properties decline (the arm reads one column).
    assert_eq!(
        count("MATCH (a:N) WHERE a.k * a.j + 1 > 5 RETURN count(*) AS c").unwrap(),
        2.0
    );
    // A zero divisor THROWS on both the inner and the outer step, as the general path does.
    assert!(count("MATCH (a:N) WHERE a.k / 0 + 1 > 1 RETURN count(*) AS c").is_err());
    assert!(count("MATCH (a:N) WHERE (a.k + 1) / 0 > 1 RETURN count(*) AS c").is_err());
    // A COLUMN divisor declines rather than answering, because a row holding 0 would have to
    // throw and a keep-pass cannot express that. Here no row is 0, so the general path answers:
    // 8/1+1, 8/2+1 and 8/3+1 are 9, 5 and 3.67, all above 3; 8/4+1 is exactly 3 and is not.
    // (Written as 2.0 first — my arithmetic, not the engine's.)
    assert_eq!(
        count("MATCH (a:N) WHERE 8 / a.k + 1 > 3 RETURN count(*) AS c").unwrap(),
        3.0
    );
    // And the one-level shape still works, so a split that lost an arm is visible.
    assert_eq!(
        count("MATCH (a:N) WHERE a.k * 2 > 6 RETURN count(*) AS c").unwrap(),
        1.0
    );
}

/// Item 464: a `CASE` whose branch values and `ELSE` are all LITERALS selects between constants
/// instead of materializing a column per arm — `count(CASE WHEN a.k > 3 THEN 1 ELSE 0 END)` went
/// from 26.0 ms to 8.5 at 1,000,000 rows (3.0x), and the `ELSE null` idiom from 30.2 to 11.4.
///
/// The ORACLE is the same CASE with a PROPERTY arm that computes the same value: `a.k - a.k + 1`
/// is 1 for every non-null `k`, and a non-literal arm makes this path decline, so `eval` answers.
/// That keeps the comparison between two readings of one question rather than against my
/// arithmetic.
#[test]
fn literal_armed_case_agrees_with_the_general_path() {
    use crate::value::Value;

    let store = {
        let mut b = crate::store::Builder::default();

        for v in [-3.0f64, 0.0, 1.0, 4.0, 7.0] {
            b.node(
                &["N"],
                &[("k", Value::Num(v)), ("s", Value::Str("a".into()))],
            );
        }
        // No `k`, so every condition has an UNKNOWN row — the one that falls through to ELSE
        // without the branch being FALSE.
        b.node(&["N"], &[("s", Value::Str("b".into()))]);
        b.build()
    };
    let rows = |expr: &str| -> Result<String, String> {
        let q = format!("MATCH (a:N) RETURN {expr} AS v ORDER BY v");
        let raw = crate::gql::parse(&q)?;
        let plan = crate::opt::optimize_indexed(raw, &store);
        let out = crate::exec::try_run(&plan, &store).map_err(|e| e.to_string())?;

        Ok(out
            .rows
            .iter()
            .filter_map(|r| r.first())
            .map(|v| format!("{v:?}"))
            .collect::<Vec<_>>()
            .join(","))
    };
    let mut checked = 0;

    for cond in ["a.k > 3", "a.k < 0", "a.k = 1", "a.k <> 1", "a.s = 'a'"] {
        // Literal THEN against a property arm computing the SAME value.
        for (lit, same) in [("1", "a.k - a.k + 1"), ("0", "a.k - a.k")] {
            for els in ["", " ELSE 0", " ELSE null", " ELSE 9"] {
                let fast = format!("CASE WHEN {cond} THEN {lit}{els} END");
                let slow = format!("CASE WHEN {cond} THEN {same}{els} END");

                // The property arm is NULL where `k` is absent and the literal arm is not, so
                // the rows are comparable only where the condition is not TRUE for that row —
                // which is every row here, since `a.k > 3` and friends are UNKNOWN on it.
                match (rows(&fast), rows(&slow)) {
                    (Ok(f), Ok(s)) => assert_eq!(f, s, "{fast} against {slow}"),
                    (Err(_), Err(_)) => {}
                    (f, s) => panic!("{fast}: fast {f:?}, general {s:?}"),
                }

                checked += 1;
            }
        }
    }

    assert_eq!(checked, 5 * 2 * 4, "form count drifted: {checked}");
}

/// Item 464's semantics, pinned against the ANSWER: branch ORDER, three-valued fall-through,
/// the absent `ELSE`, mixed literal types, and the non-boolean condition that must still raise.
#[test]
fn literal_armed_case_keeps_case_semantics() {
    use crate::value::Value;

    let store = {
        let mut b = crate::store::Builder::default();

        b.node(&["N"], &[("k", Value::Num(5.0))]);
        b.node(&["N"], &[("k", Value::Num(1.0))]);
        b.node(&["N"], &[]);
        b.build()
    };
    let rows = |expr: &str| -> Result<String, String> {
        let q = format!("MATCH (a:N) RETURN {expr} AS v ORDER BY v");
        let raw = crate::gql::parse(&q)?;
        let plan = crate::opt::optimize_indexed(raw, &store);
        let out = crate::exec::try_run(&plan, &store).map_err(|e| e.to_string())?;

        Ok(out
            .rows
            .iter()
            .filter_map(|r| r.first())
            .map(|v| format!("{v:?}"))
            .collect::<Vec<_>>()
            .join(","))
    };

    // BRANCH ORDER: k = 5 satisfies both, and the FIRST wins. A path that scanned backwards, or
    // took the last match, answers 2 for that row.
    assert_eq!(
        rows("CASE WHEN a.k > 3 THEN 1 WHEN a.k > 0 THEN 2 ELSE 9 END").unwrap(),
        "Num(1.0),Num(2.0),Num(9.0)"
    );
    // The UNKNOWN row takes the ELSE, not the first branch: `a.k > 3` on an absent `k` is
    // UNKNOWN, which falls through exactly as FALSE does.
    assert_eq!(
        rows("CASE WHEN a.k > 3 THEN 1 ELSE 0 END").unwrap(),
        "Num(0.0),Num(0.0),Num(1.0)"
    );
    // NO `ELSE` is NULL, and a NULL literal arm forces the boxed column rather than a `Col::Num`.
    assert_eq!(
        rows("CASE WHEN a.k > 3 THEN 1 END").unwrap(),
        "Num(1.0),Null,Null"
    );
    assert_eq!(
        rows("CASE WHEN a.k > 3 THEN null ELSE 7 END").unwrap(),
        "Num(7.0),Num(7.0),Null"
    );
    // MIXED literal types cannot be a `Col::Num` and must still answer.
    assert_eq!(
        rows("CASE WHEN a.k > 3 THEN 'big' ELSE 0 END").unwrap(),
        "Num(0.0),Num(0.0),Str(\"big\")"
    );
    assert_eq!(
        rows("CASE WHEN a.k > 3 THEN true ELSE false END").unwrap(),
        "Bool(false),Bool(false),Bool(true)"
    );
    // A NON-BOOLEAN condition is a data exception, on this path as on the general one.
    assert!(rows("CASE WHEN a.k THEN 1 ELSE 0 END").is_err());
    // A non-literal arm DECLINES to the general path and still answers.
    assert_eq!(
        rows("CASE WHEN a.k > 3 THEN a.k ELSE 0 END").unwrap(),
        "Num(0.0),Num(0.0),Num(5.0)"
    );
}

/// The four specialized scan folds (item 470) answer exactly what the single-aggregate paths
/// answer for the same question.
///
/// The oracle is the SAME aggregate asked alone, which takes a different route entirely
/// (`try_scan_count_prop`, `try_scan_num_agg`, …) — so a specialization that dropped a
/// quantity, counted the wrong rows or routed `avg` to a loop that never sums shows up as a
/// disagreement between two routes rather than against a constant I worked out.
#[test]
fn scan_multi_agg_specializations_match_single_aggregates() {
    let mut b = Builder::default();
    for v in [3.0f64, 1.0, 4.0, 1.0, 5.0] {
        b.node(&["P"], &[("age", n(v))]);
    }
    // No `age`: `count(*)` must see it and `count(n.age)` must not.
    b.node(&["P"], &[("name", s("none"))]);
    let st = b.build();
    // `Value` has no `PartialEq` on purpose (NaN), so the comparison is on the DEBUG
    // rendering — structural, and it distinguishes `Null` from `Num(0.0)`, which is the
    // distinction every empty-group assertion below turns on.
    let vals = |q: &str| -> String {
        format!(
            "{:?}",
            run(&crate::gql::parse(q).unwrap(), &st)
                .rows
                .iter()
                .next()
                .expect("one row")
                .to_vec()
        )
    };
    let one = |q: &str| -> String {
        let r = run(&crate::gql::parse(q).unwrap(), &st);
        let row = r.rows.iter().next().expect("one row");
        format!("{:?}", row[0])
    };

    // (false, false) — counts only.
    assert_eq!(
        vals("MATCH (n:P) RETURN count(n.age) AS a, count(*) AS b"),
        format!(
            "[{}, {}]",
            one("MATCH (n:P) RETURN count(n.age) AS a"),
            one("MATCH (n:P) RETURN count(*) AS b")
        )
    );
    // (true, false) — sum and avg, which both need the total AND the count.
    assert_eq!(
        vals("MATCH (n:P) RETURN sum(n.age) AS a, avg(n.age) AS b"),
        format!(
            "[{}, {}]",
            one("MATCH (n:P) RETURN sum(n.age) AS a"),
            one("MATCH (n:P) RETURN avg(n.age) AS b")
        )
    );
    // `avg` ALONE picks the summing loop — the mutant that read `need_sum` as `Sum` only and
    // sent this to the counting loop SURVIVED until this line, because every other `avg` here
    // sits beside a `sum` that sets the flag anyway.
    assert_eq!(
        vals("MATCH (n:P) RETURN avg(n.age) AS a, count(*) AS b"),
        format!(
            "[{}, {}]",
            one("MATCH (n:P) RETURN avg(n.age) AS a"),
            one("MATCH (n:P) RETURN count(*) AS b")
        )
    );
    // `sum` beside `count(*)` is the summing loop's ROW counter, which is a different number
    // from its value count — the mutant that stopped incrementing `rows` there survived until
    // this line, because the only other `count(*)` pairing routed to the all-quantities loop.
    assert_eq!(
        vals("MATCH (n:P) RETURN sum(n.age) AS a, count(*) AS b"),
        "[Num(14.0), Num(6.0)]"
    );
    // (false, true) — min and max, which need the count only to tell empty from real.
    assert_eq!(
        vals("MATCH (n:P) RETURN min(n.age) AS a, max(n.age) AS b"),
        format!(
            "[{}, {}]",
            one("MATCH (n:P) RETURN min(n.age) AS a"),
            one("MATCH (n:P) RETURN max(n.age) AS b")
        )
    );
    // (true, true) — all four quantities at once, plus `count(*)` for the row counter.
    assert_eq!(
        vals("MATCH (n:P) RETURN sum(n.age) AS a, max(n.age) AS b, count(*) AS c"),
        format!(
            "[{}, {}, {}]",
            one("MATCH (n:P) RETURN sum(n.age) AS a"),
            one("MATCH (n:P) RETURN max(n.age) AS b"),
            one("MATCH (n:P) RETURN count(*) AS c")
        )
    );
    // And the values themselves, so a bug the single paths SHARE cannot hide: 3+1+4+1+5 = 14
    // over five present values out of six rows.
    assert_eq!(
        vals("MATCH (n:P) RETURN count(n.age) AS a, count(*) AS b"),
        "[Num(5.0), Num(6.0)]"
    );
    assert_eq!(
        vals("MATCH (n:P) RETURN sum(n.age) AS a, avg(n.age) AS b"),
        format!("[Num(14.0), Num({:?})]", 14.0 / 5.0)
    );
    assert_eq!(
        vals("MATCH (n:P) RETURN min(n.age) AS a, max(n.age) AS b"),
        "[Num(1.0), Num(5.0)]"
    );

    // TWO DISTINCT COLUMNS (item 471), which is one pass each rather than one interleaved
    // pass. `score` is present on a DIFFERENT set of nodes from `age`, so a mix-up between the
    // two groups — or a `count` reading the other column's tally — changes an answer.
    let mut b2 = Builder::default();
    for (age, score) in [
        (Some(3.0f64), Some(10.0f64)),
        (Some(1.0), None),
        (Some(4.0), Some(20.0)),
        (None, Some(30.0)),
        (Some(5.0), None),
    ] {
        let mut props: Vec<(&str, Value)> = Vec::new();
        if let Some(a) = age {
            props.push(("age", n(a)));
        }
        if let Some(sc) = score {
            props.push(("score", n(sc)));
        }
        b2.node(&["Q"], &props);
    }
    let st2 = b2.build();
    let vals2 = |q: &str| -> String {
        format!(
            "{:?}",
            run(&crate::gql::parse(q).unwrap(), &st2)
                .rows
                .iter()
                .next()
                .expect("one row")
                .to_vec()
        )
    };
    let one2 = |q: &str| -> String {
        let r = run(&crate::gql::parse(q).unwrap(), &st2);
        let row = r.rows.iter().next().expect("one row");
        format!("{:?}", row[0])
    };

    // age: 3,1,4,5 (four of five). score: 10,20,30 (three of five). Six rows of output across
    // the assertions below, every one of them against the single-aggregate route.
    assert_eq!(
        vals2("MATCH (n:Q) RETURN sum(n.age) AS a, max(n.score) AS b"),
        format!(
            "[{}, {}]",
            one2("MATCH (n:Q) RETURN sum(n.age) AS a"),
            one2("MATCH (n:Q) RETURN max(n.score) AS b")
        )
    );
    assert_eq!(
        vals2("MATCH (n:Q) RETURN count(n.age) AS a, count(n.score) AS b, count(*) AS c"),
        "[Num(4.0), Num(3.0), Num(5.0)]"
    );
    // Both quantities from BOTH columns at once — four passes' worth of state, two passes of
    // work, and every value distinct so a crossed wire shows.
    assert_eq!(
        vals2("MATCH (n:Q) RETURN sum(n.age) AS a, min(n.age) AS b, sum(n.score) AS c, max(n.score) AS d"),
        "[Num(13.0), Num(1.0), Num(60.0), Num(30.0)]"
    );
    // A column nobody has: its aggregates are the empty answers while the other column's are
    // real, which an interleaved pass and a per-column pass can disagree about.
    assert_eq!(
        vals2("MATCH (n:Q) RETURN sum(n.age) AS a, max(n.missing) AS b"),
        format!(
            "[{}, {}]",
            one2("MATCH (n:Q) RETURN sum(n.age) AS a"),
            one2("MATCH (n:Q) RETURN max(n.missing) AS b")
        )
    );

    // A column that EXISTS but holds nothing for the scanned label. This is the only way to
    // reach `cnt == 0` INSIDE this arm — an absent column makes the whole arm decline, so the
    // empty-graph assertions below never exercise its null handling, and the mutant that
    // dropped the `cnt == 0` guard on `min`/`max` SURVIVED until this case existed.
    let mut b3 = Builder::default();
    b3.node(&["Q"], &[("score", n(10.0))]);
    b3.node(&["R"], &[("other", n(1.0))]);
    let st3 = b3.build();
    let vals3 = |q: &str| -> String {
        format!(
            "{:?}",
            run(&crate::gql::parse(q).unwrap(), &st3)
                .rows
                .iter()
                .next()
                .expect("one row")
                .to_vec()
        )
    };

    assert_eq!(
        vals3("MATCH (n:R) RETURN min(n.score) AS a, max(n.score) AS b, count(*) AS c"),
        "[Null, Null, Num(1.0)]"
    );
    assert_eq!(
        vals3("MATCH (n:R) RETURN sum(n.score) AS a, avg(n.score) AS b"),
        "[Num(0.0), Null]"
    );

    // An EMPTY scan: every variant must give the empty answer its aggregate owes ISO, and the
    // `cnt` each one carries is what tells it apart from a real zero.
    let empty = Builder::default().build();
    let evals = |q: &str| -> String {
        format!(
            "{:?}",
            run(&crate::gql::parse(q).unwrap(), &empty)
                .rows
                .iter()
                .next()
                .expect("one row")
                .to_vec()
        )
    };
    assert_eq!(
        evals("MATCH (n:P) RETURN count(n.age) AS a, count(*) AS b"),
        "[Num(0.0), Num(0.0)]"
    );
    assert_eq!(
        evals("MATCH (n:P) RETURN sum(n.age) AS a, avg(n.age) AS b"),
        "[Num(0.0), Null]"
    );
    assert_eq!(
        evals("MATCH (n:P) RETURN min(n.age) AS a, max(n.age) AS b"),
        "[Null, Null]"
    );
}

/// Two or more aggregates over one frontier (item 473) answer exactly what the single-aggregate
/// frontier paths answer, and `sum`/`avg` are REFUSED there for item 376's reason.
///
/// The oracle is each aggregate asked ALONE, which takes a different route
/// (`try_frontier_count`, `try_frontier_count_prop`, `try_frontier_prop_agg`), so a mix-up
/// between the multiplicity-weighted accumulators and the unweighted ones is a disagreement
/// between two routes. The fixture gives one far end TWO in-edges, which is what makes
/// weighted and unweighted differ at all — without a repeated far end the distinction is
/// vacuous and every mutant about it survives.
#[test]
fn frontier_multi_agg_matches_single_frontier_aggregates() {
    let mut b = Builder::default();
    // The START nodes carry their own numeric property, so an aggregate over SLOT 0 can be
    // asked. Nothing else in the fixture needs it, and the mutant that dropped the
    // "arg must be a property of the chain frontier" check SURVIVED without it — the arm then
    // reads `a.k2`'s column while indexing by the FRONTIER's vertex ids.
    let a1 = b.node(&["A"], &[("name", s("a1")), ("k2", n(100.0))]);
    let a2 = b.node(&["A"], &[("name", s("a2")), ("k2", n(200.0))]);
    let hi = b.node(&["B"], &[("k", n(9.0))]);
    let lo = b.node(&["B"], &[("k", n(2.0))]);
    let no = b.node(&["B"], &[("name", s("no k"))]);
    // `hi` is reached TWICE, so `count(*)` is 4 while the distinct frontier holds 3 nodes.
    b.edge(a1, hi, "E");
    b.edge(a2, hi, "E");
    b.edge(a1, lo, "E");
    b.edge(a2, no, "E");
    let st = b.build();
    let vals = |q: &str| -> String {
        format!(
            "{:?}",
            run(&crate::gql::parse(q).unwrap(), &st)
                .rows
                .iter()
                .next()
                .expect("one row")
                .to_vec()
        )
    };
    let one = |q: &str| -> String {
        let r = run(&crate::gql::parse(q).unwrap(), &st);
        let row = r.rows.iter().next().expect("one row");
        format!("{:?}", row[0])
    };
    let hop = "MATCH (:A)-[:E]->(x)";

    assert_eq!(
        vals(&format!("{hop} RETURN count(*) AS c, max(x.k) AS m")),
        format!(
            "[{}, {}]",
            one(&format!("{hop} RETURN count(*) AS c")),
            one(&format!("{hop} RETURN max(x.k) AS m"))
        )
    );
    assert_eq!(
        vals(&format!("{hop} RETURN min(x.k) AS lo, max(x.k) AS hi")),
        format!(
            "[{}, {}]",
            one(&format!("{hop} RETURN min(x.k) AS lo")),
            one(&format!("{hop} RETURN max(x.k) AS hi"))
        )
    );
    // `count(x.k)` is MULTIPLICITY-weighted (hi counts twice) while `max` is not, which is the
    // distinction the repeated far end exists to expose: 3 against 4 rows.
    assert_eq!(
        vals(&format!(
            "{hop} RETURN count(x.k) AS n, count(*) AS c, max(x.k) AS m"
        )),
        "[Num(3.0), Num(4.0), Num(9.0)]"
    );
    // `sum`/`avg` are refused on a frontier (item 376) and answered by the general path — they
    // must still be RIGHT, which is what a wrongly-admitted weighted sum would break.
    assert_eq!(
        vals(&format!("{hop} RETURN sum(x.k) AS s, count(*) AS c")),
        "[Num(20.0), Num(4.0)]"
    );
    // An aggregate over the START (slot 0) is not this arm's shape — it must DECLINE, and the
    // general path's answer is the oracle. `a2` reaches one far end and `a1` two, so a
    // frontier-indexed read of `k2` would not even be a plausible number.
    assert_eq!(
        vals(&format!("{hop} RETURN count(*) AS c, max(a.k2) AS m").replace("(:A)", "(a:A)")),
        format!(
            "[{}, {}]",
            one(&format!("{hop} RETURN count(*) AS c")),
            one("MATCH (a:A)-[:E]->(x) RETURN max(a.k2) AS m")
        )
    );

    // An empty frontier: the counts are zero and the extrema are NULL, not a zero.
    let mut b2 = Builder::default();
    b2.node(&["A"], &[("name", s("alone"))]);
    b2.node(&["B"], &[("k", n(1.0))]);
    let st2 = b2.build();

    assert_eq!(
        format!(
            "{:?}",
            run(
                &crate::gql::parse("MATCH (:A)-[:E]->(x) RETURN count(*) AS c, max(x.k) AS m")
                    .unwrap(),
                &st2
            )
            .rows
            .iter()
            .next()
            .expect("one row")
            .to_vec()
        ),
        "[Num(0.0), Null]"
    );
}

/// Item 572: the TRAVERSAL mask must count what enumeration counts.
///
/// A `k = 1` per-repetition `WHERE` is a function of one `(source, edge, target)` triple, and
/// under `Dir::Out` an edge id fixes all three — so one edge-indexed mask carries a target test,
/// an edge test, a source test, and any conjunction. That is why it is a traversal mask and not a
/// node mask beside an edge mask: `WHERE y.k > 20 AND e.w > 5` does not factor into those two.
///
/// Measured on a 60,000-vertex / 180,000-edge probe, one case per process:
///
///   WHERE e.w > 5                37.29ms -> 1.82   the EDGE
///   WHERE x.k > 50               32.61   -> 1.68   the rep SOURCE
///   WHERE y.k > 50 AND e.w > 5   43.81   -> 2.61   both at once
///   WHERE y.k > 50               (item 570's body_filter route)    1.58
///
/// THE FIXTURE SIZE IS LOAD-BEARING, which item 570 learned by having four mutants survive. The
/// algebra is gated on `src.len() * avg_deg.powi(max) > 2 * (nodes + edges)`; 400 nodes at
/// out-degree 4 gives 6,400 against 4,000, where a 12-node fixture gives 48 against 120 and the
/// closed form never executes.
///
/// The check is the COUNT against the materialized ROWS of the same pattern — the rows go through
/// the walk, so this is algebra against enumeration.
#[test]
fn the_traversal_mask_counts_what_enumeration_counts() {
    let mut b = Builder::default();
    let n: u32 = 400;

    for i in 0..n {
        // every fifth vertex is MISSING `k`, so the null comparisons are reached
        if i % 5 == 4 {
            b.node(&["P"], &[]);
        } else {
            b.node(&["P"], &[("k", Value::Num(f64::from(i % 90)))]);
        }
    }

    for i in 0..n {
        for d in [1u32, 7, 13, 29] {
            b.edge(i, (i * 3 + d) % n, "T");
        }
    }
    // a SELF-LOOP (the trail correction's only witness) and a PARALLEL pair
    b.edge(0, 0, "T");
    b.edge(1, 4, "T");

    let mut store = b.build();

    // Edge props are set after `build`, by eid in insertion order. Every seventh edge is left
    // MISSING `w`, which is what reaches the null comparisons: a mask over EVERY edge has to
    // agree with the walk about those too.
    for eid in 0..(n * 4 + 2) {
        if !eid.is_multiple_of(7) {
            store.set_edge_prop(eid, "w", Value::Num(f64::from(eid % 10)));
        }
    }

    let store = store;
    let val = |q: &str| -> f64 {
        match crate::exec::try_run(&opt_plan(q, &store), &store)
            .unwrap()
            .rows
            .iter()
            .next()
            .expect("one row")[0]
        {
            Value::Num(x) => x,
            ref o => panic!("{o:?}"),
        }
    };
    let rows = |q: &str| -> usize {
        crate::exec::try_run(&opt_plan(q, &store), &store)
            .unwrap()
            .rows
            .len()
    };

    for mode in ["", "TRAIL ", "WALK "] {
        for quant in ["{1,2}", "{0,2}", "{1,1}", "{2,2}"] {
            for pred in [
                " WHERE e.w > 5",
                " WHERE e.w <= 5",
                " WHERE x.k > 20",
                " WHERE y.k > 20",
                " WHERE y.k > 20 AND e.w > 5",
                " WHERE y.k > 20 OR e.w > 5",
                " WHERE e.w IS NULL",
                " WHERE y.k IS NULL",
                " WHERE NOT (e.w > 5)",
                " WHERE x.k < y.k",
                " WHERE true",
            ] {
                let unit = format!("(a:P)((x)-[e:T]->(y){pred}){quant}");

                assert_eq!(
                    val(&format!("MATCH {mode}{unit} RETURN count(*) AS c")),
                    rows(&format!("MATCH {mode}{unit}(z) RETURN z.k AS n")) as f64,
                    "the algebra disagreed with enumeration: {mode}{unit}"
                );
            }
            // the ENDPOINT filter beside the per-rep one: two masks, two positions
            let both = format!("(a:P)((x)-[e:T]->(y) WHERE e.w > 5){quant}(z WHERE z.k < 40)");

            assert_eq!(
                val(&format!("MATCH {mode}{both} RETURN count(*) AS c")),
                rows(&format!("MATCH {mode}{both} RETURN z.k AS n")) as f64,
                "endpoint beside per-rep disagreed: {mode}{both}"
            );

            // THE PATH SOURCE, mini-scope slot `2k+1`, which is why the guard is `max_slot <= 2`
            // and not `<= 3`. An inline bracket `WHERE` on an abbreviated var-length hop MAY
            // read the outer anchor — `varlen.rs` documents the slot and the parser maps it —
            // and that lowers to a `k = 1` RepeatGroup, so this shape reaches here. It is NOT a
            // function of one traversal: the anchor varies per path, and the mini-batch the mask
            // builds has only three columns, so admitting it reads a column that is not there.
            //
            // Measured: this shape stays at 33.92ms where the traversal-mask shapes are ~1.8,
            // which is the guard declining exactly as intended. Mutating the bound to `<= 3`
            // survived the whole suite until this case existed.
            let anchored = format!("(a:P)-[e:T WHERE a.k > 20]->{quant}(z)");

            assert_eq!(
                val(&format!("MATCH {mode}{anchored} RETURN count(*) AS c")),
                rows(&format!("MATCH {mode}{anchored} RETURN z.k AS n")) as f64,
                "a per-rep predicate on the PATH SOURCE disagreed: {mode}{anchored}"
            );
        }
    }
}

/// Item 572: the traversal mask asks the predicate about EVERY edge in the store, so it can FAULT
/// where the walk never would — and a query that answers today has to keep answering.
///
/// The same hazard `an_endpoint_predicate_is_evaluated_only_for_reached_nodes` records for the
/// node mask. `traversal_pass_mask` returns `Err`, the algebra breaks out of its labelled block,
/// and enumeration answers. Without that path this query would start raising.
#[test]
fn a_faulting_traversal_predicate_falls_back_to_enumeration() {
    let mut b = Builder::default();
    let n: u32 = 400;

    for i in 0..n {
        b.node(&["P"], &[("k", Value::Num(f64::from(i % 90)))]);
    }
    for i in 0..n {
        for d in [1u32, 7, 13, 29] {
            b.edge(i, (i * 3 + d) % n, "T");
        }
    }
    // Two vertices NOT labelled `P`, joined by an edge whose `w` is a STRING. No walk anchored on
    // `(a:P)` reaches it, so enumeration never evaluates the predicate there — but the mask does.
    let u = b.node(&["Q"], &[("k", Value::Num(1.0))]);
    let v = b.node(&["Q"], &[("k", Value::Num(2.0))]);

    b.edge(u, v, "T");

    let mut store = b.build();
    let poison = n * 4;

    // `% 10`, NOT `% 4`: with every weight under the threshold the predicate rejects nothing,
    // the filtered and unfiltered counts coincide, and the mutant that swallows the mask's
    // `Err` (so the mask is dropped entirely) survives. It did, until this line spanned the
    // threshold. Sixth coinciding fixture in this run of ticks.
    for eid in 0..poison {
        store.set_edge_prop(eid, "w", Value::Num(f64::from(eid % 10)));
    }
    store.set_edge_prop(poison, "w", s("not a number"));

    let store = store;
    let q = "MATCH (a:P)((x)-[e:T]->(y) WHERE CAST(e.w AS INTEGER) <= 5){1,2} RETURN count(*) AS c";
    let got = crate::exec::try_run(&opt_plan(q, &store), &store);

    // FIRST: prove the poison edge really does fault the EVALUATOR THE MASK USES, or this test
    // passes for the wrong reason.
    //
    // It cannot be shown through the per-rep predicate itself, and that is the interesting part:
    // `rep_pred_ok` ends in `.unwrap_or(false)` — "a false / null / faulting predicate fails the
    // rep" — so a per-repetition `WHERE` NEVER raises. The mask is built with `filter_keep`,
    // which does, so the same value is poison there and inert in the walk. The non-group
    // spelling is what exhibits it.
    assert!(
        crate::exec::try_run(
            &opt_plan(
                "MATCH (a:Q)-[e:T]->(y) WHERE CAST(e.w AS INTEGER) <= 5 RETURN count(*) AS c",
                &store,
            ),
            &store,
        )
        .is_err(),
        "the fixture's poison edge must fault `filter_keep`, or this test proves nothing"
    );
    assert!(
        got.is_ok(),
        "an unreached edge's value must not be evaluated: {:?}",
        got.err()
    );
    // And the answer is still the enumerated one.
    let rows = crate::exec::try_run(
        &opt_plan(
            "MATCH (a:P)((x)-[e:T]->(y) WHERE CAST(e.w AS INTEGER) <= 5){1,2}(z) RETURN z.k AS n",
            &store,
        ),
        &store,
    )
    .unwrap()
    .rows
    .len();

    match got.unwrap().rows.iter().next().expect("one row")[0] {
        Value::Num(x) => assert_eq!(x, rows as f64, "fallback answered a different count"),
        ref o => panic!("{o:?}"),
    }
}

/// Item 575: a per-repetition predicate reading nothing but the PATH SOURCE is a filter on the
/// source ROW, because it is constant along a path — it admits every repetition from that source
/// or none.
///
/// It was the one position in the per-rep enum still enumerating: `query_bench` priced it at
/// 304,725us against the traversal case's 7,978. On a 60,000-vertex probe,
/// `-[e:T WHERE a.age > 50]->{1,2}(y)` goes 32.27ms -> 0.81.
///
/// THE SUBTLETY, and the reason this is not just a filter on `src`: a ZERO-LENGTH path has NO
/// REPETITIONS, so the predicate never runs for it and the row is emitted whatever the predicate
/// says. On a 4-node ring where `a.age > 25` admits two of four sources, both engines agree:
///
///   `{0,2}`  8 = 4 filtered hop paths + 4 zero-length rows, one per source
///   `{0,0}`  4, the predicate irrelevant
///
/// So the seed mask gates the HOP terms and NOT the `min == 0` term. Gating both answers 6 and 2.
///
/// The fixture is 400 nodes at out-degree 4 for the reason item 570 learned: the algebra is gated
/// on `src.len() * avg_deg.powi(max) > 2 * (nodes + edges)`, so a small fixture never reaches it
/// and the arithmetic goes untested.
#[test]
fn a_path_source_per_rep_predicate_is_a_seed_filter() {
    let mut b = Builder::default();
    let n: u32 = 400;

    for i in 0..n {
        b.node(&["P"], &[("k", Value::Num(f64::from(i % 90)))]);
    }
    for i in 0..n {
        for d in [1u32, 7, 13, 29] {
            b.edge(i, (i * 3 + d) % n, "T");
        }
    }
    b.edge(0, 0, "T"); // the trail correction's witness

    let store = b.build();
    let val = |q: &str| -> f64 {
        match crate::exec::try_run(&opt_plan(q, &store), &store)
            .unwrap()
            .rows
            .iter()
            .next()
            .expect("one row")[0]
        {
            Value::Num(x) => x,
            ref o => panic!("{o:?}"),
        }
    };
    let rows = |q: &str| -> usize {
        crate::exec::try_run(&opt_plan(q, &store), &store)
            .unwrap()
            .rows
            .len()
    };

    for mode in ["", "TRAIL ", "WALK "] {
        for quant in ["{1,2}", "{0,2}", "{1,1}", "{2,2}", "{0,1}"] {
            for pred in [
                "a.k > 20",
                "a.k < 20",
                "a.k >= 0",
                "a.k > 999",
                "a.k IS NULL",
            ] {
                let pat = format!("(a:P)-[e:T WHERE {pred}]->{quant}");

                // The count against the materialized ROWS of the same pattern: the rows go
                // through the walk, so this is the closed form against enumeration.
                assert_eq!(
                    val(&format!("MATCH {mode}{pat}(z) RETURN count(*) AS c")),
                    rows(&format!("MATCH {mode}{pat}(z) RETURN z.k AS n")) as f64,
                    "the seed filter disagreed with enumeration: {mode}{pat}"
                );
            }
            // An ENDPOINT filter beside it, which applies at a different place.
            let both = format!("(a:P)-[e:T WHERE a.k > 20]->{quant}(z WHERE z.k < 40)");

            assert_eq!(
                val(&format!("MATCH {mode}{both} RETURN count(*) AS c")),
                rows(&format!("MATCH {mode}{both} RETURN z.k AS n")) as f64,
                "endpoint beside the seed filter disagreed: {mode}{both}"
            );
        }
    }

    // A FAULTING source predicate. The mask asks about EVERY node, so it can fault where the
    // walk never would — a `:Q` vertex no `(a:P)` walk reaches, carrying a STRING `k`. The mask
    // returns `Err`, the algebra breaks out of its labelled block, and enumeration answers with
    // the per-rep rule that a faulting predicate fails the rep. Swallowing that `Err` instead
    // drops the mask entirely and counts the paths the predicate rejects — a mutant that
    // survived until this case existed.
    //
    // `CAST`, not arithmetic: item 572 records that `k + 1` on a string is NULL rather than an
    // error, which made an earlier fault test vacuous.
    {
        let mut c = Builder::default();

        for i in 0..n {
            c.node(&["P"], &[("k", Value::Num(f64::from(i % 90)))]);
        }
        for i in 0..n {
            for d in [1u32, 7, 13, 29] {
                c.edge(i, (i * 3 + d) % n, "T");
            }
        }

        let poison = c.node(&["Q"], &[("k", s("not a number"))]);

        c.edge(poison, 0, "T");

        let st = c.build();
        let q = "MATCH (a:P)-[e:T WHERE CAST(a.k AS INTEGER) > 20]->{1,2}(z) RETURN count(*) AS c";
        let got = crate::exec::try_run(&opt_plan(q, &st), &st);

        assert!(
            got.is_ok(),
            "an unreached vertex's value must not be evaluated: {:?}",
            got.err()
        );

        let want = crate::exec::try_run(
            &opt_plan(
                "MATCH (a:P)-[e:T WHERE CAST(a.k AS INTEGER) > 20]->{1,2}(z) RETURN z.k AS n",
                &st,
            ),
            &st,
        )
        .unwrap()
        .rows
        .len();

        match got.unwrap().rows.iter().next().expect("one row")[0] {
            Value::Num(x) => assert_eq!(x, want as f64, "the fallback answered a different count"),
            ref o => panic!("{o:?}"),
        }
        // And the poison really is poison for `filter_keep`, which is what the mask uses.
        assert!(
            crate::exec::try_run(
                &opt_plan(
                    "MATCH (a:Q)-[:T]->(z) WHERE CAST(a.k AS INTEGER) > 20 RETURN count(*) AS c",
                    &st,
                ),
                &st,
            )
            .is_err(),
            "the fixture's poison value must fault `filter_keep`, or this proves nothing"
        );
    }

    // THE ZERO-LENGTH TERM IS NOT GATED. `{0,1}` from 400 sources is 400 zero-length rows plus
    // the filtered one-hop paths; gating it would lose the rows of every rejected source. This
    // asserts the relationship directly rather than through a constant, so it survives a
    // fixture change.
    let zero_only = val("MATCH (a:P)-[e:T WHERE a.k > 999]->{0,1}(z) RETURN count(*) AS c");

    assert_eq!(
        zero_only, 400.0,
        "a predicate NO source passes must still emit every zero-length path"
    );
    assert_eq!(
        val("MATCH (a:P)-[e:T WHERE a.k > 999]->{0,2}(z) RETURN count(*) AS c"),
        400.0,
        "and at a deeper bound too"
    );
    assert_eq!(
        val("MATCH (a:P)-[e:T WHERE a.k > 999]->{1,2}(z) RETURN count(*) AS c"),
        0.0,
        "while `min = 1` has no zero-length path to emit"
    );
}

/// Item 586: the degree algebra reads IN-adjacency as happily as OUT.
///
/// `try_degree_algebra` was gated on `Dir::Out` from item 64, and the refusal cost 9.0x for an
/// IDENTICAL count — 35.99ms against 3.99 at 200,000 vertices / 1,000,000 edges, both answering
/// 5,999,996 — while a single IN hop costs exactly what a single OUT hop does (0.51ms each). The
/// in-adjacency was never the reason; nothing in degree arithmetic prefers a direction.
///
/// TWO fixture properties are load-bearing, and the first one nearly cost this test its teeth:
///
///   - THE START LABEL MUST BE SELECTIVE. Counting every path from EVERY source, reversal is a
///     bijection between the forward and backward path sets, so `(a:P)-[:T]->{1,2}(y)` and its
///     `<-[:T]-` twin return the SAME NUMBER whatever the engine does. A probe of mine read
///     `out=232 in=232` and would have passed with the direction wired backwards. `:Q` sits on a
///     third of the nodes, and the asymmetry is asserted below rather than assumed.
///   - THE FIXTURE MUST TRIP THE GATE (`src.len() * avg_deg.powi(max) > 2 * (nodes + edges)`),
///     item 570's lesson: at 400 nodes of degree 4 the algebra executes; at 12 nodes it never
///     does and every mutant survives.
///
/// The check is the COUNT against the materialized ROWS of the same pattern. Rows go through the
/// walk, so this is algebra against enumeration — including the group form, whose per-rep
/// predicate is the only shape that can see `traversal_pass_mask`'s slot swap: under `Dir::In` the
/// node the traversal STANDS ON is the edge's target and the node it REACHES is the edge's source,
/// so `WHERE x.k < y.k` asks the opposite question if the mask is built from `(from, eid, to)`.
#[test]
fn the_degree_algebra_reads_in_adjacency_too() {
    let mut b = Builder::default();
    let n: u32 = 400;

    for i in 0..n {
        // `:Q` on a third, so the source set is SELECTIVE and the two directions differ.
        let labels: &[&str] = if i % 3 == 0 { &["P", "Q"] } else { &["P"] };

        // every fifth vertex MISSING `k`, so the null comparisons are reached
        if i % 5 == 4 {
            b.node(labels, &[]);
        } else {
            b.node(labels, &[("k", Value::Num(f64::from(i % 90)))]);
        }
    }

    // THE DEGREE IS LOAD-BEARING, and a selective source set is what makes it so. The gate is
    // `src.len() * avg_deg^max > 2 * (nodes + edges)`; with `:Q` on a third and `edges = d*n`
    // that is `(n/3) * d^2 > 2n(1 + d)`, i.e. `d^2 > 6 + 6d` — **`d >= 7` or the algebra NEVER
    // runs at any n.** Written first at degree 4 (item 572's figure, where the whole graph was
    // the source set) this test passed in 0.16s having never once executed the code it exists for.
    // Ten edges per vertex gives `33n > 22n`, comfortably over.
    //
    // A SKEWED shape rather than a regular one: a hub every 40th vertex collects extra in-edges,
    // so in-degree and out-degree differ per vertex and not just in aggregate.
    for i in 0..n {
        for d in [1u32, 7, 13, 29, 31, 37, 41, 43, 47, 53] {
            b.edge(i, (i * 3 + d) % n, "T");
        }

        if i % 40 == 0 {
            for j in 0..12 {
                b.edge((i + j * 7 + 1) % n, i, "T");
            }
        }
    }

    b.edge(0, 0, "T"); // SELF-LOOP: the trail correction's witness, and it sits in BOTH adjacencies
    b.edge(1, 4, "T"); // PARALLEL with one of the generated edges

    let mut store = b.build();
    let ec = store.edge_count() as u32;

    for eid in 0..ec {
        if !eid.is_multiple_of(7) {
            store.set_edge_prop(eid, "w", Value::Num(f64::from(eid % 10)));
        }
    }

    let store = store;
    let val = |q: &str| -> f64 {
        match crate::exec::try_run(&opt_plan(q, &store), &store)
            .unwrap()
            .rows
            .iter()
            .next()
            .expect("one row")[0]
        {
            Value::Num(x) => x,
            ref o => panic!("{o:?}"),
        }
    };
    let rows = |q: &str| -> usize {
        crate::exec::try_run(&opt_plan(q, &store), &store)
            .unwrap()
            .rows
            .len()
    };

    // THE GATE ITSELF, asserted. Item 570 had four mutants survive because the fixture never
    // reached the closed form, and the only symptom was a fast green test. Recomputing the gate's
    // own arithmetic here means a future edit that shrinks the fixture fails loudly instead.
    {
        let nc = store.node_count() as f64;
        let ec = store.edge_count() as f64;
        let avg_deg = ec / nc;
        let srcs = store.nodes_with_label("Q").len() as f64;
        let est = srcs * avg_deg * avg_deg;

        assert!(
            est > 2.0 * (nc + ec),
            "the fixture does NOT trip the degree algebra's gate ({est} vs {}), so every mutant \
             of it would survive this test",
            2.0 * (nc + ec)
        );
    }

    // THE FIXTURE'S OWN PRECONDITION. If these ever coincide the test below is measuring nothing,
    // and it would still pass — so it is asserted, not commented.
    for quant in ["{1,2}", "{2,2}", "{1,1}"] {
        let out = val(&format!(
            "MATCH (a:Q)-[:T]->{quant}(y) RETURN count(*) AS c"
        ));
        let inc = val(&format!(
            "MATCH (a:Q)<-[:T]-{quant}(y) RETURN count(*) AS c"
        ));

        assert_ne!(
            out, inc,
            "{quant}: the fixture is direction-SYMMETRIC, so this test cannot witness a reversed \
             direction at all"
        );
    }

    // The ABBREVIATED form, both directions, against enumeration.
    for mode in ["", "TRAIL ", "WALK "] {
        for quant in ["{1,2}", "{0,2}", "{1,1}", "{2,2}"] {
            for arrow in ["-[:T]->", "<-[:T]-"] {
                for end in [
                    "(y)",
                    "(y:Q)",
                    "(y WHERE y.k > 20)",
                    "(y WHERE y.k IS NULL)",
                ] {
                    let pat = format!("{mode}(a:Q){arrow}{quant}{end}");
                    let c = val(&format!("MATCH {pat} RETURN count(*) AS c"));
                    let r = rows(&format!("MATCH {pat} RETURN y"));

                    assert_eq!(c, r as f64, "count != rows for MATCH {pat}");
                }
            }
        }
    }

    // The GROUP form, where a per-rep predicate names BOTH ends of one traversal. This is the
    // shape that sees the mask's slot swap, and `x.k < y.k` is the member that distinguishes them.
    for mode in ["", "WALK "] {
        for quant in ["{1,2}", "{2,2}", "{0,2}"] {
            for arrow in ["-[e:T]->", "<-[e:T]-"] {
                for pred in [
                    " WHERE e.w > 5",
                    " WHERE x.k > 20",
                    " WHERE y.k > 20",
                    " WHERE x.k < y.k",
                    " WHERE y.k < x.k",
                    " WHERE y.k > 20 AND e.w > 5",
                    " WHERE e.w IS NULL",
                    " WHERE true",
                ] {
                    let unit = format!("{mode}(a:Q)((x){arrow}(y){pred}){quant}");
                    let c = val(&format!("MATCH {unit} RETURN count(*) AS c"));
                    let r = rows(&format!("MATCH {unit} RETURN y"));

                    assert_eq!(c, r as f64, "count != rows for MATCH {unit}");
                }
            }
        }
    }

    // `x.k < y.k` and `y.k < x.k` must DISAGREE in at least one direction, or the slot swap is
    // untested even though every assertion above passed.
    let lt = val("MATCH (a:Q)((x)<-[e:T]-(y) WHERE x.k < y.k){1,2} RETURN count(*) AS c");
    let gt = val("MATCH (a:Q)((x)<-[e:T]-(y) WHERE y.k < x.k){1,2} RETURN count(*) AS c");

    assert_ne!(
        lt, gt,
        "the two orderings coincide, so the slot swap is unwitnessed"
    );
}

/// Item 587: a WALK counts by LEVELS at any depth, and must agree with enumeration at every one.
///
/// The algebra was bounded at `max <= 2` by the TRAIL correction — at two hops there is exactly
/// one way to reuse an edge and the closed form subtracts it; at three there are several
/// interacting ways and no single term. A WALK forbids nothing, so `u_j(v) = sum over traversals
/// v -> y of u_{j-1}(y)` counts it in one pass per level. And WALK is the GREMLIN mode: `repeat()`
/// lowers to `PathMode::Walk`, so depth past 2 is the common Gremlin shape, not a niche ISO one.
/// Priced at 200,000 vertices / 600,000 edges: WALK `{1,3}` 40.36ms -> 3.96, `{1,4}` 107.45 ->
/// 5.25, `g.V().repeat(out()).times(4).count()` 104.96 -> 4.94.
///
/// THE GATE AGAIN (items 570, 586). `src.len() * avg_deg^max > max.max(2) * (nodes + edges)`: with
/// the whole graph as sources that is `d^3 > 3(1 + d)`, so **degree 3 is the minimum at depth 3**
/// and degree 2 never reaches the recurrence at all. Asserted below, because the only symptom of
/// getting it wrong is a fast green test.
///
/// The check is count against the materialized ROWS at every depth from 1 to 5, which also pins
/// the two routes against each other: depths 1 and 2 run the closed form and depths 3+ the
/// recurrence, so a disagreement between them shows up as one depth failing while its neighbour
/// passes.
#[test]
fn a_deep_walk_counts_what_enumeration_counts() {
    let mut b = Builder::default();
    let n: u32 = 300;

    for i in 0..n {
        let labels: &[&str] = if i % 3 == 0 { &["P", "Q"] } else { &["P"] };

        if i % 5 == 4 {
            b.node(labels, &[]);
        } else {
            b.node(labels, &[("k", Value::Num(f64::from(i % 90)))]);
        }
    }

    // Degree 4, over the WHOLE graph as sources: `4^3 = 64 > 3 * 5 = 15`, so depth 3 reaches the
    // recurrence. A SKEWED hub so in- and out-degree differ, since both directions are checked.
    for i in 0..n {
        for d in [1u32, 7, 13, 29] {
            b.edge(i, (i * 3 + d) % n, "T");
        }

        if i % 30 == 0 {
            for j in 0..8 {
                b.edge((i + j * 11 + 1) % n, i, "T");
            }
        }
    }

    b.edge(0, 0, "T"); // a SELF-LOOP, which a WALK may take repeatedly and a trail may not
    b.edge(1, 4, "T"); // a PARALLEL pair

    let mut store = b.build();
    let ec = store.edge_count() as u32;

    for eid in 0..ec {
        if !eid.is_multiple_of(7) {
            store.set_edge_prop(eid, "w", Value::Num(f64::from(eid % 10)));
        }
    }

    let store = store;

    {
        let nc = store.node_count() as f64;
        let ecf = store.edge_count() as f64;
        let avg_deg = ecf / nc;
        let est = nc * avg_deg.powi(3);

        assert!(
            est > 3.0 * (nc + ecf),
            "the fixture does NOT reach the level recurrence at depth 3 ({est} vs {}), so every \
             mutant of it would survive",
            3.0 * (nc + ecf)
        );
    }

    let val = |q: &str| -> f64 {
        match crate::exec::try_run(&opt_plan(q, &store), &store)
            .unwrap()
            .rows
            .iter()
            .next()
            .expect("one row")[0]
        {
            Value::Num(x) => x,
            ref o => panic!("{o:?}"),
        }
    };
    let rows = |q: &str| -> usize {
        crate::exec::try_run(&opt_plan(q, &store), &store)
            .unwrap()
            .rows
            .len()
    };

    // DEPTH 1 THROUGH 5. One and two run the closed form, three and up the recurrence.
    for max in 1..=5u32 {
        for min in [0u32, 1, max] {
            for arrow in ["-[:T]->", "<-[:T]-"] {
                for end in [
                    "(y)",
                    "(y:Q)",
                    "(y WHERE y.k > 20)",
                    "(y WHERE y.k IS NULL)",
                ] {
                    let pat = format!("WALK (a:P){arrow}{{{min},{max}}}{end}");
                    let c = val(&format!("MATCH {pat} RETURN count(*) AS c"));
                    let r = rows(&format!("MATCH {pat} RETURN y"));

                    assert_eq!(c, r as f64, "count != rows for MATCH {pat}");
                }
            }
        }
    }

    // The per-rep masks at depth 3+, where they gate every LEVEL rather than one hop.
    for max in [3u32, 4] {
        for arrow in ["-[e:T]->", "<-[e:T]-"] {
            for pred in [
                " WHERE e.w > 5",
                " WHERE y.k > 20",
                " WHERE x.k < y.k",
                " WHERE y.k > 20 AND e.w > 5",
                " WHERE e.w IS NULL",
            ] {
                let unit = format!("WALK (a:P)((x){arrow}(y){pred}){{1,{max}}}");
                let c = val(&format!("MATCH {unit} RETURN count(*) AS c"));
                let r = rows(&format!("MATCH {unit} RETURN y"));

                assert_eq!(c, r as f64, "count != rows for MATCH {unit}");
            }
        }
    }

    // THE SEED PREDICATE at depth 3+, which is item 575's shape: a per-rep `WHERE` reading only
    // the PATH SOURCE. It is constant along a path, so it admits every repetition from that
    // source or none, and the recurrence gates the source where the level's contribution is
    // collected rather than inside the step.
    //
    // These cases were MISSING at first and two mutants survived because of it — dropping the
    // seed gate entirely, and gating the zero-length term by it. Every other per-rep predicate in
    // this test reads `x`, `y` or `e`, so `seed` was `None` throughout and both mutants were
    // no-ops. A predicate on the hop's outer anchor is a different slot (`2k+1`) and needs its
    // own case.
    for max in [3u32, 4] {
        for arrow in ["-[e:T WHERE a.k > 20]->", "<-[e:T WHERE a.k > 20]-"] {
            for min in [0u32, 1] {
                let pat = format!("WALK (a:P){arrow}{{{min},{max}}}(y)");
                let c = val(&format!("MATCH {pat} RETURN count(*) AS c"));
                let r = rows(&format!("MATCH {pat} RETURN y"));

                assert_eq!(c, r as f64, "count != rows for MATCH {pat}");
            }
        }
    }

    // The ZERO-LENGTH term is NOT seed-gated, and that has to be witnessed rather than asserted
    // by construction: a `{0,n}` with a seed predicate emits one row per source whatever the
    // predicate says, because a zero-length path has no repetition for it to run on. So the
    // `{0,3}` count must exceed the `{1,3}` count by the FULL source row count, not by the
    // number of sources the predicate admits.
    {
        let zero = val("MATCH WALK (a:P)-[e:T WHERE a.k > 20]->{0,3}(y) RETURN count(*) AS c");
        let one = val("MATCH WALK (a:P)-[e:T WHERE a.k > 20]->{1,3}(y) RETURN count(*) AS c");
        let sources = val("MATCH (a:P) RETURN count(*) AS c");
        let admitted = val("MATCH (a:P) WHERE a.k > 20 RETURN count(*) AS c");

        assert!(
            admitted < sources,
            "the seed predicate admits every source, so this is vacuous"
        );
        assert_eq!(
            zero - one,
            sources,
            "the zero-length term was gated by the seed predicate"
        );
    }

    // A TRAIL at depth 3 must still be REFUSED, not quietly counted as a walk. The two answers
    // differ on this fixture (the self-loop and the parallel pair give a walk strictly more
    // paths), so if the trail ever took the recurrence this assertion fails.
    let walk3 = val("MATCH WALK (a:P)-[:T]->{1,3}(y) RETURN count(*) AS c");
    let trail3 = val("MATCH (a:P)-[:T]->{1,3}(y) RETURN count(*) AS c");

    assert!(
        trail3 < walk3,
        "a trail cannot have at least as many paths as a walk here ({trail3} vs {walk3}) — either \
         the fixture lost its self-loop or the trail took the walk's route"
    );
    assert_eq!(
        trail3,
        rows("MATCH (a:P)-[:T]->{1,3}(y) RETURN y") as f64,
        "the depth-3 TRAIL count disagrees with its own enumeration"
    );
}

/// A TWO-hop chain whose FIRST position is gated: the shape item 748 newly routes to
/// `try_nhop_sweep_count`, and which had no test at all before it did.
///
/// The sweep took two hops only when the LAST position was gated
/// (`2 => chain.gates[hops].is_some()`). Item 306 measured that split and recorded an INTERIOR
/// gate as 0.74x — slower than the product arm that already answers it — but its table has no row
/// for a gate on the FIRST position, and the condition excluded start and interior together. Item
/// 309 had meanwhile established that a START gate is the sweep's BEST case: it reverses a chain
/// to turn an end gate into a start one, 0.80ms against 0.29. So the excluded case was the good
/// one, and admitting it measured 4.5-6.4x at every fixture size from 5,000 to 200,000 vertices.
///
/// A ROUTE CHOICE IS ANSWER-EQUIVALENT, so nothing here can fail if the route simply flips back —
/// that guard is the alternated A/B ([[perf-gate-needs-its-own-test]]). What this test covers is
/// the thing the A/B cannot see: the sweep now receives a shape it never received before, and its
/// seed gate has to be applied correctly on it.
///
/// Compared against `count(c.k)`, which does NOT take this route — the technique
/// `three_hop_product_agrees_with_the_general_path_in_every_direction` records, and for its reason:
/// the first version of that test compared the fast path WITH ITSELF and all five mutants survived.
/// Every node carries `k`, so the two spellings count the same rows.
#[test]
fn a_two_hop_chain_gated_at_its_first_position_agrees_with_the_general_path() {
    use crate::value::Value;

    let store = {
        let mut b = crate::store::Builder::default();
        for i in 0..16u32 {
            b.node(&["Univ"], &[("k", Value::Num(f64::from(i % 3)))]);
        }
        // Irregular, with cycles (13 -> 0, 14 -> 2), so a mis-walked hop finds walks rather than
        // returning a silent zero.
        for (from, to) in [
            (0u32, 1u32),
            (0, 2),
            (1, 3),
            (1, 4),
            (2, 5),
            (3, 6),
            (4, 6),
            (5, 7),
            (6, 8),
            (7, 9),
            (8, 10),
            (9, 11),
            (10, 12),
            (11, 13),
            (12, 14),
            (13, 0),
            (14, 2),
            (15, 1),
        ] {
            b.edge(from, to, "K");
        }
        b.build()
    };

    let run = |q: &str| -> f64 {
        let plan = crate::opt::optimize(crate::gql::parse(q).expect("parse"));
        let out = crate::exec::try_run(&plan, &store).expect("run");
        match out.rows.iter().next().and_then(|r| r.first()) {
            Some(Value::Num(n)) => *n,
            other => panic!("not a number: {other:?}"),
        }
    };

    let gated_sweep = run("MATCH (a:Univ)-[:K]->(b)-[:K]->(c) WHERE a.k > 0 RETURN count(*) AS n");
    let gated_general =
        run("MATCH (a:Univ)-[:K]->(b)-[:K]->(c) WHERE a.k > 0 RETURN count(c.k) AS n");
    let ungated = run("MATCH (a:Univ)-[:K]->(b)-[:K]->(c) RETURN count(*) AS n");

    assert!(
        gated_sweep > 0.0,
        "a vacuous fixture proves nothing; the gated count must be positive"
    );
    assert_eq!(
        gated_sweep, gated_general,
        "the newly-routed sweep must agree with a spelling that does not take it"
    );
    // THE MUTATION TARGET: if the seed gate is dropped, the gated count becomes the ungated one.
    assert!(
        gated_sweep < ungated,
        "the start gate must EXCLUDE something ({gated_sweep} against {ungated}), or a dropped \
         gate would be invisible"
    );
}

/// The same shape gated at its INTERIOR position, which item 749 newly routes to the sweep.
///
/// Item 306 measured this case at **0.74x** — genuinely slower than the product arm — and excluded
/// it deliberately, unlike the FIRST position, which its table simply has no row for (item 748).
/// That verdict is now stale and does not reproduce at any fixture size: three alternated rounds
/// read 17.2/16.9/16.7 -> 11.7/10.9/11.0 at 200,000 vertices (**1.53x, disjoint**) and 1.1 -> 1.0
/// at 20,000, with the UNGATED row flat at 2.6-2.7 both arms. The likely reason is that item 309
/// landed AFTER 306 and made the sweep faster — it reverses a chain to turn an end gate into a
/// start one — so 306's number was measured against a worse sweep. That is a hypothesis, not a
/// verified claim: confirming it would need the pre-309 code rebuilt.
///
/// Same oracle as its first-position sibling, and for the same reason: `count(c.k)` does not take
/// this route, so the comparison is against an independent path rather than the fast path itself.
#[test]
fn a_two_hop_chain_gated_at_its_interior_position_agrees_with_the_general_path() {
    use crate::value::Value;

    let store = {
        let mut b = crate::store::Builder::default();
        for i in 0..16u32 {
            b.node(&["Univ"], &[("k", Value::Num(f64::from(i % 3)))]);
        }
        for (from, to) in [
            (0u32, 1u32),
            (0, 2),
            (1, 3),
            (1, 4),
            (2, 5),
            (3, 6),
            (4, 6),
            (5, 7),
            (6, 8),
            (7, 9),
            (8, 10),
            (9, 11),
            (10, 12),
            (11, 13),
            (12, 14),
            (13, 0),
            (14, 2),
            (15, 1),
        ] {
            b.edge(from, to, "K");
        }
        b.build()
    };

    let run = |q: &str| -> f64 {
        let plan = crate::opt::optimize(crate::gql::parse(q).expect("parse"));
        let out = crate::exec::try_run(&plan, &store).expect("run");
        match out.rows.iter().next().and_then(|r| r.first()) {
            Some(Value::Num(n)) => *n,
            other => panic!("not a number: {other:?}"),
        }
    };

    let gated_sweep = run("MATCH (a:Univ)-[:K]->(b)-[:K]->(c) WHERE b.k > 0 RETURN count(*) AS n");
    let gated_general =
        run("MATCH (a:Univ)-[:K]->(b)-[:K]->(c) WHERE b.k > 0 RETURN count(c.k) AS n");
    let ungated = run("MATCH (a:Univ)-[:K]->(b)-[:K]->(c) RETURN count(*) AS n");

    assert!(gated_sweep > 0.0, "a vacuous fixture proves nothing");
    assert_eq!(
        gated_sweep, gated_general,
        "the newly-routed interior gate must agree with a spelling that does not take this route"
    );
    assert!(
        gated_sweep < ungated,
        "the interior gate must EXCLUDE something ({gated_sweep} against {ungated}), or a dropped \
         gate would be invisible"
    );
}

/// A TRAIL's distinct-endpoint set is NOT a WALK's at `min <= 1`, so `try_varlen_distinct_count`'s
/// `max <= 1` trail region cannot be widened to `min <= 1` (items 756, 757).
///
/// That widening is attractive: the default path mode is TRAIL, so the shape a user writes —
/// `MATCH (a)-[:R]->{1,2}(y) RETURN count(DISTINCT y)` — declines the BFS and enumerates, and at
/// 50,000 vertices of degree 5 it does not merely run slowly, it fails with E_RESOURCE_EXHAUSTED
/// while the `MATCH WALK` twin answers in 0.5 ms. Item 756 floated the widening on the strength of
/// the fast path's own doc, which argued the two coincide for `min <= 1` because "the shortest path
/// is simple, reusing no edge".
///
/// It does not hold. The shortest path is a trail only when its length is `>= min`, and for a
/// SOURCE on a cycle that length is 0. Two nodes and one edge is the whole counterexample: a WALK
/// returns to the source by re-crossing the edge, a TRAIL cannot.
///
/// This test is the guard rather than the comment, because the widening produces a wrong ANSWER
/// (2 against 1) and not a slow one — [[perf-gate-needs-its-own-test]] in reverse: a route choice
/// needs a perf A/B, and a SEMANTICS choice needs a pinned answer.
#[test]
fn a_trail_distinct_endpoint_count_is_not_the_walks_at_min_one() {
    let store = {
        let mut b = crate::store::Builder::default();
        b.node(&["S"], &[]); // 0: the only source
        b.node(&["T"], &[]); // 1
        b.edge(0, 1, "R");
        b.build()
    };

    let num = |q: &str| -> f64 {
        use crate::value::Value;
        let plan = crate::opt::optimize(crate::gql::parse(q).expect("parse"));
        let out = crate::exec::try_run(&plan, &store).expect("run");

        match out.rows.iter().next().and_then(|r| r.first()) {
            Some(Value::Num(n)) => *n,
            other => panic!("not a number: {other:?}"),
        }
    };

    // `-[:R]-` is both-directions, so a WALK may cross the single edge back.
    let walk = num("MATCH WALK (x:S)-[:R]-{1,3}(y) RETURN count(DISTINCT y) AS n");
    let trail = num("MATCH (x:S)-[:R]-{1,3}(y) RETURN count(DISTINCT y) AS n");

    assert_eq!(
        walk, 2.0,
        "a walk reaches the source again by re-crossing the edge"
    );
    assert_eq!(
        trail, 1.0,
        "a trail cannot re-cross it, so the source is NOT an endpoint"
    );
    assert_ne!(
        walk, trail,
        "if these ever agree the counterexample has gone and the widening needs re-deriving, \
         not enabling"
    );

    // At ONE hop the two semantics do coincide, which is why `max <= 1` is the region.
    let walk1 = num("MATCH WALK (x:S)-[:R]-{1,1}(y) RETURN count(DISTINCT y) AS n");
    let trail1 = num("MATCH (x:S)-[:R]-{1,1}(y) RETURN count(DISTINCT y) AS n");

    assert_eq!(walk1, trail1, "at one hop no edge can be reused");
    assert_eq!(trail1, 1.0, "and the answer is the single neighbour");
}

/// Item 864: the RANK-BOUNDED streaming top-K for a dictionary key. A dictionary's smallest (or
/// largest) string bounds every value in the column, so once `skip+limit` rows at that extreme
/// rank have been seen IN ARRIVAL ORDER — which is the total order's own tiebreak — nothing later
/// can displace them and the scan stops. Measured at ~1800x on an 8-way column at 200k nodes.
///
/// Every number here was diffed against the PREVIOUS implementation's output before being written
/// down, so these are the old path's answers, not this path's self-report. The fixture is sized
/// and shaped for mutation sensitivity, which took two tries:
///   - 400 nodes, not 60: with a buffer smaller than the trim threshold a DROPPED arrival tiebreak
///     still happened to return the right rows, so that mutant survived.
///   - `d` is ABSENT on most nodes rather than holding an explicit `Value::Null`: an explicit null
///     makes the column `Gen`, which this path declines, so the null case never reached it at all.
///
/// The spelling matters and is the reason an earlier version of this test was vacuous: a
/// CLAUSE-position `ORDER BY` (`RETURN x ORDER BY k`) sorts above the projection, so the plan is
/// `OrderPage{Project{Scan}}` and `try_late_materialize` handles it. Only the STATEMENT position
/// (`ORDER BY k LIMIT n RETURN x`) leaves a bare `Scan` under the sort. A mutant that made this
/// path return NO rows survived all 1,972 tests until the spelling was fixed.
#[test]
fn top_k_rank_bounded_dict_key() {
    const CY: [&str; 4] = ["bb", "aa", "dd", "cc"]; // sorted: aa < bb < cc < dd
    let mut b = Builder::default();
    for i in 0..400u32 {
        let mut props = vec![
            ("c", s(CY[(i % 4) as usize])),
            ("s", s(&format!("s{i:03}"))),
        ];
        // present on three nodes, ABSENT (not null-valued) elsewhere, so the column stays
        // dictionary-encoded and a wide window has to reach past the present rows into NULLs
        if i % 137 == 0 {
            props.push(("d", s(&format!("r{i}"))));
        }
        b.node(&["T"], &props);
    }
    let store = b.build();

    // Asserted, not assumed: if these stopped being dictionary-encoded the arm under test would
    // silently stop being exercised and every case below would still pass.
    assert!(
        matches!(store.column("c"), Some(crate::store::Column::Dict { .. })),
        "c must be dictionary-encoded"
    );
    assert!(
        matches!(store.column("d"), Some(crate::store::Column::Dict { .. })),
        "d must be dictionary-encoded with absent cells"
    );

    let col = |q: &str| -> Vec<String> {
        let plan = crate::opt::optimize_indexed(crate::gql::parse(q).unwrap(), &store);
        run(&plan, &store)
            .rows
            .iter()
            .map(|r| match &r[0] {
                Value::Str(x) => x.to_string(),
                Value::Null => "NULL".to_string(),
                o => panic!("{o:?}"),
            })
            .collect()
    };

    // ASC: "aa" is the smallest, carried by i % 4 == 1, and the tiebreak is arrival — so the
    // answer is the FIRST five such rows, which is also exactly what the early exit claims.
    assert_eq!(
        col("MATCH (t:T) ORDER BY t.c LIMIT 5 RETURN t.s AS x"),
        ["s001", "s005", "s009", "s013", "s017"]
    );
    // DESC: "dd", i % 4 == 2. DESC flips which rank is extreme; it does NOT flip the tiebreak.
    assert_eq!(
        col("MATCH (t:T) ORDER BY t.c DESC LIMIT 5 RETURN t.s AS x"),
        ["s002", "s006", "s010", "s014", "s018"]
    );
    // SKIP pages INSIDE the extreme group, so the window is a slice of it and not its head.
    assert_eq!(
        col("MATCH (t:T) ORDER BY t.c SKIP 3 LIMIT 4 RETURN t.s AS x"),
        ["s013", "s017", "s021", "s025"]
    );
    assert_eq!(
        col("MATCH (t:T) ORDER BY t.c DESC SKIP 2 LIMIT 3 RETURN t.s AS x"),
        ["s010", "s014", "s018"]
    );
    // A WINDOW WIDER THAN THE EXTREME GROUP: 100 rows carry "aa", so a 103-wide window spills into
    // the next rank and the early exit must NOT fire. The three spilled rows are the first "bb"s by
    // arrival, which is what a dropped tiebreak gets wrong.
    let wide = col("MATCH (t:T) ORDER BY t.c LIMIT 103 RETURN t.s AS x");
    assert_eq!(wide.len(), 103);
    assert_eq!(wide[0], "s001");
    assert_eq!(wide[99], "s397", "the hundredth and last \"aa\" by arrival");
    assert_eq!(
        &wide[100..103],
        ["s000", "s004", "s008"],
        "the spill must be the FIRST rows of the next rank, by arrival"
    );
    // NULLS INSIDE THE WINDOW: only three nodes have `d`, so a 6-wide window must place three
    // NULLs after them. This path skips nulls and so cannot order them — it must DECLINE and let
    // the general path do it, rather than return three rows.
    assert_eq!(
        col("MATCH (t:T) ORDER BY t.d LIMIT 6 RETURN t.d AS x"),
        ["r0", "r137", "r274", "NULL", "NULL", "NULL"]
    );
    // Same key DESC: null placement is the front-end's contract and is decided BEFORE the total
    // order, so GQL keeps nulls last under DESC too.
    assert_eq!(
        col("MATCH (t:T) ORDER BY t.d DESC LIMIT 4 RETURN t.d AS x"),
        ["r274", "r137", "r0", "NULL"]
    );
    // CONTROL: a plain string key has no bounded rank, so it has no arm here and goes through the
    // general path. It must still be right, and it must not change when this path changes.
    assert_eq!(
        col("MATCH (t:T) ORDER BY t.s LIMIT 4 RETURN t.s AS x"),
        ["s000", "s001", "s002", "s003"]
    );

    // THE CLAUSE SPELLING MUST AGREE WITH THE STATEMENT SPELLING (item 866). `RETURN x ORDER BY k
    // LIMIT n` puts a `Project` between the sort and the scan, so it reaches this path only
    // because `try_late_materialize` lifts it; before that it was ~1760x slower than the
    // statement spelling of the same query. Asserting the two against EACH OTHER is the property
    // that actually matters, and it is what keeps the lift from drifting.
    for tail in [
        "LIMIT 5",
        "DESC LIMIT 5",
        "SKIP 3 LIMIT 4",
        "LIMIT 103",
        "DESC SKIP 2 LIMIT 3",
    ] {
        let (key, rest) = tail
            .strip_prefix("DESC ")
            .map_or(("t.c", tail), |r| ("t.c DESC", r));
        let stmt = col(&format!(
            "MATCH (t:T) ORDER BY {key} {rest} RETURN t.s AS x"
        ));
        let clause = col(&format!(
            "MATCH (t:T) RETURN t.s AS x ORDER BY {key} {rest}"
        ));
        assert_eq!(stmt, clause, "spellings must agree for `{key} {rest}`");
        assert!(!stmt.is_empty(), "`{key} {rest}` returned nothing");
    }
    // And the same for a NULL-bearing key, where both spellings must decline to the general path.
    assert_eq!(
        col("MATCH (t:T) RETURN t.d AS x ORDER BY t.d LIMIT 6"),
        ["r0", "r137", "r274", "NULL", "NULL", "NULL"]
    );
}

/// Item 871: the two TEMPORAL filter paths added by the filter-representation census — a streaming
/// DATE range predicate, and the typed arm in the unindexed seek fallback that answers a DATE
/// EQUALITY. Both are answer-equivalent to the boxed paths they replace, so the ROUTE has to be
/// asserted alongside the answers: a mutant turning either off returns identical rows.
///
/// The fixture gives every node a date AND a numeric twin carrying the same ordinal, so each date
/// expectation has an independent arithmetic check that does not go through the date path at all.
#[test]
fn temporal_filter_paths() {
    use crate::temporal::{Date, Temporal};
    let mut b = Builder::default();
    for i in 0..400u32 {
        let m = i % 50;
        b.node(
            &["T"],
            &[
                (
                    "d",
                    Value::Temporal(Temporal::Date(Date {
                        days: 19_723 + i32::try_from(m).unwrap_or(0),
                    })),
                ),
                ("m", n(f64::from(m))),
            ],
        );
    }
    // a node with the key ABSENT, which must never match a comparison
    b.node(&["T"], &[("m", n(-1.0))]);
    let store = b.build();

    assert!(
        matches!(
            store.column("d"),
            Some(crate::store::Column::Temporal { .. })
        ),
        "d must be a packed temporal column or neither path under test is reached"
    );

    let cnt = |q: &str| -> f64 {
        let plan = crate::opt::optimize_indexed(crate::gql::parse(q).unwrap(), &store);
        match run(&plan, &store).rows[0][0] {
            Value::Num(x) => x,
            ref o => panic!("{o:?}"),
        }
    };

    // 400 nodes over 50 distinct days => 8 per day. The numeric twin proves the 8 independently.
    assert_eq!(cnt("MATCH (t:T) WHERE t.m = 0 RETURN count(*) AS c"), 8.0);
    assert_eq!(
        cnt("MATCH (t:T) WHERE t.d = DATE '2024-01-01' RETURN count(*) AS c"),
        8.0
    );
    // >= the 8th distinct day keeps 43 of 50 days
    assert_eq!(
        cnt("MATCH (t:T) WHERE t.m >= 7 RETURN count(*) AS c"),
        344.0
    );
    assert_eq!(
        cnt("MATCH (t:T) WHERE t.d >= DATE '2024-01-08' RETURN count(*) AS c"),
        344.0
    );
    assert_eq!(
        cnt("MATCH (t:T) WHERE t.d < DATE '2024-01-08' RETURN count(*) AS c"),
        56.0
    );
    assert_eq!(
        cnt("MATCH (t:T) WHERE t.d <> DATE '2024-01-01' RETURN count(*) AS c"),
        392.0
    );
    // THE FLIPPED SPELLING must reach the same path and the same answer — `num_conj_on_slot`
    // already honoured it and the temporal twin has to as well.
    assert_eq!(
        cnt("MATCH (t:T) WHERE DATE '2024-01-08' <= t.d RETURN count(*) AS c"),
        344.0
    );
    // A DIFFERENT temporal KIND never equals a Date, and must not match rather than fault.
    assert_eq!(
        cnt("MATCH (t:T) WHERE t.d = DATETIME '2024-01-01T00:00:00' RETURN count(*) AS c"),
        0.0
    );
    // The absent-key node is in the label but carries no `d`, so it matches no comparison and
    // IS NOT NULL sees exactly the 400 that do.
    assert_eq!(
        cnt("MATCH (t:T) WHERE t.d IS NOT NULL RETURN count(*) AS c"),
        400.0
    );
    assert_eq!(
        cnt("MATCH (t:T) WHERE t.d IS NULL RETURN count(*) AS c"),
        1.0
    );
    // THE ABSENT CELL'S BACKING VALUE MUST NOT MATCH. A packed column still stores something at
    // an absent row, and for a date column that is day 0 — 1970-01-01. So this query is the one
    // that distinguishes "skipped because `present[i]` is false" from "happened not to equal the
    // literal": without the presence check the absent node would match it. Nothing else in this
    // test can see that, and its mutant survived until this line existed.
    assert_eq!(
        cnt("MATCH (t:T) WHERE t.d = DATE '1970-01-01' RETURN count(*) AS c"),
        0.0,
        "an absent temporal cell must not match its backing default"
    );
    assert_eq!(
        cnt("MATCH (t:T) WHERE t.d >= DATE '1970-01-01' RETURN count(*) AS c"),
        400.0,
        "and must not be swept in by a range that covers its backing default"
    );

    // THE ROUTES, asserted directly. Both are answer-equivalent, so nothing above can tell
    // whether they fired.
    let scan = Plan::Scan {
        label: Some("T".into()),
    };
    let ge = Expr::Compare {
        op: crate::ir::CompareOp::Ge,
        left: Box::new(Expr::Prop {
            slot: 0,
            key: "d".into(),
        }),
        right: Box::new(Expr::Lit(Value::Temporal(Temporal::Date(Date {
            days: 19_730,
        })))),
    };
    assert!(
        matches!(scan, Plan::Scan { .. }),
        "the shape under test is a bare scan"
    );
    assert_eq!(
        fastpath::try_stream_date_count(&store, &Some("T".into()), &ge),
        Some(344),
        "a single-bound DATE range must take the streaming path"
    );
    // a NUMERIC predicate must NOT be claimed by the date path
    let numge = Expr::Compare {
        op: crate::ir::CompareOp::Ge,
        left: Box::new(Expr::Prop {
            slot: 0,
            key: "m".into(),
        }),
        right: Box::new(Expr::Lit(Value::Num(7.0))),
    };
    assert_eq!(
        fastpath::try_stream_date_count(&store, &Some("T".into()), &numge),
        None,
        "the date path must decline a numeric column"
    );
}

/// Item 872: a BARE property in boolean context (`WHERE p.flag`) and its negation, over a typed
/// bool column. Only the comparison spelling (`= true`) had a typed path, so three spellings of
/// one question measured 6.6x apart.
///
/// The fixture carries the two cells a bool column can hold besides `true`/`false`: an ABSENT key
/// and a STORED PRESENT NULL. Both are UNKNOWN in boolean context, and `NOT UNKNOWN` is UNKNOWN
/// rather than TRUE — so neither spelling may keep them. That is the whole correctness question
/// here, and a fixture of only true/false cannot ask it.
#[test]
fn bare_bool_property_predicate() {
    let mut b = Builder::default();
    for i in 0..300u32 {
        // 150 true, 50 false, 100 absent. The true and false groups are DELIBERATELY UNEQUAL:
        // with 100 each, a mutant that ignored the negation (keeping the TRUE rows for `NOT f`)
        // returned the same COUNT as the correct answer and survived the whole test.
        let m = i % 6;
        let props: Vec<(&str, Value)> = match m {
            0..=2 => vec![("f", Value::Bool(true)), ("i", n(f64::from(i)))],
            3 => vec![("f", Value::Bool(false)), ("i", n(f64::from(i)))],
            // ABSENT, which is UNKNOWN in boolean context. A stored `Value::Null` would be too,
            // but writing one through `Builder` promotes the column to `Gen` (measured — the
            // "never de-opts on a null" rule in `store.rs` is about the `SET` path), and a `Gen`
            // column is not what this arm claims. The `Gen` spelling gets its own fixture below.
            _ => vec![("i", n(f64::from(i)))],
        };
        b.node(&["T"], &props);
    }
    let store = b.build();
    assert!(
        matches!(store.column("f"), Some(crate::store::Column::Bool { .. })),
        "f must be a typed bool column or the arm under test is not reached"
    );

    let cnt = |q: &str| -> f64 {
        let plan = crate::opt::optimize_indexed(crate::gql::parse(q).unwrap(), &store);
        match run(&plan, &store).rows[0][0] {
            Value::Num(x) => x,
            ref o => panic!("{o:?}"),
        }
    };

    // 150 true, 50 false, 100 ABSENT
    assert_eq!(cnt("MATCH (t:T) WHERE t.f RETURN count(*) AS c"), 150.0);
    assert_eq!(cnt("MATCH (t:T) WHERE NOT t.f RETURN count(*) AS c"), 50.0);
    // the comparison spelling must agree with the bare one, which is the point of the item
    assert_eq!(
        cnt("MATCH (t:T) WHERE t.f = true RETURN count(*) AS c"),
        150.0
    );
    assert_eq!(
        cnt("MATCH (t:T) WHERE t.f = false RETURN count(*) AS c"),
        50.0
    );
    // THE UNKNOWNS ARE KEPT BY NEITHER SPELLING. `WHERE t.f` plus `WHERE NOT t.f` is 200, not
    // 300 — if the negation inverted the presence test too it would read 200 here and 300 there.
    assert_eq!(
        cnt("MATCH (t:T) WHERE t.f IS NULL RETURN count(*) AS c"),
        100.0
    );
    assert_eq!(
        cnt("MATCH (t:T) WHERE t.f IS NOT NULL RETURN count(*) AS c"),
        200.0
    );
    // a double negation is the positive, and still drops the unknowns
    assert_eq!(
        cnt("MATCH (t:T) WHERE NOT NOT t.f RETURN count(*) AS c"),
        150.0
    );
    // conjunction with another predicate still works (the arm must not claim a compound)
    assert_eq!(
        cnt("MATCH (t:T) WHERE t.f AND t.i < 6 RETURN count(*) AS c"),
        3.0
    );
    // AN OPTIONAL MISS carries the `u32::MAX` sentinel in the node slot, and indexing the column
    // by it would be out of bounds. No plain scan produces one, so without an OPTIONAL MATCH the
    // guard is unreachable and its mutant survived. Nothing here has an `R` edge, so EVERY row's
    // `u` is a miss: the predicate must keep none of them rather than panic.
    assert_eq!(
        cnt("MATCH (t:T) OPTIONAL MATCH (t)-[:R]->(u) FILTER u.f RETURN count(*) AS c"),
        0.0,
        "a bool predicate on an optional miss keeps nothing"
    );
    assert_eq!(
        cnt("MATCH (t:T) OPTIONAL MATCH (t)-[:R]->(u) FILTER NOT u.f RETURN count(*) AS c"),
        0.0,
        "and NOT on an optional miss is UNKNOWN, not TRUE"
    );

    // THE ROUTE, asserted directly: the arm is answer-equivalent, so nothing above can tell
    // whether it fired.
    let batch = pull(
        &Plan::Scan {
            label: Some("T".into()),
        },
        &store,
        false,
    )
    .unwrap();
    let bare = Expr::Prop {
        slot: 0,
        key: "f".into(),
    };
    let negated = Expr::Not(Box::new(bare.clone()));
    assert_eq!(
        try_filter_keep_bool_prop(&bare, &store, &batch).map(|k| k.len()),
        Some(150),
        "a bare bool property must take the typed arm"
    );
    assert_eq!(
        try_filter_keep_bool_prop(&negated, &store, &batch).map(|k| k.len()),
        Some(50),
        "and so must its negation, keeping the FALSE rows and not the true ones"
    );
    // a NUMERIC property is not a boolean context this arm may claim
    let numeric = Expr::Prop {
        slot: 0,
        key: "i".into(),
    };
    assert!(
        try_filter_keep_bool_prop(&numeric, &store, &batch).is_none(),
        "a non-bool column must be declined, leaving the general path to judge it"
    );

    // A STORED NULL makes the column `Gen`, so the typed arm declines and the general path
    // answers — and it must answer identically. Measured before being written down: both
    // representations return the same four counts, so the asymmetry is representational only and
    // carries no correctness consequence.
    let mut gb = Builder::default();
    for i in 0..12u32 {
        let props: Vec<(&str, Value)> = match i % 6 {
            0 | 1 => vec![("f", Value::Bool(true))],
            2 | 3 => vec![("f", Value::Bool(false))],
            4 => vec![],
            _ => vec![("f", Value::Null)],
        };
        gb.node(&["T"], &props);
    }
    let gen_store = gb.build();
    assert!(
        matches!(
            gen_store.column("f"),
            Some(crate::store::Column::Gen { .. })
        ),
        "a stored NULL written through Builder promotes the column to Gen"
    );
    let gcnt = |q: &str| -> f64 {
        let plan = crate::opt::optimize_indexed(crate::gql::parse(q).unwrap(), &gen_store);
        match run(&plan, &gen_store).rows[0][0] {
            Value::Num(x) => x,
            ref o => panic!("{o:?}"),
        }
    };
    // 4 true, 4 false, 2 absent, 2 stored null
    assert_eq!(gcnt("MATCH (t:T) WHERE t.f RETURN count(*) AS c"), 4.0);
    assert_eq!(gcnt("MATCH (t:T) WHERE NOT t.f RETURN count(*) AS c"), 4.0);
    assert_eq!(
        gcnt("MATCH (t:T) WHERE t.f IS NULL RETURN count(*) AS c"),
        4.0
    );
    assert_eq!(
        gcnt("MATCH (t:T) WHERE t.f IS NOT NULL RETURN count(*) AS c"),
        8.0,
        "a stored NULL must read as NULL even where the column stores it with present = true"
    );
    let gbatch = pull(
        &Plan::Scan {
            label: Some("T".into()),
        },
        &gen_store,
        false,
    )
    .unwrap();
    assert!(
        try_filter_keep_bool_prop(&bare, &gen_store, &gbatch).is_none(),
        "a Gen column must be declined — it can hold a non-boolean, which is the general \
         path's (and the static check's) business"
    );
}

/// Item 876: a VACUOUS label no longer defeats the O(1) typed-hop count.
///
/// `typed_hop_count_from_size` answers `()-[:T]->()` from the length of `T`'s CSR partition. It
/// required `Scan { label: None }` literally, so writing the label every vertex already carries
/// cost 0.4777 ms against 0.0002 for the same answer — about 2400x, in both front ends, and the TS
/// engine has had this elision all along.
///
/// The SELECTIVE label is the control that matters: an elision that fired there would return a
/// spectacular wrong answer (every edge instead of the labelled sources' edges), so every case
/// below asserts the COUNT and not just the timing's sibling.
#[test]
fn vacuous_label_hop_count() {
    // `verts`, not `n` — this file's `n(f64)` Value helper is used inside the closure and a
    // parameter of that name shadows it.
    let build = |staff_every: u32, verts: u32| -> crate::store::Store {
        let mut b = Builder::default();
        for i in 0..verts {
            if i % staff_every == 0 {
                b.node(&["Person", "Staff"], &[("i", n(f64::from(i)))]);
            } else {
                b.node(&["Person"], &[("i", n(f64::from(i)))]);
            }
        }
        for k in 0..(verts * 3) {
            b.edge((k * 7) % verts, (k * 13) % verts, "KNOWS");
        }
        b.build()
    };
    let store = build(10, 100);
    let cnt = |q: &str, st: &crate::store::Store| -> f64 {
        let plan = crate::opt::optimize_indexed(crate::gql::parse(q).unwrap(), st);
        match run(&plan, st).rows[0][0] {
            Value::Num(x) => x,
            ref o => panic!("{o:?}"),
        }
    };

    // 100 vertices x 3 edges each = 300 KNOWS edges. Every vertex is a `Person`, so the labelled
    // and unlabelled spellings are the same question and must agree.
    assert_eq!(
        cnt("MATCH ()-[:KNOWS]->() RETURN count(*) AS c", &store),
        300.0
    );
    assert_eq!(
        cnt("MATCH (p:Person)-[:KNOWS]->() RETURN count(*) AS c", &store),
        300.0
    );
    // THE SELECTIVE LABEL MUST NOT BE ELIDED. 10 of 100 are `Staff`; their out-edges are a
    // fraction of 300, so an elision firing here would answer 300 and be loudly wrong.
    let staff = cnt("MATCH (p:Staff)-[:KNOWS]->() RETURN count(*) AS c", &store);

    assert!(
        staff > 0.0 && staff < 300.0,
        "a selective label must count only its own sources, got {staff}"
    );
    // and the Gremlin spellings answer the same three things
    let gcnt = |q: &str| -> f64 {
        let plan = crate::opt::optimize_indexed(crate::gremlin::parse(q).unwrap(), &store);
        match run(&plan, &store).rows[0][0] {
            Value::Num(x) => x,
            ref o => panic!("{o:?}"),
        }
    };

    assert_eq!(gcnt("g.V().out('KNOWS').count()"), 300.0);
    assert_eq!(gcnt("g.V().hasLabel('Person').out('KNOWS').count()"), 300.0);
    assert_eq!(gcnt("g.V().hasLabel('Staff').out('KNOWS').count()"), staff);

    // THE ROUTE, asserted directly — the elision is answer-equivalent, so no count above can tell
    // whether it fired.
    let scan_none = Plan::Scan { label: None };
    let scan_vac = Plan::Scan {
        label: Some("Person".into()),
    };
    let scan_sel = Plan::Scan {
        label: Some("Staff".into()),
    };

    assert!(fastpath::whole_graph_scan(&scan_none, &store));
    assert!(
        fastpath::whole_graph_scan(&scan_vac, &store),
        "a label every live vertex carries IS the whole graph"
    );
    assert!(
        !fastpath::whole_graph_scan(&scan_sel, &store),
        "a selective label is not"
    );
    assert!(
        !fastpath::whole_graph_scan(&Plan::EdgeScan, &store),
        "only a node Scan is a whole-graph node scan"
    );

    // THE CALL SITE, not just the predicate. Reverting the call site to its old literal
    // `label: None` check leaves `whole_graph_scan` itself intact and true, so the assertions
    // above all still pass while the elision no longer fires — that mutant survived until this
    // block existed. `try_scan_count` is the entry point, so asking it directly is the only way
    // to see that the hop was CLAIMED.
    let hop = |label: Option<&str>| {
        Plan::Scan {
            label: label.map(Into::into),
        }
        .expand(0, Dir::Out, &["KNOWS".to_string()])
    };
    let count_agg = [Agg {
        func: AggFn::Count,
        arg: None,
        distinct: false,
        name: "c".into(),
        frac: None,
        null_on_empty: false,
        numeric_only: false,
    }];

    assert!(
        fastpath::try_scan_count(&hop(None), &[], &count_agg, &store).is_some(),
        "an unlabelled hop count is answered from the CSR partition size"
    );
    assert!(
        fastpath::try_scan_count(&hop(Some("Person")), &[], &count_agg, &store).is_some(),
        "and so is a VACUOUS label's — this is the elision, and the call site has to use it"
    );
    assert!(
        fastpath::try_scan_count(&hop(Some("Staff")), &[], &count_agg, &store).is_none(),
        "a SELECTIVE label must decline: the partition spans sources it does not"
    );

    // A DELETE REMOVES THE ID FROM THE LABEL'S LIST — measured, not assumed, which is what
    // corrected this predicate. `node_count` stays 100 while both the live count and the
    // `Person` list drop to 99, so a label that still covers every LIVE vertex keeps counting as
    // whole-graph. The first version compared coverage against `node_count` and declined here.
    let mut holed = build(10, 100);

    holed.delete_node(7);
    assert_eq!(holed.node_count(), 100);
    assert_eq!(holed.live_node_count(), 99);
    assert_eq!(holed.nodes_with_label("Person").len(), 99);
    assert!(
        fastpath::whole_graph_scan(&scan_vac, &holed),
        "a label covering every LIVE vertex is still the whole graph after a delete"
    );
    assert!(fastpath::whole_graph_scan(&scan_none, &holed));
    assert!(
        !fastpath::whole_graph_scan(&scan_sel, &holed),
        "and a selective label is still not"
    );
    // The ANSWERS are what ultimately matter, and the two spellings agree over the holed graph
    // whichever route each takes — a delete also staleness-invalidates the CSR overlay, so the
    // size shortcut declines there on its own.
    assert_eq!(
        cnt("MATCH (p:Person)-[:KNOWS]->() RETURN count(*) AS c", &holed),
        cnt("MATCH ()-[:KNOWS]->() RETURN count(*) AS c", &holed)
    );
}

/// Item 877: `count(*)` over an edge scan filtered by edge label, and the UNTYPED hop count —
/// two spellings that were answered by materializing where a stored size would do.
///
/// Both are the same question GQL already answered from a size, so the cross-spelling equality is
/// the assertion that matters most: `g.E().hasLabel('KNOWS').count()` and
/// `MATCH ()-[:KNOWS]->() RETURN count(*)` must agree, and they were 89,800x apart.
#[test]
fn edge_label_and_untyped_counts() {
    let build = || -> crate::store::Store {
        let mut b = Builder::default();
        for i in 0..200u32 {
            b.node(&["P"], &[("i", n(f64::from(i)))]);
        }
        // 600 edges: one in four LIKES, the rest KNOWS
        for k in 0..600u32 {
            let ty = if k % 4 == 0 { "LIKES" } else { "KNOWS" };
            b.edge(k % 200, (k * 7) % 200, ty);
        }
        b.build()
    };
    let store = build();
    let g = |q: &str, st: &crate::store::Store| -> f64 {
        let plan = crate::opt::optimize_indexed(crate::gremlin::parse(q).unwrap(), st);
        match run(&plan, st).rows[0][0] {
            Value::Num(x) => x,
            ref o => panic!("{o:?}"),
        }
    };
    let q = |s: &str, st: &crate::store::Store| -> f64 {
        let plan = crate::opt::optimize_indexed(crate::gql::parse(s).unwrap(), st);
        match run(&plan, st).rows[0][0] {
            Value::Num(x) => x,
            ref o => panic!("{o:?}"),
        }
    };

    // 150 LIKES, 450 KNOWS, 600 total.
    assert_eq!(g("g.E().hasLabel('KNOWS').count()", &store), 450.0);
    assert_eq!(g("g.E().hasLabel('LIKES').count()", &store), 150.0);
    // THE CROSS-SPELLING EQUALITY, which is the point of the item.
    assert_eq!(
        g("g.E().hasLabel('KNOWS').count()", &store),
        q("MATCH ()-[:KNOWS]->() RETURN count(*) AS c", &store)
    );
    // A LABEL SET IS AN OR — verified by measurement before it was relied on, and pinned here.
    assert_eq!(g("g.E().hasLabel('KNOWS','LIKES').count()", &store), 600.0);
    // An UNKNOWN type contributes 0 and must not decline the path for the others.
    assert_eq!(g("g.E().hasLabel('NOPE').count()", &store), 0.0);
    assert_eq!(g("g.E().hasLabel('KNOWS','NOPE').count()", &store), 450.0);
    // A DUPLICATE label is one partition, not two — `450 + 450` is the mistake this guards.
    assert_eq!(g("g.E().hasLabel('KNOWS','KNOWS').count()", &store), 450.0);

    // THE UNTYPED HOP: one row per edge, because each edge is an out-edge of exactly one source.
    assert_eq!(q("MATCH ()-[]->() RETURN count(*) AS c", &store), 600.0);
    assert_eq!(g("g.E().count()", &store), 600.0);
    assert_eq!(
        q("MATCH ()-[]->() RETURN count(*) AS c", &store),
        g("g.E().count()", &store),
        "the untyped hop count and the edge count are the same number"
    );

    // AFTER A DELETE both spellings must still agree. A delete invalidates the CSR overlay, so
    // the typed arm declines and the general path answers — the point is that the ANSWERS match
    // whichever route each takes.
    let mut holed = build();

    holed.delete_node(3);
    assert_eq!(
        g("g.E().hasLabel('KNOWS').count()", &holed),
        q("MATCH ()-[:KNOWS]->() RETURN count(*) AS c", &holed),
        "the two spellings agree on a mutated graph too"
    );
    assert_eq!(
        q("MATCH ()-[]->() RETURN count(*) AS c", &holed),
        g("g.E().count()", &holed)
    );

    // THE ROUTES, asserted directly — both arms are answer-equivalent, so no count above can tell
    // whether either fired.
    let count_agg = [Agg {
        func: AggFn::Count,
        arg: None,
        distinct: false,
        name: "c".into(),
        frac: None,
        null_on_empty: false,
        numeric_only: false,
    }];
    let labelled = Plan::EdgeScan.filter(Expr::IsLabeled {
        slot: 0,
        labels: vec!["KNOWS".to_string()],
    });

    assert!(
        fastpath::try_edge_label_count(&labelled, &[], &count_agg, &store).is_some(),
        "an edge-label count must be answered from the partitions"
    );
    // a NODE-label filter over a node scan is a different shape and must be declined
    let node_labelled = Plan::Scan { label: None }.filter(Expr::IsLabeled {
        slot: 0,
        labels: vec!["P".to_string()],
    });

    assert!(
        fastpath::try_edge_label_count(&node_labelled, &[], &count_agg, &store).is_none(),
        "only an EdgeScan input is this shape"
    );
    // and the untyped hop reaches the size arm
    let untyped = Plan::Scan { label: None }.expand(0, Dir::Out, &[]);

    assert!(
        fastpath::try_scan_count(&untyped, &[], &count_agg, &store).is_some(),
        "an untyped hop count is answered from the live edge count"
    );

    // AN UNKNOWN TYPE MUST CONTRIBUTE 0 AND STILL BE CLAIMED. Declining instead is
    // answer-equivalent — the general path also answers 0, just by walking every edge — so only
    // a route assertion sees it, and its mutant survived until these two lines existed.
    let unknown = Plan::EdgeScan.filter(Expr::IsLabeled {
        slot: 0,
        labels: vec!["NOPE".to_string()],
    });
    let mixed = Plan::EdgeScan.filter(Expr::IsLabeled {
        slot: 0,
        labels: vec!["KNOWS".to_string(), "NOPE".to_string()],
    });

    assert!(
        fastpath::try_edge_label_count(&unknown, &[], &count_agg, &store).is_some(),
        "an unknown type is 0 edges, which this path knows without walking any"
    );
    assert!(
        fastpath::try_edge_label_count(&mixed, &[], &count_agg, &store).is_some(),
        "and one unknown type among known ones must not forfeit the path"
    );

    // A MULTI-LABEL EDGE MUST DECLINE. `Adj.etype` holds an edge's PRIMARY type only, so summing
    // partitions would UNDERCOUNT an edge whose secondary type is the one being asked for.
    // `Builder` cannot create one — it takes a single label — so this goes through NDJSON ingest,
    // which is the only reachable way to build the shape. Without it the guard's mutant survived.
    let multi = crate::ndjson::from_ndjson(
        "{\"type\":\"node\",\"id\":\"a\",\"labels\":[\"P\"],\"properties\":{}}\n\
         {\"type\":\"node\",\"id\":\"b\",\"labels\":[\"P\"],\"properties\":{}}\n\
         {\"type\":\"edge\",\"id\":\"e0\",\"labels\":[\"KNOWS\"],\"from\":\"a\",\"to\":\"b\",\"properties\":{}}\n\
         {\"type\":\"edge\",\"id\":\"e1\",\"labels\":[\"EXTRA\",\"KNOWS\"],\"from\":\"b\",\"to\":\"a\",\"properties\":{}}",
    )
    .expect("the multi-label fixture must parse");

    assert!(
        multi.has_multi_label_edges(),
        "the fixture must actually carry a multi-label edge or the guard is untested"
    );
    assert!(
        fastpath::try_edge_label_count(&labelled, &[], &count_agg, &multi).is_none(),
        "a graph with multi-label edges must decline: the partition sum would undercount"
    );
    // and the ANSWER stays right on the general path — both edges carry KNOWS
    assert_eq!(g("g.E().hasLabel('KNOWS').count()", &multi), 2.0);
    assert_eq!(g("g.E().hasLabel('EXTRA').count()", &multi), 1.0);
    assert_eq!(
        g("g.E().hasLabel('KNOWS').count()", &multi),
        q("MATCH ()-[:KNOWS]->() RETURN count(*) AS c", &multi),
        "the two spellings agree with multi-label edges present too"
    );
}

/// Item 893: a dotted path reads its BASE property by reference when the column can give one, and
/// falls back to an owned read when it cannot. The three base kinds route DIFFERENTLY, and only a
/// record base takes the new arm:
///
/// - a RECORD base (`Gen` column)  -> `prop_ref` returns `Some`, the new arm resolves the field
/// - a TYPED base (`Num`/`Str`/…)  -> `prop_ref` returns `None`; the fallback must still yield
///   `Null` for a sub-field of a scalar, not a panic and not the scalar itself
/// - an ABSENT base                -> `prop_ref` returns `None`; `Null` again
///
/// The two paths are answer-equivalent, which is exactly why this needs asserting: the route is
/// invisible to every other test, and a mutant that deletes the fast arm SURVIVES the suite (that
/// survival is the equivalence assertion, cf. item 359's control mutant).
#[test]
fn dotted_path_base_kinds() {
    let nd = concat!(
        // n0: a record base with two fields, plus a typed scalar and a typed string.
        r#"{"id":"n0","labels":["P"],"props":{"age":40,"city":"oslo","meta":{"city":"nyc","tier":2}}}"#,
        "\n",
        // n1: a record base whose sub-field is ABSENT from the record.
        r#"{"id":"n1","labels":["P"],"props":{"age":50,"city":"rome","meta":{"tier":7}}}"#,
        "\n",
        // n2: NO `meta` at all — the absent-base case.
        r#"{"id":"n2","labels":["P"],"props":{"age":60,"city":"bern"}}"#,
        "\n",
        // n3: `meta` PRESENT IN THE SCHEMA but NULL at this node. This is the case the hoisted
        // scan's `present[id]` guard exists for (item 894): with the column resolved once, the
        // per-row read indexes `data` directly, so the present flag is the only thing standing
        // between a null-at-this-node record and a bogus read. Nothing covered it until now.
        r#"{"id":"n3","labels":["P"],"props":{"age":70,"city":"lima","meta":null}}"#,
        "\n",
    );
    let store = crate::ndjson::from_ndjson(nd).unwrap();
    let ids = |q: &str| -> Vec<String> {
        let plan = crate::opt::optimize_indexed(crate::gql::parse(q).unwrap(), &store);
        let mut v = names_of(&run(&plan, &store), 0);
        v.sort();
        v
    };

    // A RECORD base, one sub-field: the new by-reference arm. Only n0 matches.
    assert_eq!(
        ids("MATCH (n:P) WHERE n.meta.city = 'nyc' RETURN n.city AS x"),
        vec!["oslo"]
    );
    // The same path PROJECTED, so the value itself is checked and not just the predicate.
    assert_eq!(
        ids("MATCH (n:P) WHERE n.city = 'oslo' RETURN n.meta.city AS x"),
        vec!["nyc"]
    );
    // A sub-field absent FROM the record is Null, so it matches nothing — n1 has `meta` but no
    // `meta.city`, and must not be confused with n2, which has no `meta` at all.
    assert_eq!(
        ids("MATCH (n:P) WHERE n.meta.tier = 7 RETURN n.city AS x"),
        vec!["rome"]
    );

    // A record column that is NULL at this node matches nothing, and must not be confused with
    // a record that HAS the field. n3 is the only node whose `meta` is null.
    assert_eq!(
        ids("MATCH (n:P) WHERE n.meta.city = 'lima' RETURN n.city AS x"),
        Vec::<String>::new()
    );
    assert_eq!(
        ids("MATCH (n:P) WHERE n.city = 'lima' RETURN n.meta.city AS x"),
        vec!["Null"]
    );

    // A TYPED base with a sub-field: `prop_ref` declines and the fallback resolves to Null, so
    // nothing matches. The scalar must NOT leak through as its own value.
    assert_eq!(
        ids("MATCH (n:P) WHERE n.age.anything = 40 RETURN n.city AS x"),
        Vec::<String>::new()
    );
    assert_eq!(
        ids("MATCH (n:P) WHERE n.city.anything = 'oslo' RETURN n.city AS x"),
        Vec::<String>::new()
    );

    // An ABSENT base with a sub-field: Null, nothing matches, no panic.
    assert_eq!(
        ids("MATCH (n:P) WHERE n.nosuch.field = 1 RETURN n.city AS x"),
        Vec::<String>::new()
    );

    // And a THREE-segment path, which is the one shape that still takes `resolve_path`'s general
    // loop rather than its one-segment arm — a record nested in a record resolves, and going one
    // level too deep is Null.
    let nd2 = concat!(
        r#"{"id":"m0","labels":["Q"],"props":{"tag":"deep","a":{"b":{"c":5}}}}"#,
        "\n",
    );
    let store2 = crate::ndjson::from_ndjson(nd2).unwrap();
    let ids2 = |q: &str| -> Vec<String> {
        let plan = crate::opt::optimize_indexed(crate::gql::parse(q).unwrap(), &store2);
        let mut v = names_of(&run(&plan, &store2), 0);
        v.sort();
        v
    };

    assert_eq!(
        ids2("MATCH (n:Q) WHERE n.a.b.c = 5 RETURN n.tag AS x"),
        vec!["deep"]
    );
    assert_eq!(
        ids2("MATCH (n:Q) WHERE n.a.b.c.d = 5 RETURN n.tag AS x"),
        Vec::<String>::new()
    );
}

/// Item 894: a REMOVED record property must not match on its stale value.
///
/// The hoisted dotted-path scan resolves the base column once and then indexes `data` per row, so
/// `present[id]` is the only thing standing between a removed property and a bogus read — and
/// `Column::set_absent` for a `Gen` column clears `present[i]` while LEAVING `data[i]` untouched,
/// so the old record is still physically there.
///
/// Found by mutation: dropping that guard SURVIVED the whole suite including the null-at-this-node
/// cases, because a never-set slot holds `Value::Null` anyway. Only a REMOVE leaves a stale
/// non-null value behind, and nothing exercised it. The pre-894 path read through `prop_ref`,
/// which checks `present` itself, so this is a guard the change had to carry rather than a new
/// idea — and an unguarded version returns a WRONG ROW, not an error.
#[test]
fn removed_record_prop_does_not_match_stale_value() {
    let nd = concat!(
        r#"{"id":"n0","labels":["P"],"props":{"city":"oslo","meta":{"city":"nyc"}}}"#,
        "\n",
        r#"{"id":"n1","labels":["P"],"props":{"city":"rome","meta":{"city":"nyc"}}}"#,
        "\n",
    );
    let mut store = crate::ndjson::from_ndjson(nd).unwrap();

    let ids = |st: &crate::store::Store, q: &str| -> Vec<String> {
        let plan = crate::opt::optimize_indexed(crate::gql::parse(q).unwrap(), st);
        let mut v = names_of(&run(&plan, st), 0);
        v.sort();
        v
    };
    let q = "MATCH (n:P) WHERE n.meta.city = 'nyc' RETURN n.city AS x";

    // Both match to begin with, so the removal below has something to remove.
    assert_eq!(ids(&store, q), vec!["oslo", "rome"]);

    // Remove n0's `meta`. Its slot in `data` still holds the record; only `present` is cleared.
    store.remove_prop(0, "meta");

    // n0 must be GONE from the result. Without the `present[]` guard it is still there, matching
    // on a property it no longer has.
    assert_eq!(ids(&store, q), vec!["rome"]);
    // And reading the path on n0 yields Null rather than the stale value.
    assert_eq!(
        ids(
            &store,
            "MATCH (n:P) WHERE n.city = 'oslo' RETURN n.meta.city AS x"
        ),
        vec!["Null"]
    );
}

/// Item 893: `Store::prop_path` / `prop_path_parts` tested DIRECTLY, because their contract is
/// wider than any query exercises.
///
/// `prop_path_parts` has exactly one caller inside the engine (the unindexed `IndexSeek` fallback
/// filter) and it only ever passes a DOTTED key — two segments or more. `prop_path` has no
/// internal caller at all: it is public API for a host. So the documented single-segment case
/// ("`parts[0]` is the base property and the rest are record sub-fields") is unreachable from
/// GQL, and a mutant that replaced the owned-read fallback with `Value::Null` SURVIVED all 1980
/// tests — the engine never asks for the one case that fallback exists to serve.
///
/// These assertions close that gap. They are unit-level on purpose: routing them through a query
/// cannot reach the shape.
#[test]
fn prop_path_contract() {
    use crate::value::{equals, Value};

    let nd = concat!(
        r#"{"id":"n0","labels":["P"],"props":{"age":40,"city":"oslo","meta":{"city":"nyc","tier":2}}}"#,
        "\n",
        // A record column that is NULL at this node, so `prop_ref` declines and the owned read is
        // what answers — the other way the fallback is reached.
        r#"{"id":"n1","labels":["P"],"props":{"age":41,"city":"rome","meta":null}}"#,
        "\n",
    );
    let store = crate::ndjson::from_ndjson(nd).unwrap();

    // Node ids come from document order. ASSERTED rather than assumed, so a change in that
    // ordering fails here instead of silently testing the wrong node.
    let (n0, n1) = (0u32, 1u32);
    assert!(
        equals(&store.prop(n0, "city"), &Value::Str("oslo".into()))
            && equals(&store.prop(n1, "city"), &Value::Str("rome".into())),
        "fixture nodes are not in the assumed order"
    );

    // ONE SEGMENT, typed base: must return the SCALAR, not Null. This is the case the surviving
    // mutant broke and nothing else covered.
    assert!(equals(&store.prop_path(n0, "age"), &Value::Num(40.0)));
    assert!(equals(
        &store.prop_path(n0, "city"),
        &Value::Str("oslo".into())
    ));
    assert!(equals(
        &store.prop_path_parts(n0, &["age"]),
        &Value::Num(40.0)
    ));

    // ONE SEGMENT, record base: the whole record comes back.
    assert!(matches!(store.prop_path(n0, "meta"), Value::Record(_)));

    // TWO SEGMENTS, through the by-reference arm.
    assert!(equals(
        &store.prop_path(n0, "meta.city"),
        &Value::Str("nyc".into())
    ));
    assert!(equals(&store.prop_path(n0, "meta.tier"), &Value::Num(2.0)));

    // A sub-field of a TYPED base is Null, not the scalar. An absent base, and an absent
    // sub-field of a present record, likewise.
    assert!(store.prop_path(n0, "age.anything").is_null());
    assert!(store.prop_path(n0, "nosuch.field").is_null());
    assert!(store.prop_path(n0, "meta.nosuch").is_null());

    // A record column NULL at this node: `prop_ref` declines, the owned read answers.
    assert!(store.prop_path(n1, "meta").is_null());
    assert!(store.prop_path(n1, "meta.city").is_null());
    // ...while its typed siblings still read normally through that same fallback.
    assert!(equals(&store.prop_path(n1, "age"), &Value::Num(41.0)));
}

/// Item 896: a dotted path read off an OPTIONAL hop's MISS must be `Null`, not a panic.
///
/// The fused `n.rec.field` arm indexes the base column's `present` slice directly, and an OPTIONAL
/// hop that matches nothing binds the `u32::MAX` null sentinel — so without the sentinel guard,
/// `present[u32::MAX as usize]` is an out-of-bounds slice index and the query PANICS. Rust bounds-
/// checks slice indexing in release too, so this is a crash, not a wrong answer.
///
/// Found by mutation: dropping that guard SURVIVED the whole suite, because nothing combined an
/// OPTIONAL hop with a nested-path read. `read_property`, the path this fuses, handles the sentinel
/// explicitly and returns `Null` for it — so this is a check the fused arm had to CARRY, and the
/// second one in two items (894 carried `present`; this carries the sentinel).
#[test]
fn optional_miss_then_dotted_path_is_null() {
    let nd = concat!(
        r#"{"id":"a","labels":["N"],"props":{"tag":"start"}}"#,
        "\n",
        // A node with a record property, reachable only by an edge type the OPTIONAL hop below
        // does NOT follow — so the hop misses and binds the sentinel.
        r#"{"id":"b","labels":["N"],"props":{"tag":"other","meta":{"city":"nyc"}}}"#,
        "\n",
        r#"{"id":"e0","from":"a","to":"b","labels":["R"],"props":{}}"#,
        "\n",
    );
    let store = crate::ndjson::from_ndjson(nd).unwrap();
    let ids = |q: &str| -> Vec<String> {
        let plan = crate::opt::optimize_indexed(crate::gql::parse(q).unwrap(), &store);
        let mut v = names_of(&run(&plan, &store), 0);
        v.sort();
        v
    };

    // The hop MISSES (no `:NOSUCH` edge), so `m` is the null sentinel and `m.meta.city` is Null.
    // Without the guard this panics on an out-of-bounds index rather than returning a row.
    assert_eq!(
        ids(
            "MATCH (a:N {tag:'start'}) OPTIONAL MATCH (a)-[:NOSUCH]->(m) \
             RETURN m.meta.city AS x"
        ),
        vec!["Null"]
    );

    // (The PREDICATE form of this shape is not reachable to assert: a `WHERE` inside
    // `OPTIONAL MATCH` is E_NOT_IMPLEMENTED in this engine. The projection above is the reachable
    // one, and it is the one that indexes `present`.)

    // And the hop that HITS still reads the nested value through the same arm, so the test is not
    // merely asserting that everything is Null.
    assert_eq!(
        ids("MATCH (a:N {tag:'start'}) OPTIONAL MATCH (a)-[:R]->(m) \
             RETURN m.meta.city AS x"),
        vec!["nyc"]
    );
}

/// `WHERE p.b = true` IS `WHERE p.b`, on the route where it matters (items 978-982).
///
/// `try_filter_keep_bool_prop` reads a boolean column directly and served only the BARE and
/// `NOT` spellings; the comparison form fell to the general vectorized filter and cost ~5.8x for
/// the same rows on the same `Filter { Scan }` plan (item 978: 919.2 us against 160.2 at
/// 200,000 nodes).
///
/// THE FIXTURE IS THREE CORRECTIONS DEEP, each forced by a counter or a mutant (items 980-982):
///
///   * NO STORED NULL. One `Value::Null` makes the store keep the column as `Column::Gen`
///     rather than `Column::Bool` (item 982, measured) — and the fast path requires `Bool`, so
///     a fixture with a null tests nothing. An ABSENT cell is fine and is kept below, because
///     absence rides in `present[]` and leaves the column typed.
///   * AN INDEX, because without one `eq_seek_worth_it` seeds UNCONDITIONALLY (items 947-949)
///     and the plan is an `IndexSeek`, not a filter.
///   * ASYMMETRIC counts. At 50/50 the inverted-polarity mutant PASSED: the complement of
///     10,000 rows is also 10,000. Same trap `long-chain-count.test.ts` warns about for degrees.
///
/// The route assertion is first for the same reason: without it the counts below silently stop
/// describing this path.
fn bool_cmp_fixture() -> Store {
    let mut b = Builder::default();
    for i in 0..20_000 {
        b.node(&["P"], &[("b", Value::Bool(i % 5 != 0))]);
    }
    // ABSENT, not null: UNKNOWN either way, but this keeps the column `Column::Bool`.
    b.node(&["P"], &[("tag", Value::Str("x".into()))]);
    let mut s = b.build();
    s.create_index("b");
    s
}

#[test]
fn a_boolean_comparison_is_the_bare_predicate_on_the_filter_route() {
    let store = bool_cmp_fixture();
    let n = |q: &str| -> f64 {
        match crate::exec::try_run(&opt_plan(q, &store), &store)
            .unwrap()
            .rows
            .iter()
            .next()
            .expect("one row")[0]
        {
            Value::Num(x) => x,
            ref o => panic!("count returns a number, got {o:?}"),
        }
    };

    let shape = format!(
        "{:?}",
        opt_plan("MATCH (p:P) WHERE p.b = true RETURN count(*) AS c", &store)
    );
    assert!(
        !shape.contains("IndexSeek"),
        "past the seek gate, or this tests the wrong path: {shape}"
    );

    for q in [
        "MATCH (p:P) WHERE p.b = true RETURN count(*) AS c",
        "MATCH (p:P) WHERE true = p.b RETURN count(*) AS c",
        "MATCH (p:P) WHERE p.b <> false RETURN count(*) AS c",
        "MATCH (p:P) WHERE p.b RETURN count(*) AS c",
    ] {
        assert_eq!(n(q), 16_000.0, "16,000 TRUE, absent not counted: {q}");
    }

    for q in [
        "MATCH (p:P) WHERE p.b = false RETURN count(*) AS c",
        "MATCH (p:P) WHERE false = p.b RETURN count(*) AS c",
        "MATCH (p:P) WHERE p.b <> true RETURN count(*) AS c",
        "MATCH (p:P) WHERE NOT p.b RETURN count(*) AS c",
    ] {
        assert_eq!(n(q), 4_000.0, "4,000 FALSE, absent not counted: {q}");
    }
}

/// The typed-count fast path is gated PER TYPE, not on "any edge is multi-label" (item 1004).
///
/// The partitions key an edge by its PRIMARY type, so `out_typed_flat(t).len()` is the exact
/// count of `t` exactly when no edge carries `t` BEHIND its primary. The old guard asked the
/// global question and refused the O(1) count for every type as soon as one unrelated edge gained
/// a second label — `storage/multilabel` measured 0.3 us against **368.6** for
/// `-[:KNOWS]->` with `["KNOWS","X"]` on every edge, ~1200x, even though `KNOWS` is the PRIMARY
/// there and its partition is complete.
///
/// BOTH DIRECTIONS ARE ASSERTED, and the second is the one with teeth: a type carried as a
/// SECONDARY is missing from its own partition, so reading the length would UNDERCOUNT. A mutant
/// that drops the guard entirely passes the first assertion and fails this one.
#[test]
fn the_typed_count_fast_path_is_gated_per_type_not_globally() {
    let count_of = |q: &str, st: &Store| -> f64 {
        match &run(&crate::gql::parse(q).unwrap(), st)
            .rows
            .iter()
            .next()
            .expect("one count row")[0]
        {
            Value::Num(n) => *n,
            other => panic!("not a number: {other:?}"),
        }
    };

    // Every edge is [KNOWS, X]: KNOWS is PRIMARY everywhere, X is secondary everywhere.
    let mut b = Builder::default();
    // `k` exists so item 1011's FILTERED assertions below have a property to test; every node
    // carries 0 so `k >= 0` keeps all of them and the filter selects nothing away.
    let a = b.node(&["P"], &[("k", Value::Num(0.0))]);
    let c = b.node(&["P"], &[("k", Value::Num(0.0))]);
    let d = b.node(&["P"], &[("k", Value::Num(0.0))]);
    b.edge(a, c, "KNOWS");
    b.edge(a, d, "KNOWS");
    b.edge(c, d, "KNOWS");
    let mut store = b.build();

    for eid in 0..store.edge_count() as u32 {
        store.set_edge_extra_labels(eid, &["X"]);
    }
    store.rebuild_csr();

    // KNOWS is primary on every edge, so its partition is complete and the count is exact —
    // this is the case the global guard refused.
    assert_eq!(
        count_of("MATCH (p:P)-[:KNOWS]->() RETURN count(*) AS c", &store),
        3.0
    );
    // X is carried ONLY as a secondary, so it is in NO partition. The fast path must decline
    // here or the answer is 0 instead of 3.
    assert_eq!(
        count_of("MATCH (p:P)-[:X]->() RETURN count(*) AS c", &store),
        3.0
    );

    // The Gremlin spelling of the same question, which sums named partitions.
    assert_eq!(
        count_of("MATCH ()-[:KNOWS]->() RETURN count(*) AS c", &store),
        3.0
    );
    assert_eq!(
        count_of("MATCH ()-[:X]->() RETURN count(*) AS c", &store),
        3.0
    );

    // A MIXED graph: one edge whose primary is X, so X is primary on one and secondary on three.
    let mut b2 = Builder::default();
    let a2 = b2.node(&["P"], &[]);
    let c2 = b2.node(&["P"], &[]);
    b2.edge(a2, c2, "KNOWS");
    b2.edge(c2, a2, "X");
    let mut s2 = b2.build();
    s2.set_edge_extra_labels(0, &["X"]); // the KNOWS edge also carries X
    s2.rebuild_csr();

    assert_eq!(
        count_of("MATCH ()-[:KNOWS]->() RETURN count(*) AS c", &s2),
        1.0
    );
    // Both edges carry X: one as primary, one as secondary. The partition holds only the first.
    assert_eq!(count_of("MATCH ()-[:X]->() RETURN count(*) AS c", &s2), 2.0);

    // THE TRAVERSAL PATH, not just the count (item 1008). `for_each_nbr` and the degree reader
    // gate the per-type CSR and index the same way, and a count is answered from a partition
    // LENGTH without reaching either — so a row-returning hop is the only shape that tests them.
    let rows_of = |q: &str, st: &Store| -> usize {
        run(&crate::gql::parse(q).unwrap(), st).rows.iter().count()
    };

    // KNOWS is primary on every edge of the first fixture: the gate must ALLOW the per-type
    // structures and still return all three rows.
    assert_eq!(rows_of("MATCH ()-[:KNOWS]->(m) RETURN m AS m", &store), 3);
    // X is carried only as a SECONDARY there, so the per-type structures hold none of it. The
    // gate must DECLINE, or the hop returns 0 rows instead of 3.
    assert_eq!(rows_of("MATCH ()-[:X]->(m) RETURN m AS m", &store), 3);
    // And on the mixed fixture, where X is primary on one edge and secondary on another.
    assert_eq!(rows_of("MATCH ()-[:X]->(m) RETURN m AS m", &s2), 2);

    // THE FILTERED SHAPE (item 1011), which neither of the two above reaches: the route selector
    // for `Filter { Expand { Scan } }` takes a SINGLE wanted type and used to decline the whole
    // route when ANY edge was multi-label. A count never reaches it and a bare hop has no filter.
    //
    // Every node here carries `k = 0`, so `k >= 0` keeps all of them and the row counts match the
    // unfiltered assertions above — the filter is there to reach the route, not to select.
    assert_eq!(
        rows_of(
            "MATCH ()-[:KNOWS]->(m) WHERE m.k >= 0 RETURN m AS m",
            &store
        ),
        3
    );
    // ...and the DECLINE still has to happen for a secondary-carried type, or the filtered hop
    // takes a partition that holds none of its edges and returns nothing.
    assert_eq!(
        rows_of("MATCH ()-[:X]->(m) WHERE m.k >= 0 RETURN m AS m", &store),
        3
    );

    // THE ROUTE ITSELF, pinned in both directions. Both assertions above pass whichever way the
    // gate goes — taking the route for a secondary type is the only wrong ANSWER, and inverting
    // the gate is a pure perf regression no answer can see (the hazard CLAUDE.md records as "a
    // perf gate needs its own test"). So ask the selector directly.
    fn fused_route_taken(q: &str, store: &Store) -> bool {
        // Only the two wrappers these queries actually produce — a generic walk would hide a
        // plan-shape change behind a `false` that reads like a route decision.
        fn walk(p: &Plan, store: &Store) -> bool {
            match p {
                Plan::Filter { input, .. } => {
                    super::fused_hop_shape(p, store).is_some() || walk(input, store)
                }
                Plan::Project { input, .. } => walk(input, store),
                _ => false,
            }
        }
        let plan = crate::opt::optimize_indexed(crate::gql::parse(q).unwrap(), store);
        walk(&plan, store)
    }
    assert!(
        fused_route_taken(
            "MATCH ()-[:KNOWS]->(m) WHERE m.k >= 0 RETURN m AS m",
            &store
        ),
        "KNOWS is never carried as a secondary label, so its partition is complete and the \
         fused route must be taken even though the graph has multi-label edges"
    );
    assert!(
        !fused_route_taken("MATCH ()-[:X]->(m) WHERE m.k >= 0 RETURN m AS m", &store),
        "X is carried only as a secondary label, so its partition is incomplete and the fused \
         route must still decline"
    );
}

#[test]
fn an_element_renders_a_dict_encoded_column() {
    // THE DICT ARM of the specialized property loop (item 1071), which mutation found UNTESTED:
    // `dict[codes[i]]` could be replaced by `dict[0]` and all 1,264 tests still passed, because
    // no fixture rendered an element off a dictionary-encoded column.
    //
    // `dict_encode` takes a string column only when the values REPEAT — distinct * 2 <= rows — so
    // the fixture needs several rows sharing few values. Ten nodes over three departments
    // qualifies (3 * 2 <= 10) where the four-node fixtures elsewhere in this file cannot.
    let mut nd = String::new();

    for i in 0..10 {
        nd.push_str(&format!(
            "{{\"id\":\"n{i}\",\"labels\":[\"P\"],\"props\":{{\"dept\":\"d{}\",\"k\":{i}}}}}\n",
            i % 3
        ));
    }

    let store = crate::ndjson::from_ndjson(&nd).unwrap();

    assert!(
        store.scan_is_cheap("dept"),
        "`scan_is_cheap` is true only for a Dict column: the fixture must actually dict-encode, or this test proves nothing about that arm"
    );

    let plan = crate::opt::optimize_indexed(
        crate::gql::parse("MATCH (p:P) RETURN p ORDER BY p.k").unwrap(),
        &store,
    );
    let out = run(&plan, &store);

    assert_eq!(out.rows.len(), 10);

    // Every row's `dept` must be ITS OWN value, which is what a wrong code index breaks: with
    // `dict[0]` every row reads `d0`, and three of the ten legitimately do.
    let depts: Vec<String> = out
        .rows
        .iter()
        .map(|r| {
            let Value::Map(pairs) = &r[0] else {
                panic!("an element renders as a map");
            };
            let props = pairs
                .iter()
                .find(|(k, _)| matches!(k, Value::Str(s) if s.as_str() == "properties"))
                .map(|(_, v)| v)
                .expect("an element map carries `properties`");
            let Value::Map(props) = props else {
                panic!("`properties` is a map");
            };
            let dept = props
                .iter()
                .find(|(k, _)| matches!(k, Value::Str(s) if s.as_str() == "dept"))
                .map(|(_, v)| v)
                .expect("the node has `dept`");

            match dept {
                Value::Str(s) => s.as_str().to_string(),
                other => panic!("dept is a string, got {other:?}"),
            }
        })
        .collect();

    assert_eq!(
        depts,
        vec!["d0", "d1", "d2", "d0", "d1", "d2", "d0", "d1", "d2", "d0"],
        "each row decodes its OWN dictionary code"
    );
}

// --- Frontier count over a `PropertyExists` filter (item 1135) ---

/// Three `P` nodes with an outgoing `K` edge each, and the `name` key in all three states the
/// frontier filter has to distinguish: a real value, a STORED PRESENT-NULL, and absent.
///
/// The present-null is the whole point of the fixture. `PropertyExists` counts it (`present_at`)
/// while `count(<arg>)` does not (`has_value_at`), so a frontier arm written with the wrong
/// accessor returns a count that is off by exactly the number of present-nulls — correct-looking,
/// and invisible to any fixture that has none.
fn present_filter_store() -> Store {
    let mut st = Builder::default().build();
    let a = st.add_node(&["P"], &[("name", s("a"))]);
    let b = st.add_node(&["P"], &[("name", Value::Null)]); // STORED present-null
    let c = st.add_node(&["P"], &[]); // absent
    let hub = st.add_node(&["P"], &[("name", s("hub"))]);
    st.add_edge(hub, a, "K");
    st.add_edge(hub, b, "K");
    st.add_edge(hub, c, "K");
    st
}

/// The frontier fold and the general path agree on `count(*)` over a `has('k')` frontier — and
/// both count the present-null, so the answer is 2 of 3 and not 1 of 3.
#[test]
fn the_frontier_count_over_a_present_filter_counts_a_stored_null() {
    let st = present_filter_store();

    // The fixture really does hold a present-null, asserted rather than assumed: a `Gen` column
    // would route elsewhere and the test would pin nothing.
    let col = st.column("name").expect("name column exists");
    assert!(col.present_at(1), "node 1 must be PRESENT");
    assert!(!col.has_value_at(1), "node 1 must be a present-NULL");
    assert!(!col.present_at(2), "node 2 must be absent");

    let q = "g.V().hasLabel('P').out('K').has('name').count()";
    let plan = crate::opt::optimize_indexed(crate::gremlin::parse(q).unwrap(), &st);
    let got = match run(&plan, &st).rows[0][0] {
        Value::Num(x) => x,
        ref v => panic!("count is not a number: {v:?}"),
    };

    // a (value) and b (present-null) survive; c (absent) does not.
    assert_eq!(got, 2.0, "a present-null is PRESENT for has('k')");
}

/// `values('k').count()` — the shape whose `Project` the entry sees through — agrees with the
/// same answer, so the see-through has not changed which rows are counted.
#[test]
fn the_project_see_through_counts_the_same_rows_as_the_filter_alone() {
    let st = present_filter_store();
    let cnt = |q: &str| {
        let plan = crate::opt::optimize_indexed(crate::gremlin::parse(q).unwrap(), &st);
        match run(&plan, &st).rows[0][0] {
            Value::Num(x) => x,
            ref v => panic!("count is not a number: {v:?}"),
        }
    };

    assert_eq!(
        cnt("g.V().hasLabel('P').out('K').values('name').count()"),
        cnt("g.V().hasLabel('P').out('K').has('name').count()"),
        "values(k).count() and has(k).count() count the same rows"
    );
    assert_eq!(cnt("g.V().hasLabel('P').out('K').has('name').count()"), 2.0);
}

/// A key NO node carries is an empty frontier, not a decline into a wrong answer.
#[test]
fn a_present_filter_on_an_unknown_key_counts_zero() {
    let st = present_filter_store();
    let q = "g.V().hasLabel('P').out('K').has('nosuchkey').count()";
    let plan = crate::opt::optimize_indexed(crate::gremlin::parse(q).unwrap(), &st);

    assert_eq!(
        match run(&plan, &st).rows[0][0] {
            Value::Num(x) => x,
            ref v => panic!("count is not a number: {v:?}"),
        },
        0.0
    );
}

/// The fold must agree with the general path on a MULTI-HOP chain, where a node reachable by
/// several paths carries a multiplicity the fold folds and the general path enumerates. A
/// frontier arm that dropped the multiplicity would still answer correctly on the single-path
/// fixture above.
#[test]
fn the_frontier_count_over_a_present_filter_keeps_path_multiplicity() {
    let mut st = Builder::default().build();
    let a = st.add_node(&["P"], &[("name", s("a"))]);
    let b = st.add_node(&["P"], &[("name", s("b"))]);
    let t = st.add_node(&["P"], &[("name", s("t"))]);
    let u = st.add_node(&["P"], &[]); // absent — must not be counted at any multiplicity
                                      // a and b both reach t, so t carries multiplicity 2 at hop 2.
    st.add_edge(a, t, "K");
    st.add_edge(b, t, "K");
    st.add_edge(t, u, "K");
    let seed = st.add_node(&["P"], &[("name", s("seed"))]);
    st.add_edge(seed, a, "K");
    st.add_edge(seed, b, "K");

    let cnt = |q: &str, st: &Store| {
        let plan = crate::opt::optimize_indexed(crate::gremlin::parse(q).unwrap(), st);
        match run(&plan, st).rows[0][0] {
            Value::Num(x) => x,
            ref v => panic!("count is not a number: {v:?}"),
        }
    };

    // Two paths seed->a->t and seed->b->t, both ending on a node WITH `name`.
    assert_eq!(
        cnt(
            "g.V().has('name').out('K').out('K').has('name').count()",
            &st
        ),
        2.0
    );
    // One more hop lands on `u`, which has no `name`: nothing survives.
    assert_eq!(
        cnt(
            "g.V().has('name').out('K').out('K').out('K').has('name').count()",
            &st
        ),
        0.0
    );
}

/// The frontier-slot guard, pinned on the shape that makes it load-bearing: a `has()` on an EDGE
/// property. `outE('K')` binds an edge slot AND a far-node slot, so the chain's frontier is the
/// node while the filter tests the edge — and a node column is indexed by node id, so applying an
/// edge-slot filter to the node frontier is a WRONG ANSWER, not merely a slower one.
///
/// Written because the guard's mutant SURVIVED the first test set (which only ever filtered the
/// frontier itself). The surviving mutant was the missing test, not a safe line.
#[test]
fn a_present_filter_on_a_non_frontier_slot_does_not_reach_the_frontier_fold() {
    let mut st = Builder::default().build();
    let a = st.add_node(&["P"], &[("name", s("a"))]);
    let b = st.add_node(&["P"], &[("name", s("b"))]);
    let e = st.add_edge(a, b, "K");
    // An edge property whose NAME COLLIDES with nothing on the nodes, and one that DOES collide:
    // the collision is the case where a mis-slotted filter silently reads the wrong column.
    st.set_edge_prop(e, "weight", n(1.0));
    let e2 = st.add_edge(b, a, "K");
    let _ = e2; // no `weight` on this one

    let cnt = |q: &str| {
        let plan = crate::opt::optimize_indexed(crate::gremlin::parse(q).unwrap(), &st);
        match run(&plan, &st).rows[0][0] {
            Value::Num(x) => x,
            ref v => panic!("count is not a number: {v:?}"),
        }
    };

    // One of the two edges carries `weight`.
    assert_eq!(cnt("g.V().outE('K').has('weight').count()"), 1.0);
    // And `name`, which EVERY NODE carries but NO EDGE does, must count zero through the edge
    // frontier — the exact confusion a dropped frontier-slot guard produces.
    assert_eq!(cnt("g.V().outE('K').has('name').count()"), 0.0);
}

/// The `Project` see-through admits only `Prop`/`Slot`, because skipping a projection that can
/// RAISE would turn a faulting plan into one that returns a number. No Gremlin or GQL spelling
/// puts a faulting expression in this position today, so the guard is pinned by a DIRECTLY BUILT
/// plan rather than left unexercised — the practice item 369 established for its own unreachable
/// gates, and the reason item 1118's defensive arm is labelled as such.
#[test]
fn the_project_see_through_declines_a_projection_that_can_raise() {
    let st = present_filter_store();

    // `Agg{count(*)} / Project{[("c", CAST of a string to INT)]} / Filter{PropertyExists} / chain`.
    // The cast faults on a non-numeric string, so the plan MUST fault rather than count rows.
    let chain = Plan::Scan { label: None }
        .expand(0, Dir::Out, &["K".to_string()])
        .filter(Expr::PropertyExists {
            slot: 1,
            key: "name".into(),
        })
        .project(vec![(
            "c".to_string(),
            Expr::Cast {
                target: crate::ir::CastTarget::Integer,
                expr: Box::new(Expr::Prop {
                    slot: 1,
                    key: "name".into(),
                }),
            },
        )])
        .aggregate(
            vec![],
            vec![Agg {
                func: AggFn::Count,
                arg: None,
                distinct: false,
                name: "count".into(),
                frac: None,
                null_on_empty: false,
                numeric_only: false,
            }],
        );

    assert!(
        crate::exec::try_run(&chain, &st).is_err(),
        "a faulting projection under count(*) must still fault, not be skipped"
    );
}

/// The route predicate of item 1137, asserted directly. Both routes return the same count, so an
/// inline condition here is unfalsifiable by any answer-based test — which is why it is a pure
/// function (item 1122's rule, and the reason item 1136's M2 verdict could not be resolved).
#[test]
fn the_bare_present_count_route_predicate_admits_only_that_shape() {
    let count_star = Agg {
        func: AggFn::Count,
        arg: None,
        distinct: false,
        name: "c".into(),
        frac: None,
        null_on_empty: false,
        numeric_only: false,
    };
    let present_1 = Expr::PropertyExists {
        slot: 1,
        key: "k".into(),
    };
    let f = crate::exec::fastpath::bare_present_count_belongs_to_the_frontier_fold;

    // The one admitted shape.
    assert!(f(&count_star, &present_1));

    // A present-filter on a NON-frontier slot is not this shape.
    assert!(!f(
        &count_star,
        &Expr::PropertyExists {
            slot: 0,
            key: "k".into()
        }
    ));
    // A label test still belongs to the mask (the fold has its own IsLabeled arm, and this entry
    // answers that one faster — measured 777.9us against the fold's path).
    assert!(!f(
        &count_star,
        &Expr::IsLabeled {
            slot: 1,
            labels: vec!["P".into()]
        }
    ));
    // `count(DISTINCT *)`, `count(<arg>)`, and every value-reading aggregate keep the mask,
    // because the mask arm reads a value per row and the fold does not.
    assert!(!f(
        &Agg {
            distinct: true,
            ..count_star.clone()
        },
        &present_1
    ));
    assert!(!f(
        &Agg {
            arg: Some(Expr::Prop {
                slot: 1,
                key: "k".into()
            }),
            ..count_star.clone()
        },
        &present_1
    ));
    for func in [AggFn::Sum, AggFn::Min, AggFn::Max] {
        assert!(
            !f(
                &Agg {
                    func,
                    arg: Some(Expr::Prop {
                        slot: 1,
                        key: "k".into()
                    }),
                    ..count_star.clone()
                },
                &present_1
            ),
            "{func:?} reads a value per row and must keep the mask"
        );
        // ALSO with no arg. A `sum` of nothing is not a shape any surface spelling produces, but
        // the function is total and the `AggFn::Count` pin is the only thing excluding it — a
        // mutant widening that pin to `Count | Sum` SURVIVED until this case existed, because
        // every arg-carrying case above still declined for a different reason.
        assert!(
            !f(
                &Agg {
                    func,
                    ..count_star.clone()
                },
                &present_1
            ),
            "{func:?} is not count(*) whatever its arg"
        );
    }
}

/// Does the fused streaming count agree with the frontier fold on a STORED PRESENT-NULL?
/// (item 1142)
///
/// `num_conj_on_slot` accepts a bare `PropertyExists` as an atom with NO bound, on the stated
/// grounds that the presence gate is "redundant with the streaming count's own `present[i]`
/// check". For a `Column::Num`, `present[i]` is the NON-NULL bit (`has_value_at`) while
/// `PropertyExists` is `present || nulls` (`present_at`) — which `store.rs` names the single
/// source of truth for `has('k')`.
///
/// ANSWER: they agree, and the fused path is not even reachable with a present-null in the column,
/// because storing one promotes the column to `Gen` and the fused path requires `Column::Num`. So
/// the shortcut is correct — for a reason its own comment does not give.
///
/// BUILT THROUGH THE BUILDER, not `add_node`/`add_edge`: the fused path requires a fresh per-type
/// CSR, which only LOAD arms. A first version of this test used the mutators, both spellings fell
/// to the fold, and the agreement it asserted proved nothing at all about the path under test —
/// which a claim trace showed rather than inspection.
#[test]
fn the_fused_streaming_count_and_the_frontier_fold_agree_on_a_present_null() {
    let mut b = Builder::default();
    // 0 is the hub; 1.. are its targets, cycling value / present-null / absent.
    b.node(&["P"], &[("age", n(9.0))]);
    for i in 0..3000u32 {
        match i % 3 {
            0 => b.node(&["P"], &[("age", n(f64::from(i)))]),
            1 => b.node(&["P"], &[("age", Value::Null)]), // STORED present-null
            _ => b.node(&["P"], &[]),                     // absent
        };
    }
    for i in 1..=3000u32 {
        b.edge(0, i, "K");
    }
    let st = b.build();

    let col = st.column("age").expect("age column");
    // THE COLUMN IS `Gen` HERE, AND THAT IS THE POINT (measured, not assumed — a `VARIANT1142`
    // print said so). A stored present-null promotes the column OUT of the packed representation,
    // so `Column::Num` can never contain one — which is why `try_fused_hop_num_count` testing the
    // bare `present[i]` bit for a `PropertyExists` atom is CORRECT and not the undercount it
    // looks like. The fused path declines this fixture on its `Column::Num` gate, so what this
    // test pins is the AGREEMENT of the two spellings, and the invariant is recorded at the
    // shortcut itself.
    assert!(col.present_at(2), "node 2 must be PRESENT (a stored null)");
    assert!(!col.has_value_at(2), "node 2 must be a present-NULL");

    let cnt = |q: &str| {
        let plan = crate::opt::optimize_indexed(crate::gremlin::parse(q).unwrap(), &st);
        match run(&plan, &st).rows[0][0] {
            Value::Num(x) => x,
            ref v => panic!("count is not a number: {v:?}"),
        }
    };

    // 1000 values and 1000 present-nulls carry `age`; 1000 absent do not.
    let fused = cnt("g.V().out('K').has('age').count()");
    let fold = cnt("g.V().out('K').values('age').count()");

    assert_eq!(fold, 2000.0, "the frontier fold counts the present-nulls");
    assert_eq!(
        fused, fold,
        "has('age').count() and values('age').count() are ONE question and must agree"
    );
}

/// Does the streaming presence count agree with the frontier fold for EVERY column type, and on a
/// stored present-null? (item 1143)
///
/// `try_fused_hop_present_count` reads `Column::presence_bits` instead of a type-specific `present`
/// slice, so it runs for `Num`, `Str`, `Dict`, `Bool`, `Temporal` and `Gen` alike — which is the
/// whole point (item 1142 measured a 21.4x gap decided by the storage type). Each variant gets its
/// own key here, because a `presence_bits` arm that returned the wrong pair for ONE variant would
/// be invisible to a single-column test.
///
/// NOTE ON WHAT THIS CANNOT REACH. A `VARIANT1143` print established that all three columns here
/// are `Column::Gen`, because storing a present-null promotes them (item 1142) — so the `nulls`
/// half of the entry's presence test never fires, and its mutant SURVIVES. That is the code being
/// defensive rather than this test being weak: no public path builds a packed column holding a
/// null, so no fixture can distinguish the two. Labelled at the function.
#[test]
fn the_streaming_presence_count_agrees_with_the_fold_for_every_column_type() {
    let mut b = Builder::default();
    b.node(&["P"], &[]); // 0 is the hub
                         // 600 targets, cycling: has-every-key / present-null-on-every-key / absent.
    for i in 0..600u32 {
        match i % 3 {
            0 => b.node(
                &["P"],
                &[
                    ("num", n(f64::from(i))),
                    ("txt", s("x")),
                    ("flag", Value::Bool(true)),
                ],
            ),
            1 => b.node(
                &["P"],
                &[
                    ("num", Value::Null),
                    ("txt", Value::Null),
                    ("flag", Value::Null),
                ],
            ),
            _ => b.node(&["P"], &[]),
        };
    }
    for i in 1..=600u32 {
        b.edge(0, i, "K");
    }
    let st = b.build();

    let cnt = |q: &str| {
        let plan = crate::opt::optimize_indexed(crate::gremlin::parse(q).unwrap(), &st);
        match run(&plan, &st).rows[0][0] {
            Value::Num(x) => x,
            ref v => panic!("count is not a number: {v:?}"),
        }
    };

    // The ROW COUNT of the same traversal, through the GENERAL path. After item 1144 BOTH count
    // spellings reach the streaming entry (a claim trace says so: 6 `present` claims, 3 per
    // spelling), so comparing them to each other no longer crosses a route boundary. This does,
    // and it is what keeps the test from being a self-comparison.
    let rows = |q: &str| {
        let plan = crate::opt::optimize_indexed(crate::gremlin::parse(q).unwrap(), &st);
        run(&plan, &st).rows.len() as f64
    };

    for key in ["num", "txt", "flag"] {
        // 200 with a value and 200 with a stored present-null carry the key; 200 do not.
        let streamed = cnt(&format!("g.V().out('K').has('{key}').count()"));
        let projected = cnt(&format!("g.V().out('K').values('{key}').count()"));
        let general = rows(&format!("g.V().out('K').has('{key}')"));

        assert_eq!(
            general, 400.0,
            "{key}: the general path yields a row per value AND per stored present-null"
        );
        assert_eq!(
            streamed, general,
            "{key}: has(k).count() must equal the rows the general path produces"
        );
        assert_eq!(
            projected, general,
            "{key}: values(k).count() is the SAME question and must agree too"
        );
    }

    // A key no node carries is zero, not a decline into something else.
    assert_eq!(cnt("g.V().out('K').has('nosuchkey').count()"), 0.0);
}

/// The STREAMING entry's projection see-through must decline a projection that can RAISE —
/// item 1144.
///
/// Item 1136 pins the same guard on `try_frontier_count` with a hand-built CAST plan, and that
/// test does NOT cover this entry: its store is built with `add_node`/`add_edge`, which leaves the
/// per-type CSR stale, so `fused_hop_shape` declines and the plan never reaches here. The widened
/// admission mutant SURVIVED until this test existed, for exactly that reason — item 1142's
/// lesson about fused-path fixtures, arriving a second time.
#[test]
fn the_streaming_see_through_declines_a_projection_that_can_raise() {
    let mut b = Builder::default();
    b.node(&["P"], &[]);
    for i in 0..200u32 {
        b.node(&["P"], &[("txt", s(if i % 2 == 0 { "zz" } else { "7" }))]);
    }
    for i in 1..=200u32 {
        b.edge(0, i, "K");
    }
    let st = b.build();

    // `Agg{count(*)} / Project{[("c", CAST txt AS INT)]} / Filter{PropertyExists} / Expand / Scan`
    // — the shape this entry claims, with a cast that faults on "zz". It MUST fault, not count.
    let plan = Plan::Scan { label: None }
        .expand(0, Dir::Out, &["K".to_string()])
        .filter(Expr::PropertyExists {
            slot: 1,
            key: "txt".into(),
        })
        .project(vec![(
            "c".to_string(),
            Expr::Cast {
                target: crate::ir::CastTarget::Integer,
                expr: Box::new(Expr::Prop {
                    slot: 1,
                    key: "txt".into(),
                }),
            },
        )])
        .aggregate(
            vec![],
            vec![Agg {
                func: AggFn::Count,
                arg: None,
                distinct: false,
                name: "count".into(),
                frac: None,
                null_on_empty: false,
                numeric_only: false,
            }],
        );

    assert!(
        crate::exec::try_run(&plan, &st).is_err(),
        "a faulting projection under count(*) must still fault, not be skipped by the stream"
    );
}

/// Clearing an unread `bind_edge` must not change any answer — item 1146.
///
/// The rewrite fires for a KEYLESS aggregate whose every agg is a bare non-DISTINCT `count(*)`,
/// and it changes which element sits in the Expand's last slot (the edge, or the target). Nothing
/// reads that slot under those guards, so the row COUNT is all that is observable — and
/// `bind_edge` appends a column rather than changing the row count. Pinned here on the shapes
/// where that could go wrong, including a SELF-LOOP under `bothE`, since self-loop doubling is a
/// separate flag (`double_loops`) that the rewrite must carry through untouched.
#[test]
fn clearing_an_unread_bound_edge_changes_no_answer() {
    let mut b = Builder::default();
    b.node(&["P"], &[("age", n(1.0))]); // 0
    b.node(&["P"], &[("age", n(2.0))]); // 1
    b.node(&["P"], &[("age", n(3.0))]); // 2
    b.edge(0, 1, "K");
    b.edge(0, 2, "K");
    b.edge(1, 2, "K");
    b.edge(2, 2, "K"); // a SELF-LOOP
    let st = b.build();

    let cnt = |q: &str| {
        let plan = crate::opt::optimize_indexed(crate::gremlin::parse(q).unwrap(), &st);
        match run(&plan, &st).rows[0][0] {
            Value::Num(x) => x,
            ref v => panic!("count is not a number: {v:?}"),
        }
    };
    let rows = |q: &str| {
        let plan = crate::opt::optimize_indexed(crate::gremlin::parse(q).unwrap(), &st);
        run(&plan, &st).rows.len() as f64
    };

    // THE TWO SPELLINGS OF ONE HOP. TinkerPop ground truth (item 1145): `out(T)` IS
    // `outE(T).inV()`, both yielding the edge's HEAD.
    assert_eq!(cnt("g.V().out('K').count()"), 4.0);
    assert_eq!(cnt("g.V().outE('K').inV().count()"), 4.0);
    // And both equal the rows the general path produces for the same traversal.
    assert_eq!(rows("g.V().out('K')"), 4.0);

    // The EDGE frontier itself: one row per edge either way, so clearing the flag is invisible.
    assert_eq!(cnt("g.V().outE('K').count()"), 4.0);

    // `bothE` over a self-loop is where `double_loops` lives. The rewrite preserves that flag, so
    // these must still match the general path rather than gaining or losing the loop's second
    // traversal.
    assert_eq!(
        cnt("g.V().bothE('K').count()"),
        rows("g.V().bothE('K')"),
        "bothE count must equal the rows the general path yields (self-loop doubling intact)"
    );
    assert_eq!(
        cnt("g.V().both('K').count()"),
        rows("g.V().both('K')"),
        "both() likewise"
    );

    // Shapes the rewrite must DECLINE, still answering correctly: a DISTINCT count and an
    // aggregate with an ARG both read the frontier, so the bound edge is not unread.
    assert_eq!(cnt("g.V().outE('K').dedup().count()"), 4.0);
    assert_eq!(cnt("g.V().out('K').dedup().count()"), 2.0);
}

/// A NULL join key must not match a real node — item 1150, and this was a WRONG ANSWER.
///
/// `hash_join`'s dense path used to place the `u32::MAX` OPTIONAL sentinel at "the slot just past
/// the largest real id" ON THE RIGHT, while probing with LEFT ids. Two collisions followed, and
/// the second is the general one:
///
///   - every right key NULL  => the sentinel slot is 0, so a real LEFT id of 0 matched it;
///   - any right side at all => a real LEFT id of `right_max + 1` matched it, since
///     `counts.len()` was `sentinel + 2` and the bounds guard therefore let it through.
///
/// Both arms are pinned below. The fixture is built so the colliding id is PRESENT on the left,
/// because the bug is invisible otherwise — which is exactly why `rewrite_fuzz` needed 500,000
/// seeds to reach it.
#[test]
fn a_null_join_key_does_not_match_a_real_node() {
    use crate::batch::{Batch, Col};

    // ARM 1: every right key is NULL, and the left holds id 0 — the seed-383127 shape.
    let left = Batch::of(vec![Col::Nodes(vec![0, 1, 0])]);
    let right = Batch::of(vec![Col::Nodes(vec![u32::MAX, u32::MAX])]);
    let out = super::hash_join(&left, &right, &[(0, 0)]);
    assert_eq!(
        out.rows(),
        0,
        "all-NULL right keys must match no real left id (got {} rows)",
        out.rows()
    );

    // ARM 2: a real left id equal to `right_max + 1`. Right max is 3, so left id 4 used to land
    // in the sentinel bucket and match the NULL row.
    let left = Batch::of(vec![Col::Nodes(vec![4])]);
    let right = Batch::of(vec![Col::Nodes(vec![3, u32::MAX])]);
    let out = super::hash_join(&left, &right, &[(0, 0)]);
    assert_eq!(
        out.rows(),
        0,
        "a left id of right_max + 1 must not match the NULL row (got {} rows)",
        out.rows()
    );

    // AND NULL STILL MATCHES NULL, which is deliberate in this engine: `value_at` maps the
    // sentinel to NULL on both sides, so the two key derivations agree. Two left NULLs against
    // two right NULLs is the full 2x2.
    let left = Batch::of(vec![Col::Nodes(vec![u32::MAX, 7, u32::MAX])]);
    let right = Batch::of(vec![Col::Nodes(vec![u32::MAX, 7, u32::MAX])]);
    let out = super::hash_join(&left, &right, &[(0, 0)]);
    assert_eq!(out.rows(), 5, "2x2 NULL pairs plus the one real 7-7 pair");

    // A plain real-id join is unaffected: id 2 appears twice on the right.
    let left = Batch::of(vec![Col::Nodes(vec![1, 2, 9])]);
    let right = Batch::of(vec![Col::Nodes(vec![2, 5, 2])]);
    let out = super::hash_join(&left, &right, &[(0, 0)]);
    assert_eq!(
        out.rows(),
        2,
        "left id 2 matches both right 2s, and nothing else"
    );
}

/// The IN spelling of a 1-hop count is the same question as the OUT one — item 1153.
///
/// Over a whole-graph scan every edge is an out-edge of exactly one source AND an in-edge of
/// exactly one target, so both emit one row per edge. The shortcut used to refuse `Dir::In`
/// (1510x at bench scale), and the answers agreed throughout, so only a timing row could see it.
///
/// The fixture carries a SELF-LOOP and a PARALLEL edge, because those are where the "one row per
/// edge" argument could fail: a self-loop is an in-edge of exactly one target (itself), and
/// parallel edges are two edges rather than one. `Dir::Both` is also asserted, since it counts
/// edge ENDS and must NOT take this shortcut.
#[test]
fn the_in_spelling_of_a_one_hop_count_matches_the_out_spelling() {
    let mut b = Builder::default();
    for _ in 0..40u32 {
        b.node(&["Person"], &[]);
    }
    // A plain chain, a SELF-LOOP, and a PARALLEL pair.
    for i in 0..30u32 {
        b.edge(i, i + 1, "KNOWS");
    }
    b.edge(7, 7, "KNOWS"); // self-loop
    b.edge(3, 4, "KNOWS"); // parallel with the chain's 3->4
    let st = b.build();

    let cnt = |q: &str| {
        let plan = crate::opt::optimize_indexed(crate::gql::parse(q).unwrap(), &st);
        match run(&plan, &st).rows[0][0] {
            Value::Num(x) => x,
            ref v => panic!("count is not a number: {v:?}"),
        }
    };
    let rows = |q: &str| {
        let plan = crate::opt::optimize_indexed(crate::gql::parse(q).unwrap(), &st);
        run(&plan, &st).rows.len() as f64
    };

    // 32 edges: 30 chain + 1 self-loop + 1 parallel.
    let out = cnt("MATCH (a:Person)-[:KNOWS]->(x) RETURN count(*) AS c");
    let inn = cnt("MATCH (a:Person)<-[:KNOWS]-(x) RETURN count(*) AS c");
    let general = rows("MATCH (a:Person)-[:KNOWS]->(x) RETURN a, x");

    assert_eq!(
        out, 32.0,
        "one row per edge, self-loop and parallel included"
    );
    assert_eq!(
        inn, out,
        "the IN spelling is the SAME question as the OUT one"
    );
    assert_eq!(
        general, out,
        "and both equal the rows the general path yields"
    );

    // BOTH counts edge ENDS, so it is a DIFFERENT number and must not take this shortcut:
    // 2*32 - 1 self-loop = 63.
    assert_eq!(
        cnt("MATCH (a:Person)-[:KNOWS]-(x) RETURN count(*) AS c"),
        63.0,
        "Dir::Both counts edge ends, with a self-loop counted once"
    );
}

/// The two UNDIRECTED spellings count a self-loop differently, and only the doubling one takes
/// the shortcut — item 1154.
///
/// A both-expansion emits a row per edge END, so the count is `2*|E_t|` with a self-loop
/// contributing two rows or one, and `double_loops` is exactly which:
///
///   * Gremlin `both(T)` doubles it. TINKERPOP GROUND TRUTH, run in a console: on a 2-edge graph
///     where one edge is a self-loop, `out(K)` is 2 and `both(K)` is 4.
///   * GQL `-[:T]-` counts it once.
///
/// So the two spellings legitimately DISAGREE, and a fixture without a self-loop cannot tell them
/// apart — which is why this one has two.
#[test]
fn the_two_undirected_spellings_differ_on_a_self_loop() {
    let mut b = Builder::default();
    for _ in 0..30u32 {
        b.node(&["Person"], &[]);
    }
    for i in 0..20u32 {
        b.edge(i, i + 1, "KNOWS");
    }
    b.edge(5, 5, "KNOWS"); // self-loop
    b.edge(9, 9, "KNOWS"); // and a second, so an off-by-one cannot pass
    let st = b.build();

    let gql = |q: &str| {
        let plan = crate::opt::optimize_indexed(crate::gql::parse(q).unwrap(), &st);
        match run(&plan, &st).rows[0][0] {
            Value::Num(x) => x,
            ref v => panic!("count is not a number: {v:?}"),
        }
    };
    let gremlin = |q: &str| {
        let plan = crate::opt::optimize_indexed(crate::gremlin::parse(q).unwrap(), &st);
        match run(&plan, &st).rows[0][0] {
            Value::Num(x) => x,
            ref v => panic!("count is not a number: {v:?}"),
        }
    };
    let rows = |q: &str| {
        let plan = crate::opt::optimize_indexed(crate::gremlin::parse(q).unwrap(), &st);
        run(&plan, &st).rows.len() as f64
    };

    // 22 edges: 20 chain + 2 self-loops.
    assert_eq!(
        gql("MATCH (a:Person)-[:KNOWS]->(x) RETURN count(*) AS c"),
        22.0
    );

    // Gremlin `both()` DOUBLES both self-loops: 2*22 = 44.
    assert_eq!(gremlin("g.V().both('KNOWS').count()"), 44.0);
    // And it equals the rows the general traversal yields, which is the cross-route check.
    assert_eq!(rows("g.V().both('KNOWS')"), 44.0);

    // GQL `-[:KNOWS]-` counts each self-loop ONCE: 2*22 - 2 = 42. A DIFFERENT number, and the
    // reason the shortcut must not answer this spelling from `2*|E_t|`.
    assert_eq!(
        gql("MATCH (a:Person)-[:KNOWS]-(x) RETURN count(*) AS c"),
        42.0
    );
}

/// The lazy self-loop cache must be dropped by a WRITE — item 1155.
///
/// `live_etype_loops` caches a per-type self-loop count and `invalidate_csr` clears it. That is
/// one maintenance site instead of the eight a maintained count would need, and invalidation is
/// the single thing the design can get wrong: a stale cache answers the undirected count with
/// yesterday's `loops(t)` and is off by exactly the difference.
///
/// So this queries FIRST (populating the cache), then mutates, then queries again — the order
/// that can fail. A test that writes before its first read cannot see this at all.
#[test]
fn the_self_loop_cache_is_dropped_by_a_write() {
    let mut b = Builder::default();
    for _ in 0..10u32 {
        b.node(&["Person"], &[]);
    }
    b.edge(0, 1, "KNOWS");
    b.edge(1, 2, "KNOWS");
    b.edge(3, 3, "KNOWS"); // one self-loop
    let mut st = b.build();

    let undirected = |st: &Store| {
        let plan = crate::opt::optimize_indexed(
            crate::gql::parse("MATCH (a:Person)-[:KNOWS]-(x) RETURN count(*) AS c").unwrap(),
            st,
        );
        match run(&plan, st).rows[0][0] {
            Value::Num(x) => x,
            ref v => panic!("count is not a number: {v:?}"),
        }
    };

    // 3 edges, 1 self-loop: 2*3 - 1 = 5. This POPULATES the cache.
    assert_eq!(undirected(&st), 5.0);

    // ADD A SELF-LOOP. 4 edges, 2 self-loops: 2*4 - 2 = 6. A stale cache would say 2*4 - 1 = 7.
    let loop_eid = st.add_edge(5, 5, "KNOWS");
    assert_eq!(
        undirected(&st),
        6.0,
        "a stale self-loop cache would answer 7 here"
    );

    // ADD A NON-LOOP. 5 edges, 2 self-loops: 2*5 - 2 = 8.
    st.add_edge(6, 7, "KNOWS");
    assert_eq!(undirected(&st), 8.0);

    // DELETE the 5->5 self-loop added above. 4 edges, 1 self-loop: 2*4 - 1 = 7.
    // `add_edge` returns the eid, so capture it rather than looking it up.
    st.delete_edge(5, 5, loop_eid);
    assert_eq!(
        undirected(&st),
        7.0,
        "a delete must drop the cache as well as an insert"
    );
}

/// A hop matching SEVERAL edge types counts the sum of the per-type counts — item 1157.
///
/// The label-arity enum's third variant used to decline (1205x against a single type). The sum is
/// only correct under two conditions the arm enforces, and both are pinned here because each one
/// silently DOUBLE-COUNTS if dropped:
///
///   * a repeated name is ONE wanted type, since the general path builds a SET;
///   * a type carried as a SECONDARY label elsewhere has an incomplete partition (item 1004), so
///     every listed type needs its own `type_ever_secondary` guard — not just the first.
#[test]
fn a_multi_type_hop_count_is_the_sum_of_its_types() {
    let mut b = Builder::default();
    for _ in 0..20u32 {
        b.node(&["Person"], &[]);
    }
    for i in 0..6u32 {
        b.edge(i, i + 1, "KNOWS");
    }
    for i in 0..4u32 {
        b.edge(i, i + 2, "FOLLOWS");
    }
    b.edge(9, 9, "KNOWS"); // a self-loop, so the undirected arm is exercised too
    let st = b.build();

    let cnt = |q: &str, st: &Store| {
        let plan = crate::opt::optimize_indexed(crate::gql::parse(q).unwrap(), st);
        match run(&plan, st).rows[0][0] {
            Value::Num(x) => x,
            ref v => panic!("count is not a number: {v:?}"),
        }
    };
    let rows = |q: &str, st: &Store| {
        let plan = crate::opt::optimize_indexed(crate::gql::parse(q).unwrap(), st);
        run(&plan, st).rows.len() as f64
    };

    // 7 KNOWS (6 chain + 1 self-loop) and 4 FOLLOWS.
    assert_eq!(
        cnt("MATCH (a:Person)-[:KNOWS]->(x) RETURN count(*) AS c", &st),
        7.0
    );
    assert_eq!(
        cnt("MATCH (a:Person)-[:FOLLOWS]->(x) RETURN count(*) AS c", &st),
        4.0
    );

    // THE SUM, and the general path's row count as the cross-route check.
    assert_eq!(
        cnt(
            "MATCH (a:Person)-[:KNOWS|FOLLOWS]->(x) RETURN count(*) AS c",
            &st
        ),
        11.0
    );
    assert_eq!(
        rows("MATCH (a:Person)-[:KNOWS|FOLLOWS]->(x) RETURN a, x", &st),
        11.0
    );

    // A REPEATED NAME is one type, not two. Without the dedupe this answers 14.
    assert_eq!(
        cnt(
            "MATCH (a:Person)-[:KNOWS|KNOWS]->(x) RETURN count(*) AS c",
            &st
        ),
        7.0
    );

    // AN UNKNOWN type contributes zero rather than declining the query.
    assert_eq!(
        cnt(
            "MATCH (a:Person)-[:KNOWS|NOSUCH]->(x) RETURN count(*) AS c",
            &st
        ),
        7.0
    );

    // UNDIRECTED over two types: 2*11 - 1 self-loop = 21, so the per-type loop adjustment has to
    // be applied inside the sum and not once outside it.
    assert_eq!(
        cnt(
            "MATCH (a:Person)-[:KNOWS|FOLLOWS]-(x) RETURN count(*) AS c",
            &st
        ),
        21.0
    );

    // AND A SECONDARY LABEL MAKES THE SUM UNSAFE, so the arm must decline and the general path
    // answer. Give one FOLLOWS edge a second label of `KNOWS`: it is now matched by BOTH listed
    // types, and summing the partitions would count it twice.
    let mut st2 = st.clone();
    let eid = st2
        .edge_by_ext("e7")
        .expect("the first FOLLOWS edge exists with a minted id");
    st2.set_edge_extra_labels(eid, &["KNOWS"]);

    // 11 edges still, each matched once: the answer must stay 11, not become 12.
    assert_eq!(
        cnt(
            "MATCH (a:Person)-[:KNOWS|FOLLOWS]->(x) RETURN count(*) AS c",
            &st2
        ),
        11.0,
        "a secondary label must make the sum decline, not double-count"
    );
}

/// Does the maintained per-type count SUM to the live edge count, after every mutation kind?
/// (item 1158)
///
/// `live_edge_count` is `out_adj.iter().map(Vec::len).sum()` — O(nodes), and item 1157 measured the
/// untyped hop-count arm paying 36.6us for it against 0.4 for the single-type arm. Item 1118's
/// `etype_counts` already holds the pieces, so the same number is `sum(live_etype_count(t))`, which
/// is O(#types).
///
/// This asserts they agree against an INDEPENDENT adjacency walk (`all_edges().len()`), because
/// item 1158 made `live_edge_count` the per-type sum itself — comparing those two would be a
/// tautology. Written BEFORE relying on the equality rather than after:
/// every edge has exactly one OUT adjacency entry and exactly one PRIMARY type, so the sums must
/// match — unless a mutation path updates one and not the other, which is precisely what item
/// 1118's own recount oracle exists to catch for the counts and what this catches for their sum.
#[test]
fn the_per_type_counts_sum_to_the_live_edge_count_after_every_mutation() {
    let mut b = Builder::default();
    for _ in 0..12u32 {
        b.node(&["P"], &[]);
    }
    b.edge(0, 1, "A");
    b.edge(1, 2, "B");
    b.edge(2, 2, "A"); // self-loop
    let mut st = b.build();

    // THE ORACLE IS `all_edges().len()`, NOT `live_edge_count()`.
    //
    // Item 1158 made `live_edge_count` itself the per-type sum, so comparing the two would be a
    // TAUTOLOGY — the trap this file warns about, caught here while writing the change. `all_edges`
    // flat-maps `out_adj` independently, and the doc on `live_edge_count` states the equivalence
    // with it, so it is the right second opinion: an adjacency walk against a maintained sum.
    let agree = |st: &Store, what: &str| {
        let walked = st.all_edges().len();
        let counted = st.live_edge_count();
        let summed: usize = st
            .all_etype_ids()
            .iter()
            .map(|&t| st.live_etype_count(t))
            .sum();

        assert_eq!(
            walked, counted,
            "{what}: the adjacency WALK and live_edge_count disagree"
        );
        assert_eq!(
            walked, summed,
            "{what}: the adjacency WALK and the maintained per-type sum disagree"
        );

        walked
    };

    assert_eq!(agree(&st, "after load"), 3);

    // INSERTS, including a second type and another self-loop.
    let e3 = st.add_edge(3, 4, "B");
    assert_eq!(agree(&st, "after add_edge"), 4);
    let e4 = st.add_edge(5, 5, "C");
    assert_eq!(agree(&st, "after add_edge of a new type"), 5);

    // DELETES, of a plain edge and of a self-loop.
    st.delete_edge(3, 4, e3);
    assert_eq!(agree(&st, "after delete_edge"), 4);
    st.delete_edge(5, 5, e4);
    assert_eq!(agree(&st, "after delete_edge of a self-loop"), 3);

    // A NODE DELETE, which takes its whole adjacency with it — item 1118's `mem::take` arm.
    st.delete_node(0);
    assert_eq!(agree(&st, "after delete_node"), 2);

    // AND A NODE ADD, so the id space grows without edges.
    st.add_node(&["P"], &[]);
    assert_eq!(agree(&st, "after add_node"), 2);
}

/// A stored NaN is the GREATEST value in the contract's total order (`cmp_num_total`: NaN last,
/// all NaNs tie), so `max` over a group containing one must BE NaN — in EVERY spelling.
///
/// Until item 1161 it was not. `scan_fold_minmax` folded with a plain `x > mx` on the stated
/// premise that "stored Nums are finite"; they are not (`SET n.v = sqrt(0 - 1)` stores one from
/// the surface language, and `stored_infinity_is_a_value` already settled ±∞), so the NaN was
/// skipped and the MULTI-aggregate spelling answered 5.0 where the SINGLE-aggregate spelling of
/// the same query answered NaN. Two spellings of one question, both plausible, one wrong.
///
/// `ORDER BY ... DESC` is the reference rather than a hand-written expectation: it is the
/// contract's own order, decided in one place, so the assertion cannot drift from it.
#[test]
fn a_stored_nan_is_the_maximum_in_every_agg_spelling() {
    let mut b = Builder::default();
    b.node(&["N"], &[("v", Value::Num(1.0))]);
    b.node(&["N"], &[("v", Value::Num(f64::NAN))]);
    b.node(&["N"], &[("v", Value::Num(5.0))]);
    let st = b.build();

    let ask = |q: &str| -> Vec<Value> {
        let plan = crate::opt::optimize_indexed(crate::gql::parse(q).unwrap(), &st);
        run(&plan, &st).rows[0].to_vec()
    };
    let is_nan = |v: &Value| matches!(v, Value::Num(x) if x.is_nan());
    let num = |v: &Value| match v {
        Value::Num(x) => *x,
        other => panic!("not a number: {other:?}"),
    };

    // The reference: the first row descending IS the maximum under the total order.
    let top = ask("MATCH (n:N) RETURN n.v AS c ORDER BY n.v DESC");
    assert!(is_nan(&top[0]), "ORDER BY DESC puts NaN first: {top:?}");

    // SINGLE aggregate — `try_scan_num_agg`'s extremum block.
    let one = ask("MATCH (n:N) RETURN max(n.v) AS c");
    assert!(is_nan(&one[0]), "single-agg max: {one:?}");
    assert_eq!(num(&ask("MATCH (n:N) RETURN min(n.v) AS c")[0]), 1.0);

    // MULTI aggregate — `scan_fold_minmax`, the arm that was wrong.
    let two = ask("MATCH (n:N) RETURN min(n.v) AS a, max(n.v) AS b");
    assert_eq!(num(&two[0]), 1.0, "multi-agg min: {two:?}");
    assert!(is_nan(&two[1]), "multi-agg max: {two:?}");

    // `scan_fold_all` — the arm that wants sum AND an extremum off one column.
    let three = ask("MATCH (n:N) RETURN sum(n.v) AS a, max(n.v) AS b, min(n.v) AS c");
    assert!(is_nan(&three[0]), "sum NaN-poisons: {three:?}");
    assert!(is_nan(&three[1]), "scan_fold_all max: {three:?}");
    assert_eq!(num(&three[2]), 1.0, "scan_fold_all min: {three:?}");
}

/// Every NaN ties under the total order, so a group whose present values are ALL NaN has NaN as
/// its MINIMUM too — the one case where the extremum fold cannot read its `<`/`>` accumulator,
/// because no comparison ever displaced the sentinel. Guards the `cnt == nan_cnt` arm, which a
/// mixed group cannot reach.
#[test]
fn an_all_nan_group_has_nan_for_both_extrema() {
    let mut b = Builder::default();
    b.node(&["N"], &[("v", Value::Num(f64::NAN))]);
    b.node(&["N"], &[("v", Value::Num(f64::NAN))]);
    let st = b.build();

    let ask = |q: &str| -> Vec<Value> {
        let plan = crate::opt::optimize_indexed(crate::gql::parse(q).unwrap(), &st);
        run(&plan, &st).rows[0].to_vec()
    };
    let is_nan = |v: &Value| matches!(v, Value::Num(x) if x.is_nan());

    for q in [
        "MATCH (n:N) RETURN min(n.v) AS c",
        "MATCH (n:N) RETURN max(n.v) AS c",
    ] {
        assert!(is_nan(&ask(q)[0]), "{q}");
    }
    let both = ask("MATCH (n:N) RETURN min(n.v) AS a, max(n.v) AS b");
    assert!(is_nan(&both[0]) && is_nan(&both[1]), "multi-agg: {both:?}");
}

/// The extremum fold against the contract's order over EVERY numeric edge case the sentinel
/// start could get wrong, each spelled three ways (single agg, multi agg, and `ORDER BY` as the
/// reference). The fixtures that matter and why:
///
/// - `±INFINITY` — the sentinels ARE ±∞, so a stored one must still be returned rather than
///   read as "nothing seen".
/// - `-0.0` / `0.0` — `cmp_num_total` ties them deliberately, so either is a correct VALUE but
///   only one is the correct BYTES; both folds must keep the incumbent, i.e. the first seen.
/// - a single value, and a column present on only some nodes.
#[test]
fn the_extremum_fold_matches_the_contract_order_on_every_numeric_edge_case() {
    let cases: &[(&str, &[f64])] = &[
        ("one value", &[7.5]),
        ("plus infinity alone", &[f64::INFINITY]),
        ("minus infinity alone", &[f64::NEG_INFINITY]),
        (
            "both infinities and a finite",
            &[f64::INFINITY, 2.5, f64::NEG_INFINITY],
        ),
        ("negative zero first", &[-0.0, 0.0]),
        ("positive zero first", &[0.0, -0.0]),
        ("nan among finites", &[3.0, f64::NAN, -1.0]),
        (
            "nan and both infinities",
            &[f64::INFINITY, f64::NAN, f64::NEG_INFINITY],
        ),
        ("descending", &[9.0, 4.0, 1.0]),
    ];

    for (name, vals) in cases {
        let mut b = Builder::default();
        for &x in *vals {
            b.node(&["N"], &[("v", Value::Num(x))]);
        }
        // A node with the key ABSENT, so `present` is not all-true and the labelled walk and the
        // whole-column walk are both exercised across the case list.
        b.node(&["N"], &[]);
        let st = b.build();

        let ask = |q: &str| -> Vec<Value> {
            let plan = crate::opt::optimize_indexed(crate::gql::parse(q).unwrap(), &st);
            run(&plan, &st).rows[0].to_vec()
        };
        // The reference: ORDER BY decides the order in ONE place, so sorting the values through
        // the engine gives the expected extrema without restating `cmp_num_total` here. NULLs
        // sort somewhere in that order, so read the extrema off the non-null ends.
        let sorted = {
            let plan = crate::opt::optimize_indexed(
                crate::gql::parse("MATCH (n:N) WHERE n.v IS NOT NULL RETURN n.v AS c ORDER BY n.v")
                    .unwrap(),
                &st,
            );
            run(&plan, &st)
                .rows
                .iter()
                .map(|r| r[0].clone())
                .collect::<Vec<_>>()
        };
        let (lo, hi) = (sorted[0].clone(), sorted[sorted.len() - 1].clone());
        let num = |v: &Value| match v {
            Value::Num(x) => *x,
            other => panic!("{name}: not a number: {other:?}"),
        };
        // TWO assertions per extremum, because one oracle cannot carry both halves.
        //
        // AGAINST THE CONTRACT, by `cmp_num_total` and NOT by `==`: `NaN != NaN` under `==`, so
        // an equality check would pass vacuously on the case this test exists for. It is also
        // not a BIT check, because `cmp_num_total` ties `-0.0` with `0.0` deliberately — both
        // are a correct maximum of `{-0.0, 0.0}`, so ORDER BY's tie order is unspecified and
        // cannot be a bit-exact oracle. (Asserting bits here is what this test did first, and
        // the `-0.0` case failed against a fold that was right.)
        let agrees = |got: f64, want: &Value, which: &str| {
            assert_eq!(
                crate::value::cmp_num_total(got, num(want)),
                std::cmp::Ordering::Equal,
                "{name}: {which} is {got:?}, contract order says {want:?}"
            );
        };
        // ACROSS THE SPELLINGS, by BITS: whichever of a tied pair the fold keeps, every path
        // claiming the query must keep the SAME one, or two spellings of it return different
        // bytes. That is the half that was broken — the single-agg path answered NaN and the
        // multi-agg path 5.0 — and it holds for ties too, where the contract has no preference
        // but byte-identity still does.
        let one_min = num(&ask("MATCH (n:N) RETURN min(n.v) AS c")[0]);
        let one_max = num(&ask("MATCH (n:N) RETURN max(n.v) AS c")[0]);
        agrees(one_min, &lo, "single-agg min");
        agrees(one_max, &hi, "single-agg max");

        let two = ask("MATCH (n:N) RETURN min(n.v) AS a, max(n.v) AS b");
        let all = ask("MATCH (n:N) RETURN sum(n.v) AS a, min(n.v) AS b, max(n.v) AS c");
        for (which, got) in [
            ("multi-agg min", num(&two[0])),
            ("scan_fold_all min", num(&all[1])),
        ] {
            assert_eq!(
                got.to_bits(),
                one_min.to_bits(),
                "{name}: {which} is {got:?}, single-agg min is {one_min:?}"
            );
        }
        for (which, got) in [
            ("multi-agg max", num(&two[1])),
            ("scan_fold_all max", num(&all[2])),
        ] {
            assert_eq!(
                got.to_bits(),
                one_max.to_bits(),
                "{name}: {which} is {got:?}, single-agg max is {one_max:?}"
            );
        }
    }
}

/// The percentile fast path against the GENERAL grouped fold, for every fraction and every
/// numeric fixture shape — a cross-path differential, which is the strongest oracle available
/// in-process: both spellings answer one question, one takes `try_scan_percentile` and the other
/// `aggregation::percentile_of`, and they must agree in BITS.
///
/// `LET g = 1 ... GROUP BY g` is the general-path spelling (one group, so the answer is the same
/// question) because `try_scan_percentile` requires a SOLE aggregate over a bare `Scan` with no
/// grouping keys. GROUP BY takes a bound name, hence the `LET`.
///
/// The fractions include OUT-OF-RANGE ones on purpose: `percentile_of` clamps at the point of use
/// and an unclamped fraction once PANICKED by indexing past the end (item 530), so the fast path
/// has to clamp identically rather than merely not crash.
#[test]
fn the_percentile_fast_path_agrees_with_the_grouped_fold() {
    let cases: &[(&str, &[Option<f64>])] = &[
        ("one value", &[Some(7.5)]),
        ("two values", &[Some(1.0), Some(2.0)]),
        ("odd count", &[Some(3.0), Some(1.0), Some(2.0)]),
        ("even count", &[Some(4.0), Some(1.0), Some(3.0), Some(2.0)]),
        ("duplicates", &[Some(5.0), Some(5.0), Some(5.0), Some(1.0)]),
        (
            "negatives",
            &[Some(-10.0), Some(0.5), Some(-3.0), Some(8.0)],
        ),
        ("descending", &[Some(9.0), Some(7.0), Some(4.0), Some(1.0)]),
        // A column that is present on only some nodes, so the gather's `present` test matters.
        (
            "some absent",
            &[Some(2.0), None, Some(6.0), None, Some(4.0)],
        ),
        // DROPPED by both paths (`percentile_of` keeps only finite values), so these check the
        // fast path drops exactly the same ones rather than folding them in.
        (
            "a NaN among finites",
            &[Some(1.0), Some(f64::NAN), Some(9.0)],
        ),
        (
            "both infinities among finites",
            &[
                Some(f64::INFINITY),
                Some(2.0),
                Some(f64::NEG_INFINITY),
                Some(6.0),
            ],
        ),
        (
            "every value non-finite",
            &[Some(f64::NAN), Some(f64::INFINITY)],
        ),
        ("all absent", &[None, None]),
    ];

    for (name, vals) in cases {
        let mut b = Builder::default();
        for v in *vals {
            match v {
                Some(x) => b.node(&["N"], &[("v", Value::Num(*x))]),
                None => b.node(&["N"], &[]),
            };
        }
        let st = b.build();

        // OUT-OF-RANGE in both directions. The fraction must be a numeric LITERAL ("percentile
        // fraction must be a numeric constant"), so a negative one is `-1` and not `0 - 1`.
        for frac in ["-1", "0", "0.001", "0.25", "0.5", "0.75", "0.999", "1", "2"] {
            for kind in ["percentile_cont", "percentile_disc"] {
                let ask = |q: &str| -> Value {
                    let plan = crate::opt::optimize_indexed(crate::gql::parse(q).unwrap(), &st);
                    run(&plan, &st).rows[0][0].clone()
                };
                let fast = ask(&format!("MATCH (n:N) RETURN {kind}(n.v, {frac}) AS c"));
                let general = ask(&format!(
                    "MATCH (n:N) LET g = 1 RETURN {kind}(n.v, {frac}) AS c GROUP BY g"
                ));
                let bits = |v: &Value| match v {
                    Value::Num(x) => Some(x.to_bits()),
                    Value::Null => None,
                    other => panic!("{name}/{kind}/{frac}: {other:?}"),
                };
                assert_eq!(
                    bits(&fast),
                    bits(&general),
                    "{name} / {kind}(v, {frac}): fast {fast:?} vs general {general:?}"
                );
            }
        }
    }
}

/// A `-0.0` in the column makes the fast path DECLINE, and the answer is then the general fold's.
///
/// This is the one exactness guard in `try_scan_percentile` and the only case an unstable
/// selection can get bit-wrong: `-0.0` and `0.0` TIE under `partial_cmp` (the comparator
/// `percentile_of` sorts with) but differ in bits, so a stable sort keeps a tied run in input
/// order where a selection may return either member. The assertion is on BITS, because on VALUES
/// `-0.0 == 0.0` and the whole question is invisible.
///
/// THE FIXTURES ARE A MUTANT'S DOING, and the first version of this test was worthless. With the
/// guard removed the test PASSED (item 1162, mutant M1) — it used three values and fractions up
/// to 0.5, and `select_nth_unstable_by` on a slice that short falls into an INSERTION SORT, which
/// is stable, so the selection and the sort agree and the test passed for the wrong reason.
///
/// A standalone search over both algorithms then settled how real the divergence is: **1,454,911
/// of 5,916,000 (input, index) pairs differ in bits**, and the minimal case is `n = 2, idx = 1`
/// over `[-0.0, 0.0]` — stable gives `0.0`, selection gives `-0.0`. So the cases below are built
/// FROM that counterexample: the two-value fixture at fraction 1 (which is exactly `idx = 1`),
/// plus a 64-value fixture to clear the insertion-sort regime entirely. Both now fail with the
/// guard removed.
///
/// The lesson generalizes past this test: a size-dependent algorithm needs the size swept, and a
/// fixture small enough to be convenient can sit entirely inside the branch that cannot fail.
#[test]
fn a_negative_zero_declines_the_percentile_fast_path() {
    // THE MINIMAL DISTINGUISHING CASE, in both input orders: two tied zeros, and the fraction
    // that selects the second of them.
    for order in [[-0.0f64, 0.0], [0.0, -0.0]] {
        let mut b = Builder::default();
        b.node(&["N"], &[("v", Value::Num(order[0]))]);
        b.node(&["N"], &[("v", Value::Num(order[1]))]);
        let st = b.build();
        agree_on_bits(
            &st,
            &format!("two zeros {order:?}"),
            &["1", "0.75", "0.5", "0"],
        );
    }

    // AND WELL CLEAR OF THE INSERTION-SORT REGIME: 64 values, the zeros scattered among finites
    // so a pivot choice actually moves them.
    for &zeros_first in &[true, false] {
        let mut b = Builder::default();
        for i in 0..64u32 {
            let x = match i % 4 {
                0 => {
                    if zeros_first {
                        -0.0
                    } else {
                        0.0
                    }
                }
                1 => {
                    if zeros_first {
                        0.0
                    } else {
                        -0.0
                    }
                }
                2 => f64::from(i),
                _ => -f64::from(i),
            };
            b.node(&["N"], &[("v", Value::Num(x))]);
        }
        let st = b.build();
        agree_on_bits(
            &st,
            &format!("64 values, zeros_first={zeros_first}"),
            &["0", "0.25", "0.5", "0.51", "0.75", "1"],
        );
    }
}

/// Both percentile spellings, over every fraction given, compared as BITS — the fast path against
/// the general grouped fold. Shared by the negative-zero test's fixtures.
fn agree_on_bits(st: &Store, name: &str, fracs: &[&str]) {
    let ask = |q: &str| -> u64 {
        let plan = crate::opt::optimize_indexed(crate::gql::parse(q).unwrap(), st);
        match run(&plan, st).rows[0][0] {
            Value::Num(x) => x.to_bits(),
            ref v => panic!("{name}: not a number: {v:?}"),
        }
    };
    for kind in ["percentile_cont", "percentile_disc"] {
        for frac in fracs {
            assert_eq!(
                ask(&format!("MATCH (n:N) RETURN {kind}(n.v, {frac}) AS c")),
                ask(&format!(
                    "MATCH (n:N) LET g = 1 RETURN {kind}(n.v, {frac}) AS c GROUP BY g"
                )),
                "{name} / {kind}(v, {frac}): the fast path and the grouped fold differ in BITS"
            );
        }
    }
}

/// The fast path must not claim a shape it cannot answer: a DISTINCT percentile, a percentile
/// over a non-`Num` column, one over a non-bare-`Scan` input, and a second aggregate beside it.
/// Each must still answer, which it only can if the entry declined and the general path ran.
#[test]
fn the_percentile_fast_path_declines_what_it_cannot_answer() {
    let mut b = Builder::default();
    for i in 0..6u32 {
        b.node(
            &["N"],
            &[
                ("v", Value::Num(f64::from(i))),
                ("s", Value::Str(format!("s{i}").into())),
            ],
        );
    }
    for i in 0..5u32 {
        b.edge(i, i + 1, "E");
    }
    let st = b.build();

    for q in [
        // DISTINCT — a different question, so claiming it would be a wrong answer.
        "MATCH (n:N) RETURN percentile_disc(DISTINCT n.v, 0.5) AS c",
        // A STRING column: the general path's own error or coercion rule, not this path's.
        "MATCH (n:N) RETURN percentile_disc(n.s, 0.5) AS c",
        // Not a bare `Scan`.
        "MATCH (n:N) WHERE n.v > 1 RETURN percentile_disc(n.v, 0.5) AS c",
        "MATCH (a:N)-[:E]->(b) RETURN percentile_disc(b.v, 0.5) AS c",
        // A second aggregate beside it, which `sole_agg` refuses.
        "MATCH (n:N) RETURN percentile_disc(n.v, 0.5) AS c, count(*) AS d",
        // Grouped.
        "MATCH (n:N) LET g = n.v RETURN percentile_disc(n.v, 0.5) AS c GROUP BY g",
    ] {
        let plan = crate::opt::optimize_indexed(crate::gql::parse(q).unwrap(), &st);
        // Answering at all is the assertion: an entry that claimed one of these and could not
        // answer it would panic or return the wrong arity here.
        let rows = crate::exec::try_run(&plan, &st);
        assert!(rows.is_ok() || q.contains("n.s"), "{q}: {rows:?}");
    }
}

/// The boolean extremum arm against the GENERAL grouped fold, over every arrangement its SHORT
/// CIRCUIT can get wrong (item 1172).
///
/// `try_scan_bool_agg` stops the walk the moment it sees the value that ends the search — `false`
/// for `min`, `true` for `max` — so unlike every other extremum arm its answer depends on WHICH
/// cells it reached, not merely on what the column holds. That makes the arrangement the thing to
/// sweep: the sought value first, last, only, absent, and interleaved with absent cells and stored
/// nulls.
///
/// `LET g = 1 ... GROUP BY g` is the oracle because it is one group — the same question — and it
/// routes to the general fold, since the fast path requires a SOLE aggregate over a bare `Scan`
/// with no grouping keys.
#[test]
fn the_boolean_extremum_agrees_with_the_grouped_fold_for_every_arrangement() {
    // `None` is an ABSENT key; `Some(None)` is a STORED null; `Some(Some(b))` is a value.
    #[allow(clippy::option_option)]
    let cases: &[(&str, &[Option<Option<bool>>])] = &[
        ("empty", &[]),
        ("one false", &[Some(Some(false))]),
        ("one true", &[Some(Some(true))]),
        ("all false", &[Some(Some(false)), Some(Some(false))]),
        ("all true", &[Some(Some(true)), Some(Some(true))]),
        // The sought value FIRST, which is where the short circuit fires immediately.
        (
            "false first",
            &[Some(Some(false)), Some(Some(true)), Some(Some(true))],
        ),
        (
            "true first",
            &[Some(Some(true)), Some(Some(false)), Some(Some(false))],
        ),
        // And LAST, which is the arrangement where it never fires early.
        (
            "false last",
            &[Some(Some(true)), Some(Some(true)), Some(Some(false))],
        ),
        (
            "true last",
            &[Some(Some(false)), Some(Some(false)), Some(Some(true))],
        ),
        ("all absent", &[None, None]),
        ("all stored null", &[Some(None), Some(None)]),
        // A present-null must NOT participate, and must not be mistaken for a value either way.
        ("null then false", &[Some(None), Some(Some(false))]),
        ("null then true", &[Some(None), Some(Some(true))]),
        ("absent then true", &[None, Some(Some(true))]),
        (
            "value, null, absent mixed",
            &[Some(Some(true)), Some(None), None, Some(Some(false))],
        ),
    ];

    for (name, cells) in cases {
        let mut b = Builder::default();
        for cell in *cells {
            match cell {
                None => b.node(&["N"], &[]),
                Some(None) => b.node(&["N"], &[("f", Value::Null)]),
                Some(Some(x)) => b.node(&["N"], &[("f", Value::Bool(*x))]),
            };
        }
        let st = b.build();

        // The FIRST row, or `None` when the query produced none. Both happen here, and which is
        // which is the point of the `empty` case below.
        let ask = |q: &str| -> Option<Value> {
            let plan = crate::opt::optimize_indexed(crate::gql::parse(q).unwrap(), &st);
            run(&plan, &st).rows.iter().next().map(|r| r[0].clone())
        };

        for kind in ["min", "max"] {
            let fast = ask(&format!("MATCH (n:N) RETURN {kind}(n.f) AS c"));

            if cells.is_empty() {
                // THE ORACLE DOES NOT APPLY HERE, and the reason is GQL and not a defect: a
                // scalar aggregate over zero rows yields ONE row (the identity — NULL for an
                // extremum), while `GROUP BY` over zero rows yields NO GROUPS and therefore no
                // rows at all. Comparing them would assert the two spellings answer the same
                // question when they do not. So the empty fixture is checked against the contract
                // directly, and the grouped oracle is used for every fixture that has a row.
                assert_eq!(
                    format!("{fast:?}"),
                    format!("{:?}", Some(Value::Null)),
                    "{name} / {kind}: an extremum over zero rows is one NULL row"
                );

                continue;
            }

            let general = ask(&format!(
                "MATCH (n:N) LET g = 1 RETURN {kind}(n.f) AS c GROUP BY g"
            ));

            assert_eq!(
                format!("{fast:?}"),
                format!("{general:?}"),
                "{name} / {kind}: fast {fast:?} vs grouped fold {general:?}"
            );
        }
    }
}

/// The boolean arm over a PARTIAL label and over DELETED nodes — the two walks `scan_visit_while`
/// chooses between, which the arrangement sweep above never leaves the `whole` branch to exercise.
///
/// The short circuit makes this sharper than it is for the other arms: a walk that visited a node
/// it should not have could STOP on that node's value and answer from a row the query excludes.
#[test]
fn the_boolean_extremum_respects_the_label_and_liveness() {
    let mut b = Builder::default();
    // The only `true` sits on a node the label does NOT cover, so a label-blind walk would stop
    // there and answer `true` for `max` where the answer is `false`.
    b.node(&["Other"], &[("f", Value::Bool(true))]);
    b.node(&["N"], &[("f", Value::Bool(false))]);
    b.node(&["N"], &[("f", Value::Bool(false))]);
    let mut st = b.build();

    let ask = |st: &Store, q: &str| -> Value {
        let plan = crate::opt::optimize_indexed(crate::gql::parse(q).unwrap(), st);
        run(&plan, st).rows[0][0].clone()
    };

    assert_eq!(
        format!("{:?}", ask(&st, "MATCH (n:N) RETURN max(n.f) AS c")),
        format!("{:?}", Value::Bool(false)),
        "a label-blind walk would find the `Other` node's true"
    );

    // THE NO-PRESENT-CELL CASE, and it took a surviving mutant to find a fixture that REACHES it.
    // The arrangement sweep's "all absent" and "all stored null" fixtures do not: with no node
    // carrying the key the column does not exist (`store.column` is None), and a stored
    // present-null promotes the column to `Column::Gen` (item 1142) — so both decline before the
    // boolean arm is entered and its NULL branch was never exercised. A mutant answering `false`
    // there SURVIVED.
    //
    // This reaches it: the column EXISTS as `Column::Bool` because an out-of-label node carries a
    // value, while every node the label covers lacks the key — so the walk visits only cells whose
    // `present` bit is false and must answer NULL rather than a default.
    let mut b2 = Builder::default();
    b2.node(&["Other"], &[("f", Value::Bool(true))]);
    b2.node(&["N"], &[]);
    b2.node(&["N"], &[]);
    let st2 = b2.build();

    for kind in ["min", "max"] {
        let got = ask(&st2, &format!("MATCH (n:N) RETURN {kind}(n.f) AS c"));

        assert_eq!(
            format!("{got:?}"),
            format!("{:?}", Value::Null),
            "{kind} over a Bool column with no present cell under the label"
        );
    }

    // AND LIVENESS: delete the only `false`-carrying node that the label covers, leaving one.
    st.add_node(&["N"], &[("f", Value::Bool(true))]);
    let before = ask(&st, "MATCH (n:N) RETURN min(n.f) AS c");

    assert_eq!(format!("{before:?}"), format!("{:?}", Value::Bool(false)));

    st.delete_node(1);
    st.delete_node(2);

    // Only the live `true` node remains under `:N`, so both extrema are now `true`.
    for kind in ["min", "max"] {
        let fast = ask(&st, &format!("MATCH (n:N) RETURN {kind}(n.f) AS c"));
        let general = ask(
            &st,
            &format!("MATCH (n:N) LET g = 1 RETURN {kind}(n.f) AS c GROUP BY g"),
        );

        assert_eq!(
            format!("{fast:?}"),
            format!("{general:?}"),
            "after deletes / {kind}"
        );
        assert_eq!(format!("{fast:?}"), format!("{:?}", Value::Bool(true)));
    }
}

/// The boolean top-K arm against the GENERAL sort, over the arrangements its early exit can get
/// wrong (item 1175).
///
/// The oracle is the SAME query without `LIMIT`: `try_scan_top_k` needs a limit (`let limit =
/// limit?`), so the unlimited form cannot take the streaming arm and is the general path. The
/// limited answer must be a PREFIX of it — which also pins the tie-break, and ties are the whole
/// difficulty here: a boolean column has two distinct values, so a `LIMIT 10` over many rows is
/// almost all tied and WHICH rows come back is the question. The streaming buffer carries an
/// `arrival` counter for exactly that, so the order is scan-stable.
#[test]
fn the_boolean_top_k_is_a_prefix_of_the_general_sort() {
    #[allow(clippy::option_option)]
    let cases: &[(&str, &[Option<Option<bool>>])] = &[
        ("all false", &[Some(Some(false)); 6]),
        ("all true", &[Some(Some(true)); 6]),
        (
            "false first then true",
            &[
                Some(Some(false)),
                Some(Some(false)),
                Some(Some(true)),
                Some(Some(true)),
            ],
        ),
        (
            "true first then false",
            &[
                Some(Some(true)),
                Some(Some(true)),
                Some(Some(false)),
                Some(Some(false)),
            ],
        ),
        (
            "interleaved",
            &[
                Some(Some(true)),
                Some(Some(false)),
                Some(Some(true)),
                Some(Some(false)),
                Some(Some(true)),
                Some(Some(false)),
            ],
        ),
        // NULLS and ABSENT cells, which the arm does not push and instead records via
        // `nulls_seen` — the flag that makes it hand the whole query back when a null could fall
        // inside the window. Both placements relative to the values.
        (
            "nulls first",
            &[Some(None), Some(None), Some(Some(false)), Some(Some(true))],
        ),
        (
            "nulls last",
            &[Some(Some(false)), Some(Some(true)), Some(None), Some(None)],
        ),
        (
            "absent mixed in",
            &[None, Some(Some(true)), None, Some(Some(false))],
        ),
        ("a single row", &[Some(Some(true))]),
    ];

    for (name, cells) in cases {
        let mut b = Builder::default();
        for cell in *cells {
            match cell {
                None => b.node(&["N"], &[]),
                Some(None) => b.node(&["N"], &[("f", Value::Null)]),
                Some(Some(x)) => b.node(&["N"], &[("f", Value::Bool(*x))]),
            };
        }
        let st = b.build();

        let rows = |q: &str| -> Vec<String> {
            let plan = crate::opt::optimize_indexed(crate::gql::parse(q).unwrap(), &st);
            run(&plan, &st)
                .rows
                .iter()
                .map(|r| format!("{:?}", r[0]))
                .collect()
        };

        for dir in ["", " DESC"] {
            // The general path: no LIMIT, so `try_scan_top_k` declines on its `limit?`.
            let all = rows(&format!("MATCH (n:N) RETURN n.f AS v ORDER BY n.f{dir}"));

            for limit in 1..=cells.len() + 1 {
                let got = rows(&format!(
                    "MATCH (n:N) RETURN n.f AS v ORDER BY n.f{dir} LIMIT {limit}"
                ));
                let want: Vec<String> = all.iter().take(limit).cloned().collect();

                assert_eq!(got, want, "{name}{dir} LIMIT {limit}");
            }

            // And with SKIP, which the arm applies after trimming its buffer.
            for skip in 1..=2 {
                let got = rows(&format!(
                    "MATCH (n:N) RETURN n.f AS v ORDER BY n.f{dir} SKIP {skip} LIMIT 2"
                ));
                let want: Vec<String> = all.iter().skip(skip).take(2).cloned().collect();

                assert_eq!(got, want, "{name}{dir} SKIP {skip} LIMIT 2");
            }
        }
    }
}

/// The `nulls_seen` FALLBACK, which needs a fixture my first sweep could not build (item 1175).
///
/// The arm hands the whole query back when a null could fall inside the window
/// (`nulls_seen && buf.len() < kcap`). Reaching that needs TWO things at once, and the
/// arrangement sweep above has neither:
///
///   - `kcap * 2 < node_count` — the window must be a small PREFIX, or the function bails before
///     the scan. With a 4-node fixture only `LIMIT 1` gets past it.
///   - `buf.len() < kcap` — FEWER present rows than the window, so the pushed buffer is short.
///
/// A small fixture cannot satisfy both: at `LIMIT 1` the buffer is already long enough. So a
/// mutant deleting `nulls_seen = true` SURVIVED the sweep. This fixture is 200 nodes of which only
/// three carry a boolean, with a window of ten — the buffer holds 3 against a `kcap` of 10, and the
/// fallback is the only thing that keeps the answer right.
///
/// (A STORED null cannot be used here: it promotes the column to `Column::Gen` — item 1142 — so
/// the arm declines for a different reason and the fallback is still not reached. The nulls here
/// are ABSENT cells, which leave the column `Bool` with `present[i]` false.)
#[test]
fn the_boolean_top_k_hands_back_when_a_null_is_inside_the_window() {
    let mut b = Builder::default();
    for i in 0..200u32 {
        if i % 64 == 0 {
            b.node(&["N"], &[("f", Value::Bool(i % 128 == 0))]);
        } else {
            b.node(&["N"], &[]); // ABSENT, so the column stays `Bool`
        }
    }
    let st = b.build();

    let rows = |q: &str| -> Vec<String> {
        let plan = crate::opt::optimize_indexed(crate::gql::parse(q).unwrap(), &st);
        run(&plan, &st)
            .rows
            .iter()
            .map(|r| format!("{:?}", r[0]))
            .collect()
    };

    for dir in ["", " DESC"] {
        let all = rows(&format!("MATCH (n:N) RETURN n.f AS v ORDER BY n.f{dir}"));

        for limit in [5usize, 10, 20] {
            let got = rows(&format!(
                "MATCH (n:N) RETURN n.f AS v ORDER BY n.f{dir} LIMIT {limit}"
            ));
            let want: Vec<String> = all.iter().take(limit).cloned().collect();

            assert_eq!(
                got.len(),
                limit.min(all.len()),
                "{dir} LIMIT {limit}: row count"
            );
            assert_eq!(got, want, "{dir} LIMIT {limit}");
        }
    }
}

/// The boolean top-K arm under a PARTIAL label, which is the other walk `scan_visit_while`
/// chooses between — and where the early exit is most dangerous, since stopping on an
/// out-of-label row would answer from a row the query excludes.
#[test]
fn the_boolean_top_k_respects_the_label() {
    let mut b = Builder::default();
    // The `false` rows — which ASC wants first — are all OUT of the label.
    b.node(&["Other"], &[("f", Value::Bool(false))]);
    b.node(&["Other"], &[("f", Value::Bool(false))]);
    b.node(&["N"], &[("f", Value::Bool(true))]);
    b.node(&["N"], &[("f", Value::Bool(true))]);
    let st = b.build();

    let rows = |q: &str| -> Vec<String> {
        let plan = crate::opt::optimize_indexed(crate::gql::parse(q).unwrap(), &st);
        run(&plan, &st)
            .rows
            .iter()
            .map(|r| format!("{:?}", r[0]))
            .collect()
    };

    let limited = rows("MATCH (n:N) RETURN n.f AS v ORDER BY n.f LIMIT 2");
    let all = rows("MATCH (n:N) RETURN n.f AS v ORDER BY n.f");

    assert_eq!(
        limited, all,
        "a label-blind early exit would return the Other rows"
    );
    assert_eq!(
        limited,
        vec![
            format!("{:?}", Value::Bool(true)),
            format!("{:?}", Value::Bool(true))
        ],
        "only the in-label `true` rows exist under :N"
    );
}

/// `order().limit()` over a boolean key WITH STORED NULLS, in both null placements — the oracle a
/// future relaxation of `try_scan_top_k_wide`'s `nulls_first` guard will have to keep passing
/// (item 1179).
///
/// WHY THIS EXISTS BEFORE THE CHANGE IT GUARDS. That guard's own comment says it is "unexercised,
/// not verified": no front end currently reaches the arm with `nulls_first`, because Gremlin's
/// `values(k).order().limit(n)` lowers to `OrderPage{Project{Filter{Scan}}}` and the lift requires
/// a bare `Scan` under the projection (item 1178). So the guard is a precondition nothing tests.
///
/// Item 1151's rule is that relaxing an oracle needs two proofs — that it still fires, and that it
/// still catches a real bug — and the cheapest way to have the second is to pin the ANSWERS first,
/// while the slow general path is the one producing them. Then a relaxation that reaches the arm
/// either reproduces these rows or is wrong, and the test says which.
///
/// A STORED null is the only kind that matters here: an ABSENT key is dropped by the
/// `PropertyExists` filter that `values(k)` inserts, while a stored present-null survives it — so
/// it is the row that can land inside a top-K window and the one the guard is about. (A stored
/// null on a bool property promotes the column to `Column::Gen`, item 1142, which is itself part
/// of what the relaxation must handle rather than assume away.)
#[test]
fn a_bool_order_limit_with_stored_nulls_pins_both_null_placements() {
    let mut b = Builder::default();
    // Interleaved so neither placement can be satisfied by luck of scan order.
    for (i, cell) in [
        Some(true),
        None,
        Some(false),
        Some(true),
        None,
        Some(false),
        Some(false),
        Some(true),
    ]
    .iter()
    .enumerate()
    {
        let _ = i;
        match cell {
            Some(x) => b.node(&["N"], &[("f", Value::Bool(*x))]),
            None => b.node(&["N"], &[("f", Value::Null)]),
        };
    }
    let st = b.build();

    let rows = |q: &str| -> Vec<String> {
        let plan = crate::opt::optimize_indexed(crate::gql::parse(q).unwrap(), &st);
        run(&plan, &st)
            .rows
            .iter()
            .map(|r| format!("{:?}", r[0]))
            .collect()
    };

    // The unlimited sort is the reference: it cannot take the streaming arm (`limit?` declines),
    // so it is the general path both today and after any relaxation.
    for dir in ["", " DESC"] {
        let all = rows(&format!("MATCH (n:N) RETURN n.f AS v ORDER BY n.f{dir}"));

        assert_eq!(all.len(), 8, "every row is returned{dir}");

        for limit in 1..=8 {
            let got = rows(&format!(
                "MATCH (n:N) RETURN n.f AS v ORDER BY n.f{dir} LIMIT {limit}"
            ));

            assert_eq!(
                got,
                all.iter().take(limit).cloned().collect::<Vec<_>>(),
                "{dir} LIMIT {limit} must be a prefix of the full sort"
            );
        }
    }

    // AND THE PLACEMENT ITSELF, stated rather than merely compared: GQL places nulls LAST, so a
    // `LIMIT` that stops short of them never sees one, and the DESC spelling does not move them to
    // the front. A relaxation that got placement wrong would still pass the prefix checks above if
    // it broke BOTH spellings consistently, so this pins the direction.
    let asc = rows("MATCH (n:N) RETURN n.f AS v ORDER BY n.f");
    let desc = rows("MATCH (n:N) RETURN n.f AS v ORDER BY n.f DESC");
    let nulls_at = |v: &[String]| -> Vec<usize> {
        v.iter()
            .enumerate()
            .filter(|(_, s)| s.contains("Null"))
            .map(|(i, _)| i)
            .collect()
    };

    assert_eq!(nulls_at(&asc), vec![6, 7], "ASC places the two nulls last");
    assert_eq!(
        nulls_at(&desc),
        vec![6, 7],
        "DESC also places them last (GQL)"
    );
}
